CREATE OR REPLACE FUNCTION "private"."active_report_no"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
  select b.report_no
  from public.report_items i
  join public.report_batches b on b.id = i.report_id
  where i.entity_type = p_entity_type
    and i.entity_id = p_entity_id
    and i.active = true
    and b.status = 'active'
  order by b.created_at desc, b.id desc
  limit 1;
$$;


ALTER FUNCTION "private"."active_report_no"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."active_rubber_export_no_for_report"("p_report_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
  select e.export_no
  from public.rubber_export_items x
  join public.rubber_exports e on e.id = x.export_id
  join public.report_items i on i.id = x.source_report_item_id
  where i.report_id = p_report_id
    and i.active = true
    and x.active = true
    and e.status in ('draft', 'verified')
  order by e.created_at, e.id
  limit 1;
$$;


ALTER FUNCTION "private"."active_rubber_export_no_for_report"("p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."active_transfer_report_no"("p_transfer_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
  select b.report_no
  from public.report_items i
  join public.report_batches b on b.id = i.report_id
  where i.entity_id = p_transfer_id
    and i.entity_type in (
      'bank_transfer_source',
      'bank_transfer_target',
      'cash_transfer_sent',
      'cash_transfer_received'
    )
    and i.active = true
    and b.status = 'active'
  order by b.created_at desc, b.id desc
  limit 1;
$$;


ALTER FUNCTION "private"."active_transfer_report_no"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."append_dashboard_money_event"("p_source_type" "text", "p_source_id" "uuid", "p_action" "text", "p_payload" "jsonb", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_actor_name" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor_id uuid := coalesce(auth.uid(), p_actor_user_id, nullif(p_payload->>'actorUserId', '')::uuid);
  v_actor_name text;
  v_occurred_at timestamptz := clock_timestamp();
begin
  if v_actor_id is not null then
    select name into v_actor_name
    from public.profiles
    where id = v_actor_id;
  end if;

  v_actor_name := coalesce(
    nullif(v_actor_name, ''),
    nullif(p_actor_name, ''),
    nullif(p_payload->>'actorName', ''),
    'ระบบ'
  );

  insert into public.dashboard_money_events (
    location_id, source_type, source_id, event_key, action, kind, number,
    title, direction, amount, actor_user_id, actor_name, occurred_at, event_date
  ) values (
    (p_payload->>'locationId')::uuid,
    p_source_type,
    p_source_id,
    p_payload->>'eventKey',
    p_action,
    p_payload->>'kind',
    p_payload->>'number',
    p_payload->>'title',
    p_payload->>'direction',
    (p_payload->>'amount')::numeric,
    v_actor_id,
    v_actor_name,
    v_occurred_at,
    case when coalesce(p_payload->>'eventDate', '') ~ '^\d{4}-\d{2}-\d{2}$'
      then (p_payload->>'eventDate')::date
      else (v_occurred_at at time zone 'Asia/Bangkok')::date end
  );
end;
$_$;


ALTER FUNCTION "private"."append_dashboard_money_event"("p_source_type" "text", "p_source_id" "uuid", "p_action" "text", "p_payload" "jsonb", "p_actor_user_id" "uuid", "p_actor_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."apply_time_tracking_deductions"("p_profile_id" "uuid", "p_through_month" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_month date;
  v_first_month date;
  v_through_month date := date_trunc('month', p_through_month)::date;
  v_current_month date := date_trunc(
    'month',
    (now() at time zone 'Asia/Bangkok')::date
  )::date;
  v_daily_wage numeric;
  v_gross numeric;
  v_used numeric;
  v_available numeric;
  v_amount numeric;
  v_total numeric := 0;
  v_parent record;
  v_child_type public.financial_transaction_type;
  v_comment text;
begin
  perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || p_profile_id::text, 0));

  if v_through_month > v_current_month then
    v_through_month := v_current_month;
  end if;

  select p.daily_wage
  into v_daily_wage
  from public.profiles p
  where p.id = p_profile_id
    and p.is_active = true;

  if not found or coalesce(v_daily_wage, 0) <= 0 then
    return jsonb_build_object('deducted', 0);
  end if;

  select min(date_trunc('month', ft.effective_date)::date)
  into v_first_month
  from public.financial_transactions ft
  where ft.profile_id = p_profile_id
    and ft.type in ('DEBT', 'WITHDRAWAL')
    and ft.status = 'APPROVED'
    and ft.remaining_amount > 0
    and ft.effective_date < (v_through_month + interval '1 month')::date;

  if v_first_month is null then
    return jsonb_build_object('deducted', 0);
  end if;

  for v_month in
    select generate_series(
      v_first_month::timestamp,
      v_through_month::timestamp,
      interval '1 month'
    )::date
  loop
    if exists (
      select 1
      from public.payroll_slips ps
      where ps.profile_id = p_profile_id
        and ps.month = to_char(v_month, 'YYYY-MM')
    ) then
      continue;
    end if;

    v_gross := public.calculate_paid_work_days(
      p_profile_id,
      v_month::timestamp at time zone 'Asia/Bangkok',
      (v_month + interval '1 month')::timestamp at time zone 'Asia/Bangkok'
    ) * v_daily_wage;

    select coalesce(sum(ft.amount), 0)
    into v_used
    from public.financial_transactions ft
    where ft.profile_id = p_profile_id
      and ft.status = 'APPROVED'
      and ft.type in ('DEBT_DEDUCTION', 'WITHDRAWAL_DEDUCTION')
      and ft.applied_month = v_month;

    v_available := greatest(trunc(v_gross - v_used, 2), 0);
    if v_available <= 0 then
      continue;
    end if;

    for v_parent in
      select ft.*
      from public.financial_transactions ft
      where ft.profile_id = p_profile_id
        and ft.type in ('DEBT', 'WITHDRAWAL')
        and ft.status = 'APPROVED'
        and ft.remaining_amount > 0
        and ft.effective_date < (v_month + interval '1 month')::date
      order by ft.effective_date, ft.created_at, ft.id
      for update
    loop
      exit when v_available <= 0;

      v_amount := trunc(least(v_parent.remaining_amount, v_available), 2);
      if v_amount <= 0 then
        continue;
      end if;

      if v_parent.type = 'DEBT' then
        v_child_type := 'DEBT_DEDUCTION';
        v_comment := 'หักหนี้อัตโนมัติ';
      else
        v_child_type := 'WITHDRAWAL_DEDUCTION';
        v_comment := 'หักยอดเบิกเงินอัตโนมัติ';
      end if;

      update public.financial_transactions
      set remaining_amount = greatest(remaining_amount - v_amount, 0)
      where id = v_parent.id;

      insert into public.financial_transactions (
        profile_id,
        type,
        amount,
        status,
        parent_debt_id,
        applied_month,
        admin_comment,
        approved_by,
        approved_at
      )
      values (
        p_profile_id,
        v_child_type,
        v_amount,
        'APPROVED',
        v_parent.id,
        v_month,
        v_comment,
        v_parent.approved_by,
        now()
      );

      insert into public.time_tracking_audit_logs (
        admin_id,
        action,
        target_table,
        record_id,
        new_data,
        comment
      )
      values (
        coalesce(v_parent.approved_by, p_profile_id),
        'AUTO_DEDUCTION',
        'financial_transactions',
        v_parent.id,
        jsonb_build_object(
          'deducted_amount', v_amount,
          'remaining_amount', greatest(v_parent.remaining_amount - v_amount, 0),
          'type', v_child_type,
          'applied_month', v_month
        ),
        v_comment
      );

      v_parent.remaining_amount := greatest(v_parent.remaining_amount - v_amount, 0);
      v_available := trunc(v_available - v_amount, 2);
      v_total := v_total + v_amount;
    end loop;
  end loop;

  return jsonb_build_object('deducted', v_total);
end;
$$;


ALTER FUNCTION "private"."apply_time_tracking_deductions"("p_profile_id" "uuid", "p_through_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_attendance_month_open"("p_profile_id" "uuid", "p_month" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (
    select 1 from public.payroll_slips ps
    where ps.profile_id = p_profile_id and ps.month = p_month and ps.status in ('PENDING', 'APPROVED')
  ) then raise exception 'MONTH_CLOSED:%', p_month; end if;
  if exists (
    select 1
    from public.financial_transactions ft
    where ft.profile_id = p_profile_id
      and ft.status = 'APPROVED'
      and ft.type in ('DEBT_DEDUCTION', 'WITHDRAWAL_DEDUCTION')
      and ft.applied_month = (p_month || '-01')::date
  ) then raise exception 'DEDUCTION_LOCKED:%', p_month; end if;
end
$$;


ALTER FUNCTION "private"."assert_attendance_month_open"("p_profile_id" "uuid", "p_month" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_attendance_range_open"("p_profile_id" "uuid", "p_start_date" "date", "p_end_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_month date;
begin
  if p_start_date is null or p_end_date is null or p_start_date > p_end_date then
    return;
  end if;
  for v_month in
    select generate_series(
      date_trunc('month', p_start_date)::date,
      date_trunc('month', p_end_date)::date,
      interval '1 month'
    )::date
  loop
    perform private.assert_attendance_month_open(p_profile_id, to_char(v_month, 'YYYY-MM'));
  end loop;
end
$$;


ALTER FUNCTION "private"."assert_attendance_range_open"("p_profile_id" "uuid", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."assert_rubber_approval_group_not_empty"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_group_id uuid := coalesce(new.group_id, old.group_id);
begin
  if exists (select 1 from public.rubber_approval_groups g where g.id = v_group_id)
     and not exists (
       select 1 from public.rubber_approval_group_locations gl
       where gl.group_id = v_group_id
     ) then
    raise exception 'RUBBER_GROUP_EMPTY: กลุ่มต้องมีอย่างน้อยหนึ่งสาขา';
  end if;
  return null;
end
$$;


ALTER FUNCTION "private"."assert_rubber_approval_group_not_empty"() OWNER TO "postgres";


