    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (
      private.can_access_super_admin_features()
      and exists (
        select 1
        from public.profiles target
        where target.id = target_user
          and target.role <> 'super_admin'
          and target.is_active = true
