    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  location_id uuid;
begin
  for location_id in
    select l.id
    from public.locations l
    where l.is_active = true
  loop
    perform private.mark_dashboard_dirty(location_id);
  end loop;
  return null;
end;
$$;


