    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.can_request_dashboard_refresh(p_location_id) then
    raise exception 'ไม่มีสิทธิ์คำนวณ Dashboard สำหรับสาขานี้';
  end if;
end;
$$;


