CREATE OR REPLACE FUNCTION "private"."dashboard_rollover_if_needed"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  today date := (current_timestamp at time zone 'Asia/Bangkok')::date;
  changed boolean := false;
  next_version bigint := pg_catalog.txid_current();
begin
  insert into public.dashboard_refresh_settings (id)
  values (true)
  on conflict (id) do nothing;

  insert into public.dashboard_branch_snapshots (location_id)
  select l.id
  from public.locations l
  where l.is_active = true
  on conflict (location_id) do nothing;

  insert into public.dashboard_alert_thresholds (location_id)
  select l.id
  from public.locations l
  where l.is_active = true
  on conflict (location_id) do nothing;

  update public.dashboard_refresh_settings
  set last_rollover_date = today,
      updated_at = now()
  where id = true
    and last_rollover_date < today
  returning true into changed;

  if not coalesce(changed, false) then
    return false;
  end if;

  update public.dashboard_branch_snapshots
  set status = case
        when dashboard_branch_snapshots.status in ('queued', 'running')
          then dashboard_branch_snapshots.status
        else 'dirty'
      end,
      source_version = greatest(
        dashboard_branch_snapshots.source_version + 1,
        next_version
      ),
      updated_at = now()
  where location_id in (
    select l.id
    from public.locations l
    where l.is_active = true
  );

  return true;
end;
$$;


ALTER FUNCTION "private"."dashboard_rollover_if_needed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."dashboard_seed_active_location"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' and new.is_active = true then
    perform private.mark_dashboard_dirty(new.id);
  elsif new.is_active = true
    and old.is_active is distinct from new.is_active
  then
    perform private.mark_dashboard_dirty(new.id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."dashboard_seed_active_location"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."default_first_user_location_primary"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform pg_advisory_xact_lock(hashtextextended('user-locations:' || new.user_id::text, 0));
  if not new.is_primary and not exists (
    select 1 from public.user_locations ul where ul.user_id = new.user_id
  ) then
    new.is_primary := true;
  end if;
  return new;
end
$$;


ALTER FUNCTION "private"."default_first_user_location_primary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."delete_money_transfer"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor public.profiles%rowtype;
  v_transfer public.money_transfers%rowtype;
  v_released_item_count integer := 0;
begin
  if p_transfer_id is null
    or not private.can_access_money_transfer_module() then
    raise exception 'MONEY_TRANSFER_DELETE_FORBIDDEN';
  end if;

  select *
  into v_transfer
  from public.money_transfers t
  where t.id = p_transfer_id
  for update;

  if not found then
    raise exception 'MONEY_TRANSFER_NOT_FOUND';
  end if;

  if not private.can_access_location(v_transfer.location_id) then
    raise exception 'MONEY_TRANSFER_DELETE_FORBIDDEN';
  end if;

  if v_transfer.transfer_type = 'cash'
    or v_transfer.transfer_method = 'cash' then
    raise exception 'MONEY_TRANSFER_CASH_DELETE_REQUIRES_DEDICATED_WORKFLOW';
  end if;

  select *
  into v_actor
  from public.profiles p
  where p.id = auth.uid()
    and p.is_active = true;

  if not found then
    raise exception 'MONEY_TRANSFER_DELETE_FORBIDDEN';
  end if;

  -- Delete relations first so their existing report-lock trigger can abort the
  -- whole transaction before the parent is hidden.
  delete from public.money_transfer_items i
  where i.transfer_id = p_transfer_id;

  get diagnostics v_released_item_count = row_count;

  if v_transfer.record_status = 'deleted' then
    return pg_catalog.jsonb_build_object(
      'transferId', p_transfer_id,
      'status', 'deleted',
      'idempotent', true,
      'releasedItemCount', v_released_item_count
    );
  end if;

  perform pg_catalog.set_config(
    'app.money_transfer_delete_rpc',
    'true',
    true
  );

  update public.money_transfers
  set record_status = 'deleted',
      deleted_at = pg_catalog.now(),
      deleted_by_name = v_actor.name,
      deleted_by_phone = v_actor.phone,
      revision_no = revision_no + 1,
      updated_at = pg_catalog.now()
  where id = p_transfer_id;

  return pg_catalog.jsonb_build_object(
    'transferId', p_transfer_id,
    'status', 'deleted',
    'idempotent', false,
    'releasedItemCount', v_released_item_count
  );
end;
$$;


ALTER FUNCTION "private"."delete_money_transfer"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."effective_rubber_approval_settings"("p_location_id" "uuid") RETURNS TABLE("group_id" "uuid", "price_time_exempt" boolean, "edit_window_minutes" integer, "configured_price" numeric, "updated_by_name" "text", "updated_by_phone" "text", "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    g.id,
    g.id is null,
    g.edit_window_minutes,
    g.configured_price,
    g.updated_by_name,
    g.updated_by_phone,
    g.updated_at
  from (select 1) seed
  left join public.rubber_approval_group_locations gl
    on gl.location_id = p_location_id
  left join public.rubber_approval_groups g
    on g.id = gl.group_id
$$;


ALTER FUNCTION "private"."effective_rubber_approval_settings"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."effective_time_payroll_settings"() RETURNS TABLE("mode" "text", "workday_end_time" time without time zone, "pending_workday_end_time" time without time zone, "pending_effective_date" "date", "activated_on" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    s.mode,
    case
      when s.pending_effective_date <= (now() at time zone 'Asia/Bangkok')::date
        then s.pending_workday_end_time
      else s.workday_end_time
    end,
    case
      when s.pending_effective_date <= (now() at time zone 'Asia/Bangkok')::date then null
      else s.pending_workday_end_time
    end,
    case
      when s.pending_effective_date <= (now() at time zone 'Asia/Bangkok')::date then null
      else s.pending_effective_date
    end,
    s.activated_on
  from public.time_payroll_settings s
  where s.singleton = true
$$;


ALTER FUNCTION "private"."effective_time_payroll_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_complete_wex_before_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (
    select 1
    from public.export_vehicle_weigh_lines l
    where l.wex_id = new.wex_id
      and (l.outbound_weight = 0 or l.outbound_at is null)
  ) then
    raise exception 'WEX_INCOMPLETE_WEIGHING: ต้องชั่งออกรถทุกคันก่อนเลือกรายการขายยาง';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_complete_wex_before_reservation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_rubber_bill_ocr_source_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.owner_user_id is distinct from old.owner_user_id
     or new.location_id is distinct from old.location_id
     or new.image_sha256 is distinct from old.image_sha256
     or new.drive_file_id is distinct from old.drive_file_id then
    raise exception 'ห้ามแก้ไขข้อมูลอ้างอิงต้นทาง OCR ของบิลยาง';
  end if;
  if new.state is distinct from old.state
     and not (
       (old.state = 'staged' and new.state = 'reserved')
       or (old.state = 'reserved' and new.state in ('attached', 'abandoned'))
     ) then
    raise exception 'เปลี่ยนสถานะต้นทาง OCR ของบิลยางไม่ถูกต้อง: % -> %', old.state, new.state;
  end if;
  return new;
end
$$;


ALTER FUNCTION "private"."enforce_rubber_bill_ocr_source_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_time_tracking_expense_relation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_rpc_write boolean := coalesce(current_setting('app.time_tracking_expense_rpc', true), 'false') = 'true';
begin
  if tg_table_name = 'financial_transactions' then
    if old.status <> 'APPROVED'
      and new.status = 'APPROVED'
      and new.type = 'WITHDRAWAL' then
      if not v_rpc_write
        or new.approved_at is null
        or new.cancelled_at is not null then
        raise exception 'Withdrawal approval must use the time tracking approval RPC';
      end if;
    end if;

    if old.status = 'APPROVED'
      and old.type = 'WITHDRAWAL'
      and (
        new.expense_location_id is distinct from old.expense_location_id
        or new.cancelled_at is distinct from old.cancelled_at
        or new.cancelled_by is distinct from old.cancelled_by
        or new.cancel_reason is distinct from old.cancel_reason
      )
      and not v_rpc_write then
      raise exception 'Withdrawal expense relation must be changed at its source through the time tracking RPC';
    end if;

  elsif tg_table_name = 'payroll_slips' then
    if old.status <> 'APPROVED' and new.status = 'APPROVED' then
      if not v_rpc_write
        or new.approved_at is null
        or new.cancelled_at is not null then
        raise exception 'Payroll approval must use the time tracking approval RPC';
      end if;
    end if;

    if old.status = 'APPROVED'
      and (
        new.expense_location_id is distinct from old.expense_location_id
        or new.cancelled_at is distinct from old.cancelled_at
        or new.cancelled_by is distinct from old.cancelled_by
        or new.cancel_reason is distinct from old.cancel_reason
      )
      and not v_rpc_write then
      raise exception 'Payroll expense relation must be changed at its source through the time tracking RPC';
    end if;
  end if;

  return new;
end;
$$;


