$$;


ALTER FUNCTION "private"."is_super_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_time_payroll_manager"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.has_time_payroll_manager_access()
$$;


ALTER FUNCTION "private"."is_time_payroll_manager"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."mark_dashboard_dirty"("p_location_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  next_version bigint := pg_catalog.txid_current();
begin
  if p_location_id is null or not exists (
    select 1
    from public.locations l
    where l.id = p_location_id
      and l.is_active = true
  ) then
    return;
  end if;

  insert into public.dashboard_branch_snapshots (
    location_id,
    status,
    source_version
  )
  values (
    p_location_id,
    'dirty',
    next_version
  )
  on conflict (location_id) do update
  set status = case
        when dashboard_branch_snapshots.status in ('queued', 'running')
          then dashboard_branch_snapshots.status
        else 'dirty'
      end,
      source_version = excluded.source_version,
      updated_at = now()
  where dashboard_branch_snapshots.source_version < excluded.source_version;

  insert into public.dashboard_alert_thresholds (location_id)
  values (p_location_id)
  on conflict (location_id) do nothing;
end;
$$;


ALTER FUNCTION "private"."mark_dashboard_dirty"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."merge_pending_money_transfers"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor public.profiles%rowtype;
  v_group record;
  v_secondary_ids uuid[];
  v_group_total numeric(12,2);
  v_pending_count integer := 0;
  v_merged_group_count integer := 0;
  v_merged_transfer_count integer := 0;
  v_deleted_transfer_count integer := 0;
  v_survivor_ids uuid[] := array[]::uuid[];
begin
  if p_location_id is null
    or not private.can_access_money_transfer_module()
    or not private.can_access_location(p_location_id) then
    raise exception 'ไม่มีสิทธิ์รวมรายการโอนเงินของสาขานี้';
  end if;

  select * into v_actor
  from public.profiles
  where id = auth.uid() and is_active = true;

  if not found then
    raise exception 'ไม่พบบัญชีผู้ใช้งานที่เปิดใช้งาน';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'money-transfer-pending-merge:' || p_location_id::text,
      0
    )
  );

  -- Parent locks serialize concurrent child/slip writes through their FKs.
  perform 1
  from public.money_transfers t
  where t.location_id = p_location_id
    and t.transfer_type = 'customer'
    and t.transfer_method = 'bank'
    and t.record_status = 'active'
    and t.sync_status = 'synced'
    and t.transfer_status = 'pending'
  order by t.created_at, t.id
  for update;

  select count(*) into v_pending_count
  from public.money_transfers t
  where t.location_id = p_location_id
    and t.transfer_type = 'customer'
    and t.transfer_method = 'bank'
    and t.record_status = 'active'
    and t.sync_status = 'synced'
    and t.transfer_status = 'pending';

  for v_group in
    with eligible as (
      select t.id, t.customer_id, t.account_number, t.created_at
      from public.money_transfers t
      where t.location_id = p_location_id
        and t.transfer_type = 'customer'
        and t.transfer_method = 'bank'
        and t.record_status = 'active'
        and t.sync_status = 'synced'
        and t.transfer_status = 'pending'
        and t.customer_id is not null
        and not exists (
          select 1
          from public.money_transfer_slips s
          where s.transfer_id = t.id
        )
        and private.active_transfer_report_no(t.id) is null
        and not exists (
          select 1
          from public.money_transfer_items i
          where i.transfer_id = t.id
            and private.active_report_no(i.source_type, i.source_id) is not null
        )
    )
    select
      e.customer_id,
      e.account_number,
      pg_catalog.array_agg(e.id order by e.created_at, e.id) as transfer_ids
    from eligible e
    group by e.customer_id, e.account_number
    having count(*) >= 2
    order by min(e.created_at), min(e.id::text)
  loop
    v_secondary_ids := v_group.transfer_ids[
      2:pg_catalog.array_length(v_group.transfer_ids, 1)
    ];

    update public.money_transfer_items
    set transfer_id = v_group.transfer_ids[1]
    where transfer_id = any(v_secondary_ids);

    select coalesce(sum(i.amount), 0)::numeric(12,2)
    into v_group_total
    from public.money_transfer_items i
    where i.transfer_id = v_group.transfer_ids[1];

    update public.money_transfers
    set net_amount_to_pay = v_group_total,
        revision_no = revision_no + 1,
        updated_at = pg_catalog.now()
    where id = v_group.transfer_ids[1];

    perform pg_catalog.set_config(
      'app.money_transfer_delete_rpc',
      'true',
      true
    );

    update public.money_transfers
    set record_status = 'deleted',
        deleted_at = pg_catalog.now(),
        deleted_by_name = v_actor.name,
        deleted_by_phone = v_actor.phone,
        revision_no = revision_no + 1,
        updated_at = pg_catalog.now()
    where id = any(v_secondary_ids);

    v_merged_group_count := v_merged_group_count + 1;
    v_merged_transfer_count := v_merged_transfer_count
      + pg_catalog.array_length(v_group.transfer_ids, 1);
    v_deleted_transfer_count := v_deleted_transfer_count
      + pg_catalog.array_length(v_secondary_ids, 1);
    v_survivor_ids := pg_catalog.array_append(
      v_survivor_ids,
      v_group.transfer_ids[1]
    );
  end loop;

  return pg_catalog.jsonb_build_object(
    'mergedGroupCount', v_merged_group_count,
    'mergedTransferCount', v_merged_transfer_count,
    'deletedTransferCount', v_deleted_transfer_count,
    'skippedTransferCount', v_pending_count - v_merged_transfer_count,
    'survivorIds', pg_catalog.to_jsonb(v_survivor_ids)
  );
end;
$$;


ALTER FUNCTION "private"."merge_pending_money_transfers"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."money_transfer_ocr_fingerprint"("p_reference_number" "text", "p_amount" numeric, "p_transaction_date" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when nullif(pg_catalog.btrim(p_reference_number), '') is null
      or p_amount is null
      or p_transaction_date is null
    then null
    else pg_catalog.md5(
      pg_catalog.lower(
        pg_catalog.regexp_replace(pg_catalog.btrim(p_reference_number), '[^[:alnum:]]+', '', 'g')
      )
      || '|' || pg_catalog.round(p_amount, 2)::text
      || '|' || (extract(epoch from p_transaction_date) * 1000)::bigint::text
    )
  end
$$;


ALTER FUNCTION "private"."money_transfer_ocr_fingerprint"("p_reference_number" "text", "p_amount" numeric, "p_transaction_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."money_transfer_source_relations"("p_location_id" "uuid", "p_source_type" "text" DEFAULT NULL::"text") RETURNS TABLE("source_type" "text", "source_id" "uuid", "transfer_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select i.source_type, i.source_id, i.transfer_id
  from public.money_transfer_items i
  join public.money_transfers t on t.id = i.transfer_id
  where t.location_id = p_location_id
    and t.record_status <> 'deleted'
    and (p_source_type is null or i.source_type = p_source_type);
$$;


ALTER FUNCTION "private"."money_transfer_source_relations"("p_location_id" "uuid", "p_source_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."next_document_sequence"("p_document_kind" "text", "p_location_id" "uuid", "p_document_date" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sequence integer;
begin
  if p_document_kind not in ('RPT', 'REX', 'WEX')
     or p_location_id is null
     or p_document_date is null then
    raise exception 'Invalid document sequence request';
  end if;

  insert into private.document_number_counters (
    document_kind, location_id, document_date, last_sequence_no, updated_at
  )
  values (p_document_kind, p_location_id, p_document_date, 1, clock_timestamp())
  on conflict (document_kind, location_id, document_date)
  do update set
    last_sequence_no = private.document_number_counters.last_sequence_no + 1,
    updated_at = clock_timestamp()
  returning last_sequence_no into v_sequence;

  return v_sequence;
end;
$$;


ALTER FUNCTION "private"."next_document_sequence"("p_document_kind" "text", "p_location_id" "uuid", "p_document_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_income_sale_lines"("payload" "jsonb") RETURNS TABLE("income_sale_item_id" "uuid", "stock_product_id" "uuid", "title" "text", "quantity" numeric, "unit_price" numeric, "line_total" numeric, "sequence_no" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
  select
    item.id,
    item.stock_product_id,
    item.name,
    parsed.quantity,
    parsed.unit_price,
    round(parsed.quantity * parsed.unit_price, 2),
    parsed.sequence_no
  from (
    select
      nullif(line.value->>'incomeSaleItemId', '')::uuid as income_sale_item_id,
      nullif(line.value->>'quantity', '')::numeric as quantity,
      nullif(line.value->>'unitPrice', '')::numeric as unit_price,
      line.ordinality::integer as sequence_no
    from jsonb_array_elements(payload->'saleLines') with ordinality as line(value, ordinality)
  ) parsed
  join public.income_sale_items item
    on item.id = parsed.income_sale_item_id
   and item.is_active = true
   and item.stock_product_id is not null;
$$;


