CREATE OR REPLACE FUNCTION "private"."normalize_rubber_bill_calculation_payload"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_operation text := payload->>'operation';
  v_items jsonb := '[]'::jsonb;
  v_item jsonb;
  v_item_type text;
  v_in_weight numeric;
  v_out_weight numeric;
  v_row_weight numeric;
  v_price numeric;
  v_quantity numeric;
  v_line_value numeric;
  v_total_weight numeric := 0;
  v_total_weigh_value numeric := 0;
  v_money_deduction_raw numeric := 0;
  v_deduct_weight numeric;
  v_net_weight numeric;
  v_average_price numeric;
  v_net_rubber_value numeric;
  v_deduction_total numeric;
  v_payable_before_rounding numeric;
  v_weigh_count integer := 0;
begin
  if v_operation not in ('create', 'update') then
    return payload;
  end if;

  if jsonb_typeof(payload->'items') <> 'array' then
    raise exception 'items must be an array';
  end if;

  v_deduct_weight := coalesce(nullif(payload->>'deductWeight', '')::numeric, 0);
  if v_deduct_weight < 0 or v_deduct_weight <> round(v_deduct_weight, 2) then
    raise exception 'deductWeight must be non-negative with at most 2 decimal places';
  end if;

  for v_item in
    select value from jsonb_array_elements(payload->'items')
  loop
    v_item_type := v_item->>'itemType';

    if v_item_type = 'weigh' then
      v_in_weight := nullif(v_item->>'inWeight', '')::numeric;
      v_out_weight := nullif(v_item->>'outWeight', '')::numeric;

      if v_in_weight is not null and v_out_weight is not null then
        if v_in_weight < 0 or v_out_weight < 0 then
          raise exception 'weigh-row weights must be non-negative';
        end if;
        if v_in_weight <> round(v_in_weight, 2)
           or v_out_weight <> round(v_out_weight, 2) then
          raise exception 'weigh-row weights must have at most 2 decimal places';
        end if;
        v_row_weight := v_in_weight - v_out_weight;
      else
        v_row_weight := nullif(v_item->>'netWeight', '')::numeric;
        if v_row_weight is null or v_row_weight <> round(v_row_weight, 2) then
          raise exception 'weigh-row net weight must have at most 2 decimal places';
        end if;
      end if;

      v_price := nullif(v_item->>'unitPrice', '')::numeric;
      if v_row_weight <= 0 then
        raise exception 'weigh-row net weight must be positive';
      end if;
      if v_price is null or v_price < 0 or v_price <> round(v_price, 2) then
        raise exception 'weigh-row price must be non-negative with at most 2 decimal places';
      end if;

      v_row_weight := round(v_row_weight, 2);
      v_line_value := floor(v_row_weight * v_price);
      v_total_weight := v_total_weight + v_row_weight;
      v_total_weigh_value := v_total_weigh_value + v_line_value;
      v_weigh_count := v_weigh_count + 1;
      v_item := v_item || jsonb_build_object(
        'netWeight', v_row_weight,
        'totalAmount', v_line_value
      );

    elsif v_item_type in ('acid', 'stock_deduction') then
      v_quantity := nullif(v_item->>'quantity', '')::numeric;
      v_price := nullif(v_item->>'unitPrice', '')::numeric;
      if v_quantity is null
         or v_quantity <= 0
         or v_quantity <> round(v_quantity, 2)
         or v_price is null
         or v_price < 0
         or v_price <> round(v_price, 2) then
        raise exception 'stock deductions must use non-negative values with at most 2 decimal places';
      end if;

      v_line_value := floor(v_quantity * v_price);
      v_money_deduction_raw := v_money_deduction_raw + v_line_value;
      v_item := v_item || jsonb_build_object(
        'totalAmount', v_line_value
      );

    elsif v_item_type = 'debt' then
      v_line_value := nullif(v_item->>'totalAmount', '')::numeric;
      if v_line_value is null
         or v_line_value < 0
         or v_line_value <> round(v_line_value, 2) then
        raise exception 'debt deductions must be non-negative with at most 2 decimal places';
      end if;
      v_money_deduction_raw := v_money_deduction_raw + v_line_value;
      v_item := v_item || jsonb_build_object(
        'totalAmount', round(v_line_value, 2)
      );
    end if;

    v_items := v_items || jsonb_build_array(v_item);
  end loop;

  if v_weigh_count = 0 or v_total_weight <= 0 then
    raise exception 'at least one positive weigh row is required';
  end if;
  if v_deduct_weight >= v_total_weight then
    raise exception 'deductWeight must be less than total weight';
  end if;

  v_total_weight := round(v_total_weight, 2);
  v_net_weight := trunc(v_total_weight - v_deduct_weight, 2);
  v_average_price := round(v_total_weigh_value / v_total_weight, 2);
  v_net_rubber_value := floor(
    v_total_weigh_value * v_net_weight / v_total_weight
  );
  v_deduction_total := round(v_money_deduction_raw, 2);
  v_payable_before_rounding := greatest(
    v_net_rubber_value - v_deduction_total,
    0
  );

  return payload || jsonb_build_object(
    'formulaVersion', 2,
    'items', v_items,
    'weight', v_total_weight,
    'netWeight', v_net_weight,
    'rubberValue', v_total_weigh_value,
    'netRubberValue', v_net_rubber_value,
    'averagePrice', v_average_price,
    'deductionTotal', v_deduction_total,
    'payableBeforeRounding', v_payable_before_rounding,
    'netTotal', floor(v_payable_before_rounding)
  );
end;
$$;


ALTER FUNCTION "private"."normalize_rubber_bill_calculation_payload"("payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."normalize_rubber_bill_calculation_payload"("payload" "jsonb") IS 'Recalculates Rubber Bill v2 values: floor calculated line values and rubber value to whole baht while preserving two-decimal input precision.';



CREATE OR REPLACE FUNCTION "private"."normalized_export_vehicle_weigh_lines"("p_location_id" "uuid", "p_lines" "jsonb") RETURNS TABLE("sequence_no" integer, "vehicle_registration" "text", "carrier_id" "uuid", "carrier_name" "text", "inbound_at" timestamp with time zone, "inbound_weight" numeric, "outbound_at" timestamp with time zone, "outbound_weight" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_count integer;
  v_unique_plates integer;
  v_shared_carrier_id uuid;
  v_shared_carrier_name text;
begin
  if coalesce(jsonb_typeof(p_lines), 'null') <> 'array' then
    raise exception 'WEX_INVALID_LINES: ต้องมีรายการชั่งรถ 1–2 คัน';
  end if;
  if jsonb_array_length(p_lines) not between 1 and 2 then
    raise exception 'WEX_INVALID_LINES: ต้องมีรายการชั่งรถ 1–2 คัน';
  end if;
  if p_location_id is null then
    raise exception 'WEX_INVALID_LINES: สาขาของรายการชั่งรถไม่ถูกต้อง';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_lines) line(value)
    where (line.value ? 'carrierId'
        and jsonb_typeof(line.value->'carrierId') not in ('string', 'null'))
      or (line.value ? 'carrierName'
        and jsonb_typeof(line.value->'carrierName') not in ('string', 'null'))
      or jsonb_typeof(line.value->'inboundAt') <> 'string'
      or jsonb_typeof(line.value->'inboundWeight') <> 'number'
      or jsonb_typeof(line.value->'outboundWeight') <> 'number'
      or (
        line.value ? 'outboundAt'
        and jsonb_typeof(line.value->'outboundAt') not in ('string', 'null')
      )
  ) then
    raise exception 'WEX_INVALID_LINES: รูปแบบเวลา น้ำหนัก ทะเบียนรถ หรือผู้ขนส่งไม่ถูกต้อง';
  end if;

  with parsed as (
    select regexp_replace(btrim(line.value->>'vehicleRegistration'), '\s+', ' ', 'g') as registration
    from jsonb_array_elements(p_lines) line(value)
  )
  select count(*), count(distinct lower(registration))
  into v_count, v_unique_plates
  from parsed
  where nullif(registration, '') is not null and char_length(registration) <= 64;

  if v_count <> jsonb_array_length(p_lines) or v_unique_plates <> v_count then
    raise exception 'WEX_INVALID_LINES: ทะเบียนรถไม่ถูกต้องหรือซ้ำกัน';
  end if;

  v_shared_carrier_id := nullif(btrim(p_lines->0->>'carrierId'), '')::uuid;
  if v_shared_carrier_id is not null then
    select s.id, s.main_name
    into v_shared_carrier_id, v_shared_carrier_name
    from public.transport_staffs s
    where s.id = v_shared_carrier_id
      and s.record_status = 'active'
      and (s.default_location_id is null or s.default_location_id = p_location_id)
    for share of s;

    if not found then
      raise exception 'WEX_CARRIER_INELIGIBLE: เลือกได้เฉพาะผู้ขนส่งที่ใช้งานอยู่และมีสิทธิ์ในสาขานี้';
    end if;
  else
    v_shared_carrier_name := nullif(
      regexp_replace(btrim(p_lines->0->>'carrierName'), '\s+', ' ', 'g'),
      ''
    );
  end if;

  return query
  select
    line.ordinality::integer,
    regexp_replace(btrim(line.value->>'vehicleRegistration'), '\s+', ' ', 'g'),
    v_shared_carrier_id,
    v_shared_carrier_name,
    (line.value->>'inboundAt')::timestamptz,
    round((line.value->>'inboundWeight')::numeric, 2),
    case
      when round((line.value->>'outboundWeight')::numeric, 2) = 0 then null
      else nullif(btrim(line.value->>'outboundAt'), '')::timestamptz
    end,
    round((line.value->>'outboundWeight')::numeric, 2)
  from jsonb_array_elements(p_lines) with ordinality as line(value, ordinality)
  where round((line.value->>'inboundWeight')::numeric, 2) > 0
    and round((line.value->>'outboundWeight')::numeric, 2) >= 0
    and (
      (
        round((line.value->>'outboundWeight')::numeric, 2) = 0
        and nullif(btrim(line.value->>'outboundAt'), '') is null
      )
      or (
        round((line.value->>'outboundWeight')::numeric, 2)
          > round((line.value->>'inboundWeight')::numeric, 2)
        and nullif(btrim(line.value->>'outboundAt'), '')::timestamptz
          > (line.value->>'inboundAt')::timestamptz
      )
    )
  order by line.ordinality;

  get diagnostics v_count = row_count;
  if v_count <> jsonb_array_length(p_lines) then
    raise exception 'WEX_INVALID_LINES: น้ำหนักออกต้องเป็น 0 ระหว่างรอ หรือมากกว่าน้ำหนักเข้าเมื่อชั่งออกแล้ว';
  end if;
exception
  when invalid_text_representation or datetime_field_overflow or numeric_value_out_of_range then
    raise exception 'WEX_INVALID_LINES: รูปแบบเวลา น้ำหนัก หรือทะเบียนรถไม่ถูกต้อง';
end;
$$;


ALTER FUNCTION "private"."normalized_export_vehicle_weigh_lines"("p_location_id" "uuid", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."preflight_income_sale_stock"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_location_id uuid := nullif(payload->>'locationId', '')::uuid;
  v_existing public.income_expense%rowtype;
  v_product record;
  v_current_balance numeric;
  v_old_quantity numeric;
  v_new_quantity numeric;
  v_available numeric;
  v_shortages jsonb := '[]'::jsonb;
begin
  select * into v_existing
  from public.income_expense
  where client_temp_id = payload->>'clientTempId';

  -- An already-committed retry must return the original bill, even if stock has
  -- changed since that commit.
  if v_existing.id is not null
     and v_existing.idempotency_key = payload->>'idempotencyKey' then
    return jsonb_build_object('status', 'ok');
  end if;

  for v_product in
    select products.product_id, product.name
    from (
      select distinct line.stock_product_id as product_id
      from private.normalize_income_sale_lines(payload) line
      union
      select distinct line.stock_product_id
      from public.income_expense_sale_lines line
      where line.income_expense_id = v_existing.id
    ) products
    join public.stock_products product on product.id = products.product_id
    order by products.product_id
  loop
    perform pg_advisory_xact_lock(
      hashtext('acid-stock:' || v_location_id::text || ':' || v_product.product_id::text)
    );

    v_current_balance := public.get_stock_balance(v_location_id, v_product.product_id);
    select coalesce(sum(quantity), 0) into v_old_quantity
    from public.income_expense_sale_lines
    where income_expense_id = v_existing.id
      and stock_product_id = v_product.product_id;
    select coalesce(sum(quantity), 0) into v_new_quantity
    from private.normalize_income_sale_lines(payload)
    where stock_product_id = v_product.product_id;

    v_available := v_current_balance + v_old_quantity;
    if v_new_quantity > v_available then
      v_shortages := v_shortages || jsonb_build_array(jsonb_build_object(
        'productId', v_product.product_id,
        'productName', v_product.name,
        'requestedQuantity', v_new_quantity,
        'availableQuantity', greatest(v_available, 0)
      ));
    end if;
  end loop;

  if jsonb_array_length(v_shortages) > 0 then
    return jsonb_build_object(
      'status', 'failed',
      'errorCode', 'STOCK_SHORTAGE',
      'errorMessage', 'สินค้าในสต็อกไม่พอสำหรับบิลขาย',
      'stockShortages', v_shortages
    );
  end if;

  return jsonb_build_object('status', 'ok');
exception when others then
  return jsonb_build_object('status', 'failed', 'errorMessage', sqlerrm);
end;
$$;


ALTER FUNCTION "private"."preflight_income_sale_stock"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."prevent_hard_delete_of_linked_time_tracking_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
begin
  if current_setting('app.time_tracking_permanent_delete_rpc', true) = 'true' then
    return old;
  end if;

  if tg_table_name = 'financial_transactions' then
    if old.type = 'WITHDRAWAL'
      and old.status = 'APPROVED'
      and old.expense_location_id is not null then
      raise exception 'Approved withdrawal must be permanently deleted through the time tracking RPC';
    end if;
  elsif tg_table_name = 'payroll_slips' then
    if old.status = 'APPROVED'
      and old.net_pay > 0
      and old.expense_location_id is not null then
      raise exception 'Approved payroll slip must be permanently deleted through the time tracking RPC';
    end if;
  end if;

  return old;
end;
$$;


ALTER FUNCTION "private"."prevent_hard_delete_of_linked_time_tracking_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."prevent_location_code_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.code is distinct from new.code then
    raise exception 'BRANCH_CODE_IMMUTABLE'
      using errcode = 'P0001';
  end if;
  return new;
end;
$$;


