CREATE OR REPLACE FUNCTION "private"."raise_report_lock"("p_report_no" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
begin
  raise exception 'REPORT_LOCKED:%', p_report_no
    using errcode = 'P0001',
          hint = 'ลบรายงาน active ล่าสุดตามลำดับเพื่อปลดล็อก';
end;
$$;


ALTER FUNCTION "private"."raise_report_lock"("p_report_no" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rebuild_active_report_balance_chain"("p_location_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_report record;
  v_previous_report_id uuid;
  v_running_balance numeric := 0;
  v_period_balance numeric;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text, 0));

  for v_report in
    select b.id
    from public.report_batches b
    where b.location_id = p_location_id
      and b.status = 'active'
    order by b.created_at, b.id
  loop
    select coalesce(sum(
      case when r.entry_type = 'income' then r.amount else -r.amount end
    ), 0)
    into v_period_balance
    from private.report_income_expense_period_rows(v_report.id) r;

    update public.report_batches
    set previous_report_id = v_previous_report_id,
        opening_balance = v_running_balance,
        closing_balance = v_running_balance + v_period_balance
    where id = v_report.id;

    v_previous_report_id := v_report.id;
    v_running_balance := v_running_balance + v_period_balance;
  end loop;
end;
$$;


ALTER FUNCTION "private"."rebuild_active_report_balance_chain"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rebuild_dashboard_branch"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  branch_id uuid;
  claim_version bigint;
begin
  select snapshot.location_id, snapshot.claimed_version
  into branch_id, claim_version
  from public.dashboard_branch_snapshots snapshot
  join public.locations l
    on l.id = snapshot.location_id
   and l.is_active = true
  where snapshot.status = 'running'
  order by snapshot.claimed_at, snapshot.location_id
  limit 1;

  if branch_id is null then
    return null;
  end if;

  return private.rebuild_dashboard_branch_target(branch_id, claim_version);
end;
$$;


ALTER FUNCTION "private"."rebuild_dashboard_branch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rebuild_dashboard_branch_target"("p_location_id" "uuid", "p_claimed_version" bigint) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  next_summary jsonb;
begin
  if p_location_id is null or p_claimed_version is null then
    return null;
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtext('lanflow-dashboard-rebuild'),
    pg_catalog.hashtext(p_location_id::text)
  ) then
    return null;
  end if;

  if not exists (
    select 1
    from public.dashboard_branch_snapshots snapshot
    join public.locations l
      on l.id = snapshot.location_id
     and l.is_active = true
    where snapshot.location_id = p_location_id
      and snapshot.status = 'running'
      and snapshot.claimed_version = p_claimed_version
  ) then
    return null;
  end if;

  begin
    next_summary := private.calculate_dashboard_summary(p_location_id);

    update public.dashboard_branch_snapshots
    set summary = next_summary,
        calculated_at = now(),
        snapshot_version = p_claimed_version,
        status = case
          when source_version = p_claimed_version then 'ready'
          else 'dirty'
        end,
        claimed_version = null,
        claimed_at = null,
        manual_requested_at = null,
        last_error = null,
        updated_at = now()
    where location_id = p_location_id
      and status = 'running'
      and claimed_version = p_claimed_version;
  exception when others then
    update public.dashboard_branch_snapshots
    set status = 'failed',
        claimed_version = null,
        claimed_at = null,
        last_error = 'คำนวณ Dashboard ไม่สำเร็จ',
        updated_at = now()
    where location_id = p_location_id
      and status = 'running'
      and claimed_version = p_claimed_version;
  end;

  return p_location_id;
end;
$$;


ALTER FUNCTION "private"."rebuild_dashboard_branch_target"("p_location_id" "uuid", "p_claimed_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rebuild_rubber_bill_evidence_projection"("p_location_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_count bigint;
begin
  delete from private.rubber_bill_evidence_projection where location_id = p_location_id;
  perform private.refresh_rubber_bill_evidence_projection(array(
    select b.id from public.rubber_bills b
    where b.location_id = p_location_id and b.record_status = 'active'
  ));
  select count(*) into v_count from private.rubber_bill_evidence_projection where location_id = p_location_id;
  return v_count;
end;
$$;


ALTER FUNCTION "private"."rebuild_rubber_bill_evidence_projection"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."reconcile_dashboard_money_source"("p_source_type" "text", "p_source_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_actor_name" "text" DEFAULT NULL::"text", "p_emit_events" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old_entries jsonb;
  v_new_entries jsonb := private.dashboard_money_source_entries(p_source_type, p_source_id);
  v_old jsonb;
  v_new jsonb;
begin
  perform pg_advisory_xact_lock(
    hashtextextended('dashboard-money-history:' || p_source_type || ':' || p_source_id::text, 0)
  );

  select coalesce(jsonb_agg(payload order by event_key), '[]'::jsonb)
  into v_old_entries
  from private.dashboard_money_event_projection
  where source_type = p_source_type
    and source_id = p_source_id;

  if p_emit_events then
    for v_old in select value from jsonb_array_elements(v_old_entries)
    loop
      select value into v_new
      from jsonb_array_elements(v_new_entries)
      where value->>'eventKey' = v_old->>'eventKey'
      limit 1;

      if v_new is null then
        perform private.append_dashboard_money_event(
          p_source_type, p_source_id, 'delete', v_old,
          p_actor_user_id, p_actor_name
        );
      elsif v_new->>'fingerprint' is distinct from v_old->>'fingerprint' then
        perform private.append_dashboard_money_event(
          p_source_type, p_source_id, 'update', v_new,
          p_actor_user_id, p_actor_name
        );
      end if;
      v_new := null;
    end loop;

    for v_new in select value from jsonb_array_elements(v_new_entries)
    loop
      if not exists (
        select 1
        from jsonb_array_elements(v_old_entries) old_entry
        where old_entry->>'eventKey' = v_new->>'eventKey'
      ) then
        perform private.append_dashboard_money_event(
          p_source_type, p_source_id, 'create', v_new,
          p_actor_user_id, p_actor_name
        );
      end if;
    end loop;
  end if;

  delete from private.dashboard_money_event_projection
  where source_type = p_source_type
    and source_id = p_source_id;

  insert into private.dashboard_money_event_projection (
    source_type, source_id, event_key, payload
  )
  select p_source_type, p_source_id, value->>'eventKey', value
  from jsonb_array_elements(v_new_entries);
end;
$$;


ALTER FUNCTION "private"."reconcile_dashboard_money_source"("p_source_type" "text", "p_source_id" "uuid", "p_actor_user_id" "uuid", "p_actor_name" "text", "p_emit_events" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."refresh_rubber_bill_evidence_projection"("p_bill_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_bill_ids uuid[] := array(select distinct id from unnest(coalesce(p_bill_ids, array[]::uuid[])) id where id is not null);
begin
  if cardinality(v_bill_ids) = 0 then return; end if;

  delete from private.rubber_bill_evidence_projection p
  where p.bill_id = any(v_bill_ids)
    and not exists (
      select 1 from public.rubber_bills b
      where b.id = p.bill_id and b.record_status = 'active'
    );

  insert into private.rubber_bill_evidence_projection (
    bill_id, location_id, revision_no, client_created_at, review_period_id,
    review_status, missing_rubber, missing_display_in, has_manual_correction,
    is_unpriced, has_any_evidence, required_role_count, present_required_role_count,
    decision, reviewed_by_name, reviewed_at, refreshed_at
  )
  select s.bill_id, s.location_id, s.revision_no, s.client_created_at, s.review_period_id,
    s.review_status, s.missing_rubber, s.missing_display_in, s.has_manual_correction,
    s.is_unpriced, s.has_any_evidence, s.required_role_count, s.present_required_role_count,
    s.decision, s.reviewed_by_name, s.reviewed_at, now()
  from public.rubber_bills b
  cross join lateral private.rubber_bill_evidence_review_states_for_bills(b.location_id, array[b.id]) s
  where b.id = any(v_bill_ids) and b.record_status = 'active'
  on conflict (bill_id) do update set
    location_id = excluded.location_id,
    revision_no = excluded.revision_no,
    client_created_at = excluded.client_created_at,
    review_period_id = excluded.review_period_id,
    review_status = excluded.review_status,
    missing_rubber = excluded.missing_rubber,
    missing_display_in = excluded.missing_display_in,
    has_manual_correction = excluded.has_manual_correction,
    is_unpriced = excluded.is_unpriced,
    has_any_evidence = excluded.has_any_evidence,
    required_role_count = excluded.required_role_count,
    present_required_role_count = excluded.present_required_role_count,
    decision = excluded.decision,
    reviewed_by_name = excluded.reviewed_by_name,
    reviewed_at = excluded.reviewed_at,
    refreshed_at = excluded.refreshed_at;
end;
$$;


ALTER FUNCTION "private"."refresh_rubber_bill_evidence_projection"("p_bill_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."refresh_rubber_evidence_from_bills"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.refresh_rubber_bill_evidence_projection(array[coalesce(new.id, old.id)]);
  return coalesce(new, old);
end; $$;


