CREATE OR REPLACE FUNCTION "private"."reserve_rubber_bill_ocr_source"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation text := p_payload->>'operation';
  v_input_method text := coalesce(nullif(p_payload->>'inputMethod', ''), 'manual');
  v_upload_id uuid;
  v_location_id uuid;
  v_client_temp_id text := p_payload->>'clientTempId';
  v_idempotency_key text := p_payload->>'idempotencyKey';
  v_source public.rubber_bill_ocr_sources%rowtype;
begin
  if p_payload ?| array['ocrSourceId', 'ocrImageSha256', 'driveFileId', 'driveUrl'] then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'ไม่รับข้อมูลอ้างอิง OCR ภายในจากอุปกรณ์');
  end if;
  if v_operation <> 'create' then
    if p_payload ? 'ocrUploadId' then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'รูป OCR ใช้ได้เฉพาะตอนสร้างบิลยาง');
    end if;
    return jsonb_build_object('status', 'ok');
  end if;
  if v_input_method not in ('manual', 'ocr') then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'วิธีเพิ่มบิลยางไม่ถูกต้อง');
  end if;
  if v_input_method = 'manual' then
    if p_payload ? 'ocrUploadId' then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'บิลยางที่เพิ่มเองห้ามใช้รูป OCR');
    end if;
    return jsonb_build_object('status', 'ok');
  end if;

  begin
    v_upload_id := (p_payload->>'ocrUploadId')::uuid;
    v_location_id := (p_payload->>'locationId')::uuid;
  exception when others then
    return jsonb_build_object('status', 'conflict', 'errorMessage', 'ข้อมูลอ้างอิงรูป OCR ไม่ถูกต้อง');
  end;
  if v_upload_id is null
     or nullif(btrim(v_client_temp_id), '') is null
     or nullif(btrim(v_idempotency_key), '') is null then
    return jsonb_build_object('status', 'conflict', 'errorMessage', 'ข้อมูลอ้างอิงรูป OCR ไม่ถูกต้อง');
  end if;

  select * into v_source
  from public.rubber_bill_ocr_sources s
  where s.id = v_upload_id
  for update;
  if v_source.id is null
     or v_source.owner_user_id <> auth.uid()
     or v_source.location_id <> v_location_id then
    return jsonb_build_object('status', 'conflict', 'errorMessage', 'ข้อมูลอ้างอิงรูป OCR ไม่ตรงกับคำขอ');
  end if;
  if v_source.state = 'abandoned' then
    return jsonb_build_object('status', 'conflict', 'errorMessage', 'รูป OCR นี้ถูกยกเลิกแล้ว');
  end if;
  if v_source.state in ('reserved', 'attached') then
    if v_source.reserved_client_temp_id is distinct from v_client_temp_id
       or v_source.reserved_idempotency_key is distinct from v_idempotency_key then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'รูป OCR นี้ถูกจองโดยคำขออื่น');
    end if;
    return jsonb_build_object('status', 'ok');
  end if;

  update public.rubber_bill_ocr_sources
  set state = 'reserved',
      reserved_client_temp_id = v_client_temp_id,
      reserved_idempotency_key = v_idempotency_key,
      reserved_at = now(),
      updated_at = now()
  where id = v_upload_id;
  return jsonb_build_object('status', 'ok');
end
$$;


ALTER FUNCTION "private"."reserve_rubber_bill_ocr_source"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rubber_bill_current_work_items"("p_location_id" "uuid") RETURNS TABLE("location_id" "uuid", "work_kind" "text", "work_identity" "text", "bill_id" "uuid", "sort_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    b.location_id,
    'unpriced'::text,
    'bill:' || b.id::text,
    b.id,
    coalesce(b.client_created_at, b.created_at)
  from public.rubber_bills b
  where b.location_id = p_location_id
    and b.record_status = 'active'
    and exists (
      select 1
      from public.rubber_bill_items i
      where i.bill_id = b.id
        and i.item_type = 'weigh'
        and coalesce(i.price, 0) <= 0
    )

  union all

  select
    r.location_id,
    'pending_approval'::text,
    case
      when r.bill_id is not null then 'bill:' || r.bill_id::text
      else 'approval:' || r.id::text
    end,
    r.bill_id,
    r.requested_at
  from public.rubber_bill_approval_requests r
  where r.location_id = p_location_id
    and r.request_status = 'pending';
$$;


ALTER FUNCTION "private"."rubber_bill_current_work_items"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rubber_bill_evidence_pending_snapshot"("p_location_id" "uuid") RETURNS TABLE("item_count" bigint, "item_fingerprint" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    count(*)::bigint,
    md5(coalesce(string_agg(
      concat(s.bill_id::text, ':', s.revision_no::text),
      ',' order by s.bill_id, s.revision_no
    ), ''))
  from private.rubber_bill_evidence_review_states(p_location_id) s
  where s.review_status = 'pending'
$$;


ALTER FUNCTION "private"."rubber_bill_evidence_pending_snapshot"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rubber_bill_evidence_projection_drift"("p_location_id" "uuid") RETURNS TABLE("bill_id" "uuid", "drift_kind" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with canonical as (
    select * from private.rubber_bill_evidence_review_states(p_location_id)
  ), projected as (
    select * from private.rubber_bill_evidence_projection p where p.location_id = p_location_id
  )
  select coalesce(c.bill_id, p.bill_id),
    case when c.bill_id is null then 'projection_only'
      when p.bill_id is null then 'canonical_only'
      else 'mismatch' end
  from canonical c
  full join projected p using (bill_id)
  where c.bill_id is null or p.bill_id is null
    or row(c.location_id, c.revision_no, c.client_created_at, c.review_period_id,
      c.review_status, c.missing_rubber, c.missing_display_in, c.has_manual_correction,
      c.is_unpriced, c.has_any_evidence, c.required_role_count,
      c.present_required_role_count, c.decision, c.reviewed_by_name, c.reviewed_at)
      is distinct from
      row(p.location_id, p.revision_no, p.client_created_at, p.review_period_id,
      p.review_status, p.missing_rubber, p.missing_display_in, p.has_manual_correction,
      p.is_unpriced, p.has_any_evidence, p.required_role_count,
      p.present_required_role_count, p.decision, p.reviewed_by_name, p.reviewed_at);
$$;


ALTER FUNCTION "private"."rubber_bill_evidence_projection_drift"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rubber_bill_evidence_review_states"("p_location_id" "uuid") RETURNS TABLE("location_id" "uuid", "bill_id" "uuid", "revision_no" integer, "client_created_at" timestamp with time zone, "review_period_id" "uuid", "review_status" "text", "missing_rubber" boolean, "missing_display_in" boolean, "has_manual_correction" boolean, "is_unpriced" boolean, "has_any_evidence" boolean, "required_role_count" bigint, "present_required_role_count" bigint, "decision" "text", "reviewed_by_name" "text", "reviewed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with bill_rows as (
    select
      b.id bill_id,
      b.location_id,
      b.revision_no,
      b.client_created_at,
      b.bill_type,
      b.source_rubber_export_id,
      b.evidence_manual_correction_count,
      count(distinct i.id) filter (where i.item_type = 'weigh')::bigint weigh_row_count,
      bool_or(coalesce(i.price, 0) <= 0) filter (where i.item_type = 'weigh') is_unpriced,
      count(f.bill_item_id) filter (
        where i.item_type = 'weigh' and f.role in ('rubber', 'displayIn')
      )::bigint present_required_role_count,
      count(f.bill_item_id) filter (
        where i.item_type = 'weigh' and f.role = 'rubber'
      )::bigint present_rubber_count,
      count(f.bill_item_id) filter (
        where i.item_type = 'weigh' and f.role = 'displayIn'
      )::bigint present_display_in_count,
      bool_or(f.bill_item_id is not null) has_any_evidence
    from public.rubber_bills b
    left join public.rubber_bill_items i on i.bill_id = b.id
    left join public.rubber_bill_item_evidence_files f
      on f.bill_item_id = i.id
     and f.revision_no = b.revision_no
    where b.location_id = p_location_id
      and b.record_status = 'active'
    group by b.id
  ), scoped as (
    select
      b.*,
      p.id review_period_id,
      r.decision,
      r.reviewed_by_name,
      r.reviewed_at,
      (b.weigh_row_count * 2)::bigint required_role_count
    from bill_rows b
    left join lateral (
      select period.id
      from public.rubber_bill_evidence_review_periods period
      where period.location_id = b.location_id
        and b.client_created_at is not null
        and b.client_created_at >= period.opened_at
        and (period.closed_at is null or b.client_created_at < period.closed_at)
      order by period.opened_at desc
      limit 1
    ) p on true
    left join public.rubber_bill_evidence_reviews r
      on r.bill_id = b.bill_id and r.revision_no = b.revision_no
  )
  select
    s.location_id,
    s.bill_id,
    s.revision_no,
    s.client_created_at,
    case
      when s.bill_type in ('weighing', 'บิลเครื่องชั่งเล็ก')
       and s.source_rubber_export_id is null
       and s.weigh_row_count > 0
      then s.review_period_id
      else null
    end,
    case
      when s.bill_type not in ('weighing', 'บิลเครื่องชั่งเล็ก')
        or s.source_rubber_export_id is not null
        or s.weigh_row_count = 0
        or s.client_created_at is null
        or s.review_period_id is null then 'outside'
      when s.decision is not null then s.decision
      when s.present_required_role_count < s.required_role_count
        or s.evidence_manual_correction_count > 0 then 'pending'
      else 'normal'
    end,
    s.weigh_row_count > s.present_rubber_count,
    s.weigh_row_count > s.present_display_in_count,
    s.evidence_manual_correction_count > 0,
    coalesce(s.is_unpriced, false),
    coalesce(s.has_any_evidence, false),
    s.required_role_count,
    s.present_required_role_count,
    s.decision,
    s.reviewed_by_name,
    s.reviewed_at
  from scoped s
$$;


ALTER FUNCTION "private"."rubber_bill_evidence_review_states"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rubber_bill_evidence_review_states_for_bills"("p_location_id" "uuid", "p_bill_ids" "uuid"[]) RETURNS TABLE("location_id" "uuid", "bill_id" "uuid", "revision_no" integer, "client_created_at" timestamp with time zone, "review_period_id" "uuid", "review_status" "text", "missing_rubber" boolean, "missing_display_in" boolean, "has_manual_correction" boolean, "is_unpriced" boolean, "has_any_evidence" boolean, "required_role_count" bigint, "present_required_role_count" bigint, "decision" "text", "reviewed_by_name" "text", "reviewed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with bill_rows as (
    select
      b.id bill_id, b.location_id, b.revision_no, b.client_created_at, b.bill_type,
      b.source_rubber_export_id, b.evidence_manual_correction_count,
      count(distinct i.id) filter (where i.item_type = 'weigh')::bigint weigh_row_count,
      bool_or(coalesce(i.price, 0) <= 0) filter (where i.item_type = 'weigh') is_unpriced,
      count(f.bill_item_id) filter (where i.item_type = 'weigh' and f.role in ('rubber', 'displayIn'))::bigint present_required_role_count,
      count(f.bill_item_id) filter (where i.item_type = 'weigh' and f.role = 'rubber')::bigint present_rubber_count,
      count(f.bill_item_id) filter (where i.item_type = 'weigh' and f.role = 'displayIn')::bigint present_display_in_count,
      bool_or(f.bill_item_id is not null) has_any_evidence
    from public.rubber_bills b
    left join public.rubber_bill_items i on i.bill_id = b.id
    left join public.rubber_bill_item_evidence_files f
      on f.bill_item_id = i.id and f.revision_no = b.revision_no
    where b.location_id = p_location_id
      and b.record_status = 'active'
      and b.id = any(coalesce(p_bill_ids, array[]::uuid[]))
    group by b.id
  ), scoped as (
    select b.*, p.id review_period_id, r.decision, r.reviewed_by_name, r.reviewed_at,
      (b.weigh_row_count * 2)::bigint required_role_count
    from bill_rows b
    left join lateral (
      select period.id
      from public.rubber_bill_evidence_review_periods period
      where period.location_id = b.location_id
        and b.client_created_at is not null
        and b.client_created_at >= period.opened_at
        and (period.closed_at is null or b.client_created_at < period.closed_at)
      order by period.opened_at desc
      limit 1
    ) p on true
    left join public.rubber_bill_evidence_reviews r
      on r.bill_id = b.bill_id and r.revision_no = b.revision_no
  )
  select
    s.location_id, s.bill_id, s.revision_no, s.client_created_at,
    case when s.bill_type in ('weighing', 'บิลเครื่องชั่งเล็ก')
      and s.source_rubber_export_id is null and s.weigh_row_count > 0 then s.review_period_id end,
    case
      when s.bill_type not in ('weighing', 'บิลเครื่องชั่งเล็ก')
        or s.source_rubber_export_id is not null or s.weigh_row_count = 0
        or s.client_created_at is null or s.review_period_id is null then 'outside'
      when s.decision is not null then s.decision
      when s.present_required_role_count < s.required_role_count
        or s.evidence_manual_correction_count > 0 then 'pending'
      else 'normal'
    end,
    s.weigh_row_count > s.present_rubber_count,
    s.weigh_row_count > s.present_display_in_count,
    s.evidence_manual_correction_count > 0,
    coalesce(s.is_unpriced, false), coalesce(s.has_any_evidence, false),
    s.required_role_count, s.present_required_role_count,
    s.decision, s.reviewed_by_name, s.reviewed_at
  from scoped s;
$$;


ALTER FUNCTION "private"."rubber_bill_evidence_review_states_for_bills"("p_location_id" "uuid", "p_bill_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rubber_bill_has_active_transfer"("p_bill_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
  select exists (
    select 1
    from public.money_transfer_items i
    join public.money_transfers t on t.id = i.transfer_id
    where i.source_type = 'rubber_bill'
      and i.source_id = p_bill_id
      and t.record_status <> 'deleted'
  );
$$;


