CREATE OR REPLACE FUNCTION "private"."validate_rubber_approval_group_input"("p_location_ids" "uuid"[], "p_edit_window_minutes" integer, "p_configured_price" numeric) RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_location_ids uuid[];
begin
  select coalesce(array_agg(distinct location_id order by location_id), array[]::uuid[])
    into v_location_ids
  from unnest(coalesce(p_location_ids, array[]::uuid[])) location_id
  where location_id is not null;

  if cardinality(v_location_ids) = 0 then
    raise exception 'RUBBER_GROUP_EMPTY: กลุ่มต้องมีอย่างน้อยหนึ่งสาขา';
  end if;
  if p_edit_window_minutes is null or p_edit_window_minutes < 0 then
    raise exception 'RUBBER_GROUP_INVALID: จำนวนนาทีต้องเป็นจำนวนเต็มตั้งแต่ 0 ขึ้นไป';
  end if;
  if p_configured_price is not null
     and (p_configured_price < 0 or scale(p_configured_price) > 2) then
    raise exception 'RUBBER_GROUP_INVALID: ราคายางต้องไม่ติดลบและมีทศนิยมไม่เกิน 2 ตำแหน่ง';
  end if;
  if exists (
    select 1 from unnest(v_location_ids) requested(location_id)
    left join public.locations l on l.id = requested.location_id and l.is_active = true
    where l.id is null
  ) then
    raise exception 'RUBBER_LOCATION_NOT_FOUND: ไม่พบสาขาที่ใช้งาน';
  end if;
  return v_location_ids;
end
$$;


ALTER FUNCTION "private"."validate_rubber_approval_group_input"("p_location_ids" "uuid"[], "p_edit_window_minutes" integer, "p_configured_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_rubber_export_selection"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.validate_rubber_export_selection(
    p_location_id, p_selected_report_item_ids, null::uuid
  );
$$;


ALTER FUNCTION "private"."validate_rubber_export_selection"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_rubber_export_selection"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[], "p_current_export_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_selected_count integer;
  v_candidate_count integer;
  v_invalid text;
begin
  v_selected_count := coalesce(cardinality(p_selected_report_item_ids), 0);
  if v_selected_count = 0 then
    raise exception 'RUBBER_EXPORT_SELECTION_EMPTY: กรุณาเลือกบิลอย่างน้อย 1 ใบ'
      using errcode = 'P0001';
  end if;
  if (select count(distinct selected_id) from unnest(p_selected_report_item_ids) selected_id)
    <> v_selected_count then
    raise exception 'RUBBER_EXPORT_SELECTION_DUPLICATE: พบบิลที่เลือกซ้ำ'
      using errcode = 'P0001';
  end if;

  select count(*)::integer into v_candidate_count
  from private.rubber_export_candidates(
    p_location_id, p_selected_report_item_ids, p_current_export_id
  );
  if v_candidate_count <> v_selected_count then
    raise exception 'RUBBER_EXPORT_SELECTION_STALE: บิลที่เลือกบางรายการไม่พร้อมส่งออกแล้ว'
      using errcode = 'P0001', hint = 'รีเฟรชรายการบิลแล้วเลือกใหม่';
  end if;

  select string_agg(c.bill_no, ', ' order by c.eligibility_at, c.bill_id)
  into v_invalid
  from private.rubber_export_candidates(
    p_location_id, p_selected_report_item_ids, p_current_export_id
  ) c
  where c.net_weight is null or c.net_weight <= 0
    or c.paid_amount is null or c.paid_amount < 0
    or c.rubber_value_amount is null or c.rubber_value_amount <= 0;
  if v_invalid is not null then
    raise exception 'INVALID_RUBBER_BILL:%', v_invalid
      using errcode = 'P0001', hint = 'น้ำหนักสุทธิและมูลค่ายางต้องมากกว่า 0 และยอดจ่ายจริงต้องไม่ติดลบ';
  end if;

  select string_agg(c.bill_no, ', ' order by c.eligibility_at, c.bill_id)
  into v_invalid
  from private.rubber_export_candidates(
    p_location_id, p_selected_report_item_ids, p_current_export_id
  ) c
  where c.bill_date > (clock_timestamp() at time zone 'Asia/Bangkok')::date;
  if v_invalid is not null then
    raise exception 'RUBBER_EXPORT_FUTURE_BILL:%', v_invalid
      using errcode = 'P0001', hint = 'วันที่บิลต้องไม่เกินวันที่ปัจจุบันตามประเทศไทย';
  end if;
end;
$$;


ALTER FUNCTION "private"."validate_rubber_export_selection"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[], "p_current_export_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_wex_rubber_exports"("p_location_id" "uuid", "p_wex_id" "uuid", "p_rubber_export_ids" "uuid"[]) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ids uuid[] := coalesce(p_rubber_export_ids, array[]::uuid[]);
  v_count integer;
  v_weight numeric(14,2);
begin
  if exists (select 1 from unnest(v_ids) as selected(id) where selected.id is null)
     or (select count(*) from unnest(v_ids))
       <> (select count(distinct selected.id) from unnest(v_ids) as selected(id)) then
    raise exception 'WEX_INVALID_REX: รายการขายยางห้ามว่างหรือซ้ำกัน';
  end if;

  perform e.id
  from public.rubber_exports e
  where e.id = any(v_ids)
  order by e.id
  for update;

  select count(*), coalesce(round(sum(e.current_weight), 2), 0)
  into v_count, v_weight
  from public.rubber_exports e
  where e.id = any(v_ids)
    and e.location_id = p_location_id
    and e.status = 'verified'
    and e.sold_out_at is not null
    and e.current_weight is not null
    and e.current_weight > 0;

  if v_count <> cardinality(v_ids) then
    raise exception 'WEX_REX_INELIGIBLE: เลือกได้เฉพาะรายการขายยางที่ตรวจสอบแล้ว ขายออกแล้ว และอยู่สาขาเดียวกัน';
  end if;

  if exists (
    select 1
    from public.export_vehicle_weigh_bill_reservations r
    where r.rubber_export_id = any(v_ids)
      and (p_wex_id is null or r.wex_id <> p_wex_id)
  ) then
    raise exception 'WEX_REX_RESERVED: มีรายการขายยางถูกจองในบิลรถส่งออกอื่นแล้ว';
  end if;

  return v_weight;
end;
$$;


ALTER FUNCTION "private"."validate_wex_rubber_exports"("p_location_id" "uuid", "p_wex_id" "uuid", "p_rubber_export_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_exception_attendance"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_active bigint;
  v_resume bigint;
  v_job record;
  v_today date := (now() at time zone 'Asia/Bangkok')::date;
begin
  if v_actor is null or not private.is_global_time_payroll_manager() then raise exception 'Forbidden'; end if;
  select count(*) into v_active from public.time_segments where end_time is null;
  select count(*) into v_resume from public.time_tracking_resume_schedules;
  if v_active > 0 or v_resume > 0 then raise exception 'ACTIVATION_BLOCKED:active=%:resume=%', v_active, v_resume; end if;
  update public.time_payroll_settings set mode = 'EXCEPTIONS', activated_on = coalesce(activated_on, v_today), updated_by = v_actor, updated_at = now() where singleton = true;
  for v_job in select jobid from cron.job where jobname in ('time-tracking-daily-cutoff', 'deduct-debts-daily', 'time-tracking-auto-start') loop
    perform cron.unschedule(v_job.jobid);
  end loop;
  insert into public.time_tracking_audit_logs(admin_id, action, target_table, record_id, new_data, comment)
  values (v_actor, 'ACTIVATE_EXCEPTION_ATTENDANCE', 'time_payroll_settings', v_actor,
    jsonb_build_object('activatedOn', v_today), 'เปิดใช้วันทำงานแบบข้อยกเว้น');
  return public.get_time_payroll_settings();
end
$$;


ALTER FUNCTION "public"."activate_exception_attendance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_rubber_bill_approval_request"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_request public.rubber_bill_approval_requests%rowtype;
  v_result jsonb;
  v_actor_name text;
  v_actor_phone text;
  v_created_bill_id uuid;
  v_report_no text;
begin
  if not private.is_active_user() or not public.can_access_super_admin_features() then
    raise exception 'ไม่มีสิทธิ์อนุมัติคำขอบิลยาง';
  end if;

  select *
    into v_request
  from public.rubber_bill_approval_requests
  where id = p_request_id
  for update;

  if v_request.id is null or v_request.request_status <> 'pending' then
    raise exception 'ไม่พบคำขอที่รออนุมัติ';
  end if;

  if v_request.bill_id is not null then
    perform pg_advisory_xact_lock(hashtext('rubber-bill-approval:' || v_request.bill_id::text));
    v_report_no := private.active_report_no('rubber_bill', v_request.bill_id);
    if v_report_no is not null then
      raise exception 'บิลอยู่ในรายงาน % แล้ว จึงอนุมัติไม่ได้', v_report_no;
    end if;
    if private.rubber_bill_has_active_transfer(v_request.bill_id) then
      raise exception 'บิลอยู่ในรายการโอนเงินแล้ว จึงอนุมัติไม่ได้';
    end if;
  else
    perform pg_advisory_xact_lock(hashtext('rubber-bill-create:' || v_request.client_temp_id));
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_request.location_id::text, 0));

  if v_request.operation = 'create'
     and v_request.proposed_payload->>'inputMethod' = 'ocr' then
    perform 1
    from public.rubber_bill_ocr_sources s
    where s.id = nullif(v_request.proposed_payload->>'ocrUploadId', '')::uuid
      and s.owner_user_id = v_request.requested_by_user_id
      and s.location_id = v_request.location_id
      and s.reserved_client_temp_id = v_request.client_temp_id
      and s.reserved_idempotency_key = v_request.idempotency_key
      and s.state = 'reserved'
    for update;
    if not found then
      raise exception 'ข้อมูลอ้างอิงรูป OCR ไม่ตรงกับคำขออนุมัติ';
    end if;
  end if;

  v_result := public.sync_rubber_bill_core_20260725010000(v_request.proposed_payload);
  if v_result->>'status' <> 'synced' then
    raise exception '%', coalesce(v_result->>'errorMessage', 'อนุมัติคำขอไม่สำเร็จ');
  end if;

  v_created_bill_id := (v_result->>'id')::uuid;

  select name, phone into v_actor_name, v_actor_phone
  from public.profiles where id = auth.uid();

  update public.rubber_bills
  set created_by_user_id = case
        when v_request.operation = 'create' then v_request.requested_by_user_id
        else created_by_user_id
      end,
      created_by_name = case
        when v_request.operation = 'create' then v_request.requested_by_name
        else created_by_name
      end,
      created_by_phone = case
        when v_request.operation = 'create' then v_request.requested_by_phone
        else created_by_phone
      end,
      approval_state = 'approved',
      approved_by_name = coalesce(v_actor_name, ''),
      approval_revision_no = revision_no
  where id = v_created_bill_id;

  update public.rubber_bill_approval_requests
  set request_status = 'approved',
      approved_by_user_id = auth.uid(),
      approved_by_name = coalesce(v_actor_name, ''),
      approved_by_phone = coalesce(v_actor_phone, ''),
      approved_at = now(),
      created_bill_id = case when operation = 'create' then v_created_bill_id else null end
  where id = p_request_id;

  return jsonb_build_object(
    'status', 'approved',
    'requestId', p_request_id,
    'operation', v_request.operation,
    'billId', v_created_bill_id,
    'syncResult', v_result
  );
end;
$$;


ALTER FUNCTION "public"."approve_rubber_bill_approval_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_admin_password_reset"("p_target_user_id" "uuid", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_target public.profiles%rowtype;
  v_audit public.admin_account_audit_logs%rowtype;
begin
  if v_actor_id is null or not private.is_active_user()
     or not private.can_access_super_admin_features() then
    raise exception 'FORBIDDEN: ไม่มีสิทธิ์รีเซ็ตรหัสผ่าน';
  end if;
  if p_target_user_id is null or p_request_id is null
     or p_target_user_id = v_actor_id then
    raise exception 'FORBIDDEN: ไม่สามารถรีเซ็ตรหัสผ่านบัญชีนี้ได้';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('admin-password:' || p_request_id::text, 0));
  select * into v_audit
  from public.admin_account_audit_logs a
  where a.request_id = p_request_id;
  if v_audit.id is not null then
    if v_audit.action <> 'password_reset'
       or v_audit.actor_user_id <> v_actor_id
       or v_audit.target_user_id <> p_target_user_id then
      raise exception 'ADMIN_REQUEST_CONFLICT: requestId ถูกใช้กับคำสั่งอื่นแล้ว';
    end if;
    return jsonb_build_object(
      'auditId', v_audit.id,
      'status', v_audit.status,
      'created', false
    );
  end if;

  select * into v_target from public.profiles p where p.id = p_target_user_id;
  if v_target.id is null then
    raise exception 'ADMIN_USER_NOT_FOUND: ไม่พบบัญชีพนักงาน';
  end if;
  if v_target.role = 'super_admin' or not v_target.is_active then
    raise exception 'FORBIDDEN: บัญชีนี้ไม่สามารถรีเซ็ตรหัสผ่านได้';
  end if;

  insert into public.admin_account_audit_logs (
    request_id, actor_user_id, target_user_id, action, status
  ) values (
    p_request_id, v_actor_id, p_target_user_id, 'password_reset', 'pending'
  ) returning * into v_audit;

  return jsonb_build_object(
    'auditId', v_audit.id,
    'status', v_audit.status,
    'created', true
  );
end
$$;


ALTER FUNCTION "public"."begin_admin_password_reset"("p_target_user_id" "uuid", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_paid_work_days"("p_profile_id" "uuid", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
