CREATE OR REPLACE FUNCTION "public"."claim_weight_evidence_completion"("p_bill_id" "uuid", "p_location_id" "uuid", "p_revision_no" integer, "p_completion_id" "uuid", "p_manual_correction_count" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_bill public.rubber_bills%rowtype;
  v_weigh_row_count integer;
begin
  if not private.is_active_user() or not public.can_access_location(p_location_id) then
    raise exception 'WEIGHT_EVIDENCE_ACCESS_DENIED';
  end if;
  if p_bill_id is null or p_completion_id is null
    or p_revision_no is null or p_revision_no < 0
    or p_manual_correction_count is null or p_manual_correction_count < 0 then
    raise exception 'WEIGHT_EVIDENCE_INVALID_INPUT';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text, 0));
  select * into v_bill from public.rubber_bills
  where id = p_bill_id and location_id = p_location_id for update;
  if not found or v_bill.record_status <> 'active' or v_bill.source_rubber_export_id is not null then
    return jsonb_build_object('state', 'inactive');
  end if;
  if v_bill.revision_no <> p_revision_no then
    return jsonb_build_object('state', 'stale', 'currentRevisionNo', v_bill.revision_no);
  end if;
  select count(*)::integer into v_weigh_row_count
  from public.rubber_bill_items where bill_id = p_bill_id and item_type = 'weigh';
  if v_weigh_row_count = 0 or p_manual_correction_count > v_weigh_row_count * 2 then
    raise exception 'WEIGHT_EVIDENCE_INVALID_COUNT';
  end if;
  if v_bill.evidence_completion_id is null then
    update public.rubber_bills
    set evidence_completion_id = p_completion_id,
        evidence_manual_correction_count = p_manual_correction_count,
        updated_at = now()
    where id = p_bill_id;
    return jsonb_build_object('state', 'owned', 'currentRevisionNo', v_bill.revision_no);
  end if;
  if v_bill.evidence_completion_id = p_completion_id then
    return jsonb_build_object('state', 'owned', 'currentRevisionNo', v_bill.revision_no);
  end if;
  return jsonb_build_object('state', 'owned_by_other', 'currentRevisionNo', v_bill.revision_no);
end;
$$;


ALTER FUNCTION "public"."claim_weight_evidence_completion"("p_bill_id" "uuid", "p_location_id" "uuid", "p_revision_no" integer, "p_completion_id" "uuid", "p_manual_correction_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_rubber_bill_evidence_review_period"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor public.profiles%rowtype;
  v_period_id uuid;
  v_count bigint;
  v_fingerprint text;
begin
  perform private.require_rubber_bill_evidence_review_manager(p_location_id);
  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text, 0));
  select id into v_period_id
  from public.rubber_bill_evidence_review_periods
  where location_id = p_location_id and closed_at is null
  for update;
  if v_period_id is null then return jsonb_build_object('state', 'already_closed'); end if;
  select item_count, item_fingerprint into v_count, v_fingerprint
  from private.rubber_bill_evidence_pending_snapshot(p_location_id);
  if v_count > 0 then
    return jsonb_build_object(
      'state', 'blocked', 'pendingCount', v_count, 'pendingFingerprint', v_fingerprint
    );
  end if;
  select * into strict v_actor from public.profiles where id = auth.uid() and is_active = true;
  update public.rubber_bill_evidence_review_periods
  set closed_at = now(), closed_by_user_id = auth.uid(), closed_by_name = v_actor.name
  where id = v_period_id;
  return jsonb_build_object('state', 'closed', 'periodId', v_period_id);
end;
$$;


ALTER FUNCTION "public"."close_rubber_bill_evidence_review_period"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_admin_password_reset"("p_audit_id" "uuid", "p_status" "text", "p_error_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_audit public.admin_account_audit_logs%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'FORBIDDEN: service role required';
  end if;
  if p_status not in ('succeeded', 'failed', 'unknown') then
    raise exception 'ADMIN_AUDIT_INVALID: สถานะผลลัพธ์ไม่ถูกต้อง';
  end if;
  if p_status = 'succeeded' and p_error_code is not null then
    raise exception 'ADMIN_AUDIT_INVALID: ผลสำเร็จต้องไม่มี error code';
  end if;
  if p_status in ('failed', 'unknown')
     and nullif(btrim(coalesce(p_error_code, '')), '') is null then
    raise exception 'ADMIN_AUDIT_INVALID: ผลล้มเหลวต้องมี error code';
  end if;

  select * into v_audit
  from public.admin_account_audit_logs a
  where a.id = p_audit_id and a.action = 'password_reset'
  for update;
  if v_audit.id is null then
    raise exception 'ADMIN_AUDIT_NOT_FOUND: ไม่พบหลักฐานคำสั่ง';
  end if;
  if v_audit.status = 'pending' then
    update public.admin_account_audit_logs
    set status = p_status,
        error_code = case when p_status = 'succeeded' then null else left(p_error_code, 80) end,
        completed_at = now()
    where id = p_audit_id
    returning * into v_audit;
  end if;
  return jsonb_build_object('auditId', v_audit.id, 'status', v_audit.status);
end
$$;


ALTER FUNCTION "public"."complete_admin_password_reset"("p_audit_id" "uuid", "p_status" "text", "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_telegram_badge_dispatch"("p_claim_token" "uuid", "p_outcome" "text", "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  settings public.telegram_badge_settings%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role required';
  end if;
  if p_outcome not in ('sent', 'no_items', 'failed') then
    raise exception 'ผลการส่งไม่ถูกต้อง';
  end if;

  select * into strict settings
  from public.telegram_badge_settings
  where id = true
  for update;

  if settings.claim_token is distinct from p_claim_token then
    raise exception 'claim ไม่ตรงหรือหมดอายุ';
  end if;

  update public.telegram_badge_settings
  set last_completed_slot_at = case
        when p_outcome in ('sent', 'no_items') then pending_slot_at
        else last_completed_slot_at
      end,
      last_success_at = case
        when p_outcome = 'sent' then now()
        else last_success_at
      end,
      last_error = case
        when p_outcome = 'failed' then left(coalesce(p_error, 'ส่ง Telegram ไม่สำเร็จ'), 500)
        else null
      end,
      retry_at = case
        when p_outcome = 'failed' then now() + interval '10 minutes'
        else null
      end,
      pending_slot_at = case
        when p_outcome = 'failed' then pending_slot_at
        else null
      end,
      claim_token = null,
      claimed_at = null,
      updated_at = now()
  where id = true;
end;
$$;


ALTER FUNCTION "public"."complete_telegram_badge_dispatch"("p_claim_token" "uuid", "p_outcome" "text", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_telegram_evidence_dispatch"("p_claim_token" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.role() <> 'service_role' then raise exception 'service_role required'; end if;

  update public.telegram_badge_settings
  set evidence_claim_token = null,
      evidence_claimed_at = null,
      updated_at = now()
  where id = true and evidence_claim_token = p_claim_token;

  if not found then raise exception 'claim ไม่ตรงหรือหมดอายุ'; end if;
end;
$$;


ALTER FUNCTION "public"."complete_telegram_evidence_dispatch"("p_claim_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."configure_telegram_badge_dispatcher"("p_edge_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  settings public.telegram_badge_settings%rowtype;
  normalized_url text := nullif(btrim(p_edge_url), '');
  dispatch_secret text;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service_role required';
  end if;
  if normalized_url is null or normalized_url !~ '^https?://' then
    raise exception 'Edge Function URL ไม่ถูกต้อง';
  end if;

  select * into strict settings
  from public.telegram_badge_settings
  where id = true
  for update;

  if settings.edge_url_secret_id is null then
    settings.edge_url_secret_id := vault.create_secret(
      normalized_url,
      'lanflow_telegram_badge_edge_url',
      'Telegram badge Edge Function URL'
    );
  else
    perform vault.update_secret(
      settings.edge_url_secret_id,
      normalized_url,
      'lanflow_telegram_badge_edge_url',
      'Telegram badge Edge Function URL'
    );
  end if;

  if settings.dispatch_secret_id is null then
    dispatch_secret := encode(extensions.gen_random_bytes(32), 'hex');
    settings.dispatch_secret_id := vault.create_secret(
      dispatch_secret,
      'lanflow_telegram_badge_dispatch_secret',
      'Internal secret used by pg_cron to invoke the badge Edge Function'
    );
  end if;

  update public.telegram_badge_settings
  set edge_url_secret_id = settings.edge_url_secret_id,
      dispatch_secret_id = settings.dispatch_secret_id,
      updated_at = now()
  where id = true;
end;
$$;


ALTER FUNCTION "public"."configure_telegram_badge_dispatcher"("p_edge_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_cash_branch_transfer"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  actor_id uuid := auth.uid(); actor_name text; actor_phone text;
  source_id uuid := (payload->>'sourceLocationId')::uuid;
  target_id uuid := (payload->>'targetLocationId')::uuid;
  target_name text; counts integer[]; new_transfer_id uuid := coalesce((payload->>'id')::uuid, gen_random_uuid());
  existing_transfer_id uuid;
begin
  if not private.is_active_user() or not private.can_access_location(source_id) then raise exception 'ไม่มีสิทธิ์สร้างรายการสำหรับสาขานี้'; end if;
  if source_id is null or target_id is null or source_id = target_id then raise exception 'สาขาปลายทางต้องต่างจากสาขาต้นทาง'; end if;
  select id into existing_transfer_id
  from public.money_transfers
  where idempotency_key = coalesce(payload->>'idempotencyKey', 'cash:' || new_transfer_id::text)
    and transfer_method = 'cash'
    and location_id = source_id
    and created_by_user_id = actor_id;
  if existing_transfer_id is not null then return jsonb_build_object('id', existing_transfer_id, 'status', 'synced'); end if;
  select name, phone into actor_name, actor_phone from public.profiles where id = actor_id;
  select name into target_name from public.locations where id = target_id and is_active = true;
  if target_name is null then raise exception 'ไม่พบสาขาปลายทางที่ใช้งาน'; end if;
  counts := private.cash_transfer_counts(payload, 'sent');
  insert into public.money_transfers (id, client_temp_id, idempotency_key, location_id, target_location_id, target_location_name, net_amount_to_pay, transfer_type, transfer_method, transfer_status, created_by_user_id, created_by_name, created_by_phone, revision_no, record_status)
  values (new_transfer_id, coalesce(payload->>'clientTempId', new_transfer_id::text), coalesce(payload->>'idempotencyKey', 'cash:' || new_transfer_id::text), source_id, target_id, target_name, 0, 'cash', 'cash', 'pending', actor_id, coalesce(actor_name, ''), coalesce(actor_phone, ''), 0, 'active');
  insert into public.money_transfer_cash_details (transfer_id, sent_coin_1_count, sent_coin_2_count, sent_coin_5_count, sent_coin_10_count, sent_banknote_20_count, sent_banknote_50_count, sent_banknote_100_count, sent_banknote_500_count, sent_banknote_1000_count, note)
  values (new_transfer_id, counts[1], counts[2], counts[3], counts[4], counts[5], counts[6], counts[7], counts[8], counts[9], nullif(btrim(payload->>'note'), ''));
  update public.money_transfers set net_amount_to_pay = d.sent_total, updated_at = now() from public.money_transfer_cash_details d where money_transfers.id = new_transfer_id and d.transfer_id = new_transfer_id;
  return jsonb_build_object('id', new_transfer_id, 'status', 'synced');
end;
$$;


ALTER FUNCTION "public"."create_cash_branch_transfer"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_export_vehicle_weigh_bill"("p_location_id" "uuid", "p_lines" "jsonb", "p_rubber_export_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor public.profiles%rowtype;
  v_now timestamptz := clock_timestamp();
  v_wex_date date;
  v_sequence_no integer;
  v_wex_no text;
  v_wex_id uuid;
  v_vehicle_net numeric(14,2);
  v_rubber_weight numeric(14,2);
begin
  if p_location_id is null or not private.can_manage_reports(p_location_id)
     or not exists (
       select 1 from public.locations l
       where l.id = p_location_id and l.is_active = true
     ) then
    raise exception 'WEX_FORBIDDEN: ไม่มีสิทธิ์สร้างบิลรถส่งออกของสาขานี้';
  end if;

  perform 1 from private.normalized_export_vehicle_weigh_lines(p_location_id, p_lines);
  v_rubber_weight := private.validate_wex_rubber_exports(
    p_location_id, null, p_rubber_export_ids
  );

  select * into v_actor
  from public.profiles p
  where p.id = auth.uid() and p.is_active = true;
  if v_actor.id is null then
    raise exception 'WEX_FORBIDDEN: บัญชีผู้ใช้ไม่พร้อมใช้งาน';
  end if;

  v_wex_date := (v_now at time zone 'Asia/Bangkok')::date;
  perform pg_advisory_xact_lock(hashtextextended(
    'export-vehicle-weigh-bill:' || p_location_id::text || ':' || v_wex_date::text, 0
  ));
  v_sequence_no := private.next_document_sequence('WEX', p_location_id, v_wex_date);
  v_wex_no := 'WEX-' || to_char(v_wex_date, 'YYYYMMDD') || '-'
    || lpad(v_sequence_no::text, 3, '0');

  insert into public.export_vehicle_weigh_bills (
    wex_no, wex_date, sequence_no, location_id, revision,
    created_by_user_id, created_by_name, created_at,
    updated_by_user_id, updated_by_name, updated_at
  ) values (
    v_wex_no, v_wex_date, v_sequence_no, p_location_id, 1,
    v_actor.id, v_actor.name, v_now,
    v_actor.id, v_actor.name, v_now
  ) returning id into v_wex_id;

  insert into public.export_vehicle_weigh_lines (
    wex_id, sequence_no, vehicle_registration, carrier_id, carrier_name,
    inbound_at, inbound_weight, outbound_at, outbound_weight
  )
  select
    v_wex_id, l.sequence_no, l.vehicle_registration, l.carrier_id, l.carrier_name,
    l.inbound_at, l.inbound_weight, l.outbound_at, l.outbound_weight
  from private.normalized_export_vehicle_weigh_lines(p_location_id, p_lines) l;

  select round(sum(l.net_weight), 2)
  into v_vehicle_net
  from public.export_vehicle_weigh_lines l
  where l.wex_id = v_wex_id;

  if v_rubber_weight > v_vehicle_net then
    raise exception 'WEX_OVERWEIGHT: น้ำหนักรายการขายยางรวมเกินน้ำหนักสุทธิรถ';
  end if;

  insert into public.export_vehicle_weigh_bill_reservations (
    wex_id, rubber_export_id, sequence_no, export_no, current_weight, created_at
  )
  select
    v_wex_id, e.id, selected.ordinality::integer, e.export_no, e.current_weight, v_now
  from unnest(coalesce(p_rubber_export_ids, array[]::uuid[]))
    with ordinality as selected(id, ordinality)
  join public.rubber_exports e on e.id = selected.id
  order by selected.ordinality;

  return jsonb_build_object('id', v_wex_id, 'wexNo', v_wex_no, 'revision', 1);
exception
  when unique_violation then
    raise exception 'WEX_REX_RESERVED: มีรายการขายยางถูกจองในบิลรถส่งออกอื่นแล้ว';
end;
$$;


ALTER FUNCTION "public"."create_export_vehicle_weigh_bill"("p_location_id" "uuid", "p_lines" "jsonb", "p_rubber_export_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_income_expense_approval_request"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_location_id uuid := nullif(payload->>'locationId', '')::uuid;
begin
  if payload->>'billOption' = 'บิลขาย'
     and payload->>'operation' in ('create', 'update') then
    if not coalesce(private.is_active_user(), false) then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'Unauthorized or inactive user');
    end if;
    if v_location_id is null
       or not exists (select 1 from public.locations where id = v_location_id)
       or not public.can_access_location(v_location_id) then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'Location access denied');
    end if;
    return jsonb_build_object('status', 'no_approval');
  end if;

  return private.create_income_expense_approval_request_20260805080000(payload);
exception when others then
  return jsonb_build_object('status', 'failed', 'errorMessage', sqlerrm);
end;
$$;


ALTER FUNCTION "public"."create_income_expense_approval_request"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_report_batch"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_cutoff_at timestamptz := clock_timestamp();
begin
  if p_location_id is null or not private.can_manage_reports(p_location_id) then
    raise exception 'ไม่มีสิทธิ์สร้างรายงานของสาขานี้';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text, 0));
  if exists (
    select 1 from public.cash_count_sessions s
    where s.location_id = p_location_id and s.status = 'active' and s.expires_at > v_cutoff_at
  ) then
    raise exception 'CASH_COUNT_ACTIVE: มีการตรวจนับเงินสดของสาขานี้อยู่ กรุณารอให้ส่งผล ยกเลิก หรือหมดเวลา';
  end if;
  return private.create_report_batch_at(p_location_id, v_cutoff_at, auth.uid());
end;
$$;


ALTER FUNCTION "public"."create_report_batch"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_rubber_approval_group"("p_location_ids" "uuid"[], "p_edit_window_minutes" integer, "p_configured_price" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_location_ids uuid[];
  v_group public.rubber_approval_groups%rowtype;
  v_actor public.profiles%rowtype;
begin
  if not private.is_active_user() or not private.can_access_super_admin_features() then
    raise exception 'FORBIDDEN: ไม่มีสิทธิ์จัดการกลุ่มอนุมัติบิลยาง';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('rubber-approval-groups', 0));
  v_location_ids := private.validate_rubber_approval_group_input(
    p_location_ids, p_edit_window_minutes, p_configured_price
  );
  if exists (
    select 1 from public.rubber_approval_group_locations gl
    where gl.location_id = any(v_location_ids)
  ) then
    raise exception 'RUBBER_GROUP_BRANCH_CONFLICT: มีสาขาอยู่ในกลุ่มอื่นแล้ว';
  end if;

  select * into v_actor from public.profiles p where p.id = auth.uid();
  insert into public.rubber_approval_groups (
    edit_window_minutes, configured_price,
    updated_by_user_id, updated_by_name, updated_by_phone
  ) values (
    p_edit_window_minutes, p_configured_price,
    auth.uid(), v_actor.name, v_actor.phone
  ) returning * into v_group;

  insert into public.rubber_approval_group_locations (group_id, location_id)
  select v_group.id, location_id from unnest(v_location_ids) location_id;

  return jsonb_build_object(
    'id', v_group.id,
    'locationIds', to_jsonb(v_location_ids),
    'editWindowMinutes', v_group.edit_window_minutes,
    'configuredPrice', v_group.configured_price,
    'updatedAt', v_group.updated_at
  );
exception when unique_violation then
  raise exception 'RUBBER_GROUP_BRANCH_CONFLICT: มีสาขาอยู่ในกลุ่มอื่นแล้ว';
end
$$;


ALTER FUNCTION "public"."create_rubber_approval_group"("p_location_ids" "uuid"[], "p_edit_window_minutes" integer, "p_configured_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_rubber_export"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid(); v_actor_name text; v_actor_phone text;
  v_now timestamptz := clock_timestamp(); v_export_date date; v_sequence_no integer;
  v_export_no text; v_export_id uuid; v_item_count integer;
  v_original_weight numeric; v_paid_total numeric; v_rubber_value_total numeric;
begin
  if p_location_id is null or not private.can_manage_reports(p_location_id) then
    raise exception 'ไม่มีสิทธิ์สร้างรายการส่งออกของสาขานี้';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('rubber-export:' || p_location_id::text, 0));
  perform private.validate_rubber_export_selection(p_location_id, p_selected_report_item_ids);
  select count(*)::integer, round(sum(c.net_weight), 2), round(sum(c.paid_amount), 2),
    round(sum(c.rubber_value_amount), 2)
  into v_item_count, v_original_weight, v_paid_total, v_rubber_value_total
  from private.rubber_export_candidates(p_location_id, p_selected_report_item_ids) c;
  if coalesce(v_item_count, 0) = 0 then raise exception 'ไม่มีบิลที่พร้อมสร้างรายการส่งออก'; end if;
  select p.name, p.phone into v_actor_name, v_actor_phone from public.profiles p where p.id = v_actor_id;
  v_export_date := (v_now at time zone 'Asia/Bangkok')::date;
  v_sequence_no := private.next_document_sequence('REX', p_location_id, v_export_date);
  v_export_no := 'REX-' || to_char(v_export_date, 'YYYYMMDD') || '-' || lpad(v_sequence_no::text, 3, '0');
  insert into public.rubber_exports (
    export_no, export_date, sequence_no, location_id, original_weight_total,
    paid_total, rubber_value_total, average_price, created_by_user_id,
    created_by_name, created_by_phone, created_at
  ) values (
    v_export_no, v_export_date, v_sequence_no, p_location_id, v_original_weight,
    v_paid_total, v_rubber_value_total, round(v_rubber_value_total / v_original_weight, 2),
    v_actor_id, coalesce(v_actor_name, ''), coalesce(v_actor_phone, ''), v_now
  ) returning id into v_export_id;
  insert into public.rubber_export_items (
    export_id, location_id, source_report_item_id, source_bill_id, bill_date,
    bill_no, customer_name, eligibility_at, net_weight, paid_amount,
    rubber_value_amount, age_source_at, age_is_estimated, carried_age_hours
  )
  select v_export_id, p_location_id, c.report_item_id, c.bill_id, c.bill_date,
    c.bill_no, c.customer_name, c.eligibility_at, c.net_weight, c.paid_amount,
    c.rubber_value_amount,
    case when b.source_rubber_export_id is not null then b.received_at else coalesce(b.client_created_at, b.created_at) end,
    case when b.source_rubber_export_id is not null then b.received_age_is_estimated
      else b.client_created_at is null
        or (coalesce(b.client_created_at, b.created_at) at time zone 'Asia/Bangkok')::date <> c.bill_date end,
    case when b.source_rubber_export_id is not null then b.received_age_hours else null end
  from private.rubber_export_candidates(p_location_id, p_selected_report_item_ids) c
  join public.rubber_bills b on b.id = c.bill_id;
  get diagnostics v_item_count = row_count;
  return jsonb_build_object('id', v_export_id, 'exportNo', v_export_no, 'itemCount', v_item_count);
end;
$$;


ALTER FUNCTION "public"."create_rubber_export"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_stock_entry_delete_approval_request"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_active_user boolean;
  v_user_id uuid;
  v_user_name text;
  v_user_phone text;
  v_request_key text;
  v_entry_id uuid;
  v_entry public.stock_entries%rowtype;
  v_location_name text;
  v_target_entry public.stock_entries%rowtype;
  v_target_location_name text;
  v_existing_id uuid;
  v_existing_status text;
  v_request_id uuid;
begin
  v_active_user := private.is_active_user();
  if not coalesce(v_active_user, false) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Unauthorized or inactive user');
  end if;

  v_entry_id := nullif(payload->>'stockEntryId', '')::uuid;
  if v_entry_id is null then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'ไม่พบรายการสต็อก');
  end if;

  select *
    into v_entry
  from public.stock_entries
  where id = v_entry_id
  for update;

  if v_entry.id is null or v_entry.record_status != 'active' then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'ไม่พบรายการสต็อกที่ลบได้');
  end if;

  if v_entry.tx_type = 'transfer_in' then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'รายการย้ายสต็อกต้องลบจากฝั่งย้ายออกเท่านั้น');
  end if;

  if v_entry.tx_type not in ('receive', 'transfer_out') then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'ลบได้เฉพาะรายการรับเข้า หรือย้ายออก');
  end if;

  if not public.can_access_location(v_entry.location_id) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Location access denied');
  end if;

  select name into v_location_name
  from public.locations
  where id = v_entry.location_id;

  if v_entry.tx_type = 'transfer_out' then
    if v_entry.transfer_bill_no is null then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'รายการย้ายนี้ไม่สมบูรณ์');
    end if;

    select *
      into v_target_entry
    from public.stock_entries
    where transfer_bill_no = v_entry.transfer_bill_no
      and product_id = v_entry.product_id
      and tx_type = 'transfer_in'
      and record_status = 'active'
    limit 1;

    if v_target_entry.id is null then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'ไม่พบรายการย้ายเข้าคู่กัน');
    end if;

    select name into v_target_location_name
    from public.locations
    where id = v_target_entry.location_id;

    select id, request_status
      into v_existing_id, v_existing_status
    from public.stock_entry_approval_requests
    where request_status = 'pending'
      and transfer_bill_no = v_entry.transfer_bill_no
      and tx_type = 'transfer_out'
    limit 1;
  else
    select id, request_status
      into v_existing_id, v_existing_status
    from public.stock_entry_approval_requests
    where request_status = 'pending'
      and stock_entry_id = v_entry.id
    limit 1;
  end if;

  if v_existing_id is not null then
    return jsonb_build_object(
      'status', 'pending',
      'requestId', v_existing_id,
      'requestStatus', v_existing_status
    );
  end if;

  v_request_key := nullif(payload->>'requestIdempotencyKey', '');
  if v_request_key is null then
    v_request_key := gen_random_uuid()::text;
  end if;

  v_user_id := auth.uid();
  select name, phone into v_user_name, v_user_phone
  from public.profiles
  where id = v_user_id;

  insert into public.stock_entry_approval_requests (
    request_idempotency_key,
    requested_payload,
    stock_entry_id,
    transfer_bill_no,
    tx_type,
    product_id,
    product_name,
    quantity,
    location_id,
    location_name,
    target_location_id,
    target_location_name,
    requested_by_user_id,
    requested_by_name,
    requested_by_phone
  ) values (
    v_request_key,
    jsonb_build_object(
      'action', 'delete_stock_entry',
      'stockEntryId', v_entry.id,
      'transferBillNo', v_entry.transfer_bill_no
    ),
    v_entry.id,
    v_entry.transfer_bill_no,
    v_entry.tx_type,
    v_entry.product_id,
    v_entry.product_name,
    abs(v_entry.quantity_delta),
    v_entry.location_id,
    coalesce(v_location_name, ''),
    case when v_entry.tx_type = 'transfer_out' then v_target_entry.location_id else null end,
    case when v_entry.tx_type = 'transfer_out' then coalesce(v_target_location_name, '') else null end,
    v_user_id,
    coalesce(v_user_name, ''),
    coalesce(v_user_phone, '')
  )
  returning id into v_request_id;

  return jsonb_build_object(
    'status', 'pending',
    'requestId', v_request_id,
    'requestType', 'delete_stock_entry'
  );
exception when others then
  return jsonb_build_object('status', 'failed', 'errorMessage', sqlerrm);
end;
$$;


ALTER FUNCTION "public"."create_stock_entry_delete_approval_request"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_stock_product_approval_request"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_active_user boolean;
  v_user_id uuid;
  v_user_name text;
  v_user_phone text;
  v_request_type text;
  v_request_key text;
  v_name text;
  v_name_key text;
  v_unit text;
  v_create_sale_item boolean;
  v_product_id uuid;
  v_product public.stock_products%rowtype;
  v_existing_id uuid;
  v_existing_status text;
  v_request_id uuid;
  v_payload jsonb;
begin
  v_active_user := private.is_active_user();
  if not coalesce(v_active_user, false) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Unauthorized or inactive user');
  end if;

  v_request_type := payload->>'requestType';
  if v_request_type not in ('create_product', 'delete_product') then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Invalid stock product request type');
  end if;

  v_request_key := nullif(payload->>'requestIdempotencyKey', '');
  if v_request_key is null then
    v_request_key := gen_random_uuid()::text;
  end if;

  select id, request_status
    into v_existing_id, v_existing_status
  from public.stock_product_approval_requests
  where request_idempotency_key = v_request_key
  limit 1;

  if v_existing_id is not null then
    return jsonb_build_object(
      'status', 'pending',
      'requestId', v_existing_id,
      'requestStatus', v_existing_status
    );
  end if;

  v_user_id := auth.uid();
  select name, phone into v_user_name, v_user_phone
  from public.profiles
  where id = v_user_id;

  if v_request_type = 'create_product' then
    v_name := btrim(coalesce(payload->>'name', ''));
    v_name_key := lower(v_name);
    v_unit := nullif(btrim(coalesce(payload->>'unit', '')), '');
    v_create_sale_item := coalesce((payload->>'createSaleItem')::boolean, false);

    if v_name = '' then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'กรุณาระบุชื่อสินค้า');
    end if;

    if exists (
      select 1
      from public.stock_products
      where lower(btrim(name)) = v_name_key
    ) then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'มีสินค้านี้ในสต็อกแล้ว');
    end if;

    select id, request_status
      into v_existing_id, v_existing_status
    from public.stock_product_approval_requests
    where request_status = 'pending'
      and request_type = 'create_product'
      and lower(btrim(product_name)) = v_name_key
    limit 1;

    if v_existing_id is not null then
      return jsonb_build_object(
        'status', 'pending',
        'requestId', v_existing_id,
        'requestStatus', v_existing_status
      );
    end if;

    v_payload := jsonb_build_object(
      'action', 'create_product',
      'name', v_name,
      'unit', coalesce(v_unit, 'ชิ้น'),
      'createSaleItem', v_create_sale_item
    );
  else
    v_product_id := nullif(payload->>'productId', '')::uuid;
    if v_product_id is null then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'ไม่พบสินค้า');
    end if;

    select *
      into v_product
    from public.stock_products
    where id = v_product_id
    for update;

    if v_product.id is null or v_product.is_active is not true then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'ไม่พบสินค้าในสต็อก');
    end if;

    select id, request_status
      into v_existing_id, v_existing_status
    from public.stock_product_approval_requests
    where request_status = 'pending'
      and request_type = 'delete_product'
      and product_id = v_product_id
    limit 1;

    if v_existing_id is not null then
      return jsonb_build_object(
        'status', 'pending',
        'requestId', v_existing_id,
        'requestStatus', v_existing_status
      );
    end if;

    v_name := v_product.name;
    v_unit := v_product.unit;
    v_create_sale_item := null;
    v_payload := jsonb_build_object(
      'action', 'delete_product',
      'productId', v_product_id,
      'productName', v_product.name
    );
  end if;

  insert into public.stock_product_approval_requests (
    request_type,
    request_idempotency_key,
    requested_payload,
    product_id,
    product_name,
    unit,
    create_sale_item,
    requested_by_user_id,
    requested_by_name,
    requested_by_phone
  ) values (
    v_request_type,
    v_request_key,
    v_payload,
    v_product_id,
    v_name,
    v_unit,
    v_create_sale_item,
    v_user_id,
    coalesce(v_user_name, ''),
    coalesce(v_user_phone, '')
  )
  returning id into v_request_id;

  return jsonb_build_object(
    'status', 'pending',
    'requestId', v_request_id,
    'requestType', v_request_type
  );
exception when others then
  return jsonb_build_object('status', 'failed', 'errorMessage', sqlerrm);
end;
$$;


ALTER FUNCTION "public"."create_stock_product_approval_request"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_stock_product_with_sale_item"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_active_user boolean;
  v_created_by_user_id uuid;
  v_created_by_name text;
  v_created_by_phone text;
  v_name text;
  v_name_key text;
  v_unit text;
  v_create_sale_item boolean;
  v_product public.stock_products%rowtype;
  v_active_sale_item public.income_sale_items%rowtype;
  v_sale_item public.income_sale_items%rowtype;
begin
  v_active_user := private.is_active_user();
  if not coalesce(v_active_user, false) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Unauthorized or inactive user');
  end if;

  if not public.can_access_super_admin_features() then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'ไม่มีสิทธิ์เพิ่มสินค้า');
  end if;

  v_name := btrim(coalesce(payload->>'name', ''));
  v_name_key := lower(v_name);
  v_unit := nullif(btrim(coalesce(payload->>'unit', '')), '');
  v_create_sale_item := coalesce((payload->>'createSaleItem')::boolean, false);

  if v_name = '' then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'กรุณาระบุชื่อสินค้า');
  end if;

  perform pg_advisory_xact_lock(hashtext('stock-product:' || v_name_key));

  if exists (
    select 1
    from public.stock_products
    where lower(btrim(name)) = v_name_key
  ) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'มีสินค้านี้ในสต็อกแล้ว');
  end if;

  if v_create_sale_item then
    select *
      into v_active_sale_item
    from public.income_sale_items
    where lower(btrim(name)) = v_name_key
      and is_active = true
    order by created_at desc
    limit 1;

    if v_active_sale_item.id is not null
       and v_active_sale_item.stock_product_id is not null then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'รายการขายชื่อนี้ผูกกับสินค้าอื่นแล้ว');
    end if;
  end if;

  v_created_by_user_id := auth.uid();
  select name, phone into v_created_by_name, v_created_by_phone
  from public.profiles
  where id = v_created_by_user_id;

  insert into public.stock_products (
    name, unit, created_by_user_id, created_by_name, created_by_phone
  ) values (
    v_name,
    coalesce(v_unit, 'ชิ้น'),
    v_created_by_user_id,
    coalesce(v_created_by_name, ''),
    v_created_by_phone
  )
  returning * into v_product;

  if v_create_sale_item then
    if v_active_sale_item.id is not null then
      update public.income_sale_items
      set stock_product_id = v_product.id,
          updated_at = now()
      where id = v_active_sale_item.id
      returning * into v_sale_item;
    else
      select *
        into v_sale_item
      from public.income_sale_items
      where lower(btrim(name)) = v_name_key
        and is_active = false
      order by created_at desc
      limit 1;

      if v_sale_item.id is not null then
        update public.income_sale_items
        set stock_product_id = v_product.id,
            is_active = true,
            deleted_at = null,
            deleted_by_user_id = null,
            updated_at = now()
        where id = v_sale_item.id
        returning * into v_sale_item;
      else
        insert into public.income_sale_items (
          name, stock_product_id, created_by_user_id, created_by_name, created_by_phone
        ) values (
          v_product.name,
          v_product.id,
          v_created_by_user_id,
          coalesce(v_created_by_name, ''),
          v_created_by_phone
        )
        returning * into v_sale_item;
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'status', 'synced',
    'product', jsonb_build_object(
      'id', v_product.id,
      'name', v_product.name,
      'unit', v_product.unit,
      'is_active', v_product.is_active,
      'created_by_name', v_product.created_by_name,
      'created_by_phone', v_product.created_by_phone,
      'created_at', v_product.created_at
    ),
    'saleItem', case
      when v_sale_item.id is null then null
      else jsonb_build_object(
        'id', v_sale_item.id,
        'name', v_sale_item.name,
        'stock_product_id', v_sale_item.stock_product_id,
        'is_active', v_sale_item.is_active,
        'created_by_name', v_sale_item.created_by_name,
        'created_by_phone', v_sale_item.created_by_phone,
        'created_at', v_sale_item.created_at
      )
    end
  );
exception when others then
  return jsonb_build_object('status', 'failed', 'errorMessage', 'เพิ่มสินค้าไม่สำเร็จ: ' || sqlerrm);
end;
$$;


ALTER FUNCTION "public"."create_stock_product_with_sale_item"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_time_tracking_payroll_slip"("p_profile_id" "uuid", "p_month" "text", "p_auto_start_next_month" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_mode text;
  v_month date;
  v_scan_month date;
  v_first_active_month date;
  v_created jsonb;
  v_attendance jsonb;
  v_final jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended('time-payroll-attendance:' || p_profile_id::text, 0));
  select s.mode into v_mode from public.time_payroll_settings s where s.singleton = true for share;
  if v_mode = 'EXCEPTIONS' then
    if p_month !~ '^[0-9]{4}-[0-9]{2}$' then raise exception 'INVALID_MONTH'; end if;
    begin v_month := (p_month || '-01')::date; exception when others then raise exception 'INVALID_MONTH'; end;
    if to_char(v_month, 'YYYY-MM') <> p_month then raise exception 'INVALID_MONTH'; end if;
    select min(date_trunc('month', ap.start_on)::date)
      into v_first_active_month
    from public.time_payroll_active_periods ap
    where ap.profile_id = p_profile_id;
    if v_first_active_month is not null then
      for v_scan_month in
        select generate_series(
          v_first_active_month::timestamp,
          (v_month - interval '1 month')::timestamp,
          interval '1 month'
        )::date
      loop
        if not exists (
          select 1 from public.payroll_slips ps
          where ps.profile_id = p_profile_id and ps.month = to_char(v_scan_month, 'YYYY-MM')
        ) and public.calculate_paid_work_days(
          p_profile_id,
          v_scan_month::timestamp at time zone 'Asia/Bangkok',
          (v_scan_month + interval '1 month')::timestamp at time zone 'Asia/Bangkok'
        ) > 0 then
          raise exception 'OLDER_WORK_MONTH:%', to_char(v_scan_month, 'YYYY-MM');
        end if;
      end loop;
    end if;
  end if;
  v_created := public.create_time_tracking_payroll_slip_internal_20260829(
    p_profile_id, p_month, case when v_mode = 'EXCEPTIONS' then false else p_auto_start_next_month end
  );
  v_attendance := public.get_time_payroll_attendance_month(p_profile_id, p_month);
  update public.payroll_slips
  set slip_data = coalesce(slip_data, '{}'::jsonb) || jsonb_build_object('attendance', v_attendance)
  where id = (v_created ->> 'id')::uuid;
  if private.is_global_time_payroll_manager() then
    perform public.decide_time_tracking_approval('payroll_slip', (v_created ->> 'id')::uuid, 'APPROVED', null, null);
  end if;
  select to_jsonb(ps) into v_final from public.payroll_slips ps where ps.id = (v_created ->> 'id')::uuid;
  return v_final || jsonb_build_object('auto_start_scheduled', coalesce((v_created ->> 'auto_start_scheduled')::boolean, false));
end
$_$;


ALTER FUNCTION "public"."create_time_tracking_payroll_slip"("p_profile_id" "uuid", "p_month" "text", "p_auto_start_next_month" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_time_tracking_payroll_slip_internal_20260829"("p_profile_id" "uuid", "p_month" "text", "p_auto_start_next_month" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor_id uuid := auth.uid();
  v_month date;
  v_next_month date;
  v_current_month date := date_trunc(
    'month',
    (now() at time zone 'Asia/Bangkok')::date
  )::date;
  v_scan_month date;
  v_first_segment_month date;
  v_active_segment public.time_segments%rowtype;
  v_was_running boolean := false;
  v_daily_wage numeric;
  v_total_days numeric;
  v_gross numeric;
  v_deductions numeric;
  v_net numeric;
  v_segments jsonb;
  v_transactions jsonb;
  v_slip public.payroll_slips%rowtype;
  v_blocker record;
begin
  if v_actor_id is null or not private.can_approve_time_tracking_profile(p_profile_id) then
    raise exception 'Forbidden';
  end if;
  if p_month !~ '^[0-9]{4}-[0-9]{2}$' then
    raise exception 'INVALID_MONTH';
  end if;

  begin
    v_month := (p_month || '-01')::date;
  exception when others then
    raise exception 'INVALID_MONTH';
  end;
  if to_char(v_month, 'YYYY-MM') <> p_month or v_month > v_current_month then
    raise exception 'INVALID_MONTH';
  end if;
  v_next_month := (v_month + interval '1 month')::date;

  perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || p_profile_id::text, 0));

  if exists (
    select 1 from public.payroll_slips ps
    where ps.profile_id = p_profile_id and ps.month = p_month
  ) then
    raise exception 'MONTH_CLOSED:%', p_month;
  end if;

  select ft.id, ft.type::text type, ft.effective_date
  into v_blocker
  from public.financial_transactions ft
  where ft.profile_id = p_profile_id
    and ft.type in ('DEBT', 'WITHDRAWAL')
    and ft.status = 'PENDING'
    and ft.effective_date < v_next_month
  order by ft.effective_date, ft.created_at, ft.id
  limit 1;
  if found then
    raise exception 'PENDING_BLOCKER:%:%:%',
      v_blocker.type,
      v_blocker.id,
      to_char(v_blocker.effective_date, 'YYYY-MM');
  end if;

  select min(date_trunc('month', s.start_time at time zone 'Asia/Bangkok')::date)
  into v_first_segment_month
  from public.time_segments s
  where s.profile_id = p_profile_id;

  if v_first_segment_month is not null then
    for v_scan_month in
      select generate_series(
        v_first_segment_month::timestamp,
        (v_month - interval '1 month')::timestamp,
        interval '1 month'
      )::date
    loop
      if not exists (
        select 1 from public.payroll_slips ps
        where ps.profile_id = p_profile_id
          and ps.month = to_char(v_scan_month, 'YYYY-MM')
      ) and public.calculate_paid_work_days(
        p_profile_id,
        v_scan_month::timestamp at time zone 'Asia/Bangkok',
        (v_scan_month + interval '1 month')::timestamp at time zone 'Asia/Bangkok'
      ) > 0 then
        raise exception 'OLDER_WORK_MONTH:%', to_char(v_scan_month, 'YYYY-MM');
      end if;
    end loop;
  end if;

  if v_month = v_current_month then
    select * into v_active_segment
    from public.time_segments s
    where s.profile_id = p_profile_id and s.end_time is null
    for update;
    if found then
      v_was_running := true;
      update public.time_segments
      set end_time = now()
      where id = v_active_segment.id;
    end if;
  end if;

  v_total_days := public.calculate_paid_work_days(
    p_profile_id,
    v_month::timestamp at time zone 'Asia/Bangkok',
    v_next_month::timestamp at time zone 'Asia/Bangkok'
  );

  if v_month < v_current_month and v_total_days <= 0 then
    raise exception 'NO_WORK_MONTH:%', p_month;
  end if;

  perform private.apply_time_tracking_deductions(p_profile_id, v_month);

  select p.daily_wage into v_daily_wage
  from public.profiles p
  where p.id = p_profile_id;
  if not found then raise exception 'PROFILE_NOT_FOUND'; end if;

  v_gross := trunc(v_total_days * v_daily_wage, 2);
  select coalesce(sum(ft.amount), 0)
  into v_deductions
  from public.financial_transactions ft
  where ft.profile_id = p_profile_id
    and ft.status = 'APPROVED'
    and ft.type in ('DEBT_DEDUCTION', 'WITHDRAWAL_DEDUCTION')
    and ft.applied_month = v_month;
  v_net := greatest(trunc(v_gross - v_deductions, 2), 0);

  select coalesce(jsonb_agg(to_jsonb(s) order by s.start_time), '[]'::jsonb)
  into v_segments
  from public.time_segments s
  where s.profile_id = p_profile_id
    and s.end_time is not null
    and s.end_time > (v_month::timestamp at time zone 'Asia/Bangkok')
    and s.start_time < (v_next_month::timestamp at time zone 'Asia/Bangkok');

  select coalesce(jsonb_agg(to_jsonb(ft) order by ft.created_at, ft.id), '[]'::jsonb)
  into v_transactions
  from public.financial_transactions ft
  where ft.profile_id = p_profile_id
    and (
      (
        ft.type in ('DEBT_DEDUCTION', 'WITHDRAWAL_DEDUCTION')
        and ft.applied_month = v_month
      )
      or
      (
        ft.type in ('DEBT', 'WITHDRAWAL')
        and ft.effective_date >= v_month
        and ft.effective_date < v_next_month
      )
    );

  insert into public.payroll_slips (
    profile_id,
    month,
    gross_pay,
    total_deductions,
    net_pay,
    total_days,
    daily_wage,
    slip_data,
    status,
    created_by
  )
  values (
    p_profile_id,
    p_month,
    v_gross,
    v_deductions,
    v_net,
    v_total_days,
    v_daily_wage,
    jsonb_build_object(
      'segments', v_segments,
      'transactions', v_transactions,
      'lockedAt', now()
    ),
    'PENDING',
    v_actor_id
  )
  returning * into v_slip;

  if v_month = v_current_month and v_was_running and p_auto_start_next_month then
    insert into public.time_tracking_resume_schedules (
      profile_id,
      payroll_slip_id,
      resume_at,
      created_by
    )
    values (
      p_profile_id,
      v_slip.id,
      v_next_month::timestamp at time zone 'Asia/Bangkok',
      v_actor_id
    )
    on conflict (profile_id) do update
    set
      payroll_slip_id = excluded.payroll_slip_id,
      resume_at = excluded.resume_at,
      created_by = excluded.created_by,
      created_at = now();
  else
    delete from public.time_tracking_resume_schedules
    where profile_id = p_profile_id;
  end if;

  insert into public.time_tracking_audit_logs (
    admin_id, action, target_table, record_id, new_data, comment
  )
  values (
    v_actor_id,
    'CREATE_PAYROLL_SLIP',
    'payroll_slips',
    v_slip.id,
    to_jsonb(v_slip) || jsonb_build_object(
      'was_running', v_was_running,
      'auto_start_next_month', v_month = v_current_month
        and v_was_running
        and p_auto_start_next_month
    ),
    'สร้างสลิปเดือน ' || p_month
  );

  return to_jsonb(v_slip) || jsonb_build_object(
    'auto_start_scheduled',
    v_month = v_current_month and v_was_running and p_auto_start_next_month
  );
end;
$_$;


ALTER FUNCTION "public"."create_time_tracking_payroll_slip_internal_20260829"("p_profile_id" "uuid", "p_month" "text", "p_auto_start_next_month" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_time_tracking_transaction"("p_profile_id" "uuid", "p_type" "text", "p_amount" numeric, "p_effective_date" "date", "p_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_created jsonb;
  v_decision jsonb;
  v_bangkok_today date := (now() at time zone 'Asia/Bangkok')::date;
  v_effective_date date := p_effective_date;
begin
  if p_type = 'WITHDRAWAL'
    and p_profile_id = auth.uid()
    and not private.can_manage_time_payroll_profile(p_profile_id)
  then
    v_effective_date := v_bangkok_today;
  end if;
  v_created := public.create_time_tracking_transaction_internal_20260829(
    p_profile_id, p_type, p_amount, v_effective_date, p_description
  );
  if private.is_global_time_payroll_manager() then
    v_decision := public.decide_time_tracking_approval(
      'transaction', (v_created ->> 'id')::uuid, 'APPROVED', null, null
    );
    return v_created || jsonb_build_object('status', 'approved', 'decision', v_decision);
  end if;
  return v_created;
end
$$;


ALTER FUNCTION "public"."create_time_tracking_transaction"("p_profile_id" "uuid", "p_type" "text", "p_amount" numeric, "p_effective_date" "date", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_time_tracking_transaction_internal_20260829"("p_profile_id" "uuid", "p_type" "text", "p_amount" numeric, "p_effective_date" "date", "p_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_id uuid;
  v_comment text;
  v_actor_name text;
  v_bangkok_today date := (now() at time zone 'Asia/Bangkok')::date;
begin
  if v_actor_id is null or not private.is_active_user() then
    raise exception 'Authentication required';
  end if;
  if p_type not in ('DEBT', 'WITHDRAWAL') then
    raise exception 'INVALID_TRANSACTION_TYPE';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'INVALID_AMOUNT';
  end if;
  if p_effective_date is null or p_effective_date > v_bangkok_today then
    raise exception 'FUTURE_EFFECTIVE_DATE';
  end if;
  if p_type = 'DEBT' and not private.can_manage_time_payroll_profile(p_profile_id) then
    raise exception 'Forbidden';
  end if;
  if p_type = 'WITHDRAWAL'
    and p_profile_id <> v_actor_id
    and not private.can_manage_time_payroll_profile(p_profile_id)
  then
    raise exception 'Forbidden';
  end if;
  if p_type = 'DEBT' and nullif(btrim(coalesce(p_description, '')), '') is null then
    raise exception 'DESCRIPTION_REQUIRED';
  end if;
  if not exists (
    select 1 from public.profiles p
    where p.id = p_profile_id and p.is_active = true
  ) then
    raise exception 'PROFILE_NOT_FOUND';
  end if;
  if exists (
    select 1 from public.payroll_slips ps
    where ps.profile_id = p_profile_id
      and ps.month = to_char(p_effective_date, 'YYYY-MM')
  ) then
    raise exception 'MONTH_CLOSED:%', to_char(p_effective_date, 'YYYY-MM');
  end if;

  select p.name into v_actor_name from public.profiles p where p.id = v_actor_id;
  v_comment := case
    when v_actor_id = p_profile_id and p_type = 'WITHDRAWAL' then null
    when p_type = 'DEBT' then 'สร้างหนี้สินโดย: ' || coalesce(v_actor_name, 'ผู้จัดการ')
    else 'ยื่นแทนโดยผู้จัดการ: ' || coalesce(v_actor_name, 'ผู้จัดการ')
  end;

  insert into public.financial_transactions (
    profile_id, type, amount, effective_date, due_date, description, admin_comment
  ) values (
    p_profile_id,
    p_type::public.financial_transaction_type,
    trunc(p_amount, 2),
    p_effective_date,
    case when p_type = 'DEBT' then p_effective_date else null end,
    nullif(btrim(coalesce(p_description, '')), ''),
    v_comment
  ) returning id into v_id;

  insert into public.time_tracking_audit_logs (
    admin_id, action, target_table, record_id, new_data, comment
  ) values (
    v_actor_id,
    case when p_type = 'DEBT' then 'CREATE_DEBT' else 'REQUEST_WITHDRAWAL' end,
    'financial_transactions',
    v_id,
    jsonb_build_object(
      'profile_id', p_profile_id,
      'type', p_type,
      'amount', trunc(p_amount, 2),
      'effective_date', p_effective_date,
      'description', nullif(btrim(coalesce(p_description, '')), '')
    ),
    v_comment
  );

  return jsonb_build_object('id', v_id, 'status', 'pending');
end
$$;


