ALTER FUNCTION "public"."decide_time_tracking_approval"("p_source_type" "text", "p_source_id" "uuid", "p_decision" "text", "p_comment" "text", "p_expense_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_time_tracking_approval_internal_20260829"("p_source_type" "text", "p_source_id" "uuid", "p_decision" "text", "p_comment" "text" DEFAULT NULL::"text", "p_expense_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_tx public.financial_transactions%rowtype;
  v_slip public.payroll_slips%rowtype;
  v_old_data jsonb;
  v_requires_payment_choice boolean := false;
  v_current_month date := date_trunc(
    'month',
    (now() at time zone 'Asia/Bangkok')::date
  )::date;
begin
  if v_actor_id is null or not private.is_active_user() then
    raise exception 'Authentication required';
  end if;
  if p_source_type not in ('transaction', 'payroll_slip') then
    raise exception 'Invalid approval source';
  end if;
  if p_decision not in ('APPROVED', 'REJECTED') then
    raise exception 'Invalid approval decision';
  end if;

  if p_source_type = 'transaction' then
    select * into v_tx
    from public.financial_transactions
    where id = p_source_id;
    if not found or v_tx.type not in ('DEBT', 'WITHDRAWAL') then
      raise exception 'Transaction not found';
    end if;
    if not private.can_manage_time_payroll_profile(v_tx.profile_id) then
      raise exception 'Forbidden';
    end if;

    perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || v_tx.profile_id::text, 0));
    select * into v_tx
    from public.financial_transactions
    where id = p_source_id
    for update;
    if not found or v_tx.type not in ('DEBT', 'WITHDRAWAL') then
      raise exception 'Transaction not found';
    end if;
    if exists (
      select 1 from public.payroll_slips ps
      where ps.profile_id = v_tx.profile_id
        and ps.month = to_char(v_tx.effective_date, 'YYYY-MM')
    ) then
      raise exception 'MONTH_CLOSED:%', to_char(v_tx.effective_date, 'YYYY-MM');
    end if;

    v_requires_payment_choice := p_decision = 'APPROVED' and v_tx.type = 'WITHDRAWAL';
    if v_tx.status <> 'PENDING' then
      if v_tx.status = p_decision::public.approval_status
        and (
          not v_requires_payment_choice
          or v_tx.expense_location_id is not distinct from p_expense_location_id
        )
      then
        return jsonb_build_object(
          'status', lower(p_decision),
          'idempotent', true,
          'sourceType', p_source_type,
          'sourceId', p_source_id
        );
      end if;
      raise exception 'Approval has already been decided';
    end if;

    if v_requires_payment_choice then
      if p_expense_location_id is not null
        and not private.can_assign_time_tracking_expense_location(p_expense_location_id)
      then
        raise exception 'Expense location access denied';
      end if;
    elsif p_expense_location_id is not null then
      raise exception 'Expense location is not valid for this decision';
    end if;

    v_old_data := to_jsonb(v_tx);
    if p_decision = 'APPROVED' then
      perform set_config('app.time_tracking_expense_rpc', 'true', true);
      update public.financial_transactions
      set
        status = 'APPROVED',
        admin_comment = coalesce(p_comment, ''),
        approved_by = v_actor_id,
        approved_at = now(),
        expense_location_id = case
          when v_requires_payment_choice then p_expense_location_id
          else null
        end,
        remaining_amount = amount
      where id = v_tx.id;

      perform private.apply_time_tracking_deductions(v_tx.profile_id, v_current_month);
    else
      update public.financial_transactions
      set
        status = 'REJECTED',
        admin_comment = coalesce(p_comment, ''),
        approved_by = v_actor_id
      where id = v_tx.id;
    end if;

    insert into public.time_tracking_audit_logs (
      admin_id, action, target_table, record_id, old_data, new_data, comment
    ) values (
      v_actor_id,
      'DECIDE_TRANSACTION_APPROVAL',
      'financial_transactions',
      v_tx.id,
      v_old_data,
      jsonb_build_object(
        'decision', p_decision,
        'expenseLocationId', p_expense_location_id,
        'paymentMethod', case
          when v_requires_payment_choice and p_expense_location_id is null then 'CENTRAL_OUTSIDE_SYSTEM'
          when v_requires_payment_choice then 'BRANCH'
          else null
        end
      ),
      coalesce(p_comment, '')
    );
  else
    select * into v_slip
    from public.payroll_slips
    where id = p_source_id;
    if not found then raise exception 'Payroll slip not found'; end if;
    if not private.can_manage_time_payroll_profile(v_slip.profile_id) then
      raise exception 'Forbidden';
    end if;

    perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || v_slip.profile_id::text, 0));
    select * into v_slip
    from public.payroll_slips
    where id = p_source_id
    for update;
    if not found then raise exception 'Payroll slip not found'; end if;

    v_requires_payment_choice := p_decision = 'APPROVED' and v_slip.net_pay > 0;
    if v_slip.status <> 'PENDING' then
      if v_slip.status = p_decision::public.approval_status
        and (
          not v_requires_payment_choice
          or v_slip.expense_location_id is not distinct from p_expense_location_id
        )
      then
        return jsonb_build_object(
          'status', lower(p_decision),
          'idempotent', true,
          'sourceType', p_source_type,
          'sourceId', p_source_id
        );
      end if;
      raise exception 'Approval has already been decided';
    end if;

    if v_requires_payment_choice then
      if p_expense_location_id is not null
        and not private.can_assign_time_tracking_expense_location(p_expense_location_id)
      then
        raise exception 'Expense location access denied';
      end if;
    elsif p_expense_location_id is not null then
      raise exception 'Expense location is not valid for this decision';
    end if;

    v_old_data := to_jsonb(v_slip);
    if p_decision = 'APPROVED' then
      perform set_config('app.time_tracking_expense_rpc', 'true', true);
      update public.payroll_slips
      set
        status = 'APPROVED',
        admin_comment = coalesce(p_comment, ''),
        approved_by = v_actor_id,
        approved_at = now(),
        expense_location_id = case
          when v_requires_payment_choice then p_expense_location_id
          else null
        end
      where id = v_slip.id;
    else
      update public.payroll_slips
      set
        status = 'REJECTED',
        admin_comment = coalesce(p_comment, ''),
        approved_by = v_actor_id
      where id = v_slip.id;
    end if;

    insert into public.time_tracking_audit_logs (
      admin_id, action, target_table, record_id, old_data, new_data, comment
    ) values (
      v_actor_id,
      'DECIDE_PAYROLL_SLIP_APPROVAL',
      'payroll_slips',
      v_slip.id,
      v_old_data,
      jsonb_build_object(
        'decision', p_decision,
        'expenseLocationId', p_expense_location_id,
        'paymentMethod', case
          when v_requires_payment_choice and p_expense_location_id is null then 'CENTRAL_OUTSIDE_SYSTEM'
          when v_requires_payment_choice then 'BRANCH'
          else null
        end
      ),
      coalesce(p_comment, '')
    );
  end if;

  return jsonb_build_object(
    'status', lower(p_decision),
    'idempotent', false,
    'sourceType', p_source_type,
    'sourceId', p_source_id
  );
end
$$;


ALTER FUNCTION "public"."decide_time_tracking_approval_internal_20260829"("p_source_type" "text", "p_source_id" "uuid", "p_decision" "text", "p_comment" "text", "p_expense_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."deduct_debts_daily"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile_id uuid;
  v_current_month date := date_trunc(
    'month',
    (now() at time zone 'Asia/Bangkok')::date
  )::date;
begin
  for v_profile_id in
    select distinct ft.profile_id
    from public.financial_transactions ft
    where ft.type in ('DEBT', 'WITHDRAWAL')
      and ft.status = 'APPROVED'
      and ft.remaining_amount > 0
  loop
    perform private.apply_time_tracking_deductions(v_profile_id, v_current_month);
  end loop;
end;
$$;


ALTER FUNCTION "public"."deduct_debts_daily"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_cash_branch_transfer"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  transfer_row public.money_transfers%rowtype;
  cash_row public.money_transfer_cash_details%rowtype;
  actor_id uuid := auth.uid();
  actor_name text;
  actor_phone text;
  source_name text;
  target_name text;
  requires_approval boolean;
  existing_request_id uuid;
  request_id uuid;
  report_no text;
begin
  if not private.is_active_user() then
    raise exception 'ไม่มีสิทธิ์ลบรายการเงินสด';
  end if;

  select * into transfer_row
  from public.money_transfers
  where id = p_transfer_id
  for update;

  if transfer_row.id is null
    or transfer_row.transfer_type <> 'cash'
    or transfer_row.transfer_method <> 'cash'
  then
    raise exception 'ไม่พบรายการเงินสด';
  end if;

  if not private.can_manage_location(transfer_row.location_id) then
    raise exception 'เฉพาะผู้ดูแลสาขาต้นทางหรือผู้จัดการระบบเท่านั้นที่ลบรายการเงินสดได้';
  end if;

  select * into cash_row
  from public.money_transfer_cash_details
  where transfer_id = p_transfer_id
  for update;

  if cash_row.transfer_id is null then
    raise exception 'ไม่พบรายละเอียดเงินสด';
  end if;

  report_no := private.active_transfer_report_no(p_transfer_id);
  if report_no is not null then
    perform private.raise_report_lock(report_no);
  end if;

  select id into existing_request_id
  from public.cash_transfer_delete_requests
  where transfer_id = p_transfer_id
    and request_status = 'pending'
  for update;

  if existing_request_id is not null then
    return jsonb_build_object(
      'id', p_transfer_id,
      'status', 'pending_approval',
      'requestId', existing_request_id
    );
  end if;

  select coalesce(cash_transfer_delete_requires_approval, true)
  into requires_approval
  from public.income_expense_approval_settings
  where id = true;

  if cash_row.cash_status = 'pending_receipt'
    or not coalesce(requires_approval, true)
  then
    delete from public.money_transfers where id = p_transfer_id;
    return jsonb_build_object('id', p_transfer_id, 'status', 'deleted');
  end if;

  select name, phone into actor_name, actor_phone
  from public.profiles
  where id = actor_id;
  select name into source_name
  from public.locations
  where id = transfer_row.location_id;
  select name into target_name
  from public.locations
  where id = transfer_row.target_location_id;

  insert into public.cash_transfer_delete_requests (
    transfer_id,
    source_location_id,
    source_location_name,
    target_location_id,
    target_location_name,
    transfer_display_no,
    sent_total,
    received_total,
    difference_total,
    note,
    requested_by_user_id,
    requested_by_name,
    requested_by_phone
  )
  values (
    p_transfer_id,
    transfer_row.location_id,
    coalesce(source_name, 'ไม่ทราบสาขา'),
    transfer_row.target_location_id,
    coalesce(target_name, transfer_row.target_location_name, 'ไม่ทราบสาขา'),
    'CASH-' || left(p_transfer_id::text, 8),
    cash_row.sent_total,
    cash_row.received_total,
    cash_row.difference_total,
    cash_row.note,
    actor_id,
    coalesce(actor_name, ''),
    coalesce(actor_phone, '')
  )
  returning id into request_id;

  return jsonb_build_object(
    'id', p_transfer_id,
    'status', 'pending_approval',
    'requestId', request_id
  );
end;
$$;


ALTER FUNCTION "public"."delete_cash_branch_transfer"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_cash_count"("p_cash_count_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_count public.cash_counts%rowtype;
  v_report public.report_batches%rowtype;
  v_audit public.document_deletion_audits%rowtype;
  v_actor_name text;
  v_export_no text;
  v_now timestamptz := clock_timestamp();
begin
  if not private.can_delete_reports() then
    raise exception 'เฉพาะ super_admin หรือผู้จัดการระบบเท่านั้นที่ลบผลตรวจนับได้';
  end if;

  select * into v_count
  from public.cash_counts
  where id = p_cash_count_id
  for update;

  if v_count.id is null then
    select * into v_audit
    from public.document_deletion_audits
    where document_kind = 'cash_count'
      and source_id = p_cash_count_id;
    if v_audit.id is not null then
      return jsonb_build_object(
        'id', p_cash_count_id,
        'reportId', v_audit.paired_source_id,
        'reportNo', v_audit.document_no,
        'status', 'deleted'
      );
    end if;
    raise exception 'ไม่พบผลตรวจนับ active';
  end if;

  if v_count.status <> 'active' then
    raise exception 'ไม่พบผลตรวจนับ active';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_count.location_id::text, 0)
  );
  perform pg_advisory_xact_lock(
    hashtextextended('rubber-export:' || v_count.location_id::text, 0)
  );

  select * into v_report
  from public.report_batches
  where id = v_count.report_id
  for update;

  if v_report.id is null or v_report.status <> 'active' then
    raise exception 'รายงานของผลตรวจนับไม่อยู่ในสถานะ active';
  end if;

  if exists (
    select 1 from public.report_batches newer
    where newer.location_id = v_count.location_id
      and newer.status = 'active'
      and (newer.created_at, newer.id) > (v_report.created_at, v_report.id)
  ) then
    raise exception 'ลบได้เฉพาะชุดตรวจนับและรายงาน active ล่าสุดของสาขา';
  end if;

  v_export_no := private.active_rubber_export_no_for_report(v_report.id);
  if v_export_no is not null then
    raise exception 'RUBBER_EXPORT_LOCKED:%', v_export_no
      using hint = 'ลบรายการส่งออกยางก่อนจึงจะลบชุดตรวจนับได้';
  end if;

  select p.name into v_actor_name
  from public.profiles p
  where p.id = auth.uid();

  insert into public.document_deletion_audits (
    document_kind, source_id, paired_source_id, document_no, location_id,
    original_actor_user_id, original_actor_name,
    deleted_by_user_id, deleted_by_name, deleted_at
  ) values (
    'cash_count', v_count.id, v_report.id, v_report.report_no,
    v_count.location_id, v_count.created_by_user_id, v_count.created_by_name,
    auth.uid(), coalesce(v_actor_name, ''), v_now
  );

  delete from public.cash_counts
  where id = v_count.id;

  delete from public.report_items
  where report_id = v_report.id;

  delete from public.report_batches
  where id = v_report.id;

  delete from public.cash_count_sessions
  where id = v_count.session_id
    and status = 'submitted';

  return jsonb_build_object(
    'id', v_count.id,
    'reportId', v_report.id,
    'reportNo', v_report.report_no,
    'status', 'deleted'
  );
end;
$$;


ALTER FUNCTION "public"."delete_cash_count"("p_cash_count_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_export_vehicle_weigh_bill"("p_wex_id" "uuid", "p_expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_wex public.export_vehicle_weigh_bills%rowtype;
  v_audit public.document_deletion_audits%rowtype;
  v_actor_name text;
  v_now timestamptz := clock_timestamp();
begin
  if not private.can_delete_reports() then
    raise exception 'WEX_FORBIDDEN: เฉพาะ super_admin หรือผู้จัดการระบบเท่านั้นที่ลบบิลรถส่งออกได้';
  end if;

  select * into v_wex
  from public.export_vehicle_weigh_bills w
  where w.id = p_wex_id
  for update;

  if v_wex.id is null then
    select * into v_audit
    from public.document_deletion_audits a
    where a.document_kind = 'export_vehicle_weigh_bill'
      and a.source_id = p_wex_id;
    if v_audit.id is not null then
      return jsonb_build_object(
        'id', p_wex_id, 'wexNo', v_audit.document_no, 'status', 'deleted'
      );
    end if;
    raise exception 'WEX_NOT_FOUND: ไม่พบบิลรถส่งออก';
  end if;

  if p_expected_revision is null or p_expected_revision <> v_wex.revision then
    raise exception 'WEX_STALE_REVISION: บิลรถส่งออกถูกแก้ไขแล้ว กรุณาโหลดข้อมูลใหม่';
  end if;

  select p.name into v_actor_name
  from public.profiles p
  where p.id = auth.uid() and p.is_active = true;
  if nullif(btrim(v_actor_name), '') is null then
    raise exception 'WEX_FORBIDDEN: บัญชีผู้ใช้ไม่พร้อมใช้งาน';
  end if;

  insert into public.document_deletion_audits (
    document_kind, source_id, document_no, location_id,
    deleted_by_user_id, deleted_by_name, deleted_at
  ) values (
    'export_vehicle_weigh_bill', v_wex.id, v_wex.wex_no, v_wex.location_id,
    auth.uid(), v_actor_name, v_now
  );

  delete from public.export_vehicle_weigh_bill_reservations
  where wex_id = v_wex.id;
  delete from public.export_vehicle_weigh_lines
  where wex_id = v_wex.id;
  delete from public.export_vehicle_weigh_bills
  where id = v_wex.id;

  return jsonb_build_object(
    'id', v_wex.id, 'wexNo', v_wex.wex_no, 'status', 'deleted'
  );
end;
$$;


ALTER FUNCTION "public"."delete_export_vehicle_weigh_bill"("p_wex_id" "uuid", "p_expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_money_transfer"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_backend_pid integer := pg_catalog.pg_backend_pid();
  v_transaction_id bigint := pg_catalog.txid_current();
  v_result jsonb;
begin
  insert into private.money_transfer_delete_context (
    backend_pid,
    transaction_id,
    transfer_id
  ) values (
    v_backend_pid,
    v_transaction_id,
    p_transfer_id
  );

  v_result := private.delete_money_transfer(p_transfer_id);

  delete from private.money_transfer_delete_context c
  where c.backend_pid = v_backend_pid
    and c.transaction_id = v_transaction_id
    and c.transfer_id = p_transfer_id;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."delete_money_transfer"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_money_transfer"("p_transfer_id" "uuid", "p_expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_transfer public.money_transfers;
begin
  if p_transfer_id is null or p_expected_revision is null then
    raise exception 'MT_INVALID_PAYLOAD: ข้อมูลลบรายการโอนไม่ครบ';
  end if;

  select * into v_transfer
  from public.money_transfers t
  where t.id = p_transfer_id
  for update;

  if not found then
    raise exception 'MONEY_TRANSFER_NOT_FOUND';
  end if;

  if v_transfer.transfer_type = 'branch'
    and v_transfer.target_location_id is distinct from v_transfer.location_id
  then
    raise exception 'MT_LEGACY_BRANCH_READ_ONLY: รายการโอนระหว่างสาขารุ่นเดิมลบไม่ได้';
  end if;

  if v_transfer.record_status <> 'deleted'
    and v_transfer.revision_no <> p_expected_revision
  then
    raise exception 'MT_REVISION_CONFLICT: ข้อมูลถูกแก้ไขแล้ว กรุณาโหลดใหม่';
  end if;

  return public.delete_money_transfer(p_transfer_id);
end;
$$;


ALTER FUNCTION "public"."delete_money_transfer"("p_transfer_id" "uuid", "p_expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_report_batch"("p_report_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_report public.report_batches%rowtype;
  v_audit public.document_deletion_audits%rowtype;
  v_export_no text;
  v_actor_name text;
  v_now timestamptz := clock_timestamp();
begin
  if not private.can_delete_reports() then
    raise exception 'เฉพาะ super_admin หรือผู้จัดการระบบเท่านั้นที่ลบรายงานได้';
  end if;

  select * into v_report
  from public.report_batches
  where id = p_report_id
  for update;

  if v_report.id is null then
    select * into v_audit
    from public.document_deletion_audits
    where document_kind = 'report_batch'
      and source_id = p_report_id;
    if v_audit.id is not null then
      return jsonb_build_object(
        'id', p_report_id,
        'reportNo', v_audit.document_no,
        'status', 'deleted'
      );
    end if;
    raise exception 'ไม่พบรายงาน active';
  end if;

  if v_report.status <> 'active' then
    raise exception 'ไม่พบรายงาน active';
  end if;

  if exists (
    select 1 from public.cash_counts c
    where c.report_id = p_report_id
  ) then
    raise exception 'CASH_COUNT_LINKED: รายงานนี้มีผลตรวจนับเงินสด กรุณาลบจากโมดูลนับเงิน';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_report.location_id::text, 0)
  );
  perform pg_advisory_xact_lock(
    hashtextextended('rubber-export:' || v_report.location_id::text, 0)
  );

  if exists (
    select 1 from public.report_batches newer
    where newer.location_id = v_report.location_id
      and newer.status = 'active'
      and (newer.created_at, newer.id) > (v_report.created_at, v_report.id)
  ) then
    raise exception 'ลบได้เฉพาะรายงาน active ล่าสุดของสาขา';
  end if;

  v_export_no := private.active_rubber_export_no_for_report(p_report_id);
  if v_export_no is not null then
    raise exception 'RUBBER_EXPORT_LOCKED:%', v_export_no
      using hint = 'ลบรายการส่งออกยางก่อนจึงจะลบรายงานได้';
  end if;

  select p.name into v_actor_name
  from public.profiles p
  where p.id = auth.uid();

  insert into public.document_deletion_audits (
    document_kind, source_id, document_no, location_id,
    deleted_by_user_id, deleted_by_name, deleted_at
  ) values (
    'report_batch', v_report.id, v_report.report_no, v_report.location_id,
    auth.uid(), coalesce(v_actor_name, ''), v_now
  );

  delete from public.report_items
  where report_id = v_report.id;

  delete from public.report_batches
  where id = v_report.id;

  return jsonb_build_object(
    'id', v_report.id,
    'reportNo', v_report.report_no,
    'status', 'deleted'
  );
end;
$$;


ALTER FUNCTION "public"."delete_report_batch"("p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_rubber_approval_group"("p_group_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_location_ids uuid[];
begin
  if not private.is_active_user() or not private.can_access_super_admin_features() then
    raise exception 'FORBIDDEN: ไม่มีสิทธิ์จัดการกลุ่มอนุมัติบิลยาง';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('rubber-approval-groups', 0));
  select array_agg(gl.location_id order by gl.location_id)
    into v_location_ids
  from public.rubber_approval_group_locations gl
  where gl.group_id = p_group_id;
  if v_location_ids is null then
    raise exception 'RUBBER_GROUP_NOT_FOUND: ไม่พบกลุ่ม';
  end if;
  delete from public.rubber_approval_groups where id = p_group_id;
  return jsonb_build_object(
    'success', true,
    'releasedLocationIds', to_jsonb(v_location_ids)
  );
end
$$;


ALTER FUNCTION "public"."delete_rubber_approval_group"("p_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_rubber_bill_approval_request"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.rubber_bill_approval_requests%rowtype;
  v_upload_id uuid;
begin
  if not private.is_active_user() or not private.can_access_super_admin_features() then
    raise exception 'ไม่มีสิทธิ์ลบคำขอบิลยาง';
  end if;
  select * into v_request
  from public.rubber_bill_approval_requests r
  where r.id = p_request_id
  for update;
  if v_request.id is null or v_request.request_status <> 'pending' then
    raise exception 'ไม่พบคำขอที่รออนุมัติ';
  end if;

  if v_request.operation = 'create'
     and v_request.proposed_payload->>'inputMethod' = 'ocr' then
    begin
      v_upload_id := (v_request.proposed_payload->>'ocrUploadId')::uuid;
    exception when others then
      raise exception 'ข้อมูลอ้างอิงรูป OCR ในคำขออนุมัติไม่ถูกต้อง';
    end;
    perform 1 from public.rubber_bill_ocr_sources s
    where s.id = v_upload_id
    for update;
    update public.rubber_bill_ocr_sources
    set state = 'abandoned', abandoned_at = now(), updated_at = now()
    where id = v_upload_id
      and state = 'reserved'
      and owner_user_id = v_request.requested_by_user_id
      and location_id = v_request.location_id
      and reserved_client_temp_id = v_request.client_temp_id
      and reserved_idempotency_key = v_request.idempotency_key;
    if not found then
      raise exception 'ข้อมูลอ้างอิงรูป OCR ไม่ตรงกับคำขออนุมัติ';
    end if;
  end if;

  delete from public.rubber_bill_approval_requests where id = p_request_id;
end
$$;


ALTER FUNCTION "public"."delete_rubber_bill_approval_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_rubber_export"("p_export_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_export public.rubber_exports%rowtype;
  v_audit public.document_deletion_audits%rowtype;
  v_report_no text;
  v_receipt_no text;
  v_actor_name text;
  v_now timestamptz := clock_timestamp();
begin
  if not private.can_delete_reports() then
    raise exception 'เฉพาะ super_admin หรือผู้มีสิทธิ์จัดการระบบเท่านั้นที่ลบได้';
  end if;
  select * into v_export
  from public.rubber_exports
  where id = p_export_id
  for update;
  if v_export.id is null then
    select * into v_audit
    from public.document_deletion_audits
    where document_kind = 'rubber_export' and source_id = p_export_id;
    if v_audit.id is not null then
      return jsonb_build_object(
        'id', p_export_id, 'exportNo', v_audit.document_no, 'status', 'deleted'
      );
    end if;
    raise exception 'ไม่พบรายการส่งออก';
  end if;
  if v_export.sold_out_at is not null then
    raise exception 'RUBBER_EXPORT_SOLD_OUT:%', v_export.export_no
      using errcode = 'P0001', hint = 'กรุณายกเลิกขายก่อนลบรายการ';
  end if;
  v_report_no := private.active_report_no('rubber_export', p_export_id);
  if v_report_no is not null then perform private.raise_report_lock(v_report_no); end if;
  select coalesce(b.server_bill_no, b.local_bill_no, b.bill_no)
  into v_receipt_no
  from public.rubber_bills b
  where b.source_rubber_export_id = p_export_id and b.record_status = 'active'
  limit 1;
  if v_receipt_no is not null then
    raise exception 'BRANCH_RECEIPT_SOURCE_LOCKED:%', v_export.export_no
      using hint = 'กรุณาลบบิลรับ ' || v_receipt_no || ' ก่อน';
  end if;
  select p.name into v_actor_name from public.profiles p where p.id = auth.uid();
  insert into public.document_deletion_audits (
    document_kind, source_id, document_no, location_id, previous_status,
    original_actor_user_id, original_actor_name,
    deleted_by_user_id, deleted_by_name, deleted_at
  ) values (
    'rubber_export', v_export.id, v_export.export_no, v_export.location_id,
    v_export.status, v_export.created_by_user_id, v_export.created_by_name,
    auth.uid(), coalesce(v_actor_name, ''), v_now
  );
  delete from public.rubber_export_items where export_id = v_export.id;
  delete from public.rubber_exports where id = v_export.id;
  return jsonb_build_object(
    'id', v_export.id, 'exportNo', v_export.export_no, 'status', 'deleted'
  );
end;
$$;


ALTER FUNCTION "public"."delete_rubber_export"("p_export_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_time_tracking_source_permanently"("p_source_type" "text", "p_source_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_tx public.financial_transactions%rowtype;
  v_slip public.payroll_slips%rowtype;
  v_blocked_month text;
begin
  if v_actor_id is null or not private.is_active_user() then
    raise exception 'Authentication required';
  end if;
  if p_source_type not in ('transaction', 'payroll_slip') then
    raise exception 'Invalid deletion source';
  end if;

  if p_source_type = 'transaction' then
    select * into v_tx
    from public.financial_transactions
    where id = p_source_id;
    if not found or v_tx.type not in ('DEBT', 'WITHDRAWAL') then
      raise exception 'Transaction not found';
    end if;

    perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || v_tx.profile_id::text, 0));
    select * into v_tx
    from public.financial_transactions
    where id = p_source_id
    for update;
    if not found or v_tx.type not in ('DEBT', 'WITHDRAWAL') then
      raise exception 'Transaction not found';
    end if;
    if not (
      v_tx.status = 'PENDING'
      and v_tx.type = 'WITHDRAWAL'
      and v_tx.profile_id = v_actor_id
    ) and not private.is_global_time_payroll_manager() then
      raise exception 'Forbidden';
    end if;

    select ps.month into v_blocked_month
    from public.payroll_slips ps
    where ps.profile_id = v_tx.profile_id
      and (
        ps.month = to_char(v_tx.effective_date, 'YYYY-MM')
        or exists (
          select 1
          from public.financial_transactions child
          where child.parent_debt_id = v_tx.id
            and child.applied_month is not null
            and ps.month = to_char(child.applied_month, 'YYYY-MM')
        )
      )
    order by ps.month
    limit 1;
    if v_blocked_month is not null then
      raise exception 'MONTH_CLOSED:%', v_blocked_month;
    end if;

    delete from public.time_tracking_audit_logs
    where target_table = 'financial_transactions'
      and (
        record_id = v_tx.id
        or record_id in (
          select id from public.financial_transactions where parent_debt_id = v_tx.id
        )
      );

    perform set_config('app.time_tracking_permanent_delete_rpc', 'true', true);
    delete from public.financial_transactions where parent_debt_id = v_tx.id;
    delete from public.financial_transactions where id = v_tx.id;
  else
    select * into v_slip
    from public.payroll_slips
    where id = p_source_id;
    if not found then
      raise exception 'Payroll slip not found';
    end if;

    perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || v_slip.profile_id::text, 0));
    select * into v_slip
    from public.payroll_slips
    where id = p_source_id
    for update;
    if not found then
      raise exception 'Payroll slip not found';
    end if;
    if not (
      v_slip.status = 'PENDING'
      and v_slip.created_by = v_actor_id
    ) and not private.is_global_time_payroll_manager() then
      raise exception 'Forbidden';
    end if;

    if exists (
      select 1
      from public.payroll_slips newer
      where newer.profile_id = v_slip.profile_id and newer.month > v_slip.month
    ) then
      select min(newer.month) into v_blocked_month
      from public.payroll_slips newer
      where newer.profile_id = v_slip.profile_id and newer.month > v_slip.month;
      raise exception 'DELETE_NEWER_SLIP_FIRST:%', v_blocked_month;
    end if;

    delete from public.time_tracking_audit_logs
    where target_table = 'payroll_slips' and record_id = v_slip.id;

    perform set_config('app.time_tracking_permanent_delete_rpc', 'true', true);
    delete from public.payroll_slips where id = v_slip.id;
  end if;

  return jsonb_build_object(
    'status', 'deleted',
    'sourceType', p_source_type,
    'sourceId', p_source_id
  );
end
$$;


ALTER FUNCTION "public"."delete_time_tracking_source_permanently"("p_source_type" "text", "p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dispatch_telegram_badge_tick"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  edge_url text;
  dispatch_secret text;
  request_id bigint;
begin
  if not exists (
    select 1
    from public.telegram_badge_settings s
    where s.id = true and s.enabled = true
  ) then
    return null;
  end if;

  select url_secret.decrypted_secret, dispatch_secret_row.decrypted_secret
  into edge_url, dispatch_secret
  from public.telegram_badge_settings s
  left join vault.decrypted_secrets url_secret on url_secret.id = s.edge_url_secret_id
  left join vault.decrypted_secrets dispatch_secret_row on dispatch_secret_row.id = s.dispatch_secret_id
  where s.id = true;

  if edge_url is null or dispatch_secret is null then
    return null;
  end if;

  select net.http_post(
    url := edge_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-lanflow-dispatch-secret', dispatch_secret
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 10000
  )
  into request_id;

  return request_id;
end;
$$;


ALTER FUNCTION "public"."dispatch_telegram_badge_tick"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_acid_stock_balance"("p_location_id" "uuid", "p_product_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_balance numeric;
begin
  if not public.can_access_location(p_location_id) then
    raise exception 'Location access denied';
  end if;

  select coalesce(sum(quantity_delta), 0)
    into v_balance
  from public.acid_stock_movements
  where location_id = p_location_id
    and product_id = p_product_id;

  return coalesce(v_balance, 0);
end;
$$;


ALTER FUNCTION "public"."get_acid_stock_balance"("p_location_id" "uuid", "p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_actionable_badge_counts"() RETURNS TABLE("location_id" "uuid", "module_id" "text", "item_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_role text;
  v_can_manage_system boolean;
  v_can_use_money_transfer boolean;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select p.role,
    p.role = 'super_admin' or p.can_access_super_admin_features = true,
    p.role = 'super_admin' or p.can_access_super_admin_features = true or p.can_access_money_transfer = true
  into v_role, v_can_manage_system, v_can_use_money_transfer
  from public.profiles p where p.id = v_user_id and p.is_active = true;
  if v_role is null then raise exception 'Inactive profile'; end if;

  return query
  with accessible_locations as (
    select ul.location_id from public.user_locations ul
    join public.locations l on l.id = ul.location_id and l.is_active = true
    where ul.user_id = v_user_id
  ), counts as (
    select al.location_id, 'rubber'::text module_id, count(distinct w.work_identity)::bigint item_count
    from accessible_locations al
    cross join lateral private.rubber_bill_current_work_items(al.location_id) w
    where w.work_kind = 'unpriced' or (v_can_manage_system and w.work_kind = 'pending_approval')
    group by al.location_id

    union all
    select al.location_id, 'rubber-evidence'::text, count(*)::bigint
    from accessible_locations al
    join private.rubber_bill_evidence_projection p on p.location_id = al.location_id
    where p.review_status = 'pending'
    group by al.location_id

    union all
    select t.target_location_id, 'cash', count(*)::bigint
    from public.money_transfer_cash_details d
    join public.money_transfers t on t.id = d.transfer_id
    join accessible_locations al on al.location_id = t.target_location_id
    where d.cash_status = 'pending_receipt' and t.record_status <> 'deleted'
    group by t.target_location_id

    union all
    select r.location_id, 'cash', count(*)::bigint
    from public.income_expense_approval_requests r
    join accessible_locations al on al.location_id = r.location_id
    where v_can_manage_system and r.request_status = 'pending'
    group by r.location_id

    union all
    select r.source_location_id, 'cash', count(*)::bigint
    from public.cash_transfer_delete_requests r
    join accessible_locations al on al.location_id = r.source_location_id
    where v_can_manage_system and r.request_status = 'pending'
    group by r.source_location_id

    union all
    select t.location_id, 'money-transfer', count(*)::bigint
    from public.money_transfers t
    join accessible_locations al on al.location_id = t.location_id
    where v_can_use_money_transfer and t.transfer_method = 'bank'
      and t.transfer_status in ('pending', 'partial', 'advance_payment')
      and t.record_status <> 'deleted'
    group by t.location_id

    union all
    select r.location_id, 'acid-stock', count(*)::bigint
    from public.stock_entry_approval_requests r
    join accessible_locations al on al.location_id = r.location_id
    where v_can_manage_system and r.request_status = 'pending'
    group by r.location_id

    union all
    select al.location_id, 'acid-stock', count(r.id)::bigint
    from accessible_locations al cross join public.stock_product_approval_requests r
    where v_can_manage_system and r.request_status = 'pending'
    group by al.location_id

    union all
    select e.location_id, 'rubber-export', count(*)::bigint
    from public.rubber_exports e
    join accessible_locations al on al.location_id = e.location_id
    where (v_can_manage_system or v_role = 'admin') and e.status = 'draft'
    group by e.location_id
  )
  select c.location_id, c.module_id, sum(c.item_count)::bigint
  from counts c where c.item_count > 0
  group by c.location_id, c.module_id order by c.location_id, c.module_id;
end;
$$;


ALTER FUNCTION "public"."get_actionable_badge_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cash_branch_transfer_detail"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_transfer public.money_transfers%rowtype;
  v_detail public.money_transfer_cash_details%rowtype;
begin
  if not private.is_active_user() then
    raise exception 'Authentication required';
  end if;

  select * into v_transfer
  from public.money_transfers mt
  where mt.id = p_transfer_id
    and mt.transfer_type = 'cash'
    and mt.transfer_method = 'cash'
    and mt.record_status <> 'deleted';

  if v_transfer.id is null then
    raise exception 'Cash transfer not found';
  end if;
  if not private.can_access_location(v_transfer.location_id)
    and not private.can_access_location(v_transfer.target_location_id)
  then
    raise exception 'Location access denied';
  end if;

  select * into v_detail
  from public.money_transfer_cash_details d
  where d.transfer_id = p_transfer_id;

  if v_detail.transfer_id is null then
    raise exception 'Cash transfer not found';
  end if;

  return to_jsonb(v_transfer) || jsonb_build_object(
    'report_lock_no', public.report_lock_no(v_transfer),
    'money_transfer_cash_details', jsonb_build_array(to_jsonb(v_detail))
  );
end;
$$;


ALTER FUNCTION "public"."get_cash_branch_transfer_detail"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cash_branch_transfer_pending_summary"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
begin
  if not private.is_active_user() or not private.can_access_location(p_location_id) then
    raise exception 'Location access denied';
  end if;

  return (
    with pending as (
      select mt.*, d.sent_total, d.cash_status, d.note, d.sent_at,
        source_location.name as source_location_name,
        public.report_lock_no(mt) as report_lock_no
      from public.money_transfers mt
      join public.money_transfer_cash_details d on d.transfer_id = mt.id
      left join public.locations source_location on source_location.id = mt.location_id
      where mt.transfer_type = 'cash' and mt.transfer_method = 'cash'
        and mt.record_status <> 'deleted'
        and mt.target_location_id = p_location_id
        and d.cash_status = 'pending_receipt'
    ), page as (
      select * from pending order by sent_at asc, id asc limit 20
    )
    select jsonb_build_object(
      'transfers', coalesce((select jsonb_agg(jsonb_build_object(
        'id', id,
        'locationId', location_id,
        'sourceLocationName', source_location_name,
        'targetLocationId', target_location_id,
        'targetLocationName', target_location_name,
        'createdByUserId', created_by_user_id,
        'createdByName', created_by_name,
        'createdByPhone', created_by_phone,
        'sentTotal', sent_total,
        'status', cash_status,
        'note', note,
        'sentAt', sent_at,
        'reportLockNo', report_lock_no
      ) order by sent_at asc, id asc) from page), '[]'::jsonb),
      'total', (select count(*) from pending)
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_cash_branch_transfer_pending_summary"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cash_count_session"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_session public.cash_count_sessions%rowtype;
begin
  if not private.can_use_cash_count(p_location_id) then
    raise exception 'ไม่มีสิทธิ์ตรวจนับเงินสดของสาขานี้';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text, 0));
  update public.cash_count_sessions
  set status = 'expired', ended_at = v_now
  where location_id = p_location_id and status = 'active' and expires_at <= v_now;

  select * into v_session from public.cash_count_sessions
  where location_id = p_location_id and status = 'active'
  order by started_at desc, id desc limit 1;
  if v_session.id is null then return jsonb_build_object('session', null); end if;
  return jsonb_build_object('session', jsonb_build_object(
    'id', v_session.id,
    'locationId', v_session.location_id,
    'cutoffAt', v_session.cutoff_at,
    'expiresAt', v_session.expires_at,
    'startedAt', v_session.started_at,
    'startedByName', v_session.started_by_name,
    'isOwner', v_session.started_by_user_id = auth.uid()
  ));
end;
$$;


ALTER FUNCTION "public"."get_cash_count_session"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_alert_thresholds"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  thresholds public.dashboard_alert_thresholds%rowtype;
  stock_items jsonb;
begin
  perform private.dashboard_require_manager();

  if not exists (
    select 1 from public.locations l
    where l.id = p_location_id and l.is_active = true
  ) then
    raise exception 'ไม่พบสาขาที่เปิดใช้งาน';
  end if;

  select *
  into thresholds
  from public.dashboard_alert_thresholds t
  where t.location_id = p_location_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'productId', p.id,
        'name', p.name,
        'unit', p.unit,
        'minimumBalance', st.minimum_balance
      )
      order by p.name, p.id
    ),
    '[]'::jsonb
  )
  into stock_items
  from public.stock_products p
  left join public.dashboard_stock_alert_thresholds st
    on st.product_id = p.id
   and st.location_id = p_location_id
  where p.is_active = true;

  return jsonb_build_object(
    'locationId', p_location_id,
    'purchaseAverageMin', thresholds.purchase_average_min,
    'netCashMin', coalesce(thresholds.net_cash_min, 30000),
    'stockItems', stock_items,
    'updatedAt', thresholds.updated_at,
    'updatedByName', thresholds.updated_by_name
  );
end;
$$;


ALTER FUNCTION "public"."get_dashboard_alert_thresholds"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_alerts_for_telegram"() RETURNS TABLE("location_id" "uuid", "branch_name" "text", "alert_key" "text", "metric_label" "text", "current_value" numeric, "minimum_value" numeric, "unit" "text", "detail" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with branch_metrics as (
    select
      l.id as location_id,
      l.name as branch_name,
      s.summary,
      s.status,
      s.calculated_at,
      t.purchase_average_min,
      t.net_cash_min,
      'ต่ำกว่ายอดขั้นต่ำ · ผลคำนวณ '
        || to_char(
          s.calculated_at at time zone 'Asia/Bangkok',
          'DD/MM/YYYY HH24:MI'
        )
        || case
          when s.status = 'ready' then ''
          else ' · ข้อมูลกำลังรออัปเดต'
        end as alert_detail
    from public.locations l
    join public.dashboard_branch_snapshots s on s.location_id = l.id
    join public.dashboard_alert_thresholds t on t.location_id = l.id
    where l.is_active = true
      and t.is_configured = true
      and s.summary is not null
      and s.calculated_at is not null
  ),
  scalar_alerts as (
    select
      b.location_id,
      b.branch_name,
      'purchase_average_7_days'::text as alert_key,
      'ยอดซื้อเฉลี่ย 7 วัน'::text as metric_label,
      round((b.summary #>> '{purchase7Days,dailyAverage}')::numeric, 2)
        as current_value,
      b.purchase_average_min as minimum_value,
      'บาท/วัน'::text as unit,
      b.alert_detail as detail
    from branch_metrics b
    where b.purchase_average_min is not null
      and (b.summary #>> '{purchase7Days,dailyAverage}')::numeric
        < b.purchase_average_min

    union all

    select
      b.location_id,
      b.branch_name,
      'net_cash_accumulated',
      'รับ–จ่ายสุทธิสะสม',
      round((b.summary ->> 'netCashFlow')::numeric, 2),
      b.net_cash_min,
      'บาท',
      b.alert_detail
    from branch_metrics b
    where (b.summary ->> 'netCashFlow')::numeric < b.net_cash_min
  ),
  stock_alerts as (
    select
      b.location_id,
      b.branch_name,
      'stock:' || (product.item ->> 'productId') as alert_key,
      'สต็อกสินค้า · ' || (product.item ->> 'name') as metric_label,
      round((product.item ->> 'balance')::numeric, 2) as current_value,
      threshold.minimum_balance as minimum_value,
      product.item ->> 'unit' as unit,
      b.alert_detail as detail
    from branch_metrics b
    cross join lateral jsonb_array_elements(
      coalesce(b.summary #> '{stock,items}', '[]'::jsonb)
    ) product(item)
    join public.dashboard_stock_alert_thresholds threshold
      on threshold.location_id = b.location_id
     and threshold.product_id = (product.item ->> 'productId')::uuid
    where (product.item ->> 'balance')::numeric < threshold.minimum_balance
  )
  select * from scalar_alerts
  union all
  select * from stock_alerts
  order by branch_name, alert_key;
$$;


ALTER FUNCTION "public"."get_dashboard_alerts_for_telegram"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_branch_summaries"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  payload jsonb;
begin
  if not private.is_active_user() then
    raise exception 'Access denied';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'locationId', l.id,
        'snapshotStatus', s.status,
        'calculatedAt', s.calculated_at,
        'cashStatus', case
          when s.summary is null then 'no_data'
          when coalesce(t.is_configured, false) = false then 'unconfigured'
          when (s.summary ->> 'netCashFlow')::numeric < t.net_cash_min then 'low'
          else 'normal'
        end,
        'summary', case
          when s.summary is null then null
          else jsonb_build_object(
            'netCashFlow', s.summary -> 'netCashFlow',
            'rubberInventoryWeight', s.summary -> 'rubberInventoryWeight',
            'purchaseToday', s.summary -> 'purchaseToday'
          )
        end
      )
      order by l.created_at, l.id
    ),
    '[]'::jsonb
  )
  into payload
  from public.locations l
  left join public.dashboard_branch_snapshots s on s.location_id = l.id
  left join public.dashboard_alert_thresholds t on t.location_id = l.id
  where l.is_active = true
    and public.can_access_location(l.id);

  return payload;
end;
$$;


ALTER FUNCTION "public"."get_dashboard_branch_summaries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_money_history"("p_location_id" "uuid", "p_event_date" "date" DEFAULT NULL::"date", "p_action" "text" DEFAULT NULL::"text", "p_cursor_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_page_size" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  page_size integer := least(greatest(coalesce(p_page_size, 10), 1), 50);
  today_bangkok date := (current_timestamp at time zone 'Asia/Bangkok')::date;
  from_date date := (current_timestamp at time zone 'Asia/Bangkok')::date - 14;
  selected_date date;
  normalized_action text := nullif(p_action, 'all');
begin
  if not private.is_active_user()
    or not public.can_access_location(p_location_id)
  then
    raise exception 'Location access denied';
  end if;

  if normalized_action is not null
    and normalized_action not in ('create', 'update', 'delete')
  then
    raise exception 'Invalid money history action';
  end if;

  if (p_cursor_at is null) <> (p_cursor_id is null) then
    raise exception 'Invalid money history cursor';
  end if;

  if p_event_date is not null
    and (p_event_date < from_date or p_event_date > today_bangkok)
  then
    raise exception 'Money history date is outside retention window';
  end if;

  selected_date := p_event_date;
  if selected_date is null then
    select max(event_date)
    into selected_date
    from public.dashboard_money_events
    where location_id = p_location_id
      and event_date between from_date and today_bangkok;
    selected_date := coalesce(selected_date, today_bangkok);
  end if;

  return (
    with filtered as (
      select event.*
      from public.dashboard_money_events event
      where event.location_id = p_location_id
        and event.event_date = selected_date
        and (normalized_action is null or event.action = normalized_action)
        and (
          p_cursor_at is null
          or (event.occurred_at, event.id) < (p_cursor_at, p_cursor_id)
        )
      order by event.occurred_at desc, event.id desc
      limit page_size + 1
    ),
    visible as (
      select *
      from filtered
      order by occurred_at desc, id desc
      limit page_size
    ),
    counts as (
      select
        count(*) as total,
        count(*) filter (where action = 'create') as created,
        count(*) filter (where action = 'update') as updated,
        count(*) filter (where action = 'delete') as deleted,
        max(occurred_at) as latest_at
      from public.dashboard_money_events
      where location_id = p_location_id
        and event_date = selected_date
    )
    select jsonb_build_object(
      'selectedDate', selected_date,
      'availableFrom', from_date,
      'availableTo', today_bangkok,
      'counts', jsonb_build_object(
        'all', counts.total,
        'create', counts.created,
        'update', counts.updated,
        'delete', counts.deleted
      ),
      'latestAt', counts.latest_at,
      'rows', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', id,
          'action', action,
          'kind', kind,
          'number', number,
          'title', title,
          'direction', direction,
          'amount', round(amount, 2),
          'actorName', actor_name,
          'occurredAt', occurred_at
        ) order by occurred_at desc, id desc)
        from visible
      ), '[]'::jsonb),
      'nextCursor', case
        when (select count(*) from filtered) > page_size then (
          select jsonb_build_object('at', occurred_at, 'id', id)
          from visible
          order by occurred_at desc, id desc
          offset page_size - 1
          limit 1
        )
        else null
      end
    )
    from counts
  );
end;
$$;


ALTER FUNCTION "public"."get_dashboard_money_history"("p_location_id" "uuid", "p_event_date" "date", "p_action" "text", "p_cursor_at" timestamp with time zone, "p_cursor_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_overview"("p_location_id" "uuid", "p_cursor_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_key" "text" DEFAULT NULL::"text", "p_page_size" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_today date := (current_timestamp at time zone 'Asia/Bangkok')::date;
  v_from date := v_today - 6;
  v_page_size integer := least(greatest(coalesce(p_page_size, 10), 1), 50);
begin
  if not private.is_active_user() or not public.can_access_location(p_location_id) then
    raise exception 'Location access denied';
  end if;

  if (p_cursor_at is null) <> (p_cursor_key is null) then
    raise exception 'Invalid dashboard cursor';
  end if;

  return (
    with active_bills as (
      select b.*
      from public.rubber_bills b
      where b.location_id = p_location_id
        and b.record_status = 'active'
    ),
    payable_bills as (
      select b.*
      from active_bills b
      where private.rubber_bill_is_payable(b.id)
    ),
    purchase_stats as (
      select
        (select count(*) from active_bills b where b.bill_date = v_today) as today_bill_count,
        (select coalesce(sum(b.net_weight), 0) from active_bills b where b.bill_date = v_today) as today_net_weight,
        (select coalesce(sum(b.net_total), 0) from payable_bills b where b.bill_date = v_today) as today_paid_total,
        (select coalesce(sum(b.net_weight), 0) from payable_bills b where b.bill_date between v_from and v_today) as seven_day_net_weight,
        (select coalesce(sum(b.net_total), 0) from payable_bills b where b.bill_date between v_from and v_today) as seven_day_paid_total,
        (select coalesce(sum(b.net_weight), 0) from active_bills b) as accumulated_net_weight
    ),
    export_stats as (
      select
        coalesce(sum(e.original_weight_total) filter (where e.status = 'verified'), 0) as accumulated_original_weight,
        count(*) filter (
          where e.status = 'verified'
            and (e.verified_at at time zone 'Asia/Bangkok')::date between v_from and v_today
        ) as seven_day_export_count,
        coalesce(sum(e.original_weight_total - e.current_weight) filter (
          where e.status = 'verified'
            and (e.verified_at at time zone 'Asia/Bangkok')::date between v_from and v_today
        ), 0) as seven_day_loss_weight,
        coalesce(sum(e.original_weight_total) filter (
          where e.status = 'verified'
            and (e.verified_at at time zone 'Asia/Bangkok')::date between v_from and v_today
        ), 0) as seven_day_original_weight
      from public.rubber_exports e
      where e.location_id = p_location_id
    ),
    stock_balances as (
      select
        p.id,
        p.name,
        p.unit,
        round(coalesce(sum(m.quantity_delta), 0), 2) as balance
      from public.stock_products p
      left join public.stock_movements m
        on m.product_id = p.id
       and m.location_id = p_location_id
      where p.is_active = true
      group by p.id, p.name, p.unit
    ),
    stock_summary as (
      select
        count(*) filter (where balance > 0) as in_stock_count,
        count(*) filter (where balance <= 0) as out_of_stock_count,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'productId', id,
              'name', name,
              'unit', unit,
              'balance', balance
            )
            order by (balance <= 0) desc, name, id
          ),
          '[]'::jsonb
        ) as items
      from stock_balances
    ),
    financial_events as (
      select
        coalesce(ie.client_recorded_at, ie.created_at) as occurred_at,
        ie.tx_date as business_date,
        'actual:' || ie.id::text as sort_key,
        ie.id::text as id,
        ie.type::text as kind,
        coalesce(ie.number, ie.server_bill_no, ie.local_bill_no, left(ie.id::text, 8)) as number,
        ie.title,
        ie.type::text as direction,
        ie.cost as amount,
        ie.created_by_name,
        true as affects_balance,
        ie.type = 'expense' as operating_expense
      from public.income_expense ie
      where ie.location_id = p_location_id
        and ie.record_status = 'active'
        and ie.cost > 0

      union all

      select
        mt.created_at,
        (mt.created_at at time zone 'Asia/Bangkok')::date,
        'branch-transfer-in:' || mt.id::text,
        'branch-transfer-in:' || mt.id::text,
        'transfer_in',
        'TR-' || left(mt.id::text, 8),
        'รับโอนเงินเข้าสาขา',
        'income',
        mt.net_amount_to_pay,
        coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
        true,
        false
      from public.money_transfers mt
      where mt.transfer_type = 'branch'
        and coalesce(mt.transfer_method, 'bank') <> 'cash'
        and mt.target_location_id = p_location_id
        and mt.record_status <> 'deleted'
        and mt.transfer_status in ('paid', 'overpaid', 'branch_and_transfer')
        and mt.net_amount_to_pay > 0

      union all

      select
        mt.created_at,
        (mt.created_at at time zone 'Asia/Bangkok')::date,
        'branch-transfer-out:' || mt.id::text,
        'branch-transfer-out:' || mt.id::text,
        'transfer_out',
        'TR-' || left(mt.id::text, 8),
        'โยกเงินไป ' || coalesce(mt.target_location_name, 'สาขาปลายทาง'),
        'expense',
        mt.net_amount_to_pay,
        coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
        true,
        false
      from public.money_transfers mt
      where mt.transfer_type = 'branch'
        and coalesce(mt.transfer_method, 'bank') <> 'cash'
        and mt.location_id = p_location_id
        and mt.target_location_id <> mt.location_id
        and mt.record_status <> 'deleted'
        and mt.transfer_status in ('paid', 'overpaid', 'branch_and_transfer')
        and mt.net_amount_to_pay > 0

      union all

      select
        mt.created_at,
        (mt.created_at at time zone 'Asia/Bangkok')::date,
        'customer-branch-paid:' || mt.id::text,
        'customer-branch-paid:' || mt.id::text,
        'transfer_out',
        'CT-' || left(mt.id::text, 8),
        'สาขาจ่ายส่วนต่างให้ ' || coalesce(mt.customer_name, 'ลูกค้า'),
        'expense',
        mt.branch_paid_amount,
        coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
        true,
        false
      from public.money_transfers mt
      where mt.transfer_type = 'customer'
        and mt.transfer_status = 'branch_and_transfer'
        and mt.location_id = p_location_id
        and mt.record_status <> 'deleted'
        and mt.branch_paid_amount > 0

      union all

      select
        d.sent_at,
        (d.sent_at at time zone 'Asia/Bangkok')::date,
        'cash-transfer-out:' || mt.id::text,
        'cash-transfer-out:' || mt.id::text,
        'transfer_out',
        'CASH-' || left(mt.id::text, 8),
        'โยกเงินสดไป ' || coalesce(mt.target_location_name, 'สาขาปลายทาง'),
        'expense',
        d.sent_total,
        coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
        true,
        false
      from public.money_transfers mt
      join public.money_transfer_cash_details d on d.transfer_id = mt.id
      where mt.transfer_type = 'cash'
        and mt.transfer_method = 'cash'
        and mt.location_id = p_location_id
        and mt.record_status <> 'deleted'
        and d.sent_total > 0

      union all

      select
        d.received_at,
        (d.received_at at time zone 'Asia/Bangkok')::date,
        'cash-transfer-in:' || mt.id::text,
        'cash-transfer-in:' || mt.id::text,
        'transfer_in',
        'CASH-' || left(mt.id::text, 8),
        'รับโอนเงินสดเข้าสาขา',
        'income',
        d.received_total,
        coalesce(d.received_by_name, mt.created_by_name, 'ระบบโอนเงิน'),
        true,
        false
      from public.money_transfers mt
      join public.money_transfer_cash_details d on d.transfer_id = mt.id
      where mt.transfer_type = 'cash'
        and mt.transfer_method = 'cash'
        and mt.target_location_id = p_location_id
        and mt.record_status <> 'deleted'
        and d.cash_status in ('received', 'mismatched', 'difference_accepted')
        and d.received_total > 0

      union all

      select
        ft.approved_at,
        (ft.approved_at at time zone 'Asia/Bangkok')::date,
        'withdrawal:' || ft.id::text,
        'withdrawal:' || ft.id::text,
        'expense',
        'TW-' || left(ft.id::text, 8),
        'เบิกเงิน — ' || coalesce(p.name, 'พนักงาน') ||
          coalesce(': ' || nullif(ft.description, ''), ''),
        'expense',
        ft.amount,
        coalesce(p.name, 'พนักงาน'),
        true,
        true
      from public.financial_transactions ft
      join public.profiles p on p.id = ft.profile_id
      where ft.type = 'WITHDRAWAL'
        and ft.status = 'APPROVED'
        and ft.cancelled_at is null
        and ft.expense_location_id = p_location_id
        and ft.amount > 0

      union all

      select
        ps.approved_at,
        (ps.approved_at at time zone 'Asia/Bangkok')::date,
        'payroll:' || ps.id::text,
        'payroll:' || ps.id::text,
        'expense',
        'PS-' || left(ps.id::text, 8),
        'เงินเดือน — ' || coalesce(p.name, 'พนักงาน') || ' — ' || ps.month,
        'expense',
        ps.net_pay,
        coalesce(p.name, 'พนักงาน'),
        true,
        true
      from public.payroll_slips ps
      join public.profiles p on p.id = ps.profile_id
      where ps.status = 'APPROVED'
        and ps.cancelled_at is null
        and ps.expense_location_id = p_location_id
        and ps.net_pay > 0

      union all

      select
        coalesce(b.client_recorded_at, b.created_at),
        b.bill_date,
        'rubber-bill:' || b.id::text,
        'rubber-bill:' || b.id::text,
        'rubber_bill',
        coalesce(b.server_bill_no, nullif(b.local_bill_no, ''), nullif(b.bill_no, ''), left(b.id::text, 8)),
        'รับซื้อยาง — ' || coalesce(nullif(b.customer_name, ''), 'ไม่ระบุลูกค้า'),
        'expense',
        b.net_total,
        b.created_by_name,
        not exists (
          select 1
          from public.money_transfer_items i
          where i.source_type = 'rubber_bill'
            and i.source_id = b.id
        ),
        false
      from payable_bills b

      union all

      select
        e.verified_at,
        (e.verified_at at time zone 'Asia/Bangkok')::date,
        'rubber-export:' || e.id::text,
        'rubber-export:' || e.id::text,
        'rubber_export',
        e.export_no,
        'ค่าทำงานส่งออกยาง — ' || e.export_no,
        'expense',
        e.work_total,
        e.created_by_name,
        true,
        true
      from public.rubber_exports e
      where e.location_id = p_location_id
        and e.status = 'verified'
        and e.expense_destination = 'branch'
        and e.work_total > 0
    ),
    financial_totals as (
      select coalesce(sum(
        case
          when not affects_balance then 0
          when direction = 'income' then amount
          else -amount
        end
      ), 0) as net_cash_flow
      from financial_events
    ),
    operating_stats as (
      select coalesce(sum(amount), 0) as accumulated_expense
      from financial_events
      where operating_expense
    ),
    filtered_events as (
      select *
      from financial_events
      where p_cursor_at is null
         or (occurred_at, sort_key) < (p_cursor_at, p_cursor_key)
    ),
    numbered_events as (
      select
        *,
        row_number() over (order by occurred_at desc, sort_key desc) as row_no
      from filtered_events
    ),
    page as (
      select *
      from numbered_events
      where row_no <= v_page_size + 1
    )
    select jsonb_build_object(
      'summary', jsonb_build_object(
        'purchaseToday', jsonb_build_object(
          'billCount', ps.today_bill_count,
          'netWeight', round(ps.today_net_weight, 2),
          'paidTotal', round(ps.today_paid_total, 2)
        ),
        'purchase7Days', jsonb_build_object(
          'paidTotal', round(ps.seven_day_paid_total, 2),
          'dailyAverage', round(ps.seven_day_paid_total / 7, 2),
          'netWeight', round(ps.seven_day_net_weight, 2),
          'averageCostPerKg', case
            when ps.seven_day_net_weight > 0
              then round(ps.seven_day_paid_total / ps.seven_day_net_weight, 2)
            else null
          end
        ),
        'netCashFlow', round(ft.net_cash_flow, 2),
        'operatingExpenseAccumulated', round(os.accumulated_expense, 2),
        'rubberInventoryWeight', round(
          ps.accumulated_net_weight - es.accumulated_original_weight,
          2
        ),
        'waterLoss7Days', jsonb_build_object(
          'exportCount', es.seven_day_export_count,
          'weight', round(es.seven_day_loss_weight, 2),
          'percent', case
            when es.seven_day_original_weight > 0
              then round(es.seven_day_loss_weight / es.seven_day_original_weight * 100, 2)
            else null
          end
        ),
        'stock', jsonb_build_object(
          'inStockCount', ss.in_stock_count,
          'outOfStockCount', ss.out_of_stock_count,
          'items', ss.items
        )
      ),
      'rows', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', id,
            'kind', kind,
            'number', number,
            'title', title,
            'direction', direction,
            'amount', round(amount, 2),
            'occurredAt', occurred_at,
            'createdByName', created_by_name
          )
          order by occurred_at desc, sort_key desc
        )
        from page
        where row_no <= v_page_size
      ), '[]'::jsonb),
      'nextCursor', case
        when (select count(*) from page) > v_page_size then (
          select jsonb_build_object('at', occurred_at, 'key', sort_key)
          from page
          where row_no = v_page_size
        )
        else null
      end
    )
    from purchase_stats ps
    cross join export_stats es
    cross join stock_summary ss
    cross join financial_totals ft
    cross join operating_stats os
  );
end;
$$;


ALTER FUNCTION "public"."get_dashboard_overview"("p_location_id" "uuid", "p_cursor_at" timestamp with time zone, "p_cursor_key" "text", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_refresh_settings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  settings public.dashboard_refresh_settings%rowtype;
begin
  perform private.dashboard_require_manager();

  select *
  into strict settings
  from public.dashboard_refresh_settings
  where id = true;

  return jsonb_build_object(
    'intervalMinutes', settings.interval_minutes,
    'updatedAt', settings.updated_at,
    'updatedByName', settings.updated_by_name
  );
end;
$$;


ALTER FUNCTION "public"."get_dashboard_refresh_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_snapshot"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  snapshot public.dashboard_branch_snapshots%rowtype;
begin
  if not private.is_active_user()
    or not public.can_access_location(p_location_id)
  then
    raise exception 'Location access denied';
  end if;

  select *
  into snapshot
  from public.dashboard_branch_snapshots s
  where s.location_id = p_location_id;

  if snapshot.location_id is null then
    return jsonb_build_object(
      'status', 'dirty',
      'sourceVersion', 1,
      'snapshotVersion', 0,
      'summary', null,
      'calculatedAt', null,
      'manualRequestedAt', null,
      'lastError', null
    );
  end if;

  return jsonb_build_object(
    'status', snapshot.status,
    'sourceVersion', snapshot.source_version,
    'snapshotVersion', snapshot.snapshot_version,
    'summary', snapshot.summary,
    'calculatedAt', snapshot.calculated_at,
    'manualRequestedAt', snapshot.manual_requested_at,
    'lastError', snapshot.last_error
  );
end;
$$;


ALTER FUNCTION "public"."get_dashboard_snapshot"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_effective_rubber_approval_settings"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_effective record;
  v_non_current_date_requires_approval boolean;
begin
  if p_location_id is null
     or not private.is_active_user()
     or not private.can_access_location(p_location_id) then
    raise exception 'FORBIDDEN: ไม่มีสิทธิ์ดูการตั้งค่าของสาขานี้';
  end if;
  if not exists (
    select 1 from public.locations l
    where l.id = p_location_id and l.is_active = true
  ) then
    raise exception 'RUBBER_LOCATION_NOT_FOUND: ไม่พบสาขาที่ใช้งาน';
  end if;

  select * into v_effective
  from private.effective_rubber_approval_settings(p_location_id);
  select s.non_current_date_requires_approval
    into v_non_current_date_requires_approval
  from public.rubber_bill_approval_settings s
  where s.id = true;

  return jsonb_build_object(
    'locationId', p_location_id,
    'groupId', v_effective.group_id,
    'priceTimeExempt', v_effective.price_time_exempt,
    'editWindowMinutes', v_effective.edit_window_minutes,
    'configuredPrice', v_effective.configured_price,
    'nonCurrentDateRequiresApproval', coalesce(v_non_current_date_requires_approval, false),
    'updatedByName', v_effective.updated_by_name,
    'updatedByPhone', v_effective.updated_by_phone,
    'updatedAt', v_effective.updated_at
  );
end
$$;


ALTER FUNCTION "public"."get_effective_rubber_approval_settings"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_export_vehicle_weigh_bill_detail"("p_wex_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_wex public.export_vehicle_weigh_bills%rowtype;
  v_location_name text;
  v_vehicle_count integer;
  v_rubber_export_count integer;
  v_vehicle_net numeric(14,2);
  v_reserved_weight numeric(14,2);
  v_lines jsonb;
  v_rubber_exports jsonb;
begin
  select * into v_wex
  from public.export_vehicle_weigh_bills w
  where w.id = p_wex_id;
  if v_wex.id is null then
    raise exception 'WEX_NOT_FOUND: ไม่พบบิลรถส่งออก';
  end if;
  if not private.can_manage_reports(v_wex.location_id) then
    raise exception 'WEX_FORBIDDEN: ไม่มีสิทธิ์ดูบิลรถส่งออกของสาขานี้';
  end if;

  select l.name into v_location_name
  from public.locations l where l.id = v_wex.location_id;
  select count(*)::integer, coalesce(round(sum(l.net_weight), 2), 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'id', l.id,
      'sequenceNo', l.sequence_no,
      'vehicleRegistration', l.vehicle_registration,
      'carrierId', l.carrier_id,
      'carrierName', l.carrier_name,
      'inboundAt', l.inbound_at,
      'inboundWeight', l.inbound_weight,
      'outboundAt', l.outbound_at,
      'outboundWeight', l.outbound_weight,
      'netWeight', l.net_weight
    ) order by l.sequence_no), '[]'::jsonb)
  into v_vehicle_count, v_vehicle_net, v_lines
  from public.export_vehicle_weigh_lines l
  where l.wex_id = v_wex.id;

  select count(*)::integer, coalesce(round(sum(r.current_weight), 2), 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'rubberExportId', r.rubber_export_id,
      'exportNo', r.export_no,
      'currentWeight', r.current_weight
    ) order by r.sequence_no), '[]'::jsonb)
  into v_rubber_export_count, v_reserved_weight, v_rubber_exports
  from public.export_vehicle_weigh_bill_reservations r
  where r.wex_id = v_wex.id;

  return jsonb_build_object(
    'id', v_wex.id,
    'wexNo', v_wex.wex_no,
    'locationId', v_wex.location_id,
    'locationName', v_location_name,
    'revision', v_wex.revision,
    'vehicleCount', v_vehicle_count,
    'rubberExportCount', v_rubber_export_count,
    'vehicleNetWeight', v_vehicle_net,
    'reservedRubberWeight', v_reserved_weight,
    'remainingWeight', v_vehicle_net - v_reserved_weight,
    'createdByName', v_wex.created_by_name,
    'createdAt', v_wex.created_at,
    'updatedAt', v_wex.updated_at,
    'lines', v_lines,
    'rubberExports', v_rubber_exports
  );
end;
$$;


ALTER FUNCTION "public"."get_export_vehicle_weigh_bill_detail"("p_wex_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_export_vehicle_weigh_bill_options"("p_location_id" "uuid", "p_wex_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("rubber_export_id" "uuid", "export_no" "text", "current_weight" numeric, "reserved_by_current_wex" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_wex_location_id uuid;
begin
  if p_location_id is null or not private.can_manage_reports(p_location_id) then
    raise exception 'WEX_FORBIDDEN: ไม่มีสิทธิ์ดูรายการขายยางของสาขานี้';
  end if;
  if p_wex_id is not null then
    select w.location_id into v_wex_location_id
    from public.export_vehicle_weigh_bills w
    where w.id = p_wex_id;
    if v_wex_location_id is null then
      raise exception 'WEX_NOT_FOUND: ไม่พบบิลรถส่งออก';
    end if;
    if v_wex_location_id <> p_location_id then
      raise exception 'WEX_FORBIDDEN: บิลรถส่งออกไม่อยู่ในสาขานี้';
    end if;
  end if;

  return query
  select
    e.id, e.export_no, e.current_weight,
    coalesce(r.wex_id = p_wex_id, false)
  from public.rubber_exports e
  left join public.export_vehicle_weigh_bill_reservations r
    on r.rubber_export_id = e.id
  where e.location_id = p_location_id
    and e.status = 'verified'
    and e.sold_out_at is not null
    and e.current_weight is not null
    and e.current_weight > 0
    and (r.id is null or r.wex_id = p_wex_id)
  order by e.sold_out_at desc, e.id desc;
end;
$$;


ALTER FUNCTION "public"."get_export_vehicle_weigh_bill_options"("p_location_id" "uuid", "p_wex_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_income_expense_feed"("p_location_id" "uuid", "p_from_date" "date", "p_to_date" "date", "p_cursor_date" "date" DEFAULT NULL::"date", "p_cursor_key" "text" DEFAULT NULL::"text", "p_page_size" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_page_size integer := least(greatest(coalesce(p_page_size, 100), 1), 100);
begin
  if not private.is_active_user() or not public.can_access_location(p_location_id) then
    raise exception 'Location access denied';
  end if;
  if p_from_date is null or p_to_date is null or p_from_date > p_to_date then
    raise exception 'Invalid date range';
  end if;

  return (
    with feed as (
      select ie.tx_date as sort_date, 'actual:' || ie.id::text as sort_key,
        jsonb_strip_nulls(jsonb_build_object(
          'id', ie.id, 'clientTempId', coalesce(ie.client_temp_id, ie.id::text),
          'localBillNo', ie.local_bill_no, 'serverBillNo', ie.server_bill_no,
          'idempotencyKey', coalesce(ie.idempotency_key, 'server:' || ie.id::text),
          'locationId', ie.location_id, 'syncStatus', 'synced', 'recordStatus', ie.record_status,
          'type', ie.type, 'number', coalesce(ie.number, ie.server_bill_no, ie.local_bill_no),
          'txDate', ie.tx_date, 'title', ie.title, 'cost', ie.cost, 'unit', ie.unit,
          'price', ie.price, 'incomeSaleItemId', ie.income_sale_item_id,
          'stockProductId', ie.stock_product_id, 'stockQuantity', ie.stock_quantity,
          'billOption', ie.bill_option, 'clientRecordedAt', coalesce(ie.client_recorded_at, ie.created_at),
          'clientCreatedAt', coalesce(ie.client_created_at, ie.created_at),
          'serverReceivedAt', ie.server_received_at, 'revisionNo', ie.revision_no,
          'createdByUserId', ie.created_by_user_id, 'createdByName', ie.created_by_name,
          'createdByPhone', ie.created_by_phone
        )) as row_data
      from public.income_expense ie
      where ie.location_id = p_location_id and ie.record_status = 'active'
        and ie.tx_date between p_from_date and p_to_date

      union all

      select (mt.created_at at time zone 'Asia/Bangkok')::date, 'transfer-income:' || mt.id::text,
        jsonb_build_object(
          'id', 'money-transfer-income:' || mt.id, 'clientTempId', 'money-transfer-income:' || mt.id,
          'localBillNo', 'TR-' || left(mt.id::text, 8), 'serverBillNo', 'TR-' || left(mt.id::text, 8),
          'idempotencyKey', 'money-transfer:' || mt.id, 'locationId', mt.target_location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'income',
          'number', 'TR-' || left(mt.id::text, 8), 'txDate', (mt.created_at at time zone 'Asia/Bangkok')::date,
          'title', 'รับโอนจาก สาขาต้นทาง', 'cost', mt.net_amount_to_pay, 'billOption', 'รายรับ',
          'clientRecordedAt', mt.created_at, 'clientCreatedAt', mt.created_at,
          'serverReceivedAt', mt.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', case when mt.location_id = mt.target_location_id then 'โอนให้สาขา' else 'โอนเงินสาขา' end,
          'relationLockReason', 'รายการนี้มาจากการโอนเงินสาขา ต้องแก้ไขหรือลบที่โมดูลโอนเงินต้นทาง'
        )
      from public.money_transfers mt
      where mt.transfer_type = 'branch' and mt.target_location_id = p_location_id
        and mt.record_status <> 'deleted' and mt.transfer_status <> 'cancelled'
        and mt.net_amount_to_pay > 0 and (mt.created_at at time zone 'Asia/Bangkok')::date between p_from_date and p_to_date

      union all

      select (mt.created_at at time zone 'Asia/Bangkok')::date, 'transfer-expense:' || mt.id::text,
        jsonb_build_object(
          'id', 'money-transfer-branch-expense:' || mt.id, 'clientTempId', 'money-transfer-branch-expense:' || mt.id,
          'localBillNo', 'TR-' || left(mt.id::text, 8), 'serverBillNo', 'TR-' || left(mt.id::text, 8),
          'idempotencyKey', 'money-transfer-branch-expense:' || mt.id, 'locationId', mt.location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'TR-' || left(mt.id::text, 8), 'txDate', (mt.created_at at time zone 'Asia/Bangkok')::date,
          'title', 'โยกเงินไป ' || coalesce(mt.target_location_name, 'สาขาปลายทาง'),
          'cost', mt.net_amount_to_pay, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', mt.created_at, 'clientCreatedAt', mt.created_at,
          'serverReceivedAt', mt.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', 'โอนเงินสาขา',
          'relationLockReason', 'รายการนี้มาจากการโอนเงินสาขา ต้องแก้ไขหรือลบที่โมดูลโอนเงินต้นทาง'
        )
      from public.money_transfers mt
      where mt.transfer_type = 'branch' and mt.location_id = p_location_id
        and mt.target_location_id <> mt.location_id and mt.record_status <> 'deleted'
        and mt.transfer_status <> 'cancelled' and mt.net_amount_to_pay > 0
        and (mt.created_at at time zone 'Asia/Bangkok')::date between p_from_date and p_to_date

      union all

      select (d.sent_at at time zone 'Asia/Bangkok')::date, 'cash-transfer-expense:' || mt.id::text,
        jsonb_build_object(
          'id', 'cash-transfer-expense:' || mt.id, 'clientTempId', 'cash-transfer-expense:' || mt.id,
          'localBillNo', 'CASH-' || left(mt.id::text, 8), 'serverBillNo', 'CASH-' || left(mt.id::text, 8),
          'idempotencyKey', 'cash-transfer-expense:' || mt.id, 'locationId', mt.location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'CASH-' || left(mt.id::text, 8),
          'txDate', (d.sent_at at time zone 'Asia/Bangkok')::date,
          'title', 'โยกเงินสดไป ' || coalesce(mt.target_location_name, 'สาขาปลายทาง'),
          'cost', d.sent_total, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', d.sent_at, 'clientCreatedAt', d.sent_at,
          'serverReceivedAt', d.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', mt.created_by_name,
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', 'cash:' || mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', case d.cash_status
            when 'pending_receipt' then 'รอรับเงิน'
            when 'received' then 'รับเงินแล้ว'
            when 'mismatched' then 'ยอดไม่ตรง ' || case when d.difference_total >= 0 then '+฿' else '-฿' end || trim(to_char(abs(d.difference_total), 'FM999999999990'))
            else 'ยอมรับผลต่าง ' || case when d.difference_total >= 0 then '+฿' else '-฿' end || trim(to_char(abs(d.difference_total), 'FM999999999990'))
          end,
          'relationLockReason', 'รายการนี้มาจากการโยกเงินสด ต้องเปิดรายละเอียดเพื่อดูข้อมูล'
        )
      from public.money_transfers mt
      join public.money_transfer_cash_details d on d.transfer_id = mt.id
      where mt.transfer_type = 'cash' and mt.transfer_method = 'cash'
        and mt.location_id = p_location_id and mt.record_status <> 'deleted'
        and (d.sent_at at time zone 'Asia/Bangkok')::date between p_from_date and p_to_date

      union all

      select (d.received_at at time zone 'Asia/Bangkok')::date, 'cash-transfer-income:' || mt.id::text,
        jsonb_build_object(
          'id', 'cash-transfer-income:' || mt.id, 'clientTempId', 'cash-transfer-income:' || mt.id,
          'localBillNo', 'CASH-' || left(mt.id::text, 8), 'serverBillNo', 'CASH-' || left(mt.id::text, 8),
          'idempotencyKey', 'cash-transfer-income:' || mt.id, 'locationId', mt.target_location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'income',
          'number', 'CASH-' || left(mt.id::text, 8),
          'txDate', (d.received_at at time zone 'Asia/Bangkok')::date,
          'title', 'รับโอนเงินสดจากสาขาต้นทาง',
          'cost', d.received_total, 'billOption', 'รายรับ',
          'clientRecordedAt', d.received_at, 'clientCreatedAt', d.received_at,
          'serverReceivedAt', d.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', mt.created_by_name,
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', 'cash:' || mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', case d.cash_status
            when 'received' then 'รับเงินแล้ว'
            when 'mismatched' then 'ยอดไม่ตรง ' || case when d.difference_total >= 0 then '+฿' else '-฿' end || trim(to_char(abs(d.difference_total), 'FM999999999990'))
            else 'ยอมรับผลต่าง ' || case when d.difference_total >= 0 then '+฿' else '-฿' end || trim(to_char(abs(d.difference_total), 'FM999999999990'))
          end,
          'relationLockReason', 'รายการนี้มาจากการโยกเงินสด ต้องเปิดรายละเอียดเพื่อดูข้อมูล'
        )
      from public.money_transfers mt
      join public.money_transfer_cash_details d on d.transfer_id = mt.id
      where mt.transfer_type = 'cash' and mt.transfer_method = 'cash'
        and mt.target_location_id = p_location_id and mt.record_status <> 'deleted'
        and d.cash_status in ('received', 'mismatched', 'difference_accepted')
        and (d.received_at at time zone 'Asia/Bangkok')::date between p_from_date and p_to_date

      union all

      select (mt.created_at at time zone 'Asia/Bangkok')::date, 'customer-transfer-expense:' || mt.id::text,
        jsonb_build_object(
          'id', 'money-transfer-branch-paid-expense:' || mt.id, 'clientTempId', 'money-transfer-branch-paid-expense:' || mt.id,
          'localBillNo', 'CT-' || left(mt.id::text, 8), 'serverBillNo', 'CT-' || left(mt.id::text, 8),
          'idempotencyKey', 'money-transfer-branch-paid:' || mt.id, 'locationId', mt.location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'CT-' || left(mt.id::text, 8), 'txDate', (mt.created_at at time zone 'Asia/Bangkok')::date,
          'title', 'สาขาจ่ายส่วนต่างให้ ' || coalesce(mt.customer_name, 'ลูกค้า'),
          'cost', mt.branch_paid_amount, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', mt.created_at, 'clientCreatedAt', mt.created_at,
          'serverReceivedAt', mt.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', 'โอน+สาขาจ่าย',
          'relationLockReason', 'รายการนี้มาจากโอนเงินลูกค้าแบบโอน+สาขาจ่าย ต้องแก้ไขหรือลบที่โมดูลโอนเงินลูกค้าต้นทาง'
        )
      from public.money_transfers mt
      where mt.transfer_type = 'customer' and mt.transfer_status = 'branch_and_transfer'
        and mt.location_id = p_location_id and mt.record_status <> 'deleted'
        and mt.branch_paid_amount > 0 and (mt.created_at at time zone 'Asia/Bangkok')::date between p_from_date and p_to_date

      union all

      select (ft.approved_at at time zone 'Asia/Bangkok')::date, 'time-tracking-withdrawal:' || ft.id::text,
        jsonb_build_object(
          'id', 'time-tracking-withdrawal:' || ft.id, 'clientTempId', 'time-tracking-withdrawal:' || ft.id,
          'localBillNo', 'TW-' || left(ft.id::text, 8), 'serverBillNo', 'TW-' || left(ft.id::text, 8),
          'idempotencyKey', 'time-tracking-withdrawal:' || ft.id, 'locationId', ft.expense_location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'TW-' || left(ft.id::text, 8), 'txDate', (ft.approved_at at time zone 'Asia/Bangkok')::date,
          'title', 'เบิกเงิน — ' || coalesce(p.name, 'พนักงาน') || coalesce(': ' || nullif(ft.description, ''), ''),
          'cost', ft.amount, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', ft.approved_at, 'clientCreatedAt', ft.created_at,
          'serverReceivedAt', ft.updated_at, 'revisionNo', 1,
          'createdByUserId', ft.profile_id, 'createdByName', coalesce(p.name, 'พนักงาน'), 'createdByPhone', '',
          'relationSourceType', 'time_tracking_withdrawal', 'relationSourceId', ft.id,
          'relationSourceLocationId', ft.expense_location_id, 'relationLabel', 'เบิกเงิน',
          'relationLockReason', 'รายการนี้มาจากการเบิกเงินที่อนุมัติแล้ว ต้องแก้ไขสาขาหรือยกเลิกที่โมดูลลงเวลาต้นทาง'
        )
      from public.financial_transactions ft
      join public.profiles p on p.id = ft.profile_id
      where ft.type = 'WITHDRAWAL' and ft.status = 'APPROVED'
        and ft.cancelled_at is null and ft.expense_location_id = p_location_id and ft.amount > 0
        and (ft.approved_at at time zone 'Asia/Bangkok')::date between p_from_date and p_to_date

      union all

      select (ps.approved_at at time zone 'Asia/Bangkok')::date, 'payroll-slip:' || ps.id::text,
        jsonb_build_object(
          'id', 'payroll-slip:' || ps.id, 'clientTempId', 'payroll-slip:' || ps.id,
          'localBillNo', 'PS-' || left(ps.id::text, 8), 'serverBillNo', 'PS-' || left(ps.id::text, 8),
          'idempotencyKey', 'payroll-slip:' || ps.id, 'locationId', ps.expense_location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'PS-' || left(ps.id::text, 8), 'txDate', (ps.approved_at at time zone 'Asia/Bangkok')::date,
          'title', 'เงินเดือน — ' || coalesce(p.name, 'พนักงาน') || ' — ' || ps.month,
          'cost', ps.net_pay, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', ps.approved_at, 'clientCreatedAt', ps.created_at,
          'serverReceivedAt', ps.updated_at, 'revisionNo', 1,
          'createdByUserId', ps.profile_id, 'createdByName', coalesce(p.name, 'พนักงาน'), 'createdByPhone', '',
          'relationSourceType', 'payroll_slip', 'relationSourceId', ps.id,
          'relationSourceLocationId', ps.expense_location_id, 'relationLabel', 'เงินเดือน',
          'relationLockReason', 'รายการนี้มาจากเงินเดือนที่อนุมัติแล้ว ต้องแก้ไขสาขาหรือยกเลิกที่โมดูลลงเวลาต้นทาง'
        )
      from public.payroll_slips ps
      join public.profiles p on p.id = ps.profile_id
      where ps.status = 'APPROVED' and ps.net_pay > 0 and ps.cancelled_at is null
        and ps.expense_location_id = p_location_id
        and (ps.approved_at at time zone 'Asia/Bangkok')::date between p_from_date and p_to_date

      union all

      select (e.verified_at at time zone 'Asia/Bangkok')::date,
        'rubber-export-expense:' || e.id::text,
        jsonb_build_object(
          'id', 'rubber-export-expense:' || e.id,
          'clientTempId', 'rubber-export-expense:' || e.id,
          'localBillNo', e.export_no,
          'serverBillNo', e.export_no,
          'idempotencyKey', 'rubber-export-expense:' || e.id,
          'locationId', e.location_id,
          'syncStatus', 'synced',
          'recordStatus', 'active',
          'type', 'expense',
          'number', e.export_no,
          'txDate', (e.verified_at at time zone 'Asia/Bangkok')::date,
          'title', 'ค่าทำงานส่งออกยาง — ' || e.export_no,
          'cost', e.work_total,
          'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', e.verified_at,
          'clientCreatedAt', e.created_at,
          'serverReceivedAt', e.verified_at,
          'revisionNo', 1,
          'createdByUserId', e.created_by_user_id,
          'createdByName', e.created_by_name,
          'createdByPhone', e.created_by_phone,
          'relationSourceType', 'rubber_export',
          'relationSourceId', e.id,
          'relationSourceLocationId', e.location_id,
          'relationLabel', 'ส่งออกยาง',
          'relationLockReason', 'รายการนี้มาจากรายการส่งออกยาง ต้องเปิดหรือจัดการที่โมดูลส่งออกยางต้นทาง'
        )
      from public.rubber_exports e
      where e.location_id = p_location_id
        and e.status = 'verified'
        and e.expense_destination = 'branch'
        and e.work_total > 0
        and (e.verified_at at time zone 'Asia/Bangkok')::date between p_from_date and p_to_date

      union all

      select rb.bill_date, 'rubber:' || rb.bill_date::text,
        jsonb_build_object(
          'id', 'rubber-bill-daily-expense:' || p_location_id || ':' || rb.bill_date,
          'clientTempId', 'rubber-bill-daily-expense:' || p_location_id || ':' || rb.bill_date,
          'localBillNo', 'RB-' || to_char(rb.bill_date, 'YYMMDD'), 'serverBillNo', 'RB-' || to_char(rb.bill_date, 'YYMMDD'),
          'idempotencyKey', 'rubber-bill-daily-expense:' || p_location_id || ':' || rb.bill_date,
          'locationId', p_location_id, 'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'RB-' || to_char(rb.bill_date, 'YYMMDD'), 'txDate', rb.bill_date,
          'title', 'จ่ายค่ายางจากบิลยาง ' || rb.bill_count || ' ใบ', 'cost', rb.total,
          'billOption', 'ค่าใช้จ่าย', 'clientRecordedAt', rb.recorded_at, 'clientCreatedAt', rb.recorded_at,
          'serverReceivedAt', rb.updated_at, 'revisionNo', rb.revision_no,
          'createdByUserId', '', 'createdByName', 'ระบบบิลยาง', 'createdByPhone', '',
          'relationSourceType', 'rubber_bill_daily', 'relationSourceId', rb.bill_date,
          'relationSourceLocationId', p_location_id, 'relationSourceDate', rb.bill_date,
          'relationLabel', 'บิลยางรวมรายวัน',
          'relationLockReason', 'รายการนี้มาจากบิลยาง ต้องแก้ไขหรือลบที่โมดูลบิลยางต้นทาง'
        )
      from (
        select bill_date, sum(net_total) as total, count(*) as bill_count,
          max(coalesce(client_recorded_at, updated_at, created_at)) as recorded_at,
          max(updated_at) as updated_at, max(revision_no) as revision_no
        from public.rubber_bills rb
        where rb.location_id = p_location_id and rb.record_status = 'active' and rb.net_total > 0
          and private.rubber_bill_is_payable(rb.id)
          and rb.bill_date between p_from_date and p_to_date
          and not exists (select 1 from public.money_transfer_items i where i.source_type = 'rubber_bill' and i.source_id = rb.id)
        group by bill_date
      ) rb
    ), filtered as (
      select *, row_number() over (order by sort_date desc, sort_key desc) as row_no
      from feed
      where p_cursor_date is null or (sort_date, sort_key) < (p_cursor_date, p_cursor_key)
    ), page as (
      select * from filtered where row_no <= v_page_size + 1
    )
    select jsonb_build_object(
      'rows', coalesce((select jsonb_agg(row_data order by sort_date desc, sort_key desc) from page where row_no <= v_page_size), '[]'::jsonb),
      'nextCursor', case when (select count(*) from page) > v_page_size then
        encode(convert_to((select sort_date::text || '|' || sort_key from page where row_no = v_page_size), 'utf8'), 'base64')
      else null end
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_income_expense_feed"("p_location_id" "uuid", "p_from_date" "date", "p_to_date" "date", "p_cursor_date" "date", "p_cursor_key" "text", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_income_expense_operational_feed"("p_location_id" "uuid", "p_mode" "text" DEFAULT 'latest'::"text", "p_search" "text" DEFAULT ''::"text", "p_cursor" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $_$
declare
  v_search text := lower(regexp_replace(btrim(coalesce(p_search, '')), '\s+', ' ', 'g'));
  v_cursor jsonb;
  v_cursor_date date;
  v_cursor_key text;
  v_pending_count integer := 0;
begin
  if p_mode <> 'latest' or v_search <> '' then
    return public.get_income_expense_operational_feed_on_demand(
      p_location_id, p_mode, v_search, p_cursor
    );
  end if;

  if not private.is_active_user() or not private.can_access_location(p_location_id) then
    raise exception 'Location access denied';
  end if;

  if p_cursor is not null then
    begin
      if length(p_cursor) > 4096 or length(p_cursor) % 2 <> 0 or p_cursor !~ '^[0-9a-f]+$' then
        raise exception 'Invalid cursor';
      end if;
      v_cursor := convert_from(decode(p_cursor, 'hex'), 'utf8')::jsonb;
    exception when others then raise exception 'Invalid cursor'; end;
    if coalesce((v_cursor->>'v')::integer, 0) <> 1
      or v_cursor->>'locationId' is distinct from p_location_id::text
      or v_cursor->>'mode' is distinct from 'latest'
      or v_cursor->>'search' is distinct from ''
      or v_cursor->>'sort' is distinct from 'tx_date_desc'
    then raise exception 'Cursor scope mismatch'; end if;
    begin
      v_cursor_date := (v_cursor->>'date')::date;
      v_cursor_key := nullif(v_cursor->>'key', '');
      if v_cursor_key is null then raise exception 'Invalid cursor'; end if;
    exception when others then raise exception 'Invalid cursor'; end;
  end if;

  if private.can_access_super_admin_features() then
    select
      (select count(*) from public.income_expense_approval_requests r
       where r.location_id = p_location_id and r.request_status = 'pending')
      +
      (select count(*) from public.cash_transfer_delete_requests r
       where r.source_location_id = p_location_id and r.request_status = 'pending')
    into v_pending_count;
  end if;

  return (
    with candidates as (
      select * from (
        select 'actual'::text source_kind, ie.id source_id, null::date source_date,
          ie.tx_date sort_date, 'actual:' || ie.id::text sort_key
        from public.income_expense ie
        where ie.location_id = p_location_id and ie.record_status = 'active'
          and (v_cursor_date is null or (ie.tx_date, 'actual:' || ie.id::text) < (v_cursor_date, v_cursor_key))
        order by ie.tx_date desc, ('actual:' || ie.id::text) desc limit 101
      ) actual
      union all
      select * from (
        select 'branch_income', mt.id, null::date,
          coalesce(mt.accounting_date, (mt.created_at at time zone 'Asia/Bangkok')::date) d,
          'transfer-income:' || mt.id::text k
        from public.money_transfers mt
        where mt.transfer_type = 'branch' and mt.target_location_id = p_location_id
          and mt.record_status <> 'deleted' and mt.transfer_status <> 'cancelled' and mt.net_amount_to_pay > 0
          and (v_cursor_date is null or (coalesce(mt.accounting_date,
            (mt.created_at at time zone 'Asia/Bangkok')::date),
            'transfer-income:' || mt.id::text) < (v_cursor_date, v_cursor_key))
        order by d desc, k desc limit 101
      ) branch_income
      union all
      select * from (
        select 'branch_expense', mt.id, null::date,
          coalesce(mt.accounting_date, (mt.created_at at time zone 'Asia/Bangkok')::date) d,
          'transfer-expense:' || mt.id::text k
        from public.money_transfers mt
        where mt.transfer_type = 'branch' and mt.location_id = p_location_id
          and mt.target_location_id <> mt.location_id and mt.record_status <> 'deleted'
          and mt.transfer_status <> 'cancelled' and mt.net_amount_to_pay > 0
          and (v_cursor_date is null or (coalesce(mt.accounting_date,
            (mt.created_at at time zone 'Asia/Bangkok')::date),
            'transfer-expense:' || mt.id::text) < (v_cursor_date, v_cursor_key))
        order by d desc, k desc limit 101
      ) branch_expense
      union all
      select * from (
        select 'customer_branch_paid', mt.id, null::date,
          (mt.created_at at time zone 'Asia/Bangkok')::date d, 'customer-transfer-expense:' || mt.id::text k
        from public.money_transfers mt
        where mt.transfer_type = 'customer' and mt.transfer_status = 'branch_and_transfer'
          and mt.location_id = p_location_id and mt.record_status <> 'deleted' and mt.branch_paid_amount > 0
          and (v_cursor_date is null or ((mt.created_at at time zone 'Asia/Bangkok')::date,
            'customer-transfer-expense:' || mt.id::text) < (v_cursor_date, v_cursor_key))
        order by d desc, k desc limit 101
      ) customer_branch_paid
      union all
      select * from (
        select 'cash_expense', mt.id, null::date,
          (d.sent_at at time zone 'Asia/Bangkok')::date sd, 'cash-transfer-expense:' || mt.id::text k
        from public.money_transfers mt join public.money_transfer_cash_details d on d.transfer_id = mt.id
        where mt.transfer_type = 'cash' and mt.transfer_method = 'cash'
          and mt.location_id = p_location_id and mt.record_status <> 'deleted'
          and (v_cursor_date is null or ((d.sent_at at time zone 'Asia/Bangkok')::date,
            'cash-transfer-expense:' || mt.id::text) < (v_cursor_date, v_cursor_key))
        order by sd desc, k desc limit 101
      ) cash_expense
      union all
      select * from (
        select 'cash_income', mt.id, null::date,
          (d.received_at at time zone 'Asia/Bangkok')::date rd, 'cash-transfer-income:' || mt.id::text k
        from public.money_transfers mt join public.money_transfer_cash_details d on d.transfer_id = mt.id
        where mt.transfer_type = 'cash' and mt.transfer_method = 'cash'
          and mt.target_location_id = p_location_id and mt.record_status <> 'deleted'
          and d.cash_status in ('received', 'mismatched', 'difference_accepted')
          and d.received_at is not null
          and (v_cursor_date is null or ((d.received_at at time zone 'Asia/Bangkok')::date,
            'cash-transfer-income:' || mt.id::text) < (v_cursor_date, v_cursor_key))
        order by rd desc, k desc limit 101
      ) cash_income
      union all
      select * from (
        select 'withdrawal', ft.id, null::date,
          (ft.approved_at at time zone 'Asia/Bangkok')::date d, 'time-tracking-withdrawal:' || ft.id::text k
        from public.financial_transactions ft
        where ft.type = 'WITHDRAWAL' and ft.status = 'APPROVED' and ft.cancelled_at is null
          and ft.expense_location_id = p_location_id and ft.amount > 0
          and (v_cursor_date is null or ((ft.approved_at at time zone 'Asia/Bangkok')::date,
            'time-tracking-withdrawal:' || ft.id::text) < (v_cursor_date, v_cursor_key))
        order by d desc, k desc limit 101
      ) withdrawal
      union all
      select * from (
        select 'payroll', ps.id, null::date,
          (ps.approved_at at time zone 'Asia/Bangkok')::date d, 'payroll-slip:' || ps.id::text k
        from public.payroll_slips ps
        where ps.status = 'APPROVED' and ps.net_pay > 0 and ps.cancelled_at is null
          and ps.expense_location_id = p_location_id
          and (v_cursor_date is null or ((ps.approved_at at time zone 'Asia/Bangkok')::date,
            'payroll-slip:' || ps.id::text) < (v_cursor_date, v_cursor_key))
        order by d desc, k desc limit 101
      ) payroll
      union all
      select * from (
        select 'rubber_export', e.id, null::date,
          (e.verified_at at time zone 'Asia/Bangkok')::date d, 'rubber-export-expense:' || e.id::text k
        from public.rubber_exports e
        where e.location_id = p_location_id and e.status = 'verified'
          and e.expense_destination = 'branch' and e.work_total > 0
          and (v_cursor_date is null or ((e.verified_at at time zone 'Asia/Bangkok')::date,
            'rubber-export-expense:' || e.id::text) < (v_cursor_date, v_cursor_key))
        order by d desc, k desc limit 101
      ) rubber_export
      union all
      select * from (
        select 'rubber_daily', null::uuid, b.bill_date, b.bill_date d, 'rubber:' || b.bill_date::text k
        from public.rubber_bills b
        where b.location_id = p_location_id and b.record_status = 'active' and b.net_total > 0
          and private.rubber_bill_is_payable(b.id)
          and not exists (select 1 from public.money_transfer_items i
            where i.source_type = 'rubber_bill' and i.source_id = b.id)
          and (v_cursor_date is null or (b.bill_date, 'rubber:' || b.bill_date::text) < (v_cursor_date, v_cursor_key))
        group by b.bill_date order by d desc, k desc limit 101
      ) rubber_daily
    ), page as (
      select * from candidates order by sort_date desc, sort_key desc limit 101
    ), numbered as (
      select *, row_number() over (order by sort_date desc, sort_key desc) row_no from page
    ), rows as (
      select n.*, private.income_expense_operational_row(
        p_location_id, n.source_kind, n.source_id, n.source_date
      ) row_data
      from numbered n where n.row_no <= 100
    )
    select jsonb_build_object(
      'rows', coalesce((select jsonb_agg(row_data order by sort_date desc, sort_key desc) from rows), '[]'::jsonb),
      'nextCursor', case when (select count(*) from numbered) > 100 then
        (select encode(convert_to(jsonb_build_object(
          'v', 1, 'locationId', p_location_id, 'mode', 'latest', 'search', '',
          'sort', 'tx_date_desc', 'date', sort_date, 'key', sort_key
        )::text, 'utf8'), 'hex') from numbered where row_no = 100)
        else null end,
      'hasMore', (select count(*) from numbered) > 100,
      'pendingApprovalCount', v_pending_count
    )
  );
end;
$_$;


ALTER FUNCTION "public"."get_income_expense_operational_feed"("p_location_id" "uuid", "p_mode" "text", "p_search" "text", "p_cursor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_income_expense_operational_feed_on_demand"("p_location_id" "uuid", "p_mode" "text" DEFAULT 'latest'::"text", "p_search" "text" DEFAULT ''::"text", "p_cursor" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $_$
declare
  v_search text := lower(regexp_replace(btrim(coalesce(p_search, '')), '\s+', ' ', 'g'));
  v_can_manage boolean := private.can_access_super_admin_features();
  v_pending_count integer := 0;
  v_cursor jsonb;
  v_cursor_date date;
  v_cursor_at timestamptz;
  v_cursor_key text;
begin
  if not private.is_active_user() or not private.can_access_location(p_location_id) then
    raise exception 'Location access denied';
  end if;
  if p_mode not in ('latest', 'pending_approval') then
    raise exception 'Invalid feed mode';
  end if;
  if length(v_search) > 200 then
    raise exception 'Invalid search';
  end if;
  if p_mode = 'pending_approval' and not coalesce(v_can_manage, false) then
    raise exception 'Approval access denied';
  end if;

  if p_cursor is not null then
    begin
      if length(p_cursor) > 4096
        or length(p_cursor) % 2 <> 0
        or p_cursor !~ '^[0-9a-f]+$'
      then
        raise exception 'Invalid cursor';
      end if;
      v_cursor := convert_from(decode(p_cursor, 'hex'), 'utf8')::jsonb;
    exception when others then
      raise exception 'Invalid cursor';
    end;

    if coalesce((v_cursor->>'v')::integer, 0) <> 1
      or v_cursor->>'locationId' is distinct from p_location_id::text
      or v_cursor->>'mode' is distinct from p_mode
      or v_cursor->>'search' is distinct from v_search
      or v_cursor->>'sort' is distinct from
        (case when p_mode = 'latest' then 'tx_date_desc' else 'requested_at_asc' end)
    then
      raise exception 'Cursor scope mismatch';
    end if;

    begin
      v_cursor_key := nullif(v_cursor->>'key', '');
      if p_mode = 'latest' then
        v_cursor_date := (v_cursor->>'date')::date;
      else
        v_cursor_at := (v_cursor->>'at')::timestamptz;
      end if;
      if v_cursor_key is null then raise exception 'Invalid cursor'; end if;
    exception when others then
      raise exception 'Invalid cursor';
    end;
  end if;

  if coalesce(v_can_manage, false) then
    select
      (select count(*) from public.income_expense_approval_requests r
       where r.location_id = p_location_id and r.request_status = 'pending')
      +
      (select count(*) from public.cash_transfer_delete_requests r
       where r.source_location_id = p_location_id and r.request_status = 'pending')
    into v_pending_count;
  end if;

  if p_mode = 'pending_approval' then
    return (
      with candidates as (
        select
          r.created_at as sort_at,
          'income:' || r.id::text as sort_key,
          lower(regexp_replace(concat_ws(' ',
            coalesce(r.requested_payload->>'number', r.requested_payload->>'serverBillNo', r.requested_payload->>'localBillNo'),
            coalesce(r.requested_payload->>'txDate', (r.created_at at time zone 'Asia/Bangkok')::date::text),
            r.title, coalesce(r.requested_payload->>'billOption', r.tx_type),
            r.requested_by_name, r.requested_by_phone
          ), '\s+', ' ', 'g')) as search_text,
          jsonb_strip_nulls(jsonb_build_object(
            'id', 'approval-income:' || r.id,
            'clientTempId', coalesce(r.requested_payload->>'clientTempId', r.id::text),
            'localBillNo', coalesce(r.requested_payload->>'localBillNo', 'REQ-' || left(r.id::text, 8)),
            'serverBillNo', r.requested_payload->>'serverBillNo',
            'idempotencyKey', r.request_idempotency_key,
            'locationId', r.location_id,
            'syncStatus', 'pending', 'recordStatus', 'active',
            'type', r.tx_type,
            'number', coalesce(r.requested_payload->>'number', r.requested_payload->>'serverBillNo', r.requested_payload->>'localBillNo', 'REQ-' || left(r.id::text, 8)),
            'txDate', case when coalesce(r.requested_payload->>'txDate', '') ~ '^\d{4}-\d{2}-\d{2}$'
              then r.requested_payload->>'txDate'
              else (r.created_at at time zone 'Asia/Bangkok')::date::text end,
            'title', r.title, 'cost', r.cost,
            'billOption', coalesce(r.requested_payload->>'billOption', case when r.tx_type = 'income' then 'รายรับ' else 'ค่าใช้จ่าย' end),
            'clientRecordedAt', coalesce(r.requested_payload->>'clientRecordedAt', r.created_at::text),
            'clientCreatedAt', coalesce(r.requested_payload->>'clientCreatedAt', r.created_at::text),
            'serverReceivedAt', r.created_at,
            'revisionNo', coalesce((r.requested_payload->>'expectedRevisionNo')::integer, 0),
            'createdByUserId', r.requested_by_user_id,
            'createdByName', r.requested_by_name,
            'createdByPhone', r.requested_by_phone,
            'approvalPending', true,
            'approvalRequestId', r.id,
            'approvalRequestType', 'income_expense',
            'approvalOperation', r.requested_operation,
            'approvalReasons', to_jsonb(r.matched_reasons)
          )) as row_data
        from public.income_expense_approval_requests r
        where r.location_id = p_location_id and r.request_status = 'pending'

        union all

        select
          r.created_at,
          'cash-delete:' || r.id::text,
          lower(regexp_replace(concat_ws(' ', r.transfer_display_no,
            (r.created_at at time zone 'Asia/Bangkok')::date::text,
            'ลบรายการโยกเงินสด', r.source_location_name, r.target_location_name,
            r.requested_by_name, r.requested_by_phone
          ), '\s+', ' ', 'g')),
          jsonb_strip_nulls(jsonb_build_object(
            'id', 'approval-cash-delete:' || r.id,
            'clientTempId', 'approval-cash-delete:' || r.id,
            'localBillNo', r.transfer_display_no,
            'serverBillNo', r.transfer_display_no,
            'idempotencyKey', 'approval-cash-delete:' || r.id,
            'locationId', r.source_location_id,
            'syncStatus', 'pending', 'recordStatus', 'active',
            'type', 'expense', 'number', r.transfer_display_no,
            'txDate', (r.created_at at time zone 'Asia/Bangkok')::date,
            'title', 'คำขอลบรายการโยกเงินสด — ' || r.source_location_name || ' → ' || r.target_location_name,
            'cost', r.sent_total, 'billOption', 'ค่าใช้จ่าย',
            'clientRecordedAt', r.created_at, 'clientCreatedAt', r.created_at,
            'serverReceivedAt', r.updated_at, 'revisionNo', 0,
            'createdByUserId', r.requested_by_user_id,
            'createdByName', r.requested_by_name,
            'createdByPhone', r.requested_by_phone,
            'relationSourceType', 'money_transfer',
            'relationSourceId', case when r.transfer_id is null then null else 'cash:' || r.transfer_id end,
            'relationSourceLocationId', r.source_location_id,
            'relationLabel', 'รอตรวจคำขอลบ',
            'relationLockReason', 'รายการนี้เป็นคำขอลบการโยกเงินสด ต้องตรวจคำขอก่อนดำเนินการ',
            'approvalPending', true,
            'approvalRequestId', r.id,
            'approvalRequestType', 'cash_transfer_delete',
            'approvalOperation', 'delete',
            'approvalReasons', '[]'::jsonb
          ))
        from public.cash_transfer_delete_requests r
        where r.source_location_id = p_location_id and r.request_status = 'pending'
      ), page as (
        select *
        from candidates c
        where (v_search = '' or position(v_search in c.search_text) > 0)
          and (v_cursor_at is null or (c.sort_at, c.sort_key) > (v_cursor_at, v_cursor_key))
        order by c.sort_at asc, c.sort_key asc
        limit 101
      ), numbered as (
        select *, row_number() over (order by sort_at asc, sort_key asc) as row_no
        from page
      )
      select jsonb_build_object(
        'rows', coalesce((select jsonb_agg(row_data order by sort_at asc, sort_key asc)
          from numbered where row_no <= 100), '[]'::jsonb),
        'nextCursor', case when (select count(*) from numbered) > 100 then
          (select encode(convert_to(jsonb_build_object(
            'v', 1, 'locationId', p_location_id, 'mode', p_mode, 'search', v_search,
            'sort', 'requested_at_asc', 'at', sort_at, 'key', sort_key
          )::text, 'utf8'), 'hex') from numbered where row_no = 100)
          else null end,
        'hasMore', (select count(*) from numbered) > 100,
        'pendingApprovalCount', v_pending_count
      )
    );
  end if;

  return (
    with candidates as (
      select
        ie.tx_date as sort_date,
        'actual:' || ie.id::text as sort_key,
        lower(regexp_replace(concat_ws(' ', ie.number, ie.server_bill_no, ie.local_bill_no,
          ie.tx_date::text, ie.title, ie.bill_option, ie.type::text,
          ie.created_by_name, ie.created_by_phone
        ), '\s+', ' ', 'g')) as search_text,
        jsonb_strip_nulls(jsonb_build_object(
          'id', ie.id, 'clientTempId', coalesce(ie.client_temp_id, ie.id::text),
          'localBillNo', ie.local_bill_no, 'serverBillNo', ie.server_bill_no,
          'idempotencyKey', coalesce(ie.idempotency_key, 'server:' || ie.id::text),
          'locationId', ie.location_id, 'syncStatus', 'synced', 'recordStatus', ie.record_status,
          'type', ie.type, 'number', coalesce(ie.number, ie.server_bill_no, ie.local_bill_no),
          'txDate', ie.tx_date, 'title', ie.title, 'cost', ie.cost,
          'unit', ie.unit, 'price', ie.price,
          'incomeSaleItemId', ie.income_sale_item_id,
          'stockProductId', ie.stock_product_id, 'stockQuantity', ie.stock_quantity,
          'billOption', ie.bill_option,
          'clientRecordedAt', coalesce(ie.client_recorded_at, ie.created_at),
          'clientCreatedAt', coalesce(ie.client_created_at, ie.created_at),
          'serverReceivedAt', ie.server_received_at, 'revisionNo', ie.revision_no,
          'createdByUserId', ie.created_by_user_id,
          'createdByName', ie.created_by_name, 'createdByPhone', ie.created_by_phone,
          'saleLineCount', (select count(*) from public.income_expense_sale_lines l where l.income_expense_id = ie.id),
          'reportLockNo', public.report_lock_no(ie),
          'relationLockReason', case when public.report_lock_no(ie) is not null
            then 'ล็อกโดยรายงาน ' || public.report_lock_no(ie) || ' — ต้องลบรายงานล่าสุดตามลำดับก่อน' end
        )) as row_data
      from public.income_expense ie
      where ie.location_id = p_location_id and ie.record_status = 'active'

      union all

      select
        coalesce(mt.accounting_date, (mt.created_at at time zone 'Asia/Bangkok')::date),
        'transfer-income:' || mt.id,
        lower(regexp_replace(concat_ws(' ', 'TR-' || left(mt.id::text, 8),
          coalesce(mt.accounting_date, (mt.created_at at time zone 'Asia/Bangkok')::date)::text,
          case when mt.location_id = mt.target_location_id then 'โอนให้สาขา' else 'รับโอนจาก' end,
          source_location.name, 'รายรับ', mt.created_by_name, mt.created_by_phone
        ), '\s+', ' ', 'g')),
        jsonb_strip_nulls(jsonb_build_object(
          'id', 'money-transfer-income:' || mt.id, 'clientTempId', 'money-transfer-income:' || mt.id,
          'localBillNo', 'TR-' || left(mt.id::text, 8), 'serverBillNo', 'TR-' || left(mt.id::text, 8),
          'idempotencyKey', 'money-transfer:' || mt.id, 'locationId', mt.target_location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'income',
          'number', 'TR-' || left(mt.id::text, 8),
          'txDate', coalesce(mt.accounting_date, (mt.created_at at time zone 'Asia/Bangkok')::date),
          'title', case when mt.location_id = mt.target_location_id then 'โอนให้สาขา'
            else 'รับโอนจาก ' || coalesce(source_location.name, 'สาขาต้นทาง') end,
          'cost', mt.net_amount_to_pay, 'billOption', 'รายรับ',
          'clientRecordedAt', mt.created_at, 'clientCreatedAt', mt.created_at,
          'serverReceivedAt', mt.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', case when mt.location_id = mt.target_location_id then 'โอนให้สาขา' else 'โอนเงินสาขา' end,
          'relationLockReason', case when mt.location_id = mt.target_location_id
            then 'รายการนี้มาจากโอนให้สาขา ต้องแก้ไขหรือลบที่โมดูลโอนเงิน'
            else 'รายการนี้มาจากการโอนเงินสาขา ต้องแก้ไขหรือลบที่โมดูลโอนเงินต้นทาง' end,
          'reportLockNo', public.report_lock_no(mt)
        ))
      from public.money_transfers mt
      left join public.locations source_location on source_location.id = mt.location_id
      where mt.transfer_type = 'branch' and mt.target_location_id = p_location_id
        and mt.record_status <> 'deleted' and mt.transfer_status <> 'cancelled'
        and mt.net_amount_to_pay > 0

      union all

      select
        coalesce(mt.accounting_date, (mt.created_at at time zone 'Asia/Bangkok')::date),
        'transfer-expense:' || mt.id,
        lower(regexp_replace(concat_ws(' ', 'TR-' || left(mt.id::text, 8),
          coalesce(mt.accounting_date, (mt.created_at at time zone 'Asia/Bangkok')::date)::text,
          'โยกเงินไป', mt.target_location_name, 'ค่าใช้จ่าย', mt.created_by_name, mt.created_by_phone
        ), '\s+', ' ', 'g')),
        jsonb_strip_nulls(jsonb_build_object(
          'id', 'money-transfer-branch-expense:' || mt.id, 'clientTempId', 'money-transfer-branch-expense:' || mt.id,
          'localBillNo', 'TR-' || left(mt.id::text, 8), 'serverBillNo', 'TR-' || left(mt.id::text, 8),
          'idempotencyKey', 'money-transfer-branch-expense:' || mt.id, 'locationId', mt.location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'TR-' || left(mt.id::text, 8),
          'txDate', coalesce(mt.accounting_date, (mt.created_at at time zone 'Asia/Bangkok')::date),
          'title', 'โยกเงินไป ' || coalesce(mt.target_location_name, 'สาขาปลายทาง'),
          'cost', mt.net_amount_to_pay, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', mt.created_at, 'clientCreatedAt', mt.created_at,
          'serverReceivedAt', mt.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', case when mt.location_id = mt.target_location_id then 'โอนให้สาขา' else 'โอนเงินสาขา' end,
          'relationLockReason', case when mt.location_id = mt.target_location_id
            then 'รายการนี้มาจากโอนให้สาขา ต้องแก้ไขหรือลบที่โมดูลโอนเงิน'
            else 'รายการนี้มาจากการโอนเงินสาขา ต้องแก้ไขหรือลบที่โมดูลโอนเงินต้นทาง' end,
          'reportLockNo', public.report_lock_no(mt)
        ))
      from public.money_transfers mt
      where mt.transfer_type = 'branch' and mt.location_id = p_location_id
        and mt.target_location_id <> mt.location_id and mt.record_status <> 'deleted'
        and mt.transfer_status <> 'cancelled' and mt.net_amount_to_pay > 0

      union all

      select
        (mt.created_at at time zone 'Asia/Bangkok')::date,
        'customer-transfer-expense:' || mt.id,
        lower(regexp_replace(concat_ws(' ', 'CT-' || left(mt.id::text, 8),
          (mt.created_at at time zone 'Asia/Bangkok')::date::text,
          'สาขาจ่ายส่วนต่างให้', mt.customer_name, 'ค่าใช้จ่าย', mt.created_by_name, mt.created_by_phone
        ), '\s+', ' ', 'g')),
        jsonb_strip_nulls(jsonb_build_object(
          'id', 'money-transfer-branch-paid-expense:' || mt.id,
          'clientTempId', 'money-transfer-branch-paid-expense:' || mt.id,
          'localBillNo', 'CT-' || left(mt.id::text, 8), 'serverBillNo', 'CT-' || left(mt.id::text, 8),
          'idempotencyKey', 'money-transfer-branch-paid:' || mt.id, 'locationId', mt.location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'CT-' || left(mt.id::text, 8),
          'txDate', (mt.created_at at time zone 'Asia/Bangkok')::date,
          'title', 'สาขาจ่ายส่วนต่างให้ ' || coalesce(mt.customer_name, 'ลูกค้า'),
          'cost', mt.branch_paid_amount, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', mt.created_at, 'clientCreatedAt', mt.created_at,
          'serverReceivedAt', mt.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', coalesce(mt.created_by_name, 'ระบบโอนเงิน'),
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', 'โอน+สาขาจ่าย',
          'relationLockReason', 'รายการนี้มาจากโอนเงินลูกค้าแบบโอน+สาขาจ่าย ต้องแก้ไขหรือลบที่โมดูลโอนเงินลูกค้าต้นทาง',
          'reportLockNo', public.report_lock_no(mt)
        ))
      from public.money_transfers mt
      where mt.transfer_type = 'customer' and mt.transfer_status = 'branch_and_transfer'
        and mt.location_id = p_location_id and mt.record_status <> 'deleted'
        and mt.branch_paid_amount > 0

      union all

      select
        (d.sent_at at time zone 'Asia/Bangkok')::date,
        'cash-transfer-expense:' || mt.id,
        lower(regexp_replace(concat_ws(' ', 'CASH-' || left(mt.id::text, 8),
          (d.sent_at at time zone 'Asia/Bangkok')::date::text,
          'โยกเงินสดไป', mt.target_location_name, 'ค่าใช้จ่าย', mt.created_by_name, mt.created_by_phone
        ), '\s+', ' ', 'g')),
        jsonb_strip_nulls(jsonb_build_object(
          'id', 'cash-transfer-expense:' || mt.id, 'clientTempId', 'cash-transfer-expense:' || mt.id,
          'localBillNo', 'CASH-' || left(mt.id::text, 8), 'serverBillNo', 'CASH-' || left(mt.id::text, 8),
          'idempotencyKey', 'cash-transfer-expense:' || mt.id, 'locationId', mt.location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'CASH-' || left(mt.id::text, 8),
          'txDate', (d.sent_at at time zone 'Asia/Bangkok')::date,
          'title', 'โยกเงินสดไป ' || coalesce(mt.target_location_name, 'สาขาปลายทาง'),
          'cost', d.sent_total, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', d.sent_at, 'clientCreatedAt', d.sent_at,
          'serverReceivedAt', d.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', mt.created_by_name,
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', 'cash:' || mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', case when d.cash_status = 'pending_receipt' then 'รอรับเงิน'
            when coalesce(d.difference_total, 0) <> 0 then 'รับเงินแล้ว · ผลต่าง '
              || case when d.difference_total >= 0 then '+฿' else '-฿' end
              || trim(to_char(abs(d.difference_total), 'FM999999999990'))
            else 'รับเงินแล้ว' end,
          'relationLockReason', 'รายการนี้มาจากการโยกเงินสด ต้องเปิดรายละเอียดเพื่อดูข้อมูล',
          'reportLockNo', public.report_lock_no(mt),
          'cashStatus', d.cash_status,
          'cashSourceLocationLabel', source_location.name
        ))
      from public.money_transfers mt
      join public.money_transfer_cash_details d on d.transfer_id = mt.id
      left join public.locations source_location on source_location.id = mt.location_id
      where mt.transfer_type = 'cash' and mt.transfer_method = 'cash'
        and mt.location_id = p_location_id and mt.record_status <> 'deleted'

      union all

      select
        (d.received_at at time zone 'Asia/Bangkok')::date,
        'cash-transfer-income:' || mt.id,
        lower(regexp_replace(concat_ws(' ', 'CASH-' || left(mt.id::text, 8),
          (d.received_at at time zone 'Asia/Bangkok')::date::text,
          'รับโอนเงินสดจาก', source_location.name, 'รายรับ', mt.created_by_name, mt.created_by_phone
        ), '\s+', ' ', 'g')),
        jsonb_strip_nulls(jsonb_build_object(
          'id', 'cash-transfer-income:' || mt.id, 'clientTempId', 'cash-transfer-income:' || mt.id,
          'localBillNo', 'CASH-' || left(mt.id::text, 8), 'serverBillNo', 'CASH-' || left(mt.id::text, 8),
          'idempotencyKey', 'cash-transfer-income:' || mt.id, 'locationId', mt.target_location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'income',
          'number', 'CASH-' || left(mt.id::text, 8),
          'txDate', (d.received_at at time zone 'Asia/Bangkok')::date,
          'title', 'รับโอนเงินสดจาก ' || coalesce(source_location.name, 'สาขาต้นทาง'),
          'cost', d.received_total, 'billOption', 'รายรับ',
          'clientRecordedAt', d.received_at, 'clientCreatedAt', d.received_at,
          'serverReceivedAt', d.updated_at, 'revisionNo', mt.revision_no,
          'createdByUserId', mt.created_by_user_id, 'createdByName', mt.created_by_name,
          'createdByPhone', mt.created_by_phone, 'relationSourceType', 'money_transfer',
          'relationSourceId', 'cash:' || mt.id, 'relationSourceLocationId', mt.location_id,
          'relationLabel', case when coalesce(d.difference_total, 0) <> 0
            then 'รับเงินแล้ว · ผลต่าง '
              || case when d.difference_total >= 0 then '+฿' else '-฿' end
              || trim(to_char(abs(d.difference_total), 'FM999999999990')) else 'รับเงินแล้ว' end,
          'relationLockReason', 'รายการนี้มาจากการโยกเงินสด ต้องเปิดรายละเอียดเพื่อดูข้อมูล',
          'reportLockNo', public.report_lock_no(mt),
          'cashStatus', d.cash_status,
          'cashSourceLocationLabel', source_location.name
        ))
      from public.money_transfers mt
      join public.money_transfer_cash_details d on d.transfer_id = mt.id
      left join public.locations source_location on source_location.id = mt.location_id
      where mt.transfer_type = 'cash' and mt.transfer_method = 'cash'
        and mt.target_location_id = p_location_id and mt.record_status <> 'deleted'
        and d.cash_status in ('received', 'mismatched', 'difference_accepted')
        and d.received_at is not null

      union all

      select
        (ft.approved_at at time zone 'Asia/Bangkok')::date,
        'time-tracking-withdrawal:' || ft.id,
        lower(regexp_replace(concat_ws(' ', 'TW-' || left(ft.id::text, 8),
          (ft.approved_at at time zone 'Asia/Bangkok')::date::text,
          'เบิกเงิน', profile.name, ft.description, 'ค่าใช้จ่าย', profile.phone
        ), '\s+', ' ', 'g')),
        jsonb_strip_nulls(jsonb_build_object(
          'id', 'time-tracking-withdrawal:' || ft.id, 'clientTempId', 'time-tracking-withdrawal:' || ft.id,
          'localBillNo', 'TW-' || left(ft.id::text, 8), 'serverBillNo', 'TW-' || left(ft.id::text, 8),
          'idempotencyKey', 'time-tracking-withdrawal:' || ft.id, 'locationId', ft.expense_location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'TW-' || left(ft.id::text, 8),
          'txDate', (ft.approved_at at time zone 'Asia/Bangkok')::date,
          'title', 'เบิกเงิน — ' || coalesce(profile.name, 'พนักงาน') || coalesce(': ' || nullif(ft.description, ''), ''),
          'cost', ft.amount, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', ft.approved_at, 'clientCreatedAt', ft.created_at,
          'serverReceivedAt', ft.updated_at, 'revisionNo', 1,
          'createdByUserId', ft.profile_id, 'createdByName', coalesce(profile.name, 'พนักงาน'),
          'createdByPhone', profile.phone, 'relationSourceType', 'time_tracking_withdrawal',
          'relationSourceId', ft.id, 'relationSourceLocationId', ft.expense_location_id,
          'relationLabel', 'เบิกเงิน',
          'relationLockReason', 'รายการนี้มาจากการเบิกเงินที่อนุมัติแล้ว ต้องแก้ไขสาขาหรือยกเลิกที่โมดูลลงเวลาต้นทาง',
          'reportLockNo', public.report_lock_no(ft)
        ))
      from public.financial_transactions ft
      join public.profiles profile on profile.id = ft.profile_id
      where ft.type = 'WITHDRAWAL' and ft.status = 'APPROVED'
        and ft.cancelled_at is null and ft.expense_location_id = p_location_id and ft.amount > 0

      union all

      select
        (ps.approved_at at time zone 'Asia/Bangkok')::date,
        'payroll-slip:' || ps.id,
        lower(regexp_replace(concat_ws(' ', 'PS-' || left(ps.id::text, 8),
          (ps.approved_at at time zone 'Asia/Bangkok')::date::text,
          'เงินเดือน', profile.name, ps.month, 'ค่าใช้จ่าย', profile.phone
        ), '\s+', ' ', 'g')),
        jsonb_strip_nulls(jsonb_build_object(
          'id', 'payroll-slip:' || ps.id, 'clientTempId', 'payroll-slip:' || ps.id,
          'localBillNo', 'PS-' || left(ps.id::text, 8), 'serverBillNo', 'PS-' || left(ps.id::text, 8),
          'idempotencyKey', 'payroll-slip:' || ps.id, 'locationId', ps.expense_location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', 'PS-' || left(ps.id::text, 8),
          'txDate', (ps.approved_at at time zone 'Asia/Bangkok')::date,
          'title', 'เงินเดือน — ' || coalesce(profile.name, 'พนักงาน') || ' — ' || ps.month,
          'cost', ps.net_pay, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', ps.approved_at, 'clientCreatedAt', ps.created_at,
          'serverReceivedAt', ps.updated_at, 'revisionNo', 1,
          'createdByUserId', ps.profile_id, 'createdByName', coalesce(profile.name, 'พนักงาน'),
          'createdByPhone', profile.phone, 'relationSourceType', 'payroll_slip',
          'relationSourceId', ps.id, 'relationSourceLocationId', ps.expense_location_id,
          'relationLabel', 'เงินเดือน',
          'relationLockReason', 'รายการนี้มาจากเงินเดือนที่อนุมัติแล้ว ต้องแก้ไขสาขาหรือยกเลิกที่โมดูลลงเวลาต้นทาง',
          'reportLockNo', public.report_lock_no(ps)
        ))
      from public.payroll_slips ps
      join public.profiles profile on profile.id = ps.profile_id
      where ps.status = 'APPROVED' and ps.net_pay > 0 and ps.cancelled_at is null
        and ps.expense_location_id = p_location_id

      union all

      select
        (e.verified_at at time zone 'Asia/Bangkok')::date,
        'rubber-export-expense:' || e.id,
        lower(regexp_replace(concat_ws(' ', e.export_no,
          (e.verified_at at time zone 'Asia/Bangkok')::date::text,
          'ค่าทำงานส่งออกยาง', 'ค่าใช้จ่าย', e.created_by_name, e.created_by_phone
        ), '\s+', ' ', 'g')),
        jsonb_strip_nulls(jsonb_build_object(
          'id', 'rubber-export-expense:' || e.id, 'clientTempId', 'rubber-export-expense:' || e.id,
          'localBillNo', e.export_no, 'serverBillNo', e.export_no,
          'idempotencyKey', 'rubber-export-expense:' || e.id, 'locationId', e.location_id,
          'syncStatus', 'synced', 'recordStatus', 'active', 'type', 'expense',
          'number', e.export_no, 'txDate', (e.verified_at at time zone 'Asia/Bangkok')::date,
          'title', 'ค่าทำงานส่งออกยาง — ' || e.export_no,
          'cost', e.work_total, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', e.verified_at, 'clientCreatedAt', e.created_at,
          'serverReceivedAt', e.verified_at, 'revisionNo', 1,
          'createdByUserId', e.created_by_user_id, 'createdByName', e.created_by_name,
          'createdByPhone', e.created_by_phone, 'relationSourceType', 'rubber_export',
          'relationSourceId', e.id, 'relationSourceLocationId', e.location_id,
          'relationLabel', 'ส่งออกยาง',
          'relationLockReason', 'รายการนี้มาจากรายการส่งออกยาง ต้องเปิดหรือจัดการที่โมดูลส่งออกยางต้นทาง',
          'reportLockNo', public.report_lock_no(e)
        ))
      from public.rubber_exports e
      where e.location_id = p_location_id and e.status = 'verified'
        and e.expense_destination = 'branch' and e.work_total > 0

      union all

      select
        rb.bill_date,
        'rubber:' || rb.bill_date::text,
        lower(regexp_replace(concat_ws(' ', 'RB-' || to_char(rb.bill_date, 'YYMMDD'),
          rb.bill_date::text, 'จ่ายค่ายางจากบิลยาง', 'ค่าใช้จ่าย', 'ระบบบิลยาง'
        ), '\s+', ' ', 'g')),
        jsonb_strip_nulls(jsonb_build_object(
          'id', 'rubber-bill-daily-expense:' || p_location_id || ':' || rb.bill_date,
          'clientTempId', 'rubber-bill-daily-expense:' || p_location_id || ':' || rb.bill_date,
          'localBillNo', 'RB-' || to_char(rb.bill_date, 'YYMMDD'),
          'serverBillNo', 'RB-' || to_char(rb.bill_date, 'YYMMDD'),
          'idempotencyKey', 'rubber-bill-daily-expense:' || p_location_id || ':' || rb.bill_date,
          'locationId', p_location_id, 'syncStatus', 'synced', 'recordStatus', 'active',
          'type', 'expense', 'number', 'RB-' || to_char(rb.bill_date, 'YYMMDD'),
          'txDate', rb.bill_date,
          'title', 'จ่ายค่ายางจากบิลยาง ' || rb.bill_count || ' ใบ',
          'cost', rb.total, 'billOption', 'ค่าใช้จ่าย',
          'clientRecordedAt', rb.recorded_at, 'clientCreatedAt', rb.recorded_at,
          'serverReceivedAt', rb.updated_at, 'revisionNo', rb.revision_no,
          'createdByUserId', '', 'createdByName', 'ระบบบิลยาง', 'createdByPhone', '',
          'relationSourceType', 'rubber_bill_daily', 'relationSourceId', rb.bill_date,
          'relationSourceLocationId', p_location_id, 'relationSourceDate', rb.bill_date,
          'relationLabel', 'บิลยางรวมรายวัน',
          'relationLockReason', 'รายการนี้มาจากบิลยาง ต้องแก้ไขหรือลบที่โมดูลบิลยางต้นทาง',
          'reportLockNo', rb.report_lock_no
        ))
      from (
        select b.bill_date, sum(b.net_total) as total, count(*) as bill_count,
          max(coalesce(b.client_recorded_at, b.updated_at, b.created_at)) as recorded_at,
          max(b.updated_at) as updated_at, max(b.revision_no) as revision_no,
          max(public.report_lock_no(b)) as report_lock_no
        from public.rubber_bills b
        where b.location_id = p_location_id and b.record_status = 'active' and b.net_total > 0
          and private.rubber_bill_is_payable(b.id)
          and not exists (
            select 1 from public.money_transfer_items i
            where i.source_type = 'rubber_bill' and i.source_id = b.id
          )
        group by b.bill_date
      ) rb
    ), page as (
      select *
      from candidates c
      where (v_search = '' or position(v_search in c.search_text) > 0)
        and (v_cursor_date is null or (c.sort_date, c.sort_key) < (v_cursor_date, v_cursor_key))
      order by c.sort_date desc, c.sort_key desc
      limit 101
    ), numbered as (
      select *, row_number() over (order by sort_date desc, sort_key desc) as row_no
      from page
    )
    select jsonb_build_object(
      'rows', coalesce((select jsonb_agg(row_data order by sort_date desc, sort_key desc)
        from numbered where row_no <= 100), '[]'::jsonb),
      'nextCursor', case when (select count(*) from numbered) > 100 then
        (select encode(convert_to(jsonb_build_object(
          'v', 1, 'locationId', p_location_id, 'mode', p_mode, 'search', v_search,
          'sort', 'tx_date_desc', 'date', sort_date, 'key', sort_key
        )::text, 'utf8'), 'hex') from numbered where row_no = 100)
        else null end,
      'hasMore', (select count(*) from numbered) > 100,
      'pendingApprovalCount', v_pending_count
    )
  );
end;
$_$;


ALTER FUNCTION "public"."get_income_expense_operational_feed_on_demand"("p_location_id" "uuid", "p_mode" "text", "p_search" "text", "p_cursor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_money_transfer_detail"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_transfer public.money_transfers; v_result jsonb;
begin
  if not private.is_active_user() or not private.can_access_money_transfer_module() then
    raise exception 'Money transfer module access denied';
  end if;
  select * into v_transfer from public.money_transfers t
  where t.id = p_transfer_id and t.record_status <> 'deleted';
  if v_transfer.id is null then raise exception 'Money transfer not found'; end if;
  if not private.can_access_location(v_transfer.location_id) then raise exception 'Location access denied'; end if;
  select to_jsonb(v_transfer)
    || jsonb_build_object(
      'report_lock_no', public.report_lock_no(v_transfer),
      'money_transfer_slips', coalesce((select jsonb_agg(to_jsonb(s) order by s.sort_order, s.id)
        from public.money_transfer_slips s where s.transfer_id = p_transfer_id), '[]'::jsonb),
      'money_transfer_items', coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at, i.id)
        from public.money_transfer_items i where i.transfer_id = p_transfer_id), '[]'::jsonb)
    ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_money_transfer_detail"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_money_transfer_list"("p_location_id" "uuid", "p_status" "text" DEFAULT 'all'::"text", "p_search" "text" DEFAULT ''::"text", "p_cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_search text := lower(trim(coalesce(p_search, '')));
begin
  if not private.is_active_user() or not private.can_access_money_transfer_module() then raise exception 'Money transfer module access denied'; end if;
  if not private.can_access_location(p_location_id) then raise exception 'Location access denied'; end if;
  if p_page_size < 1 or p_page_size > 100 then raise exception 'Invalid page size'; end if;
  if (p_cursor_created_at is null) <> (p_cursor_id is null) then raise exception 'Invalid transfer cursor'; end if;

  with candidates as (
    select t.*, public.report_lock_no(t) report_lock_no,
      coalesce((select sum(s.amount) from public.money_transfer_slips s where s.transfer_id = t.id), 0) paid_amount,
      coalesce((select count(*) from public.money_transfer_items i where i.transfer_id = t.id), 0) source_count
    from public.money_transfers t
    where t.location_id = p_location_id
      and t.record_status <> 'deleted'
      and t.transfer_type <> 'cash'
      and (p_status = 'all' or t.transfer_status = p_status)
      and (v_search = '' or position(v_search in lower(concat_ws(' ', t.customer_name, t.account_number, t.account_name, t.bank_name, t.transport_staff_name, t.target_location_name, t.id::text))) > 0)
      and (p_cursor_created_at is null or (t.created_at, t.id) < (p_cursor_created_at, p_cursor_id))
    order by t.created_at desc, t.id desc
    limit p_page_size + 1
  ), visible as (
    select * from candidates order by created_at desc, id desc limit p_page_size
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(to_jsonb(v) order by v.created_at desc, v.id desc) from visible v), '[]'::jsonb),
    'statusCounts', (select jsonb_build_object(
      'all', count(*), 'pending', count(*) filter (where t.transfer_status = 'pending'), 'partial', count(*) filter (where t.transfer_status = 'partial'),
      'advance_payment', count(*) filter (where t.transfer_status = 'advance_payment'), 'paid', count(*) filter (where t.transfer_status = 'paid'),
      'overpaid', count(*) filter (where t.transfer_status = 'overpaid'), 'branch_and_transfer', count(*) filter (where t.transfer_status = 'branch_and_transfer'),
      'cancelled', count(*) filter (where t.transfer_status = 'cancelled')
    ) from public.money_transfers t where t.location_id = p_location_id and t.record_status <> 'deleted' and t.transfer_type <> 'cash'),
    'hasMore', (select count(*) > p_page_size from candidates),
    'nextCreatedAt', (select v.created_at from visible v order by v.created_at, v.id limit 1),
    'nextId', (select v.id from visible v order by v.created_at, v.id limit 1)
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_money_transfer_list"("p_location_id" "uuid", "p_status" "text", "p_search" "text", "p_cursor_created_at" timestamp with time zone, "p_cursor_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_money_transfer_receipt_source_details"("p_transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_location_id uuid;
  v_items jsonb;
begin
  if not private.is_active_user() or not private.can_access_money_transfer_module() then
    raise exception 'Money transfer module access denied';
  end if;
  select t.location_id into v_location_id
  from public.money_transfers t
  where t.id = p_transfer_id and t.record_status <> 'deleted';
  if v_location_id is null then raise exception 'Money transfer not found'; end if;
  if not private.can_access_location(v_location_id) then raise exception 'Location access denied'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'itemId', i.id,
    'sourceType', 'rubber_bill',
    'sourceId', i.source_id,
    'sourceNumber', coalesce(rb.server_bill_no, rb.local_bill_no, rb.bill_no),
    'sourceDate', rb.bill_date::text,
    'customerName', coalesce(rb.customer_name, i.customer_name),
    'netWeightAfterDeduction', rb.net_weight,
    'averagePrice', rb.average_price,
    'rubberValue', rb.net_rubber_value,
    'deductedAmount', rb.deduction_total,
    'netPayableAmount', rb.net_total
  ) order by rb.created_at desc, i.source_id desc), '[]'::jsonb)
  into v_items
  from public.money_transfer_items i
  join public.rubber_bills rb on rb.id = i.rubber_bill_id
  where i.transfer_id = p_transfer_id;
  return jsonb_build_object('transferId', p_transfer_id, 'items', v_items);
end
$$;


ALTER FUNCTION "public"."get_money_transfer_receipt_source_details"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_money_transfer_source_locks"("p_location_id" "uuid", "p_source_type" "text", "p_source_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("source_type" "text", "source_id" "uuid", "transfer_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.is_active_user() or not private.can_access_location(p_location_id) then
    raise exception 'Location access denied';
  end if;
  if p_source_type <> 'rubber_bill' then raise exception 'Unsupported source type'; end if;
  return query
  select r.source_type, r.source_id, r.transfer_id
  from private.money_transfer_source_relations(p_location_id, p_source_type) r
  where p_source_ids is null or r.source_id = any(p_source_ids)
  order by r.source_id;
end;
$$;


ALTER FUNCTION "public"."get_money_transfer_source_locks"("p_location_id" "uuid", "p_source_type" "text", "p_source_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_money_transfer_sources"("p_location_id" "uuid", "p_source_type" "text", "p_search" "text" DEFAULT ''::"text", "p_cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_page_size" integer DEFAULT 50, "p_selected_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_search text := lower(trim(coalesce(p_search, '')));
  v_result jsonb;
begin
  if not private.is_active_user() or not private.can_access_money_transfer_module() then
    raise exception 'Money transfer module access denied';
  end if;
  if not private.can_access_location(p_location_id) then raise exception 'Location access denied'; end if;
  if p_source_type <> 'rubber_bill' then raise exception 'Unsupported source type'; end if;
  if p_page_size < 1 or p_page_size > 100 then raise exception 'Invalid page size'; end if;
  if (p_cursor_created_at is null) <> (p_cursor_id is null) then raise exception 'Invalid source cursor'; end if;

  with source_rows as (
    select
      'rubber_bill'::text source_type,
      b.id source_id,
      coalesce(b.server_bill_no, b.local_bill_no, b.bill_no) source_number,
      b.bill_date::text source_date,
      b.customer_name,
      b.net_total::numeric amount,
      b.net_weight::numeric net_weight,
      b.average_price::numeric average_price,
      b.net_rubber_value::numeric rubber_value,
      b.deduction_total::numeric deducted_amount,
      null::text license_plate,
      b.created_at,
      r.transfer_id,
      public.report_lock_no(b) report_lock_no,
      private.rubber_bill_has_pending_approval(b.id) approval_pending,
      b.sync_status::text sync_status,
      b.server_bill_no is not null has_server_number,
      exists (
        select 1 from public.rubber_bill_items bi
        where bi.bill_id = b.id and bi.item_type = 'weigh' and coalesce(bi.price, 0) <= 0
      ) unpriced
    from public.rubber_bills b
    left join private.money_transfer_source_relations(p_location_id, 'rubber_bill') r
      on r.source_id = b.id
    where b.location_id = p_location_id and b.record_status = 'active'
  ), classified as (
    select s.*,
      case
        when s.transfer_id is not null then 'SOURCE_ALREADY_USED'
        when s.report_lock_no is not null then 'REPORT_LOCKED'
        when s.approval_pending then 'PENDING_APPROVAL'
        when s.sync_status <> 'synced' or not s.has_server_number then 'NOT_SYNCED'
        when s.unpriced then 'UNPRICED'
        when coalesce(s.amount, 0) <= 0 then 'NOT_PAYABLE'
        when nullif(trim(coalesce(s.customer_name, '')), '') is null then 'MISSING_CUSTOMER'
        else null
      end block_reason
    from source_rows s
    where s.source_type = p_source_type
      and (
        s.source_id = any(coalesce(p_selected_ids, array[]::uuid[]))
        or v_search = ''
        or position(v_search in lower(concat_ws(' ', s.source_number, s.source_date, s.customer_name, s.license_plate))) > 0
      )
      and (s.source_id = any(coalesce(p_selected_ids, array[]::uuid[]))
        or p_cursor_created_at is null or (s.created_at, s.source_id) < (p_cursor_created_at, p_cursor_id))
    order by (s.source_id = any(coalesce(p_selected_ids, array[]::uuid[]))) desc, s.created_at desc, s.source_id desc
    limit p_page_size + cardinality(coalesce(p_selected_ids, array[]::uuid[])) + 1
  ), visible as (
    select * from classified
    order by (source_id = any(coalesce(p_selected_ids, array[]::uuid[]))) desc, created_at desc, source_id desc
    limit p_page_size + cardinality(coalesce(p_selected_ids, array[]::uuid[]))
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'sourceType', v.source_type,
      'sourceId', v.source_id,
      'sourceNumber', v.source_number,
      'sourceDate', v.source_date,
      'customerName', v.customer_name,
      'amount', v.amount,
      'netWeight', v.net_weight,
      'averagePrice', v.average_price,
      'rubberValue', v.rubber_value,
      'deductedAmount', v.deducted_amount,
      'licensePlate', v.license_plate,
      'transferId', v.transfer_id,
      'reportLockNo', v.report_lock_no,
      'available', v.block_reason is null,
      'blockReason', v.block_reason,
      'createdAt', v.created_at
    ) order by (v.source_id = any(coalesce(p_selected_ids, array[]::uuid[]))) desc, v.created_at desc, v.source_id desc) from visible v), '[]'::jsonb),
    'hasMore', (select count(*) filter (where not (source_id = any(coalesce(p_selected_ids, array[]::uuid[])))) > p_page_size from classified),
    'nextCreatedAt', (select v.created_at from visible v where not (v.source_id = any(coalesce(p_selected_ids, array[]::uuid[]))) order by v.created_at, v.source_id limit 1),
    'nextId', (select v.source_id from visible v where not (v.source_id = any(coalesce(p_selected_ids, array[]::uuid[]))) order by v.created_at, v.source_id limit 1)
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_money_transfer_sources"("p_location_id" "uuid", "p_source_type" "text", "p_search" "text", "p_cursor_created_at" timestamp with time zone, "p_cursor_id" "uuid", "p_page_size" integer, "p_selected_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_receivable_rubber_exports"("p_destination_location_id" "uuid") RETURNS TABLE("source_rubber_export_id" "uuid", "source_export_no" "text", "source_location_id" "uuid", "source_location_name" "text", "verified_at" timestamp with time zone, "current_weight" numeric, "rubber_value" numeric, "source_average_age_hours" numeric, "received_age_hours" numeric, "age_is_estimated" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_now timestamptz := clock_timestamp();
begin
  if p_destination_location_id is null
     or not public.can_access_location(p_destination_location_id)
     or not exists (select 1 from public.locations l where l.id = p_destination_location_id and l.is_active) then
    raise exception 'ไม่มีสิทธิ์รับยางเข้าสาขานี้';
  end if;
  return query
  select e.id, e.export_no, e.location_id, l.name, e.verified_at, e.current_weight,
    round(e.rubber_value_total + e.work_total, 2), round(age.average_age_hours, 2),
    round(age.average_age_hours, 6), age.estimated_age_item_count > 0
  from public.rubber_exports e
  join public.locations l on l.id = e.location_id and l.is_active
  cross join lateral private.rubber_export_raw_age_summary(e.id, v_now) age
  where e.status = 'verified' and e.sold_out_at is null and e.verified_at is not null
    and e.current_weight > 0 and e.rubber_value_total > 0
    and e.work_total is not null and e.work_total >= 0
    and exists (select 1 from public.rubber_export_items i where i.export_id = e.id)
    and not exists (select 1 from public.rubber_bills b
      where b.source_rubber_export_id = e.id and b.record_status = 'active')
  order by (e.location_id = p_destination_location_id) desc, e.verified_at desc, e.export_no, e.id;
end; $$;


ALTER FUNCTION "public"."get_receivable_rubber_exports"("p_destination_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_receivable_rubber_exports_page"("p_destination_location_id" "uuid", "p_search" "text" DEFAULT ''::"text", "p_cursor_same_location" boolean DEFAULT NULL::boolean, "p_cursor_verified_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_now timestamptz := clock_timestamp(); v_search text := lower(trim(coalesce(p_search, ''))); v_result jsonb;
begin
  if p_destination_location_id is null or not public.can_access_location(p_destination_location_id)
    or not exists (select 1 from public.locations l where l.id = p_destination_location_id and l.is_active) then
    raise exception 'ไม่มีสิทธิ์รับยางเข้าสาขานี้';
  end if;
  if p_page_size < 1 or p_page_size > 50 then raise exception 'BRANCH_RECEIPT_INVALID_PAGE_SIZE'; end if;
  if (p_cursor_verified_at is null) <> (p_cursor_id is null)
    or (p_cursor_verified_at is null) <> (p_cursor_same_location is null) then
    raise exception 'BRANCH_RECEIPT_CURSOR_INCOMPLETE';
  end if;
  with candidates as (
    select e.id, e.export_no, e.location_id, l.name location_name, e.verified_at,
      e.current_weight, round(e.rubber_value_total + e.work_total, 2) rubber_value,
      e.location_id = p_destination_location_id is_same_location
    from public.rubber_exports e join public.locations l on l.id = e.location_id and l.is_active
    where e.status = 'verified' and e.sold_out_at is null and e.verified_at is not null
      and e.current_weight > 0 and e.rubber_value_total > 0 and e.work_total >= 0
      and exists (select 1 from public.rubber_export_items i where i.export_id = e.id)
      and not exists (select 1 from public.rubber_bills b where b.source_rubber_export_id = e.id and b.record_status = 'active')
      and (v_search = '' or position(v_search in lower(concat_ws(' ', e.export_no, l.name))) > 0)
      and (p_cursor_verified_at is null or
        (e.location_id = p_destination_location_id, e.verified_at, e.id)
          < (p_cursor_same_location, p_cursor_verified_at, p_cursor_id))
    order by is_same_location desc, e.verified_at desc, e.id desc limit p_page_size + 1
  ), visible as (
    select * from candidates order by is_same_location desc, verified_at desc, id desc limit p_page_size
  ), rows as (
    select v.*, age.average_age_hours source_average_age_hours,
      round(age.average_age_hours, 6) received_age_hours,
      age.estimated_age_item_count > 0 age_is_estimated
    from visible v cross join lateral private.rubber_export_raw_age_summary(v.id, v_now) age
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'source_rubber_export_id', id, 'source_export_no', export_no,
      'source_location_id', location_id, 'source_location_name', location_name,
      'verified_at', verified_at, 'current_weight', current_weight,
      'rubber_value', rubber_value, 'source_average_age_hours', round(source_average_age_hours, 2),
      'received_age_hours', received_age_hours, 'age_is_estimated', age_is_estimated,
      'is_same_location', is_same_location
    ) order by is_same_location desc, verified_at desc, id desc) from rows), '[]'::jsonb),
    'hasMore', (select count(*) > p_page_size from candidates),
    'nextSameLocation', (select is_same_location from visible order by is_same_location, verified_at, id limit 1),
    'nextVerifiedAt', (select verified_at from visible order by is_same_location, verified_at, id limit 1),
    'nextId', (select id from visible order by is_same_location, verified_at, id limit 1)
  ) into v_result;
  return v_result;
end; $$;


ALTER FUNCTION "public"."get_receivable_rubber_exports_page"("p_destination_location_id" "uuid", "p_search" "text", "p_cursor_same_location" boolean, "p_cursor_verified_at" timestamp with time zone, "p_cursor_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_report_income_expense_rows"("p_report_id" "uuid") RETURNS TABLE("tx_date" "date", "number" "text", "entry_type" "text", "title" "text", "amount" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_report public.report_batches%rowtype;
begin
  select b.*
  into v_report
  from public.report_batches b
  where b.id = p_report_id;

  if v_report.id is null or not private.can_manage_reports(v_report.location_id) then
    raise exception 'ไม่มีสิทธิ์ดูรายงานนี้';
  end if;

  return query
  with rows as (
    select
      0 as row_order,
      (previous.cutoff_at at time zone 'Asia/Bangkok')::date as tx_date,
      previous.report_no as number,
      case when v_report.opening_balance >= 0 then 'income' else 'expense' end as entry_type,
      'ยอดยกมา'::text as title,
      abs(v_report.opening_balance) as amount,
      '00-opening-balance'::text as sort_key
    from public.report_batches previous
    where previous.id = v_report.previous_report_id

    union all

    select
      1,
      period.tx_date,
      period.number,
      period.entry_type,
      period.title,
      period.amount,
      period.sort_key
    from private.report_income_expense_period_rows(p_report_id) period
  )
  select
    rows.tx_date,
    rows.number,
    rows.entry_type,
    rows.title,
    rows.amount
  from rows
  order by rows.row_order, rows.tx_date, rows.sort_key;
end;
$$;


ALTER FUNCTION "public"."get_report_income_expense_rows"("p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rubber_bill_evidence_feed"("p_location_id" "uuid", "p_view" "text" DEFAULT 'pending'::"text", "p_search" "text" DEFAULT ''::"text", "p_bill_id" "uuid" DEFAULT NULL::"uuid", "p_cursor_sort_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_bill_id" "uuid" DEFAULT NULL::"uuid", "p_page_size" integer DEFAULT 75) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_search text := lower(trim(coalesce(p_search, '')));
  v_ascending boolean := p_view = 'pending' and p_bill_id is null;
  v_result jsonb;
begin
  if not private.is_active_user() or not private.can_access_location(p_location_id) then
    raise exception 'RUBBER_EVIDENCE_REVIEW_ACCESS_DENIED';
  end if;
  if p_view not in ('pending', 'history') then raise exception 'RUBBER_EVIDENCE_INVALID_VIEW'; end if;
  if p_page_size < 1 or p_page_size > 75 then raise exception 'RUBBER_EVIDENCE_INVALID_PAGE_SIZE'; end if;
  if (p_cursor_sort_at is null) <> (p_cursor_bill_id is null) then raise exception 'RUBBER_EVIDENCE_CURSOR_INCOMPLETE'; end if;

  with candidates as (
    select b.*,
      p.review_period_id, p.review_status, p.missing_rubber, p.missing_display_in,
      p.has_manual_correction, p.is_unpriced, p.has_any_evidence,
      p.required_role_count, p.present_required_role_count, p.decision,
      p.reviewed_by_name, p.reviewed_at,
      b.id cursor_bill_id,
      case when p_view = 'pending' then p.client_created_at
        else coalesce(p.reviewed_at, p.client_created_at) end feed_sort_at
    from private.rubber_bill_evidence_projection p
    join public.rubber_bills b on b.id = p.bill_id and b.record_status = 'active'
    where p.location_id = p_location_id
      and (
        (p_bill_id is not null and p.bill_id = p_bill_id)
        or (p_bill_id is null and v_search <> '' and position(v_search in lower(concat_ws(' ',
          b.bill_no, b.local_bill_no, b.server_bill_no, b.customer_name, b.bill_date::text
        ))) > 0)
        or (p_bill_id is null and v_search = '' and p_view = 'pending' and p.review_status = 'pending')
        or (p_bill_id is null and v_search = '' and p_view = 'history' and p.review_status in ('pass', 'improve'))
      )
  ), scoped as (
    select c.* from candidates c
    where p_cursor_sort_at is null
      or (v_ascending and (c.feed_sort_at, c.cursor_bill_id) > (p_cursor_sort_at, p_cursor_bill_id))
      or (not v_ascending and (c.feed_sort_at, c.cursor_bill_id) < (p_cursor_sort_at, p_cursor_bill_id))
    order by case when v_ascending then feed_sort_at end asc,
      case when not v_ascending then feed_sort_at end desc,
      case when v_ascending then cursor_bill_id end asc,
      case when not v_ascending then cursor_bill_id end desc
    limit p_page_size + 1
  ), visible as (
    select * from scoped
    order by case when v_ascending then feed_sort_at end asc,
      case when not v_ascending then feed_sort_at end desc,
      case when v_ascending then cursor_bill_id end asc,
      case when not v_ascending then cursor_bill_id end desc
    limit p_page_size
  ), serialized as (
    select v.feed_sort_at, v.cursor_bill_id bill_id,
      to_jsonb(v) - 'feed_sort_at' - 'cursor_bill_id' - 'review_period_id'
        - 'review_status' - 'missing_rubber' - 'missing_display_in'
        - 'has_manual_correction' - 'is_unpriced' - 'has_any_evidence'
        - 'required_role_count' - 'present_required_role_count' - 'decision'
        - 'reviewed_by_name' - 'reviewed_at'
        || jsonb_build_object(
          'items', coalesce((select jsonb_agg(to_jsonb(i) order by i.sequence_no, i.id)
            from public.rubber_bill_items i where i.bill_id = v.cursor_bill_id), '[]'::jsonb),
          'evidence_state', jsonb_build_object(
            'location_id', v.location_id, 'bill_id', v.cursor_bill_id, 'revision_no', v.revision_no,
            'client_created_at', v.client_created_at, 'review_period_id', v.review_period_id,
            'review_status', v.review_status, 'missing_rubber', v.missing_rubber,
            'missing_display_in', v.missing_display_in, 'has_manual_correction', v.has_manual_correction,
            'is_unpriced', v.is_unpriced, 'has_any_evidence', v.has_any_evidence,
            'required_role_count', v.required_role_count,
            'present_required_role_count', v.present_required_role_count,
            'decision', v.decision, 'reviewed_by_name', v.reviewed_by_name, 'reviewed_at', v.reviewed_at
          )
        ) row_json
    from visible v
  )
  select jsonb_build_object(
    'rows', coalesce((select jsonb_agg(row_json order by
      case when v_ascending then feed_sort_at end asc,
      case when not v_ascending then feed_sort_at end desc,
      case when v_ascending then bill_id end asc,
      case when not v_ascending then bill_id end desc) from serialized), '[]'::jsonb),
    'hasMore', (select count(*) > p_page_size from scoped),
    'nextSortAt', (select feed_sort_at from serialized order by
      case when v_ascending then feed_sort_at end desc,
      case when not v_ascending then feed_sort_at end asc,
      case when v_ascending then bill_id end desc,
      case when not v_ascending then bill_id end asc limit 1),
    'nextBillId', (select bill_id from serialized order by
      case when v_ascending then feed_sort_at end desc,
      case when not v_ascending then feed_sort_at end asc,
      case when v_ascending then bill_id end desc,
      case when not v_ascending then bill_id end asc limit 1)
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_rubber_bill_evidence_feed"("p_location_id" "uuid", "p_view" "text", "p_search" "text", "p_bill_id" "uuid", "p_cursor_sort_at" timestamp with time zone, "p_cursor_bill_id" "uuid", "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rubber_bill_evidence_review_overview"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_period public.rubber_bill_evidence_review_periods%rowtype; v_count bigint; v_fingerprint text;
begin
  if not private.is_active_user() or not private.can_access_location(p_location_id) then
    raise exception 'RUBBER_EVIDENCE_REVIEW_ACCESS_DENIED';
  end if;
  select * into v_period from public.rubber_bill_evidence_review_periods
    where location_id = p_location_id and closed_at is null order by opened_at desc limit 1;
  select count(*), md5(coalesce(string_agg(concat(p.bill_id::text, ':', p.revision_no::text), ',' order by p.bill_id, p.revision_no), ''))
  into v_count, v_fingerprint from private.rubber_bill_evidence_projection p
  where p.location_id = p_location_id and p.review_status = 'pending';
  return jsonb_build_object('isOpen', v_period.id is not null, 'periodId', v_period.id,
    'openedAt', v_period.opened_at, 'openedByName', v_period.opened_by_name,
    'pendingCount', coalesce(v_count, 0), 'pendingFingerprint', coalesce(v_fingerprint, md5('')));
end; $$;


ALTER FUNCTION "public"."get_rubber_bill_evidence_review_overview"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rubber_bill_evidence_review_states"("p_location_id" "uuid") RETURNS TABLE("location_id" "uuid", "bill_id" "uuid", "revision_no" integer, "client_created_at" timestamp with time zone, "review_period_id" "uuid", "review_status" "text", "missing_rubber" boolean, "missing_display_in" boolean, "has_manual_correction" boolean, "is_unpriced" boolean, "has_any_evidence" boolean, "required_role_count" bigint, "present_required_role_count" bigint, "decision" "text", "reviewed_by_name" "text", "reviewed_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.is_active_user() or not private.can_access_location(p_location_id) then
    raise exception 'RUBBER_EVIDENCE_REVIEW_ACCESS_DENIED';
  end if;
  return query select p.location_id, p.bill_id, p.revision_no, p.client_created_at,
    p.review_period_id, p.review_status, p.missing_rubber, p.missing_display_in,
    p.has_manual_correction, p.is_unpriced, p.has_any_evidence,
    p.required_role_count, p.present_required_role_count, p.decision,
    p.reviewed_by_name, p.reviewed_at
  from private.rubber_bill_evidence_projection p where p.location_id = p_location_id;
end; $$;


