CREATE OR REPLACE FUNCTION "public"."get_telegram_badge_delivery_credentials"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  token_value text;
  target_chat_id text;
begin
