CREATE OR REPLACE FUNCTION "public"."preview_rubber_export"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.preview_rubber_export(
    p_location_id, p_selected_report_item_ids, null::uuid
  );
$$;


ALTER FUNCTION "public"."preview_rubber_export"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_rubber_export"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[], "p_current_export_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_result jsonb;
  v_current public.rubber_exports%rowtype;
begin
  if p_location_id is null or not private.can_manage_reports(p_location_id) then
    raise exception 'ไม่มีสิทธิ์สร้างรายการส่งออกของสาขานี้';
  end if;
  if p_current_export_id is not null then
    select * into v_current
    from public.rubber_exports e
    where e.id = p_current_export_id;
    if v_current.id is null or v_current.location_id <> p_location_id then
      raise exception 'ไม่พบรายการส่งออกฉบับร่าง';
    end if;
    if v_current.status <> 'draft' then
      raise exception 'แก้ไขสมาชิกได้เฉพาะรายการฉบับร่าง';
    end if;
  end if;

  perform private.validate_rubber_export_selection(
    p_location_id, p_selected_report_item_ids, p_current_export_id
  );

  with candidates as (
    select c.*,
      case when b.source_rubber_export_id is not null then b.received_at
        else coalesce(b.client_created_at, b.created_at) end as age_source_at,
      case when b.source_rubber_export_id is not null then b.received_age_hours
        else null end as carried_age_hours,
      case when b.source_rubber_export_id is not null then b.received_age_is_estimated
        else b.client_created_at is null
          or (coalesce(b.client_created_at, b.created_at) at time zone 'Asia/Bangkok')::date <> c.bill_date
        end as age_is_estimated
    from private.rubber_export_candidates(
      p_location_id, p_selected_report_item_ids, p_current_export_id
    ) c
    join public.rubber_bills b on b.id = c.bill_id
  ), aged as (
    select c.*, private.rubber_export_item_age_hours(
      c.bill_date, c.age_source_at, c.carried_age_hours, v_now
    ) age_hours
    from candidates c
  )
  select jsonb_build_object(
    'itemCount', count(*)::integer,
    'originalWeightTotal', round(sum(net_weight), 2),
    'paidTotal', round(sum(paid_amount), 2),
    'rubberValueTotal', round(sum(rubber_value_amount), 2),
    'averagePrice', round(sum(rubber_value_amount) / sum(net_weight), 2),
    'calculatedAt', v_now,
    'averageAgeHours', round(sum(net_weight * age_hours) / sum(net_weight), 2),
    'oldestAgeHours', round(max(age_hours), 2),
    'estimatedAgeItemCount', count(*) filter (where age_is_estimated)::integer,
    'items', jsonb_agg(jsonb_build_object(
      'reportItemId', report_item_id, 'billId', bill_id, 'billDate', bill_date,
      'billNo', bill_no, 'customerName', customer_name, 'eligibilityAt', eligibility_at,
      'netWeight', net_weight, 'paidAmount', paid_amount,
      'rubberValueAmount', rubber_value_amount,
      'ageHours', round(age_hours, 2), 'ageIsEstimated', age_is_estimated
    ) order by eligibility_at, bill_id)
  ) into v_result from aged;
  if coalesce((v_result->>'itemCount')::integer, 0) = 0 then
    raise exception 'ไม่มีบิลที่พร้อมสร้างรายการส่งออก';
  end if;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."preview_rubber_export"("p_location_id" "uuid", "p_selected_report_item_ids" "uuid"[], "p_current_export_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provision_location"("p_request_id" "uuid", "p_name" "text", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  normalized_name text :=
    pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(p_name, '')),
      '[[:space:]]+',
      ' ',
      'g'
    );
  normalized_code text :=
    pg_catalog.upper(pg_catalog.btrim(coalesce(p_code, '')));
  location public.locations%rowtype;
  replayed boolean := false;
begin
  if not private.is_active_user()
    or not private.can_access_super_admin_features()
  then
    raise exception 'BRANCH_FORBIDDEN'
      using errcode = '42501';
  end if;

  if p_request_id is null then
    raise exception 'BRANCH_REQUEST_ID_REQUIRED'
      using errcode = '22023';
  end if;

  if normalized_name = '' or char_length(normalized_name) > 100 then
    raise exception 'BRANCH_NAME_INVALID'
      using errcode = '22023';
  end if;

  if normalized_code !~ '^[A-Z0-9]{2,8}$' then
    raise exception 'BRANCH_CODE_INVALID'
      using errcode = '22023';
  end if;

  select l.*
  into location
  from public.locations l
  where l.provision_request_id = p_request_id;

  if found then
    replayed := true;
  else
    insert into public.locations (
      name,
      code,
      is_active,
      created_by,
      provision_request_id
    )
    values (
      normalized_name,
      normalized_code,
      true,
      auth.uid(),
      p_request_id
    )
    on conflict (provision_request_id) do nothing
    returning * into location;

    if not found then
      select l.*
      into strict location
      from public.locations l
      where l.provision_request_id = p_request_id;
      replayed := true;
    else
      insert into public.user_locations (
        user_id,
        location_id,
        assigned_by,
        is_primary
      )
      values (
        auth.uid(),
        location.id,
        auth.uid(),
        false
      );
    end if;
  end if;

  if location.created_by is distinct from auth.uid()
    or location.name is distinct from normalized_name
    or location.code is distinct from normalized_code
  then
    raise exception 'BRANCH_IDEMPOTENCY_CONFLICT'
      using errcode = 'P0001';
  end if;

  return jsonb_build_object(
    'location',
    jsonb_build_object(
      'id', location.id,
      'name', location.name,
      'code', location.code,
      'active', location.is_active
    ),
    'replayed', replayed
  );
end;
$_$;


ALTER FUNCTION "public"."provision_location"("p_request_id" "uuid", "p_name" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_dashboard_refresh"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requested_version bigint;
begin
  perform private.dashboard_require_refresh_access(p_location_id);

  insert into public.dashboard_branch_snapshots (
    location_id,
    status,
    source_version,
    manual_requested_at
  )
  values (
    p_location_id,
    'queued',
    1,
    now()
  )
  on conflict (location_id) do update
  set status = case
        when dashboard_branch_snapshots.status = 'running' then 'running'
        else 'queued'
      end,
      source_version = case
        when dashboard_branch_snapshots.status in ('queued', 'running')
          then dashboard_branch_snapshots.source_version
        else dashboard_branch_snapshots.source_version + 1
      end,
      manual_requested_at = now(),
      updated_at = now()
  returning source_version into requested_version;

  return public.get_dashboard_snapshot(p_location_id)
    || jsonb_build_object('requestedVersion', requested_version);
end;
$$;


ALTER FUNCTION "public"."queue_dashboard_refresh"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rebuild_dashboard_refresh_now"("p_location_id" "uuid", "p_claimed_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.dashboard_require_refresh_access(p_location_id);

  if p_claimed_version is null or p_claimed_version < 1 then
    raise exception 'Claimed Dashboard version is invalid';
  end if;

  perform private.rebuild_dashboard_branch_target(
    p_location_id,
    p_claimed_version
  );

  return public.get_dashboard_snapshot(p_location_id);
end;
$$;


ALTER FUNCTION "public"."rebuild_dashboard_refresh_now"("p_location_id" "uuid", "p_claimed_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_cash_branch_transfer"("p_transfer_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  transfer_row public.money_transfers%rowtype;
  counts integer[];
  actor_id uuid := auth.uid();
  actor_name text;
  actor_phone text;
  total numeric;
  sent numeric;
begin
  select * into transfer_row
  from public.money_transfers
  where id = p_transfer_id
  for update;

  if transfer_row.id is null or transfer_row.transfer_method <> 'cash' then
    raise exception 'ไม่พบรายการเงินสด';
  end if;
  if not private.can_access_location(transfer_row.target_location_id) then
    raise exception 'ไม่มีสิทธิ์ตรวจรับสาขานี้';
  end if;

  counts := private.cash_transfer_counts(payload, 'received');
  select name, phone into actor_name, actor_phone
  from public.profiles
  where id = actor_id;

  update public.money_transfer_cash_details
  set received_coin_1_count = counts[1],
      received_coin_2_count = counts[2],
      received_coin_5_count = counts[3],
      received_coin_10_count = counts[4],
      received_banknote_20_count = counts[5],
      received_banknote_50_count = counts[6],
      received_banknote_100_count = counts[7],
      received_banknote_500_count = counts[8],
      received_banknote_1000_count = counts[9],
      received_by_user_id = actor_id,
      received_by_name = coalesce(actor_name, ''),
      received_by_phone = coalesce(actor_phone, ''),
      received_at = now(),
      updated_at = now(),
      cash_status = 'received'
  where transfer_id = p_transfer_id
    and cash_status = 'pending_receipt'
  returning received_total, sent_total into total, sent;

  if not found then
    raise exception 'รายการนี้ถูกตรวจรับแล้ว';
  end if;

  update public.money_transfers
  set transfer_status = 'paid',
      revision_no = revision_no + 1,
      updated_at = now()
  where id = p_transfer_id;

  return jsonb_build_object(
    'id', p_transfer_id,
    'status', 'synced',
    'difference', total - sent
  );
end;
$$;


ALTER FUNCTION "public"."receive_cash_branch_transfer"("p_transfer_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_rubber_export"("p_destination_location_id" "uuid", "p_source_rubber_export_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_source public.rubber_exports%rowtype; v_source_location_name text;
  v_actor_name text; v_actor_phone text; v_now timestamptz := clock_timestamp();
  v_bill_date date; v_date_key text; v_next_seq integer; v_bill_no text;
  v_bill_id uuid; v_client_temp_id text; v_customer_name text; v_debt_description text;
  v_age record; v_age_hours numeric; v_rubber_value numeric; v_average_price numeric;
begin
  if p_destination_location_id is null or p_source_rubber_export_id is null
     or not public.can_access_location(p_destination_location_id)
     or not exists (select 1 from public.locations l where l.id = p_destination_location_id and l.is_active) then
    raise exception 'ไม่มีสิทธิ์รับยางเข้าสาขานี้';
  end if;
  select * into v_source from public.rubber_exports e
  where e.id = p_source_rubber_export_id for update;
  if v_source.id is null then raise exception 'BRANCH_RECEIPT_SOURCE_NOT_FOUND'; end if;
  if exists (select 1 from public.rubber_bills b
    where b.source_rubber_export_id = v_source.id and b.record_status = 'active') then
    raise exception 'BRANCH_RECEIPT_ALREADY_EXISTS:%', v_source.export_no using errcode = 'P0001';
  end if;
  if v_source.status <> 'verified' or v_source.sold_out_at is not null
     or v_source.verified_at is null or v_source.current_weight is null
     or v_source.current_weight <= 0 or v_source.rubber_value_total <= 0
     or v_source.work_total is null or v_source.work_total < 0
     or not exists (select 1 from public.rubber_export_items i where i.export_id = v_source.id)
     or not exists (select 1 from public.locations l where l.id = v_source.location_id and l.is_active) then
    raise exception 'BRANCH_RECEIPT_SOURCE_STALE:%', v_source.export_no
      using errcode = 'P0001', hint = 'รีเฟรชรายการแล้วเลือกใหม่';
  end if;
  select l.name into v_source_location_name from public.locations l where l.id = v_source.location_id;
  select p.name, p.phone into v_actor_name, v_actor_phone
  from public.profiles p where p.id = auth.uid() and p.is_active;
  if v_actor_name is null then raise exception 'บัญชีผู้ใช้ไม่พร้อมใช้งาน'; end if;
  select * into v_age from private.rubber_export_raw_age_summary(v_source.id, v_now);
  v_age_hours := round(v_age.average_age_hours, 6);
  v_bill_date := (v_now at time zone 'Asia/Bangkok')::date;
  v_date_key := to_char(v_bill_date, 'YYMMDD');
  perform pg_advisory_xact_lock(hashtext(p_destination_location_id::text || v_date_key));
  select count(*) + 1 into v_next_seq from public.rubber_bills b
  where b.location_id = p_destination_location_id
    and to_char(b.bill_date, 'YYMMDD') = v_date_key and b.server_bill_no is not null;
  v_bill_no := v_date_key || lpad(v_next_seq::text, 4, '0');
  v_client_temp_id := 'branch-receipt:' || v_source.id::text || ':' || gen_random_uuid()::text;
  if v_source.location_id = p_destination_location_id then
    v_customer_name := 'ยางคงเหลือภายในสาขา';
    v_debt_description := 'หักมูลค่ายางคงเหลือภายในสาขา';
  else
    v_customer_name := 'รับยางจากสาขา ' || v_source_location_name;
    v_debt_description := 'หักมูลค่ายางรับจากสาขา ' || v_source_location_name;
  end if;
  v_rubber_value := round(v_source.rubber_value_total + v_source.work_total, 2);
  v_average_price := round(v_rubber_value / v_source.current_weight, 2);
  insert into public.rubber_bills (
    client_temp_id, local_bill_no, server_bill_no, idempotency_key,
    sync_status, record_status, location_id, bill_no, bill_date,
    customer_id, customer_name, bill_type, deduct_weight, weight,
    rubber_value, average_price, deduction_total, net_total,
    acid_pack_count, client_recorded_at, client_created_at,
    server_received_at, revision_no, created_by_user_id,
    created_by_name, created_by_phone, source_rubber_export_id,
    source_export_no, received_at, received_age_hours, received_age_is_estimated
  ) values (
    v_client_temp_id, v_bill_no, v_bill_no, v_client_temp_id,
    'synced', 'active', p_destination_location_id, v_bill_no, v_bill_date,
    null, v_customer_name, 'บิลเครื่องชั่งเล็ก', 0, v_source.current_weight,
    v_rubber_value, v_average_price, v_rubber_value, 0,
    0, v_now, v_now, v_now, 1, auth.uid(), coalesce(v_actor_name, ''),
    coalesce(v_actor_phone, ''), v_source.id, v_source.export_no, v_now,
    v_age_hours, v_age.estimated_age_item_count > 0
  ) returning id into v_bill_id;
  insert into public.rubber_bill_items (
    bill_id, item_type, description, weight_in, weight_out, net_weight,
    quantity, unit, price, total, sequence_no
  ) values
    (v_bill_id, 'weigh', v_customer_name, v_source.current_weight, 0,
      v_source.current_weight, v_source.current_weight, 'kg', v_average_price, v_rubber_value, 1),
    (v_bill_id, 'debt', v_debt_description, null, null, null, null, null, null, v_rubber_value, 2);
  return jsonb_build_object('status', 'received', 'billId', v_bill_id, 'billNo', v_bill_no,
    'sourceExportId', v_source.id, 'sourceExportNo', v_source.export_no,
    'receivedAt', v_now, 'receivedAgeHours', v_age_hours);
exception when unique_violation then
  raise exception 'BRANCH_RECEIPT_ALREADY_EXISTS:%', coalesce(v_source.export_no, '') using errcode = 'P0001';
end; $$;


ALTER FUNCTION "public"."receive_rubber_export"("p_destination_location_id" "uuid", "p_source_rubber_export_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_weight_evidence_backup"("p_bill_id" "uuid", "p_row_id" "uuid", "p_role" "text", "p_location_id" "uuid", "p_revision_no" integer, "p_completion_id" "uuid", "p_evidence_key" "text", "p_drive_file_id" "text", "p_web_view_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_bill public.rubber_bills%rowtype;
  v_existing public.rubber_bill_item_evidence_files%rowtype;
begin
  if not private.is_active_user() or not public.can_access_location(p_location_id) then
    raise exception 'WEIGHT_EVIDENCE_ACCESS_DENIED';
  end if;
  if p_bill_id is null or p_row_id is null or p_completion_id is null
    or p_revision_no is null or p_revision_no < 0
    or p_role not in ('rubber', 'displayIn', 'displayOut')
    or nullif(btrim(p_evidence_key), '') is null
    or p_evidence_key <> concat_ws(':', p_completion_id::text, p_revision_no::text, p_row_id::text, p_role)
    or nullif(btrim(p_drive_file_id), '') is null
    or nullif(btrim(p_web_view_url), '') is null then
    raise exception 'WEIGHT_EVIDENCE_INVALID_INPUT';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text, 0));
  select * into v_bill from public.rubber_bills
  where id = p_bill_id and location_id = p_location_id for update;
  if not found or v_bill.record_status <> 'active' or v_bill.source_rubber_export_id is not null then
    return jsonb_build_object('state', 'inactive');
  end if;
  if v_bill.revision_no <> p_revision_no then return jsonb_build_object('state', 'stale'); end if;
  if v_bill.evidence_completion_id is distinct from p_completion_id then
    return jsonb_build_object('state', 'not_owner');
  end if;
  if not exists (
    select 1 from public.rubber_bill_items
    where id = p_row_id and bill_id = p_bill_id and item_type = 'weigh'
  ) then return jsonb_build_object('state', 'invalid_row'); end if;
  select * into v_existing from public.rubber_bill_item_evidence_files
  where bill_item_id = p_row_id and role = p_role;
  if found then
    if v_existing.evidence_key = p_evidence_key then
      return jsonb_build_object('state', 'stored', 'fileId', v_existing.drive_file_id, 'webViewUrl', v_existing.web_view_url);
    end if;
    return jsonb_build_object('state', 'conflict');
  end if;
  begin
    insert into public.rubber_bill_item_evidence_files (
      bill_item_id, role, completion_id, revision_no, evidence_key, drive_file_id, web_view_url
    ) values (
      p_row_id, p_role, p_completion_id, p_revision_no, p_evidence_key, p_drive_file_id, p_web_view_url
    );
  exception when unique_violation then
    select * into v_existing from public.rubber_bill_item_evidence_files
    where evidence_key = p_evidence_key or (bill_item_id = p_row_id and role = p_role)
    limit 1;
    if v_existing.evidence_key = p_evidence_key then
      return jsonb_build_object('state', 'stored', 'fileId', v_existing.drive_file_id, 'webViewUrl', v_existing.web_view_url);
    end if;
    return jsonb_build_object('state', 'conflict');
  end;
  return jsonb_build_object('state', 'stored', 'fileId', p_drive_file_id, 'webViewUrl', p_web_view_url);
end;
$$;


ALTER FUNCTION "public"."record_weight_evidence_backup"("p_bill_id" "uuid", "p_row_id" "uuid", "p_role" "text", "p_location_id" "uuid", "p_revision_no" integer, "p_completion_id" "uuid", "p_evidence_key" "text", "p_drive_file_id" "text", "p_web_view_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_weight_evidence_completion"("p_bill_id" "uuid", "p_location_id" "uuid", "p_revision_no" integer, "p_completion_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_bill public.rubber_bills%rowtype;
begin
  if not private.is_active_user()
    or not public.can_access_location(p_location_id)
  then
    raise exception 'WEIGHT_EVIDENCE_ACCESS_DENIED';
  end if;
  if p_bill_id is null or p_completion_id is null
    or p_revision_no is null or p_revision_no < 0
  then
    raise exception 'WEIGHT_EVIDENCE_INVALID_INPUT';
  end if;

  select * into v_bill
  from public.rubber_bills
  where id = p_bill_id and location_id = p_location_id
  for update;

  if not found
    or v_bill.record_status <> 'active'
    or v_bill.source_rubber_export_id is not null
  then
    return jsonb_build_object('state', 'inactive');
  end if;
  if v_bill.revision_no <> p_revision_no then
    return jsonb_build_object(
      'state', 'stale',
      'currentRevisionNo', v_bill.revision_no
    );
  end if;
  if v_bill.evidence_completion_id is distinct from p_completion_id then
    return jsonb_build_object(
      'state', 'not_owner',
      'currentRevisionNo', v_bill.revision_no
    );
  end if;

  update public.rubber_bills
  set evidence_completion_id = null,
      updated_at = now()
  where id = p_bill_id;
  return jsonb_build_object(
    'state', 'released',
    'currentRevisionNo', v_bill.revision_no
  );
end;
$$;


ALTER FUNCTION "public"."release_weight_evidence_completion"("p_bill_id" "uuid", "p_location_id" "uuid", "p_revision_no" integer, "p_completion_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_user_location_with_primary_replacement"("p_user_id" "uuid", "p_location_id" "uuid", "p_replacement_location_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_was_primary boolean;
  v_remaining_count integer;
begin
  if v_actor_id is null or not private.can_access_super_admin_features() then
    raise exception 'Forbidden';
  end if;
  if exists (
    select 1 from public.profiles p where p.id = p_user_id and p.role = 'super_admin'
  ) then
    raise exception 'Cannot modify super_admin locations';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('user-locations:' || p_user_id::text, 0));
  select ul.is_primary into v_was_primary
  from public.user_locations ul
  where ul.user_id = p_user_id and ul.location_id = p_location_id
  for update;
  if not found then return jsonb_build_object('status', 'unchanged'); end if;

  select count(*) into v_remaining_count
  from public.user_locations ul
  where ul.user_id = p_user_id and ul.location_id <> p_location_id;

  if v_was_primary and v_remaining_count > 0 then
    if p_replacement_location_id is null
      or p_replacement_location_id = p_location_id
      or not exists (
        select 1 from public.user_locations ul
        where ul.user_id = p_user_id
          and ul.location_id = p_replacement_location_id
      )
    then
      raise exception 'REPLACEMENT_PRIMARY_REQUIRED';
    end if;

    update public.user_locations
    set is_primary = false
    where user_id = p_user_id and location_id = p_location_id;

    update public.user_locations
    set is_primary = true
    where user_id = p_user_id and location_id = p_replacement_location_id;
  elsif p_replacement_location_id is not null then
    raise exception 'REPLACEMENT_PRIMARY_NOT_ALLOWED';
  end if;

  delete from public.user_locations
  where user_id = p_user_id and location_id = p_location_id;

  if v_was_primary then
    insert into public.time_tracking_audit_logs (
      admin_id, action, target_table, record_id, old_data, new_data, comment
    ) values (
      v_actor_id,
      'REMOVE_PRIMARY_LOCATION',
      'profiles',
      p_user_id,
      jsonb_build_object('primaryLocationId', p_location_id),
      jsonb_build_object('primaryLocationId', p_replacement_location_id),
      ''
    );
  end if;

  return jsonb_build_object(
    'status', 'deleted',
    'primaryLocationId', case when v_was_primary then p_replacement_location_id else null end
  );
end
$$;


ALTER FUNCTION "public"."remove_user_location_with_primary_replacement"("p_user_id" "uuid", "p_location_id" "uuid", "p_replacement_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repair_rubber_bill_evidence_projection"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_before bigint; v_after bigint; v_rows bigint;
begin
  perform private.require_rubber_bill_evidence_review_manager(p_location_id);
  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text, 0));
  select count(*) into v_before from private.rubber_bill_evidence_projection_drift(p_location_id);
  select private.rebuild_rubber_bill_evidence_projection(p_location_id) into v_rows;
  select count(*) into v_after from private.rubber_bill_evidence_projection_drift(p_location_id);
  return jsonb_build_object('driftBefore', v_before, 'driftAfter', v_after, 'rowCount', v_rows);
end;
$$;


ALTER FUNCTION "public"."repair_rubber_bill_evidence_projection"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_rubber_export_items"("p_export_id" "uuid", "p_selected_report_item_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_export public.rubber_exports%rowtype; v_item_count integer;
  v_original_weight numeric; v_paid_total numeric; v_rubber_value_total numeric;
begin
  select * into v_export from public.rubber_exports e where e.id = p_export_id for update;
  if v_export.id is null or not private.can_manage_reports(v_export.location_id) then
    raise exception 'ไม่มีสิทธิ์แก้ไขรายการส่งออกนี้';
  end if;
  if v_export.status <> 'draft' then raise exception 'แก้ไขสมาชิกได้เฉพาะรายการฉบับร่าง'; end if;
  perform pg_advisory_xact_lock(hashtextextended('rubber-export:' || v_export.location_id::text, 0));
  perform private.validate_rubber_export_selection(v_export.location_id, p_selected_report_item_ids, v_export.id);
  delete from public.rubber_export_items i where i.export_id = v_export.id;
  insert into public.rubber_export_items (
    export_id, location_id, source_report_item_id, source_bill_id, bill_date,
    bill_no, customer_name, eligibility_at, net_weight, paid_amount,
    rubber_value_amount, age_source_at, age_is_estimated, carried_age_hours
  )
  select v_export.id, v_export.location_id, c.report_item_id, c.bill_id, c.bill_date,
    c.bill_no, c.customer_name, c.eligibility_at, c.net_weight, c.paid_amount,
    c.rubber_value_amount,
    case when b.source_rubber_export_id is not null then b.received_at else coalesce(b.client_created_at, b.created_at) end,
    case when b.source_rubber_export_id is not null then b.received_age_is_estimated
      else b.client_created_at is null
        or (coalesce(b.client_created_at, b.created_at) at time zone 'Asia/Bangkok')::date <> c.bill_date end,
    case when b.source_rubber_export_id is not null then b.received_age_hours else null end
  from private.rubber_export_candidates(v_export.location_id, p_selected_report_item_ids, v_export.id) c
  join public.rubber_bills b on b.id = c.bill_id;
  select count(*)::integer, round(sum(i.net_weight), 2), round(sum(i.paid_amount), 2),
    round(sum(i.rubber_value_amount), 2)
  into v_item_count, v_original_weight, v_paid_total, v_rubber_value_total
  from public.rubber_export_items i where i.export_id = v_export.id;
  update public.rubber_exports set original_weight_total = v_original_weight,
    paid_total = v_paid_total, rubber_value_total = v_rubber_value_total,
    average_price = round(v_rubber_value_total / v_original_weight, 2), current_weight = null,
    weight_loss_percent = null, work_rate = null, other_operating_cost = 0, work_total = null
  where id = v_export.id;
  return jsonb_build_object('id', v_export.id, 'status', 'draft', 'itemCount', v_item_count,
    'originalWeightTotal', v_original_weight, 'paidTotal', v_paid_total,
    'rubberValueTotal', v_rubber_value_total);
end;
$$;


ALTER FUNCTION "public"."replace_rubber_export_items"("p_export_id" "uuid", "p_selected_report_item_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_rubber_export_items"("p_export_id" "uuid", "p_selected_report_item_ids" "uuid"[]) IS 'Atomically replaces draft members, retains actual-paid snapshots, and recomputes rubber-value cost snapshots.';



CREATE OR REPLACE FUNCTION "public"."replace_time_payroll_attendance_exceptions"("p_profile_id" "uuid", "p_month" "text", "p_selections" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_month date;
  v_next date;
  v_changed integer;
  v_today date := (now() at time zone 'Asia/Bangkok')::date;
begin
  if v_actor is null or p_profile_id is null or not private.can_manage_time_payroll_profile(p_profile_id)
  then raise exception 'Forbidden'; end if;
  if p_month is null
    or p_month !~ '^[0-9]{4}-[0-9]{2}$'
    or jsonb_typeof(p_selections) is distinct from 'array'
  then raise exception 'INVALID_ATTENDANCE_SELECTIONS'; end if;
  begin v_month := (p_month || '-01')::date; exception when others then raise exception 'INVALID_MONTH'; end;
  if to_char(v_month, 'YYYY-MM') <> p_month then raise exception 'INVALID_MONTH'; end if;
  v_next := (v_month + interval '1 month')::date;
  if exists (
    select 1 from jsonb_array_elements(p_selections) item
    where (item ->> 'date') is not null and (item ->> 'date')::date > v_today
  ) then raise exception 'FUTURE_ATTENDANCE_DATE'; end if;
  perform pg_advisory_xact_lock(hashtextextended('time-payroll-attendance:' || p_profile_id::text, 0));
  perform private.assert_attendance_month_open(p_profile_id, p_month);
  if exists (
    select 1 from jsonb_array_elements(p_selections) item
    where (item ->> 'status') is null
      or (item ->> 'status') not in ('HALF_DAY', 'OFF')
      or (item ->> 'date') is null
      or (item ->> 'date')::date < v_month
      or (item ->> 'date')::date >= v_next
      or not exists (
        select 1 from public.time_payroll_active_periods ap
        where ap.profile_id = p_profile_id and ap.start_on <= (item ->> 'date')::date
          and (ap.end_on is null or ap.end_on >= (item ->> 'date')::date)
      )
  ) or (
    select count(*) <> count(distinct item ->> 'date') from jsonb_array_elements(p_selections) item
  ) then raise exception 'INVALID_ATTENDANCE_SELECTIONS'; end if;

  delete from public.time_payroll_attendance_exceptions x
  where x.profile_id = p_profile_id and x.work_date >= v_month and x.work_date < v_next;
  insert into public.time_payroll_attendance_exceptions(profile_id, work_date, status, created_by, updated_by)
  select p_profile_id, (item ->> 'date')::date, item ->> 'status', v_actor, v_actor
  from jsonb_array_elements(p_selections) item;
  get diagnostics v_changed = row_count;
  insert into public.time_tracking_audit_logs(admin_id, action, target_table, record_id, new_data, comment)
  values (v_actor, 'REPLACE_ATTENDANCE_EXCEPTIONS', 'time_payroll_attendance_exceptions', p_profile_id,
    jsonb_build_object('month', p_month, 'selections', p_selections, 'count', v_changed), 'แก้ข้อยกเว้นวันทำงาน');
  return jsonb_build_object('changed', v_changed, 'month', p_month);
end
$_$;


ALTER FUNCTION "public"."replace_time_payroll_attendance_exceptions"("p_profile_id" "uuid", "p_month" "text", "p_selections" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."replace_time_tracking_segments"("p_profile_id" "uuid", "p_selections" "jsonb", "p_full_snapshot" "jsonb" DEFAULT '{}'::"jsonb", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_item jsonb;
  v_date date;
  v_work_type text;
  v_start timestamptz;
  v_end timestamptz;
  v_old jsonb := '[]'::jsonb;
  v_new jsonb := '[]'::jsonb;
  v_inserted public.time_segments%rowtype;
begin
  if v_actor_id is null or not private.can_approve_time_tracking_profile(p_profile_id) then
    raise exception 'Forbidden';
  end if;
  if jsonb_typeof(p_selections) <> 'array' then
    raise exception 'INVALID_SELECTIONS';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || p_profile_id::text, 0));

  for v_item in select value from jsonb_array_elements(p_selections)
  loop
    v_date := (v_item->>'date')::date;
    v_work_type := v_item->>'work_type';
    if v_date is null
      or v_date > (now() at time zone 'Asia/Bangkok')::date
      or v_work_type not in ('FULL_DAY', 'HALF_DAY', 'NONE')
    then
      raise exception 'INVALID_SELECTION';
    end if;
    if exists (
      select 1 from public.payroll_slips ps
      where ps.profile_id = p_profile_id
        and ps.month = to_char(v_date, 'YYYY-MM')
    ) then
      raise exception 'MONTH_CLOSED:%', to_char(v_date, 'YYYY-MM');
    end if;
    if exists (
      select 1
      from public.financial_transactions ft
      where ft.profile_id = p_profile_id
        and ft.status = 'APPROVED'
        and ft.type in ('DEBT_DEDUCTION', 'WITHDRAWAL_DEDUCTION')
        and ft.applied_month = date_trunc('month', v_date)::date
    ) then
      raise exception 'DEDUCTION_LOCKED:%', to_char(v_date, 'YYYY-MM');
    end if;

    v_start := v_date::timestamp at time zone 'Asia/Bangkok';
    v_end := (v_date + 1)::timestamp at time zone 'Asia/Bangkok';

    select v_old || coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb)
    into v_old
    from public.time_segments s
    where s.profile_id = p_profile_id
      and s.start_time >= v_start
      and s.start_time < v_end;

    delete from public.time_segments s
    where s.profile_id = p_profile_id
      and s.start_time >= v_start
      and s.start_time < v_end;

    if v_work_type <> 'NONE' then
      insert into public.time_segments(profile_id, start_time, end_time)
      values (
        p_profile_id,
        (v_date::text || ' 08:00:00')::timestamp at time zone 'Asia/Bangkok',
        (
          v_date::text
          || case when v_work_type = 'HALF_DAY' then ' 12:00:00' else ' 16:00:00' end
        )::timestamp at time zone 'Asia/Bangkok'
      )
      returning * into v_inserted;
      v_new := v_new || jsonb_build_array(to_jsonb(v_inserted));
    end if;
  end loop;

  insert into public.time_tracking_audit_logs (
    admin_id,
    action,
    target_table,
    record_id,
    old_data,
    new_data,
    comment
  )
  values (
    v_actor_id,
    'BULK_UPDATE_SEGMENTS',
    'time_segments',
    p_profile_id,
    jsonb_build_object('segments', v_old),
    jsonb_build_object('segments', v_new, 'selections', p_selections, 'full_snapshot', p_full_snapshot),
    p_comment
  );

  return jsonb_build_object('status', 'updated');
end;
$$;


ALTER FUNCTION "public"."replace_time_tracking_segments"("p_profile_id" "uuid", "p_selections" "jsonb", "p_full_snapshot" "jsonb", "p_comment" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."financial_transactions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "type" "public"."financial_transaction_type" NOT NULL,
    "amount" numeric NOT NULL,
    "status" "public"."approval_status" DEFAULT 'PENDING'::"public"."approval_status" NOT NULL,
    "admin_comment" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "due_date" "date",
    "description" "text",
    "remaining_amount" numeric DEFAULT 0,
    "parent_debt_id" "uuid",
    "approved_by" "uuid",
    "expense_location_id" "uuid",
    "approved_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "cancel_reason" "text",
    "effective_date" "date",
    "applied_month" "date",
