    CONSTRAINT "rubber_exports_paid_total_check" CHECK (("paid_total" >= (0)::numeric)),
    CONSTRAINT "rubber_exports_previous_status_check" CHECK (("previous_status" = ANY (ARRAY['draft'::"text", 'verified'::"text"]))),
