CREATE OR REPLACE FUNCTION "public"."run_time_tracking_auto_start"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_schedule record;
  v_started integer := 0;
begin
  for v_schedule in
    select rs.*
    from public.time_tracking_resume_schedules rs
    join public.profiles p on p.id = rs.profile_id and p.is_active = true
    where rs.resume_at <= now()
    order by rs.resume_at, rs.profile_id
    for update of rs skip locked
  loop
    perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || v_schedule.profile_id::text, 0));

    if not exists (
      select 1
      from public.time_segments s
      where s.profile_id = v_schedule.profile_id
        and s.end_time is null
    ) and not exists (
      select 1
      from public.payroll_slips ps
      where ps.profile_id = v_schedule.profile_id
        and ps.month = to_char(now() at time zone 'Asia/Bangkok', 'YYYY-MM')
    ) then
      insert into public.time_segments(profile_id, start_time)
      values (v_schedule.profile_id, v_schedule.resume_at);

      insert into public.time_tracking_audit_logs (
        admin_id, action, target_table, record_id, new_data, comment
      )
      values (
        v_schedule.created_by,
        'AUTO_START_NEXT_MONTH',
        'time_segments',
        v_schedule.profile_id,
        jsonb_build_object(
          'start_time', v_schedule.resume_at,
          'payroll_slip_id', v_schedule.payroll_slip_id
        ),
        'เริ่มนับเวลาอัตโนมัติหลังปิดเดือน'
      );
      v_started := v_started + 1;
    end if;

    delete from public.time_tracking_resume_schedules
    where profile_id = v_schedule.profile_id;
  end loop;

  return v_started;
end;
$$;


ALTER FUNCTION "public"."run_time_tracking_auto_start"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_time_tracking_daily_cutoff"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_segment record;
  v_cutoff timestamptz := (
    (now() at time zone 'Asia/Bangkok')::date::text || ' 15:00:00'
  )::timestamp at time zone 'Asia/Bangkok';
  v_count integer := 0;
begin
  if now() < v_cutoff then
    return 0;
  end if;

  for v_segment in
    select s.id, s.profile_id
    from public.time_segments s
    join public.profiles p on p.id = s.profile_id and p.is_active = true
    where s.end_time is null
      and s.start_time < v_cutoff
    order by s.profile_id
  loop
    perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || v_segment.profile_id::text, 0));

    update public.time_segments
    set end_time = v_cutoff
    where id = v_segment.id
      and end_time is null
      and start_time < v_cutoff;
    if not found then
      continue;
    end if;

    if not exists (
      select 1
      from public.payroll_slips ps
      where ps.profile_id = v_segment.profile_id
        and ps.month = to_char(v_cutoff at time zone 'Asia/Bangkok', 'YYYY-MM')
    ) then
      insert into public.time_segments(profile_id, start_time)
      values (v_segment.profile_id, v_cutoff);
    end if;

    insert into public.time_tracking_audit_logs (
      admin_id, action, target_table, record_id, new_data, comment
    )
    values (
      v_segment.profile_id,
      'SYSTEM_DAILY_CUTOFF',
      'time_segments',
      v_segment.profile_id,
      jsonb_build_object('cutoff_time', v_cutoff),
      'ตัดรอบอัตโนมัติ 15:00 น.'
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."run_time_tracking_daily_cutoff"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_customer_master_data"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_name text;
  v_actor_phone text;
  v_customer_id uuid := nullif(payload->>'customerId', '')::uuid;
  v_location_id uuid := nullif(payload->>'defaultLocationId', '')::uuid;
  v_existing public.customers%rowtype;
begin
  select p.name, p.phone
    into v_actor_name, v_actor_phone
  from public.profiles p
  where p.id = v_actor_id
    and p.is_active = true;

  if not found then
    raise exception 'Active authenticated user required' using errcode = '42501';
  end if;

  if v_location_id is null or not private.can_access_location(v_location_id) then
    raise exception 'Location access denied' using errcode = '42501';
  end if;

  if nullif(btrim(payload->>'mainName'), '') is null then
    raise exception 'Customer name is required' using errcode = '22023';
  end if;

  if v_customer_id is null then
    insert into public.customers (
      client_temp_id,
      legacy_rec_id,
      legacy_member_id,
      class,
      main_name,
      fsc_status,
      starting_points_date,
      default_location_id,
      created_by_user_id,
      created_by_name,
      created_by_phone,
      sync_status,
      idempotency_key,
      revision_no,
      record_status,
      server_received_at
    ) values (
      nullif(payload->>'clientTempId', ''),
      nullif(payload->>'legacyRecId', ''),
      nullif(payload->>'legacyMemberId', ''),
      nullif(payload->>'class', ''),
      btrim(payload->>'mainName'),
      nullif(payload->>'fscStatus', ''),
      nullif(payload->>'startingPointsDate', '')::date,
      v_location_id,
      v_actor_id,
      coalesce(v_actor_name, ''),
      coalesce(v_actor_phone, ''),
      'synced',
      nullif(payload->>'idempotencyKey', ''),
      0,
      'active',
      now()
    )
    returning id into v_customer_id;
  else
    select *
      into v_existing
    from public.customers
    where id = v_customer_id
    for update;

    if not found then
      raise exception 'Customer not found' using errcode = 'P0002';
    end if;

    if v_existing.default_location_id is not null
       and not private.can_access_location(v_existing.default_location_id) then
      raise exception 'Customer access denied' using errcode = '42501';
    end if;

    update public.customers
    set legacy_rec_id = nullif(payload->>'legacyRecId', ''),
        legacy_member_id = nullif(payload->>'legacyMemberId', ''),
        class = nullif(payload->>'class', ''),
        main_name = btrim(payload->>'mainName'),
        fsc_status = nullif(payload->>'fscStatus', ''),
        starting_points_date = nullif(payload->>'startingPointsDate', '')::date,
        default_location_id = v_location_id,
        sync_status = 'synced',
        record_status = 'active',
        revision_no = revision_no + 1,
        updated_by_user_id = v_actor_id,
        updated_by_name = coalesce(v_actor_name, ''),
        updated_by_phone = coalesce(v_actor_phone, ''),
        updated_at = now(),
        server_received_at = now()
    where id = v_customer_id;
  end if;

  delete from public.customer_contacts where customer_id = v_customer_id;
  insert into public.customer_contacts (customer_id, phone)
  select v_customer_id, btrim(item.value->>'phone')
  from jsonb_array_elements(coalesce(payload->'contacts', '[]'::jsonb)) as item(value)
  where nullif(btrim(item.value->>'phone'), '') is not null;

  delete from public.customer_bank_accounts where customer_id = v_customer_id;
  insert into public.customer_bank_accounts (
    customer_id,
    bank_name,
    account_number,
    account_name,
    is_primary
  )
  select
    v_customer_id,
    btrim(item.value->>'bankName'),
    btrim(item.value->>'accountNumber'),
    btrim(item.value->>'accountName'),
    coalesce((item.value->>'isPrimary')::boolean, false)
  from jsonb_array_elements(coalesce(payload->'bankAccounts', '[]'::jsonb)) as item(value)
  where nullif(btrim(item.value->>'accountNumber'), '') is not null;

  delete from public.customer_farms where customer_id = v_customer_id;
  insert into public.customer_farms (customer_id, owner_name, address, card_number)
  select
    v_customer_id,
    nullif(btrim(item.value->>'ownerName'), ''),
    nullif(btrim(item.value->>'address'), ''),
    nullif(btrim(item.value->>'cardNumber'), '')
  from jsonb_array_elements(coalesce(payload->'farms', '[]'::jsonb)) as item(value)
  where nullif(btrim(item.value->>'ownerName'), '') is not null
     or nullif(btrim(item.value->>'address'), '') is not null
     or nullif(btrim(item.value->>'cardNumber'), '') is not null;

  return jsonb_build_object('id', v_customer_id);
end;
$$;


ALTER FUNCTION "public"."save_customer_master_data"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dashboard_alert_thresholds"("p_location_id" "uuid", "p_purchase_average_min" numeric, "p_net_cash_min" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_name text;
begin
  perform private.dashboard_require_manager();

  if p_purchase_average_min < 0
    or p_net_cash_min is null
    or p_net_cash_min < 0
  then
    raise exception 'เกณฑ์แจ้งเตือนต้องไม่ติดลบ';
  end if;

  if not exists (
    select 1 from public.locations l
    where l.id = p_location_id and l.is_active = true
  ) then
    raise exception 'ไม่พบสาขาที่เปิดใช้งาน';
  end if;

  select p.name
  into actor_name
  from public.profiles p
  where p.id = auth.uid();

  insert into public.dashboard_alert_thresholds (
    location_id,
    purchase_average_min,
    net_cash_min,
    updated_by_user_id,
    updated_by_name,
    is_configured
  )
  values (
    p_location_id,
    p_purchase_average_min,
    p_net_cash_min,
    auth.uid(),
    actor_name,
    true
  )
  on conflict (location_id) do update
  set purchase_average_min = excluded.purchase_average_min,
      net_cash_min = excluded.net_cash_min,
      updated_by_user_id = excluded.updated_by_user_id,
      updated_by_name = excluded.updated_by_name,
      is_configured = true,
      updated_at = now();

  return public.get_dashboard_alert_thresholds(p_location_id);
end;
$$;


ALTER FUNCTION "public"."save_dashboard_alert_thresholds"("p_location_id" "uuid", "p_purchase_average_min" numeric, "p_net_cash_min" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dashboard_manager_config"("p_location_id" "uuid", "p_interval_minutes" integer, "p_purchase_average_min" numeric, "p_net_cash_min" numeric, "p_stock_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item jsonb;
begin
  perform private.dashboard_require_manager();

  if jsonb_typeof(p_stock_items) <> 'array' then
    raise exception 'เกณฑ์สต็อกไม่ถูกต้อง';
  end if;

  perform public.save_dashboard_refresh_interval(p_interval_minutes);
  perform public.save_dashboard_alert_thresholds(
    p_location_id,
    p_purchase_average_min,
    p_net_cash_min
  );

  for item in select value from jsonb_array_elements(p_stock_items)
  loop
    perform public.save_dashboard_stock_alert_threshold(
      p_location_id,
      (item ->> 'productId')::uuid,
      case
        when item -> 'minimumBalance' = 'null'::jsonb then null
        else (item ->> 'minimumBalance')::numeric
      end
    );
  end loop;

  return jsonb_build_object(
    'settings', public.get_dashboard_refresh_settings(),
    'thresholds', public.get_dashboard_alert_thresholds(p_location_id)
  );
end;
$$;


ALTER FUNCTION "public"."save_dashboard_manager_config"("p_location_id" "uuid", "p_interval_minutes" integer, "p_purchase_average_min" numeric, "p_net_cash_min" numeric, "p_stock_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dashboard_refresh_interval"("p_interval_minutes" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_name text;
begin
  perform private.dashboard_require_manager();

  if p_interval_minutes is null
    or p_interval_minutes < 10
    or p_interval_minutes > 1440
  then
    raise exception 'รอบคำนวณต้องอยู่ระหว่าง 10 ถึง 1,440 นาที';
  end if;

  select p.name
  into actor_name
  from public.profiles p
  where p.id = auth.uid();

  update public.dashboard_refresh_settings
  set interval_minutes = p_interval_minutes,
      updated_by_user_id = auth.uid(),
      updated_by_name = actor_name,
      updated_at = now()
  where id = true;

  return public.get_dashboard_refresh_settings();
end;
$$;


ALTER FUNCTION "public"."save_dashboard_refresh_interval"("p_interval_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dashboard_stock_alert_threshold"("p_location_id" "uuid", "p_product_id" "uuid", "p_minimum_balance" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_name text;
begin
  perform private.dashboard_require_manager();

  if not exists (
    select 1 from public.locations l
    where l.id = p_location_id and l.is_active = true
  ) then
    raise exception 'ไม่พบสาขาที่เปิดใช้งาน';
  end if;

  if not exists (
    select 1 from public.stock_products p
    where p.id = p_product_id and p.is_active = true
  ) then
    raise exception 'ไม่พบสินค้าที่เปิดใช้งาน';
  end if;

  if p_minimum_balance is not null and p_minimum_balance < 0 then
    raise exception 'เกณฑ์สต็อกต้องไม่ติดลบ';
  end if;

  if p_minimum_balance is null then
    delete from public.dashboard_stock_alert_thresholds
    where location_id = p_location_id
      and product_id = p_product_id;
  else
    select p.name
    into actor_name
    from public.profiles p
    where p.id = auth.uid();

    insert into public.dashboard_stock_alert_thresholds (
      location_id,
      product_id,
      minimum_balance,
      updated_by_user_id,
      updated_by_name
    )
    values (
      p_location_id,
      p_product_id,
      p_minimum_balance,
      auth.uid(),
      actor_name
    )
    on conflict (location_id, product_id) do update
    set minimum_balance = excluded.minimum_balance,
        updated_by_user_id = excluded.updated_by_user_id,
        updated_by_name = excluded.updated_by_name,
        updated_at = now();
  end if;

  return public.get_dashboard_alert_thresholds(p_location_id);
end;
$$;


ALTER FUNCTION "public"."save_dashboard_stock_alert_threshold"("p_location_id" "uuid", "p_product_id" "uuid", "p_minimum_balance" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_money_transfer"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid := (p_payload->>'id')::uuid;
  v_location_id uuid := (p_payload->>'locationId')::uuid;
  v_idempotency_key text := nullif(p_payload->>'idempotencyKey', '');
  v_operation text := coalesce(p_payload->>'operation', 'create');
  v_transfer_type text := coalesce(p_payload->>'transferType', 'customer');
  v_expected_revision integer := coalesce((p_payload->>'revisionNo')::integer, 0);
  v_target_location_id uuid := nullif(p_payload->>'targetLocationId', '')::uuid;
  v_request_fingerprint text := pg_catalog.md5((p_payload - 'operation')::text);
  v_existing public.money_transfers;
  v_retry public.money_transfers;
  v_is_create boolean;
  v_slip_ids uuid[];
  v_item_ids uuid[];
  v_changed_sources jsonb;
  v_target_location_name text;
  v_accounting_date date;
  v_branch_total numeric(12,2);
  v_ocr_fingerprint text;
begin
  if not private.is_active_user() or not private.can_access_money_transfer_module() then
    raise exception 'MT_ACCESS_DENIED: ไม่มีสิทธิ์ใช้งานรายการโอนเงิน';
  end if;
  if v_id is null or v_location_id is null then
    raise exception 'MT_INVALID_PAYLOAD: ข้อมูลรายการโอนไม่ครบ';
  end if;
  if not private.can_access_location(v_location_id) then
    raise exception 'MT_LOCATION_DENIED: ไม่มีสิทธิ์เข้าถึงสาขา';
  end if;
  if v_transfer_type not in ('customer', 'transport', 'branch') then
    raise exception 'MT_UNSUPPORTED_WORKFLOW: ไม่รองรับประเภทการโอนนี้';
  end if;
  if v_operation not in ('create', 'update') then
    raise exception 'MT_INVALID_OPERATION: operation ไม่ถูกต้อง';
  end if;
  if jsonb_typeof(coalesce(p_payload->'slips', '[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_payload->'items', '[]'::jsonb)) <> 'array' then
    raise exception 'MT_INVALID_PAYLOAD: slips/items ต้องเป็นรายการ';
  end if;

  if v_idempotency_key is not null and v_operation = 'create' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('money-transfer-create:' || v_idempotency_key, 0)
    );
  end if;

  if v_idempotency_key is not null then
    select * into v_retry
    from public.money_transfers t
    where t.idempotency_key = v_idempotency_key
      and t.record_status <> 'deleted'
    for update;

    if v_retry.id is not null then
      if v_retry.location_id <> v_location_id then
        raise exception 'MT_IDEMPOTENCY_CONFLICT: idempotency key อยู่คนละสาขา';
      end if;
      if v_operation = 'create' then
        if v_retry.request_fingerprint is not null
          and v_retry.request_fingerprint <> v_request_fingerprint then
          raise exception 'MT_IDEMPOTENCY_PAYLOAD_MISMATCH: idempotency key ถูกใช้กับข้อมูลอื่นแล้ว';
        end if;
        return public.get_money_transfer_detail(v_retry.id)
          || jsonb_build_object('idempotentReplay', true, 'changedSources', '[]'::jsonb);
      end if;
      if v_retry.id <> v_id then
        raise exception 'MT_IDEMPOTENCY_CONFLICT: idempotency key ไม่ตรงรายการ';
      end if;
    end if;
  end if;

  select * into v_existing
  from public.money_transfers t
  where t.id = v_id
  for update;
  v_is_create := v_existing.id is null;

  if v_operation = 'create' and not v_is_create then
    raise exception 'MT_IDEMPOTENCY_CONFLICT: มีรหัสรายการนี้แล้ว';
  end if;
  if v_operation = 'update' and v_is_create then
    raise exception 'MT_NOT_FOUND: ไม่พบรายการโอนเงิน';
  end if;
  if not v_is_create then
    if v_existing.location_id <> v_location_id then
      raise exception 'MT_LOCATION_MISMATCH: ห้ามย้ายรายการข้ามสาขา';
    end if;
    if v_existing.record_status = 'deleted' then
      raise exception 'MT_NOT_FOUND: ไม่พบรายการโอนเงิน';
    end if;
    if v_existing.revision_no <> v_expected_revision then
      raise exception 'MT_REVISION_CONFLICT: ข้อมูลถูกแก้ไขแล้ว กรุณาโหลดใหม่';
    end if;
    if public.report_lock_no(v_existing) is not null then
      raise exception 'MT_REPORT_LOCKED: รายการถูกล็อกโดยรายงาน';
    end if;
    if v_existing.transfer_type <> v_transfer_type then
      raise exception 'MT_TRANSFER_TYPE_IMMUTABLE: ห้ามเปลี่ยนประเภทรายการโอน';
    end if;
    if v_existing.transfer_type = 'branch'
      and v_existing.location_id <> v_existing.target_location_id then
      raise exception 'MT_LEGACY_BRANCH_READ_ONLY: รายการโอนระหว่างสาขารุ่นเดิมแก้ไขไม่ได้';
    end if;
  end if;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_payload->'slips', '[]'::jsonb)) x
    group by x->>'id'
    having count(*) > 1
  ) then
    raise exception 'MT_DUPLICATE_SLIP_ID: มีรหัสสลิปซ้ำในรายการ';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_payload->'slips', '[]'::jsonb)) x
    join public.money_transfer_slips s on s.id = (x->>'id')::uuid
    where s.transfer_id <> v_id
  ) then
    raise exception 'MT_SLIP_PARENT_CONFLICT: สลิปอยู่ในรายการโอนอื่น';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x
    group by x->>'id'
    having count(*) > 1
  ) then
    raise exception 'MT_DUPLICATE_ITEM_ID: มีรหัสแหล่งจ่ายซ้ำในรายการ';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x
    join public.money_transfer_items i on i.id = (x->>'id')::uuid
    where i.transfer_id <> v_id
  ) then
    raise exception 'MT_ITEM_PARENT_CONFLICT: แหล่งจ่ายอยู่ในรายการโอนอื่น';
  end if;

  if v_transfer_type = 'branch' then
    if v_target_location_id is null or v_target_location_id <> v_location_id then
      raise exception 'MT_BRANCH_TARGET_MISMATCH: รายการโอนให้สาขาต้องเป็นของสาขาผู้รับ';
    end if;
    if not private.can_access_location(v_target_location_id) then
      raise exception 'MT_TARGET_LOCATION_DENIED: ไม่มีสิทธิ์โอนให้สาขานี้';
    end if;
    select l.name into v_target_location_name
    from public.locations l
    where l.id = v_target_location_id
      and l.is_active = true;
    if v_target_location_name is null then
      raise exception 'MT_TARGET_LOCATION_INACTIVE: สาขาผู้รับไม่เปิดใช้งาน';
    end if;
    if jsonb_array_length(coalesce(p_payload->'items', '[]'::jsonb)) <> 0 then
      raise exception 'MT_BRANCH_SOURCE_NOT_ALLOWED: โอนให้สาขาไม่มีรายการต้นทาง';
    end if;
    if jsonb_array_length(coalesce(p_payload->'slips', '[]'::jsonb)) = 0 then
      raise exception 'MT_SLIP_REQUIRED: กรุณาเพิ่มสลิปอย่างน้อยหนึ่งใบ';
    end if;
    if exists (
      select 1
      from jsonb_array_elements(p_payload->'slips') x
      where nullif(x->>'id', '') is null
        or coalesce((x->>'amount')::numeric, 0) <= 0
        or coalesce((x->>'fee')::numeric, 0) < 0
        or nullif(x->>'transactionDate', '') is null
        or x->>'inputMethod' not in ('manual', 'ocr')
        or (x->>'inputMethod' = 'manual' and nullif(trim(x->>'referenceNumber'), '') is not null)
        or (x->>'inputMethod' = 'ocr' and nullif(trim(x->>'referenceNumber'), '') is null)
    ) then
      raise exception 'MT_INVALID_SLIP: จำนวนเงิน ค่าธรรมเนียม วันเวลา หรือที่มาของสลิปไม่ถูกต้อง';
    end if;

    select
      min(((x->>'transactionDate')::timestamptz at time zone 'Asia/Bangkok')::date),
      round(sum((x->>'amount')::numeric), 2)
    into v_accounting_date, v_branch_total
    from jsonb_array_elements(p_payload->'slips') x;

    if exists (
      select 1
      from jsonb_array_elements(p_payload->'slips') x
      where ((x->>'transactionDate')::timestamptz at time zone 'Asia/Bangkok')::date
        <> v_accounting_date
    ) then
      raise exception 'MT_SLIP_DATE_MISMATCH: สลิปทุกใบต้องเป็นวันเดียวกันตามเวลาไทย';
    end if;

    if exists (
      select 1
      from jsonb_array_elements(p_payload->'slips') x
      where x->>'inputMethod' = 'ocr'
      group by private.money_transfer_ocr_fingerprint(
        x->>'referenceNumber',
        (x->>'amount')::numeric,
        (x->>'transactionDate')::timestamptz
      )
      having count(*) > 1
    ) then
      raise exception 'MT_OCR_DUPLICATE: พบสลิป OCR ซ้ำในรายการ';
    end if;

    for v_ocr_fingerprint in
      select distinct private.money_transfer_ocr_fingerprint(
        x->>'referenceNumber',
        (x->>'amount')::numeric,
        (x->>'transactionDate')::timestamptz
      )
      from jsonb_array_elements(p_payload->'slips') x
      where x->>'inputMethod' = 'ocr'
      order by 1
    loop
      perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('money-transfer-ocr:' || v_ocr_fingerprint, 0)
      );
    end loop;

    if exists (
      select 1
      from jsonb_array_elements(p_payload->'slips') x
      join public.money_transfer_slips s
        on s.ocr_fingerprint = private.money_transfer_ocr_fingerprint(
          x->>'referenceNumber',
          (x->>'amount')::numeric,
          (x->>'transactionDate')::timestamptz
        )
      join public.money_transfers t
        on t.id = s.transfer_id
       and t.record_status <> 'deleted'
      where x->>'inputMethod' = 'ocr'
        and t.id <> v_id
    ) then
      raise exception 'MT_OCR_DUPLICATE: สลิป OCR ถูกใช้ในรายการอื่นแล้ว';
    end if;
  end if;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x
    group by x->>'sourceType', x->>'sourceId'
    having count(*) > 1
  ) then
    raise exception 'MT_DUPLICATE_SOURCE: มีแหล่งจ่ายซ้ำในรายการ';
  end if;

  perform b.id
  from public.rubber_bills b
  where b.id = any(coalesce((
    select array_agg((x->>'sourceId')::uuid)
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x
    where x->>'sourceType' = 'rubber_bill'
  ), array[]::uuid[]))
  order by b.id
  for update;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x
    where x->>'sourceType' <> 'rubber_bill'
  ) then
    raise exception 'MT_INVALID_SOURCE: ประเภทแหล่งจ่ายไม่ถูกต้อง';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x
    left join public.rubber_bills b on b.id = (x->>'sourceId')::uuid
    where x->>'sourceType' = 'rubber_bill' and (
      b.id is null
      or b.location_id <> v_location_id
      or b.record_status <> 'active'
      or b.sync_status::text <> 'synced'
      or b.server_bill_no is null
      or b.net_total <= 0
      or (
        public.report_lock_no(b) is not null
        and not exists (
          select 1
          from public.money_transfer_items current_item
          where current_item.transfer_id = v_id
            and current_item.source_type = 'rubber_bill'
            and current_item.source_id = b.id
        )
      )
      or private.rubber_bill_has_pending_approval(b.id)
      or exists (
        select 1
        from public.rubber_bill_items bi
        where bi.bill_id = b.id
          and bi.item_type = 'weigh'
          and coalesce(bi.price, 0) <= 0
      )
    )
  ) then
    raise exception 'MT_RUBBER_SOURCE_BLOCKED: บิลยางยังไม่พร้อมโอนหรือถูกล็อก';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x
    join public.money_transfer_items i
      on i.source_type = x->>'sourceType'
     and i.source_id = (x->>'sourceId')::uuid
    join public.money_transfers t
      on t.id = i.transfer_id
     and t.record_status <> 'deleted'
    where i.transfer_id <> v_id
  ) then
    raise exception 'MT_SOURCE_ALREADY_USED: แหล่งจ่ายถูกใช้ในรายการโอนอื่นแล้ว';
  end if;

  if v_is_create then
    insert into public.money_transfers (
      id, client_temp_id, idempotency_key, request_fingerprint, location_id,
      customer_id, customer_name, account_number, account_name, bank_name,
      net_amount_to_pay, branch_paid_amount, transfer_type, transport_cost,
      transport_staff_id, transport_staff_name, target_location_id,
      target_location_name, transfer_status, accounting_date,
      created_by_user_id, created_by_name, created_by_phone, revision_no, record_status
    ) values (
      v_id, p_payload->>'clientTempId', v_idempotency_key, v_request_fingerprint, v_location_id,
      nullif(p_payload->>'customerId', '')::uuid, p_payload->>'customerName',
      p_payload->>'accountNumber', p_payload->>'accountName', p_payload->>'bankName',
      case when v_transfer_type = 'branch' then v_branch_total
        else coalesce((p_payload->>'netAmountToPay')::numeric, 0) end,
      case when v_transfer_type = 'branch' then 0
        else coalesce((p_payload->>'branchPaidAmount')::numeric, 0) end,
      v_transfer_type, nullif(p_payload->>'transportCost', '')::numeric,
      nullif(p_payload->>'transportStaffId', '')::uuid, p_payload->>'transportStaffName',
      case when v_transfer_type = 'branch' then v_location_id else v_target_location_id end,
      case when v_transfer_type = 'branch' then v_target_location_name else p_payload->>'targetLocationName' end,
      case when v_transfer_type = 'branch' then 'paid'
        else coalesce(p_payload->>'transferStatus', 'pending') end,
      case when v_transfer_type = 'branch' then v_accounting_date end,
      auth.uid(), coalesce(p_payload->>'createdByName', ''),
      coalesce(p_payload->>'createdByPhone', ''), 0, 'active'
    );
  else
    update public.money_transfers t set
      customer_id = nullif(p_payload->>'customerId', '')::uuid,
      customer_name = p_payload->>'customerName',
      account_number = p_payload->>'accountNumber',
      account_name = p_payload->>'accountName',
      bank_name = p_payload->>'bankName',
      net_amount_to_pay = case when v_transfer_type = 'branch' then v_branch_total
        else coalesce((p_payload->>'netAmountToPay')::numeric, 0) end,
      branch_paid_amount = case when v_transfer_type = 'branch' then 0
        else coalesce((p_payload->>'branchPaidAmount')::numeric, 0) end,
      transport_cost = nullif(p_payload->>'transportCost', '')::numeric,
      transport_staff_id = nullif(p_payload->>'transportStaffId', '')::uuid,
      transport_staff_name = p_payload->>'transportStaffName',
      target_location_id = case when v_transfer_type = 'branch' then v_location_id
        else v_target_location_id end,
      target_location_name = case when v_transfer_type = 'branch' then v_target_location_name
        else p_payload->>'targetLocationName' end,
      transfer_status = case when v_transfer_type = 'branch' then 'paid'
        else coalesce(p_payload->>'transferStatus', t.transfer_status) end,
      accounting_date = case when v_transfer_type = 'branch' then v_accounting_date
        else t.accounting_date end,
      revision_no = t.revision_no + 1,
      updated_at = now()
    where t.id = v_id;
  end if;

  select coalesce(array_agg((x->>'id')::uuid), array[]::uuid[])
  into v_slip_ids
  from jsonb_array_elements(coalesce(p_payload->'slips', '[]'::jsonb)) x;

  delete from public.money_transfer_slips s
  where s.transfer_id = v_id
    and not (s.id = any(v_slip_ids));

  insert into public.money_transfer_slips (
    id, transfer_id, amount, reference_number, fee, sender_name, receiver_name,
    transaction_date, slip_image_url, sort_order, input_method, ocr_fingerprint
  )
  select
    (x->>'id')::uuid,
    v_id,
    coalesce((x->>'amount')::numeric, 0),
    case when x->>'inputMethod' = 'manual' then null else nullif(x->>'referenceNumber', '') end,
    coalesce((x->>'fee')::numeric, 0),
    x->>'senderName',
    x->>'receiverName',
    nullif(x->>'transactionDate', '')::timestamptz,
    x->>'slipImageUrl',
    coalesce((x->>'sortOrder')::integer, 0),
    nullif(x->>'inputMethod', ''),
    case when x->>'inputMethod' = 'ocr' then private.money_transfer_ocr_fingerprint(
      x->>'referenceNumber',
      (x->>'amount')::numeric,
      (x->>'transactionDate')::timestamptz
    ) end
  from jsonb_array_elements(coalesce(p_payload->'slips', '[]'::jsonb)) x
  on conflict (id) do update set
    amount = excluded.amount,
    reference_number = excluded.reference_number,
    fee = excluded.fee,
    sender_name = excluded.sender_name,
    receiver_name = excluded.receiver_name,
    transaction_date = excluded.transaction_date,
    slip_image_url = excluded.slip_image_url,
    sort_order = excluded.sort_order,
    input_method = excluded.input_method,
    ocr_fingerprint = excluded.ocr_fingerprint,
    updated_at = now()
  where money_transfer_slips.transfer_id = v_id;

  select coalesce(array_agg((x->>'id')::uuid), array[]::uuid[])
  into v_item_ids
  from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x;

  select coalesce(jsonb_agg(jsonb_build_object(
    'sourceType', i.source_type,
    'sourceId', i.source_id
  )), '[]'::jsonb)
  into v_changed_sources
  from public.money_transfer_items i
  where i.transfer_id = v_id;

  delete from public.money_transfer_items i
  where i.transfer_id = v_id
    and not (i.id = any(v_item_ids));

  insert into public.money_transfer_items (
    id, transfer_id, source_type, source_id, rubber_bill_id, customer_name, amount
  )
  select
    (x->>'id')::uuid,
    v_id,
    'rubber_bill',
    (x->>'sourceId')::uuid,
    (x->>'sourceId')::uuid,
    b.customer_name,
    b.net_total
  from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x
  join public.rubber_bills b on b.id = (x->>'sourceId')::uuid
  where not exists (
    select 1
    from public.money_transfer_items existing
    where existing.id = (x->>'id')::uuid
      and existing.transfer_id = v_id
      and existing.source_type = 'rubber_bill'
      and existing.source_id = (x->>'sourceId')::uuid
      and existing.customer_name is not distinct from b.customer_name
      and existing.amount is not distinct from b.net_total
  )
  on conflict (id) do update set
    source_type = excluded.source_type,
    source_id = excluded.source_id,
    rubber_bill_id = excluded.rubber_bill_id,
    customer_name = excluded.customer_name,
    amount = excluded.amount
  where money_transfer_items.transfer_id = v_id
    and (
      money_transfer_items.source_type is distinct from excluded.source_type
      or money_transfer_items.source_id is distinct from excluded.source_id
      or money_transfer_items.rubber_bill_id is distinct from excluded.rubber_bill_id
      or money_transfer_items.customer_name is distinct from excluded.customer_name
      or money_transfer_items.amount is distinct from excluded.amount
    );

  select coalesce(jsonb_agg(jsonb_build_object(
    'sourceType', changed.source_type,
    'sourceId', changed.source_id
  ) order by changed.source_type, changed.source_id), '[]'::jsonb)
  into v_changed_sources
  from (
    select
      old_source.value->>'sourceType' source_type,
      (old_source.value->>'sourceId')::uuid source_id
    from jsonb_array_elements(v_changed_sources) old_source
    union
    select x->>'sourceType', (x->>'sourceId')::uuid
    from jsonb_array_elements(coalesce(p_payload->'items', '[]'::jsonb)) x
  ) changed;

  return public.get_money_transfer_detail(v_id)
    || jsonb_build_object('idempotentReplay', false, 'changedSources', v_changed_sources);
exception
  when unique_violation then
    raise exception 'MT_SOURCE_ALREADY_USED: แหล่งจ่ายถูกใช้ในรายการโอนอื่นแล้ว';
end;
$$;


ALTER FUNCTION "public"."save_money_transfer"("p_payload" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."rubber_bill_approval_settings" (
    "id" boolean DEFAULT true NOT NULL,
    "edit_window_minutes" integer DEFAULT 30 NOT NULL,
    "configured_price" numeric(12,2),
    "updated_by_user_id" "uuid",
    "updated_by_name" "text",
    "updated_by_phone" "text",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "non_current_date_requires_approval" boolean DEFAULT false NOT NULL,
    CONSTRAINT "rubber_bill_approval_settings_configured_price_check" CHECK ((("configured_price" IS NULL) OR ("configured_price" >= (0)::numeric))),
    CONSTRAINT "rubber_bill_approval_settings_edit_window_minutes_check" CHECK (("edit_window_minutes" >= 0)),
    CONSTRAINT "rubber_bill_approval_settings_id_check" CHECK (("id" = true))
);


ALTER TABLE "public"."rubber_bill_approval_settings" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_rubber_bill_approval_settings"("p_edit_window_minutes" integer, "p_configured_price" numeric) RETURNS "public"."rubber_bill_approval_settings"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
  select public.save_rubber_bill_approval_settings(
    p_edit_window_minutes,
    p_configured_price,
    coalesce((select non_current_date_requires_approval from public.rubber_bill_approval_settings where id = true), false)
  );
$$;


ALTER FUNCTION "public"."save_rubber_bill_approval_settings"("p_edit_window_minutes" integer, "p_configured_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_rubber_bill_approval_settings"("p_edit_window_minutes" integer, "p_configured_price" numeric, "p_non_current_date_requires_approval" boolean) RETURNS "public"."rubber_bill_approval_settings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_result public.rubber_bill_approval_settings%rowtype;
  v_actor_name text;
  v_actor_phone text;
begin
  if not private.is_active_user() or not public.can_access_super_admin_features() then
    raise exception 'ไม่มีสิทธิ์ตั้งค่าการอนุมัติบิลยาง';
  end if;
  if p_edit_window_minutes is null or p_edit_window_minutes < 0 then
    raise exception 'จำนวนนาทีต้องเป็นจำนวนเต็มตั้งแต่ 0 ขึ้นไป';
  end if;
  if p_configured_price is not null
     and (p_configured_price < 0 or scale(p_configured_price) > 2) then
    raise exception 'ราคายางต้องไม่ติดลบและมีทศนิยมไม่เกิน 2 ตำแหน่ง';
  end if;

  select name, phone into v_actor_name, v_actor_phone
  from public.profiles where id = auth.uid();

  update public.rubber_bill_approval_settings
  set edit_window_minutes = p_edit_window_minutes,
      configured_price = p_configured_price,
      non_current_date_requires_approval = coalesce(p_non_current_date_requires_approval, false),
      updated_by_user_id = auth.uid(),
      updated_by_name = coalesce(v_actor_name, ''),
      updated_by_phone = coalesce(v_actor_phone, ''),
      updated_at = now()
  where id = true
  returning * into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."save_rubber_bill_approval_settings"("p_edit_window_minutes" integer, "p_configured_price" numeric, "p_non_current_date_requires_approval" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_rubber_bill_date_approval_setting"("p_non_current_date_requires_approval" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.is_active_user() or not private.can_access_super_admin_features() then
    raise exception 'FORBIDDEN: ไม่มีสิทธิ์ตั้งค่าการอนุมัติบิลยาง';
  end if;
  if p_non_current_date_requires_approval is null then
    raise exception 'RUBBER_GROUP_INVALID: ต้องระบุกฎวันที่บิล';
  end if;
  update public.rubber_bill_approval_settings
  set non_current_date_requires_approval = p_non_current_date_requires_approval,
      updated_by_user_id = auth.uid(),
      updated_by_name = (select p.name from public.profiles p where p.id = auth.uid()),
      updated_by_phone = (select p.phone from public.profiles p where p.id = auth.uid()),
      updated_at = now()
  where id = true;
  return p_non_current_date_requires_approval;
end
$$;


ALTER FUNCTION "public"."save_rubber_bill_date_approval_setting"("p_non_current_date_requires_approval" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_telegram_badge_config"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_settings public.telegram_badge_settings%rowtype;
  next_enabled boolean;
  next_chat_id text;
  next_start_time time;
  next_end_time time;
  next_interval integer;
  next_keys text[];
  next_evidence_enabled boolean;
  next_evidence_interval integer;
  token_value text;
  actor_name text;
  actor_phone text;
  unknown_keys text[];
  schedule_changed boolean;
  evidence_schedule_changed boolean;
begin
  perform private.telegram_badge_require_manager();

  select * into strict current_settings
  from public.telegram_badge_settings
  where id = true
  for update;

  next_enabled := coalesce((payload->>'enabled')::boolean, current_settings.enabled);
  next_chat_id := nullif(btrim(coalesce(payload->>'chatId', current_settings.chat_id)), '');
  next_start_time := coalesce(nullif(payload->>'startTime', '')::time, current_settings.start_time);
  next_end_time := coalesce(nullif(payload->>'endTime', '')::time, current_settings.end_time);
  next_interval := coalesce((payload->>'intervalMinutes')::integer, current_settings.interval_minutes);
  next_evidence_enabled := coalesce((payload->>'evidenceEnabled')::boolean, current_settings.evidence_enabled);
  next_evidence_interval := coalesce((payload->>'evidenceIntervalMinutes')::integer, current_settings.evidence_interval_minutes);
  token_value := nullif(btrim(payload->>'botToken'), '');

  if jsonb_typeof(payload->'enabledBadgeKeys') = 'array' then
    select coalesce(array_agg(value order by value), array[]::text[])
    into next_keys
    from (
      select distinct jsonb_array_elements_text(payload->'enabledBadgeKeys') value
    ) selected;
  else
    next_keys := current_settings.enabled_badge_keys;
  end if;

  select array_agg(key) into unknown_keys
  from unnest(next_keys) key
  where not exists (
    select 1 from public.telegram_badge_catalog c where c.badge_key = key
  );

  if unknown_keys is not null then raise exception 'ประเภท Badge ไม่ถูกต้อง'; end if;
  if next_start_time >= next_end_time then raise exception 'เวลาเริ่มต้องน้อยกว่าเวลาสิ้นสุด'; end if;
  if next_interval not between 10 and 240 then raise exception 'ระยะห่างต้องอยู่ระหว่าง 10 ถึง 240 นาที'; end if;
  if next_evidence_interval not between 30 and 1440 then raise exception 'ระยะห่าง Evidence ต้องอยู่ระหว่าง 30 ถึง 1440 นาที'; end if;
  if next_enabled and next_chat_id is null then raise exception 'กรุณาระบุ Chat ID'; end if;
  if next_enabled and current_settings.bot_token_secret_id is null and token_value is null then
    raise exception 'กรุณาระบุ Bot Token';
  end if;

  schedule_changed :=
    next_start_time is distinct from current_settings.start_time
    or next_end_time is distinct from current_settings.end_time
    or next_interval is distinct from current_settings.interval_minutes;
  evidence_schedule_changed :=
    next_start_time is distinct from current_settings.start_time
    or next_end_time is distinct from current_settings.end_time
    or next_evidence_interval is distinct from current_settings.evidence_interval_minutes;

  if token_value is not null then
    if current_settings.bot_token_secret_id is null then
      current_settings.bot_token_secret_id := vault.create_secret(
        token_value,
        'lanflow_telegram_badge_bot_token',
        'Telegram Bot Token for the LanFlow badge digest'
      );
    else
      perform vault.update_secret(
        current_settings.bot_token_secret_id,
        token_value,
        'lanflow_telegram_badge_bot_token',
        'Telegram Bot Token for the LanFlow badge digest'
      );
    end if;
  end if;

  select p.name, p.phone into actor_name, actor_phone
  from public.profiles p where p.id = auth.uid();

  update public.telegram_badge_settings
  set enabled = next_enabled,
      chat_id = next_chat_id,
      start_time = next_start_time,
      end_time = next_end_time,
      interval_minutes = next_interval,
      enabled_badge_keys = next_keys,
      evidence_enabled = next_evidence_enabled,
      evidence_interval_minutes = next_evidence_interval,
      bot_token_secret_id = current_settings.bot_token_secret_id,
      initial_attempt_at = case
        when next_enabled and not current_settings.enabled then now() + interval '10 minutes'
        when not next_enabled then null
        when schedule_changed then null
        else initial_attempt_at
      end,
      retry_at = case when not next_enabled or schedule_changed then null else retry_at end,
      pending_slot_at = case when not next_enabled or schedule_changed then null else pending_slot_at end,
      claim_token = case when not next_enabled or schedule_changed then null else claim_token end,
      claimed_at = case when not next_enabled or schedule_changed then null else claimed_at end,
      last_completed_slot_at = case
        when next_enabled and current_settings.enabled and schedule_changed
          then private.telegram_badge_latest_slot(now(), next_start_time, next_end_time, next_interval)
        else last_completed_slot_at
      end,
      last_error = case when not next_enabled then null else last_error end,
      evidence_last_attempted_slot_at = case
        when next_evidence_enabled and (
          not current_settings.evidence_enabled or evidence_schedule_changed
        ) then private.telegram_badge_latest_slot(
          now(), next_start_time, next_end_time, next_evidence_interval
        )
        else evidence_last_attempted_slot_at
      end,
      evidence_claim_token = case
        when not next_evidence_enabled
          or not next_enabled
          or evidence_schedule_changed
          or next_evidence_enabled is distinct from current_settings.evidence_enabled
        then null else evidence_claim_token
      end,
      evidence_claimed_at = case
        when not next_evidence_enabled
          or not next_enabled
          or evidence_schedule_changed
          or next_evidence_enabled is distinct from current_settings.evidence_enabled
        then null else evidence_claimed_at
      end,
      updated_by_user_id = auth.uid(),
      updated_by_name = actor_name,
      updated_by_phone = actor_phone,
      updated_at = now()
  where id = true;

  return public.get_telegram_badge_config();
end;
$$;


ALTER FUNCTION "public"."save_telegram_badge_config"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_telegram_badge_config_with_evidence_locations"("payload" "jsonb", "p_all_locations" boolean, "p_location_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_config jsonb;
  v_locations jsonb;
begin
  v_config := public.save_telegram_badge_config(payload);
  v_locations := public.save_telegram_evidence_location_config(
    p_all_locations,
    p_location_ids
  );
  return v_config || jsonb_build_object(
    'evidenceAllLocations', v_locations->'allLocations',
    'evidenceLocationIds', v_locations->'locationIds',
    'evidenceLocations', v_locations->'locations'
  );
end;
$$;


ALTER FUNCTION "public"."save_telegram_badge_config_with_evidence_locations"("payload" "jsonb", "p_all_locations" boolean, "p_location_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_telegram_evidence_location_config"("p_all_locations" boolean, "p_location_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ids uuid[];
begin
  perform private.telegram_badge_require_manager();
  if p_all_locations is null or p_location_ids is null then
    raise exception 'TELEGRAM_EVIDENCE_LOCATION_INVALID_INPUT';
  end if;
  select coalesce(array_agg(id order by id), array[]::uuid[])
  into v_ids
  from (select distinct unnest(p_location_ids) id) selected;
  if not p_all_locations and cardinality(v_ids) = 0 then
    raise exception 'กรุณาเลือกอย่างน้อยหนึ่งสาขา';
  end if;
  if exists (
    select 1 from unnest(v_ids) id
    where not exists (select 1 from public.locations l where l.id = id and l.is_active = true)
  ) then
    raise exception 'สาขาที่เลือกไม่ถูกต้องหรือปิดใช้งานแล้ว';
  end if;
  update public.telegram_badge_settings
  set evidence_all_locations = p_all_locations,
      evidence_location_ids = case when p_all_locations then array[]::uuid[] else v_ids end,
      updated_by_user_id = auth.uid(),
      updated_at = now()
  where id = true;
  return public.get_telegram_evidence_location_config();
end;
$$;


ALTER FUNCTION "public"."save_telegram_evidence_location_config"("p_all_locations" boolean, "p_location_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_transport_staff_master_data"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_name text;
  v_actor_phone text;
  v_staff_id uuid := nullif(payload->>'staffId', '')::uuid;
  v_location_id uuid := nullif(payload->>'defaultLocationId', '')::uuid;
  v_existing public.transport_staffs%rowtype;
begin
  select p.name, p.phone
    into v_actor_name, v_actor_phone
  from public.profiles p
  where p.id = v_actor_id
    and p.is_active = true;

  if not found then
    raise exception 'Active authenticated user required' using errcode = '42501';
  end if;

  if v_location_id is null or not private.can_access_location(v_location_id) then
    raise exception 'Location access denied' using errcode = '42501';
  end if;

  if nullif(btrim(payload->>'mainName'), '') is null then
    raise exception 'Transport staff name is required' using errcode = '22023';
  end if;

  if v_staff_id is null then
    insert into public.transport_staffs (
      client_temp_id,
      idempotency_key,
      legacy_rec_id,
      legacy_member_id,
      main_name,
      sync_status,
      record_status,
      revision_no,
      default_location_id,
      created_by_user_id,
      created_by_name,
      created_by_phone,
      server_received_at
    ) values (
      nullif(payload->>'clientTempId', ''),
      nullif(payload->>'idempotencyKey', ''),
      nullif(payload->>'legacyRecId', ''),
      nullif(payload->>'legacyMemberId', ''),
      btrim(payload->>'mainName'),
      'synced',
      'active',
      0,
      v_location_id,
      v_actor_id,
      coalesce(v_actor_name, ''),
      coalesce(v_actor_phone, ''),
      now()
    )
    returning id into v_staff_id;
  else
    select *
      into v_existing
    from public.transport_staffs
    where id = v_staff_id
    for update;

    if not found then
      raise exception 'Transport staff not found' using errcode = 'P0002';
    end if;

    if v_existing.default_location_id is not null
       and not private.can_access_location(v_existing.default_location_id) then
      raise exception 'Transport staff access denied' using errcode = '42501';
    end if;

    update public.transport_staffs
    set legacy_rec_id = nullif(payload->>'legacyRecId', ''),
        legacy_member_id = nullif(payload->>'legacyMemberId', ''),
        main_name = btrim(payload->>'mainName'),
        sync_status = 'synced',
        record_status = 'active',
        revision_no = revision_no + 1,
        default_location_id = v_location_id,
        updated_by_user_id = v_actor_id,
        updated_by_name = coalesce(v_actor_name, ''),
        updated_by_phone = coalesce(v_actor_phone, ''),
        updated_at = now(),
        server_received_at = now()
    where id = v_staff_id;
  end if;

  delete from public.transport_staff_contacts where staff_id = v_staff_id;
  insert into public.transport_staff_contacts (staff_id, phone)
  select v_staff_id, btrim(item.value->>'phone')
  from jsonb_array_elements(coalesce(payload->'contacts', '[]'::jsonb)) as item(value)
  where nullif(btrim(item.value->>'phone'), '') is not null;

  delete from public.transport_staff_bank_accounts where staff_id = v_staff_id;
  insert into public.transport_staff_bank_accounts (
    staff_id,
    bank_name,
    account_number,
    account_name,
    is_primary
  )
  select
    v_staff_id,
    btrim(item.value->>'bankName'),
    btrim(item.value->>'accountNumber'),
    btrim(item.value->>'accountName'),
    coalesce((item.value->>'isPrimary')::boolean, false)
  from jsonb_array_elements(coalesce(payload->'bankAccounts', '[]'::jsonb)) as item(value)
  where nullif(btrim(item.value->>'accountNumber'), '') is not null;

  delete from public.transport_staff_plates where staff_id = v_staff_id;
  insert into public.transport_staff_plates (staff_id, plate_number)
  select v_staff_id, btrim(item.value->>'plateNumber')
  from jsonb_array_elements(coalesce(payload->'plates', '[]'::jsonb)) as item(value)
  where nullif(btrim(item.value->>'plateNumber'), '') is not null;

  return jsonb_build_object('id', v_staff_id);
end;
$$;


ALTER FUNCTION "public"."save_transport_staff_master_data"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_rubber_export_sold_out"("p_export_id" "uuid", "p_sold_out" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_export public.rubber_exports%rowtype;
  v_actor_name text;
  v_now timestamptz := clock_timestamp();
begin
  if p_sold_out is null then
    raise exception 'กรุณาระบุสถานะขายยางออก';
  end if;
  select * into v_export
  from public.rubber_exports e
  where e.id = p_export_id
  for update;
  if v_export.id is null or not private.can_manage_reports(v_export.location_id) then
    raise exception 'ไม่มีสิทธิ์จัดการการขายรายการส่งออกนี้';
  end if;
  if v_export.status <> 'verified' then
    raise exception 'ขายยางออกได้เฉพาะรายการตรวจสอบแล้ว';
  end if;

  if p_sold_out then
    if exists (
      select 1 from public.rubber_bills b
      where b.source_rubber_export_id = v_export.id
        and b.record_status = 'active'
    ) then
      raise exception 'BRANCH_RECEIPT_SOURCE_LOCKED:%', v_export.export_no
        using errcode = 'P0001';
    end if;
    if v_export.sold_out_at is null then
      select p.name into v_actor_name
      from public.profiles p
      where p.id = auth.uid() and p.is_active = true;
      if v_actor_name is null then raise exception 'บัญชีผู้ใช้ไม่พร้อมใช้งาน'; end if;
      update public.rubber_exports
      set sold_out_at = v_now,
          sold_out_by_user_id = auth.uid(),
          sold_out_by_name = v_actor_name
      where id = v_export.id;
    else
      v_now := v_export.sold_out_at;
      v_actor_name := v_export.sold_out_by_name;
    end if;
  else
    if exists (
      select 1
      from public.export_vehicle_weigh_bill_reservations r
      where r.rubber_export_id = v_export.id
    ) then
      raise exception 'WEX_RESERVATION_LOCKED: รายการขายยางถูกจองโดยบิลรถส่งออก:%', v_export.export_no
        using errcode = 'P0001',
          hint = 'กรุณาถอดรายการขายยางออกจากบิลรถส่งออกก่อน';
    end if;
    update public.rubber_exports
    set sold_out_at = null,
        sold_out_by_user_id = null,
        sold_out_by_name = null
    where id = v_export.id;
    v_now := null;
    v_actor_name := null;
  end if;

  return jsonb_build_object(
    'id', v_export.id,
    'status', case when p_sold_out then 'sold_out' else 'verified' end,
    'soldOutAt', v_now,
    'soldOutByName', v_actor_name
  );
end;
$$;


ALTER FUNCTION "public"."set_rubber_export_sold_out"("p_export_id" "uuid", "p_sold_out" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_time_payroll_active_period"("p_profile_id" "uuid", "p_action" "text", "p_effective_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_open public.time_payroll_active_periods%rowtype;
  v_latest public.time_payroll_active_periods%rowtype;
  v_today date := (now() at time zone 'Asia/Bangkok')::date;
begin
  if v_actor is null or not private.is_global_time_payroll_manager() then raise exception 'Forbidden'; end if;
  if p_profile_id is null
    or p_action is null
    or p_action not in ('ENABLE', 'PAUSE', 'RESUME', 'END')
    or p_effective_date is null
  then raise exception 'INVALID_PERIOD_ACTION'; end if;
  if p_effective_date > v_today then raise exception 'FUTURE_EFFECTIVE_DATE'; end if;
  if not exists (select 1 from public.profiles p where p.id = p_profile_id and p.is_active) then raise exception 'PROFILE_NOT_FOUND'; end if;
  perform pg_advisory_xact_lock(hashtextextended('time-payroll-attendance:' || p_profile_id::text, 0));
  select * into v_open
  from public.time_payroll_active_periods ap
  where ap.profile_id = p_profile_id and ap.end_on is null
  for update;

  if p_action in ('ENABLE', 'RESUME') then
    if found then raise exception 'ACTIVE_PERIOD_ALREADY_OPEN'; end if;

    if p_action = 'RESUME' then
      select * into v_latest
      from public.time_payroll_active_periods ap
      where ap.profile_id = p_profile_id
      order by ap.start_on desc
      limit 1
      for update;
    end if;

    perform private.assert_attendance_range_open(p_profile_id, p_effective_date, v_today);
    if p_action = 'RESUME' and v_latest.end_on = p_effective_date then
      update public.time_payroll_active_periods
      set end_on = null, updated_by = v_actor, updated_at = now()
      where id = v_latest.id;
    else
      insert into public.time_payroll_active_periods(profile_id, start_on, created_by, updated_by)
      values (p_profile_id, p_effective_date, v_actor, v_actor);
    end if;
  elsif p_action = 'PAUSE' then
    if not found or p_effective_date <= v_open.start_on then raise exception 'NO_OPEN_ACTIVE_PERIOD'; end if;
    perform private.assert_attendance_range_open(p_profile_id, p_effective_date, v_today);
    update public.time_payroll_active_periods
    set end_on = p_effective_date - 1, updated_by = v_actor, updated_at = now()
    where id = v_open.id;
  else
    if not found or p_effective_date < v_open.start_on then raise exception 'NO_OPEN_ACTIVE_PERIOD'; end if;
    perform private.assert_attendance_range_open(p_profile_id, p_effective_date + 1, v_today);
    update public.time_payroll_active_periods
    set end_on = p_effective_date, updated_by = v_actor, updated_at = now()
    where id = v_open.id;
  end if;

  insert into public.time_tracking_audit_logs(admin_id, action, target_table, record_id, new_data, comment)
  values (v_actor, 'SET_PAYROLL_ACTIVE_PERIOD', 'time_payroll_active_periods', p_profile_id,
    jsonb_build_object('action', p_action, 'effectiveDate', p_effective_date), 'เปลี่ยนช่วงเงินเดือน');
  return jsonb_build_object('profileId', p_profile_id, 'action', p_action, 'effectiveDate', p_effective_date);
end
$$;


ALTER FUNCTION "public"."set_time_payroll_active_period"("p_profile_id" "uuid", "p_action" "text", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_time_tracking_status"("p_profile_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_segment_id uuid;
  v_now timestamptz := now();
  v_current_month text := to_char(now() at time zone 'Asia/Bangkok', 'YYYY-MM');
begin
  if v_actor_id is null or not private.can_approve_time_tracking_profile(p_profile_id) then
    raise exception 'Forbidden';
  end if;
  if p_status not in ('RUNNING', 'PAUSED') then
    raise exception 'INVALID_TRACKING_STATUS';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('time-tracking:' || p_profile_id::text, 0));
  select s.id into v_segment_id
  from public.time_segments s
  where s.profile_id = p_profile_id and s.end_time is null
  for update;

  if p_status = 'RUNNING' then
    if exists (
      select 1 from public.payroll_slips ps
      where ps.profile_id = p_profile_id and ps.month = v_current_month
    ) then
      raise exception 'MONTH_CLOSED:%', v_current_month;
    end if;
    if v_segment_id is null then
      insert into public.time_segments(profile_id, start_time)
      values (p_profile_id, v_now)
      returning id into v_segment_id;
    end if;
  else
    if v_segment_id is not null then
      update public.time_segments set end_time = v_now where id = v_segment_id;
    end if;
    delete from public.time_tracking_resume_schedules where profile_id = p_profile_id;
  end if;

  insert into public.time_tracking_audit_logs (
    admin_id, action, target_table, record_id, new_data
  )
  values (
    v_actor_id,
    'TOGGLE_TRACKING',
    'time_segments',
    p_profile_id,
    jsonb_build_object('status', p_status, 'server_time', v_now)
  );

  return jsonb_build_object('status', lower(p_status), 'segmentId', v_segment_id);
end;
$$;


ALTER FUNCTION "public"."set_time_tracking_status"("p_profile_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_user_primary_location"("p_user_id" "uuid", "p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_old_location_id uuid;
begin
  if v_actor_id is null or not private.can_access_super_admin_features() then
    raise exception 'Forbidden';
  end if;
  if exists (
    select 1 from public.profiles p where p.id = p_user_id and p.role = 'super_admin'
  ) then
    raise exception 'Cannot modify super_admin locations';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('user-locations:' || p_user_id::text, 0));
  if not exists (
    select 1 from public.user_locations ul
    where ul.user_id = p_user_id and ul.location_id = p_location_id
  ) then
    raise exception 'LOCATION_NOT_ASSIGNED';
  end if;

  select ul.location_id into v_old_location_id
  from public.user_locations ul
  where ul.user_id = p_user_id and ul.is_primary = true;

  if v_old_location_id = p_location_id then
    return jsonb_build_object('status', 'unchanged', 'primaryLocationId', p_location_id);
  end if;

  update public.user_locations
  set is_primary = false
  where user_id = p_user_id and is_primary = true;

  update public.user_locations
  set is_primary = true
  where user_id = p_user_id and location_id = p_location_id;

  insert into public.time_tracking_audit_logs (
    admin_id, action, target_table, record_id, old_data, new_data, comment
  ) values (
    v_actor_id,
    'CHANGE_PRIMARY_LOCATION',
    'profiles',
    p_user_id,
    jsonb_build_object('primaryLocationId', v_old_location_id),
    jsonb_build_object('primaryLocationId', p_location_id),
    ''
  );

  return jsonb_build_object(
    'status', 'updated',
    'oldPrimaryLocationId', v_old_location_id,
    'primaryLocationId', p_location_id
  );
end
$$;


ALTER FUNCTION "public"."set_user_primary_location"("p_user_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_cash_count_session"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_actor record;
  v_session public.cash_count_sessions%rowtype;
begin
  if not private.can_use_cash_count(p_location_id) then
    raise exception 'ไม่มีสิทธิ์ตรวจนับเงินสดของสาขานี้';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text, 0));
  update public.cash_count_sessions set status = 'expired', ended_at = v_now
  where location_id = p_location_id and status = 'active' and expires_at <= v_now;

  select * into v_session from public.cash_count_sessions
  where location_id = p_location_id and status = 'active' limit 1;
  if v_session.id is not null then
    raise exception 'CASH_COUNT_ACTIVE: มีผู้ตรวจนับเงินสดของสาขานี้อยู่แล้ว';
  end if;
  if exists (select 1 from private.rubber_bill_report_blockers(p_location_id, v_now)) then
    raise exception 'RUBBER_BILL_PENDING: ยังมีงานบิลยางที่ต้องจัดการก่อนเริ่มตรวจนับ';
  end if;
  if not exists (select 1 from private.reportable_items(p_location_id, v_now)) then
    raise exception 'ไม่มีรายการที่พร้อมออกรายงาน';
  end if;

  select p.name, p.phone into v_actor from public.profiles p where p.id = auth.uid();
  insert into public.cash_count_sessions (
    location_id, cutoff_at, expires_at, started_by_user_id, started_by_name, started_by_phone, started_at
  ) values (
    p_location_id, v_now, v_now + interval '30 minutes', auth.uid(),
    coalesce(v_actor.name, ''), coalesce(v_actor.phone, ''), v_now
  ) returning * into v_session;
  return jsonb_build_object('session', jsonb_build_object(
    'id', v_session.id, 'locationId', v_session.location_id,
    'cutoffAt', v_session.cutoff_at, 'expiresAt', v_session.expires_at,
    'startedAt', v_session.started_at, 'startedByName', v_session.started_by_name,
    'isOwner', true
  ));
end;
$$;


ALTER FUNCTION "public"."start_cash_count_session"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_cash_count"("p_session_id" "uuid", "p_actual_counts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_session public.cash_count_sessions%rowtype;
  v_previous public.cash_counts%rowtype;
  v_actor record;
  v_report jsonb;
  v_count_id uuid;
  v_actual_total numeric;
  v_expected_total numeric;
  v_expected bigint[];
  v_actual bigint[];
  v_take bigint[];
  v_event record;
  v_event_counts bigint[];
  v_target bigint;
  v_difference jsonb;
  v_difference_total numeric;
  v_positive_value numeric := 0;
  v_churn_value numeric := 0;
  v_total_component integer;
  v_denom_component integer;
  v_pattern_component integer;
  v_score integer;
  v_confidence integer := 100;
  v_status text;
  v_formula text := 'cash-v1';
  v_high_conf_history integer := 0;
  v_pattern_baseline numeric := 0;
  v_simulated_count integer := 0;
  v_unknown_count integer := 0;
  v_allocation_failures integer := 0;
  v_fractional_count integer := 0;
  v_change_count integer := 0;
  v_change_amount bigint := 0;
  v_selected_delta bigint;
  v_change bigint[];
  v_highlights jsonb := '[]'::jsonb;
  v_limitations jsonb := '[]'::jsonb;
  v_references jsonb := '[]'::jsonb;
begin
  if not private.cash_count_counts_valid(p_actual_counts) then
    raise exception 'จำนวนเงินสดต้องมีครบ 9 ชนิดและเป็นจำนวนเต็มตั้งแต่ 0';
  end if;
  select * into v_session from public.cash_count_sessions where id = p_session_id for update;
  if v_session.id is null or not private.can_use_cash_count(v_session.location_id) then
    raise exception 'ไม่พบช่วงตรวจนับหรือไม่มีสิทธิ์';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_session.location_id::text, 0));
  if v_session.status <> 'active' then raise exception 'ช่วงตรวจนับนี้สิ้นสุดแล้ว'; end if;
  if v_session.started_by_user_id <> auth.uid() then
    raise exception 'เฉพาะผู้เริ่มตรวจนับเท่านั้นที่ส่งผลได้';
  end if;
  if v_session.expires_at <= v_now then
    update public.cash_count_sessions set status = 'expired', ended_at = v_now where id = p_session_id;
    raise exception 'ช่วงตรวจนับหมดเวลาแล้ว กรุณาเริ่มใหม่';
  end if;

  select * into v_previous from public.cash_counts c
  where c.location_id = v_session.location_id and c.status = 'active'
  order by c.created_at desc, c.id desc limit 1;
  select p.name, p.phone into v_actor from public.profiles p where p.id = auth.uid();
  v_report := private.create_report_batch_at(v_session.location_id, v_session.cutoff_at, auth.uid());
  v_actual := private.cash_json_to_array(p_actual_counts);
  v_actual_total := private.cash_count_total(p_actual_counts);

  if v_previous.id is null then
    insert into public.cash_counts (
      session_id, report_id, location_id, cutoff_at,
      actual_counts, actual_total, expected_counts, expected_total,
      difference_counts, difference_total, formula_version, evidence,
      created_by_user_id, created_by_name, created_by_phone, created_at
    ) values (
      v_session.id, (v_report->>'id')::uuid, v_session.location_id, v_session.cutoff_at,
      p_actual_counts, v_actual_total, p_actual_counts, v_actual_total,
      jsonb_build_object('1',0,'2',0,'5',0,'10',0,'20',0,'50',0,'100',0,'500',0,'1000',0),
      0, 'cash-v1-baseline',
      jsonb_build_object(
        'highlights', jsonb_build_array('รอบแรกใช้จำนวนที่นับเป็นฐานสำหรับรอบถัดไป'),
        'limitations', jsonb_build_array('ยังไม่มีฐานก่อนหน้าจึงไม่คำนวณคะแนนหรือความเชื่อมั่น'),
        'references', '[]'::jsonb,
        'components', jsonb_build_object('total', null, 'denomination', null, 'pattern', null)
      ), auth.uid(), coalesce(v_actor.name,''), coalesce(v_actor.phone,''), v_now
    ) returning id into v_count_id;
  else
    v_expected := private.cash_json_to_array(v_previous.actual_counts);
    v_expected_total := v_previous.actual_total;

    for v_event in
      select * from private.cash_count_events(v_session.location_id, v_previous.cutoff_at, v_session.cutoff_at)
      order by occurred_at, (reference->>'id')
    loop
      v_references := v_references || jsonb_build_array(v_event.reference || jsonb_build_object('kind', v_event.event_kind, 'occurredAt', v_event.occurred_at));
      if v_event.event_kind = 'known_in' then
        v_event_counts := private.cash_json_to_array(v_event.counts);
        for v_i in 1..9 loop v_expected[v_i] := v_expected[v_i] + v_event_counts[v_i]; end loop;
        v_expected_total := v_expected_total + v_event.amount;
      elsif v_event.event_kind = 'known_out' then
        v_event_counts := private.cash_json_to_array(v_event.counts);
        for v_i in 1..9 loop
          if v_expected[v_i] < v_event_counts[v_i] then v_allocation_failures := v_allocation_failures + 1; end if;
          v_expected[v_i] := greatest(0, v_expected[v_i] - v_event_counts[v_i]);
        end loop;
        v_expected_total := v_expected_total - v_event.amount;
      elsif v_event.event_kind = 'expense' then
        v_target := round(v_event.amount)::bigint;
        if v_event.amount <> v_target then v_fractional_count := v_fractional_count + 1; end if;
        select allocation.take_counts, allocation.change_amount
        into v_take, v_selected_delta
        from private.cash_take_with_change(v_expected, v_target, 999) allocation;
        v_simulated_count := v_simulated_count + 1;
        if v_take is null then
          v_allocation_failures := v_allocation_failures + 1;
        elsif v_selected_delta > 0 then
          v_change := private.cash_change_counts(v_selected_delta);
          for v_i in 1..9 loop v_expected[v_i] := v_expected[v_i] - v_take[v_i] + v_change[v_i]; end loop;
          v_change_count := v_change_count + 1;
          v_change_amount := v_change_amount + v_selected_delta;
        else
          for v_i in 1..9 loop v_expected[v_i] := v_expected[v_i] - v_take[v_i]; end loop;
        end if;
        v_expected_total := v_expected_total - v_event.amount;
      elsif v_event.event_kind = 'income' then
        v_expected_total := v_expected_total + v_event.amount;
        v_unknown_count := v_unknown_count + 1;
      end if;
    end loop;

    v_difference := jsonb_build_object(
      '1000', v_actual[1]-v_expected[1], '500', v_actual[2]-v_expected[2],
      '100', v_actual[3]-v_expected[3], '50', v_actual[4]-v_expected[4],
      '20', v_actual[5]-v_expected[5], '10', v_actual[6]-v_expected[6],
      '5', v_actual[7]-v_expected[7], '2', v_actual[8]-v_expected[8],
      '1', v_actual[9]-v_expected[9]
    );
    v_difference_total := v_actual_total - v_expected_total;
    for v_i in 1..9 loop
      v_churn_value := v_churn_value + abs(v_actual[v_i]-v_expected[v_i]) * (array[1000,500,100,50,20,10,5,2,1]::bigint[])[v_i];
      if v_actual[v_i] > v_expected[v_i] then
        v_positive_value := v_positive_value + (v_actual[v_i]-v_expected[v_i]) * (array[1000,500,100,50,20,10,5,2,1]::bigint[])[v_i];
      end if;
    end loop;
    v_total_component := least(70, round(abs(v_difference_total) / greatest(abs(v_expected_total) * 0.05, 500) * 70)::integer);
    v_denom_component := least(20, round(v_positive_value / greatest(abs(v_expected_total) * 0.10, 500) * 20)::integer);
    v_pattern_component := least(10, round(greatest(0, v_churn_value - abs(v_difference_total)) / greatest(abs(v_expected_total) * 0.20, 1000) * 10)::integer);

    select count(*), coalesce(avg((c.evidence->'components'->>'pattern')::numeric), 0)
    into v_high_conf_history, v_pattern_baseline from public.cash_counts c
    where c.location_id = v_session.location_id and c.status = 'active' and c.confidence >= 80;
    if v_high_conf_history >= 10 then
      v_pattern_component := least(10, round(greatest(0, v_pattern_component - v_pattern_baseline * 0.5))::integer);
      v_formula := 'cash-v1-adaptive';
    end if;
    v_score := least(100, v_total_component + v_denom_component + v_pattern_component);
    v_confidence := greatest(0,
      100 - least(30, v_simulated_count * 3) - least(30, v_unknown_count * 10)
      - least(36, v_change_count * 12) - least(50, v_allocation_failures * 20)
      - least(20, v_fractional_count * 5)
    );
    v_status := case
      when v_confidence < 50 then 'insufficient_data'
      when v_score < 25 then 'normal'
      when v_score < 60 then 'review'
      else 'high_anomaly'
    end;

    if v_difference_total <> 0 then
      v_highlights := v_highlights || jsonb_build_array(format('ยอดเงินจริงต่างจากยอดคาดการณ์ %s บาท', to_char(abs(v_difference_total), 'FM999G999G999G990D00')));
    end if;
    if v_positive_value > 0 and jsonb_array_length(v_highlights) < 3 then
      v_highlights := v_highlights || jsonb_build_array(format('พบเงินบางชนิดเพิ่มจากแบบจำลองรวม %s บาท', to_char(v_positive_value, 'FM999G999G999G990D00')));
    end if;
    if v_pattern_component > 0 and jsonb_array_length(v_highlights) < 3 then
      v_highlights := v_highlights || jsonb_build_array('สัดส่วนชนิดเงินเปลี่ยนจากลำดับจ่ายที่จำลองไว้');
    end if;
    if jsonb_array_length(v_highlights) = 0 then
      v_highlights := jsonb_build_array('ยอดรวมและชนิดเงินสอดคล้องกับข้อมูลที่คำนวณได้');
    end if;
    if v_simulated_count > 0 then v_limitations := v_limitations || jsonb_build_array(format('จำลองการจ่ายเงินสด %s รายการจากชนิดเงินตั้งต้น', v_simulated_count)); end if;
    if v_change_count > 0 then v_limitations := v_limitations || jsonb_build_array(format('จำลองรับเงินทอน %s ครั้ง รวม %s บาท', v_change_count, v_change_amount)); end if;
    if v_unknown_count > 0 then v_limitations := v_limitations || jsonb_build_array(format('มีเงินสดเข้า %s รายการที่ไม่ทราบชนิดเงิน', v_unknown_count)); end if;
    if v_allocation_failures > 0 then v_limitations := v_limitations || jsonb_build_array(format('จัดชนิดเงินให้ตรงยอดไม่ได้ %s จุด', v_allocation_failures)); end if;
    if v_fractional_count > 0 then v_limitations := v_limitations || jsonb_build_array(format('มี %s รายการที่ต้องปัดเป็นบาทเพื่อจำลองชนิดเงิน', v_fractional_count)); end if;
    if jsonb_array_length(v_limitations) = 0 then v_limitations := jsonb_build_array('ไม่พบข้อจำกัดสำคัญของข้อมูลรอบนี้'); end if;

    insert into public.cash_counts (
      session_id, report_id, location_id, previous_cash_count_id, cutoff_at,
      actual_counts, actual_total, expected_counts, expected_total,
      difference_counts, difference_total, anomaly_score, confidence, analysis_status,
      formula_version, evidence, created_by_user_id, created_by_name, created_by_phone, created_at
    ) values (
      v_session.id, (v_report->>'id')::uuid, v_session.location_id, v_previous.id, v_session.cutoff_at,
      p_actual_counts, v_actual_total, private.cash_array_to_json(v_expected), v_expected_total,
      v_difference, v_difference_total, v_score, v_confidence, v_status, v_formula,
      jsonb_build_object(
        'highlights', v_highlights, 'limitations', v_limitations, 'references', v_references,
        'components', jsonb_build_object('total',v_total_component,'denomination',v_denom_component,'pattern',v_pattern_component),
        'adaptiveHistoryCount', v_high_conf_history, 'adaptivePatternBaseline', v_pattern_baseline
      ), auth.uid(), coalesce(v_actor.name,''), coalesce(v_actor.phone,''), v_now
    ) returning id into v_count_id;
  end if;

  update public.cash_count_sessions set status = 'submitted', ended_at = v_now where id = v_session.id;
  return jsonb_build_object(
    'id', v_count_id, 'reportId', v_report->>'id', 'reportNo', v_report->>'reportNo',
    'cutoffAt', v_session.cutoff_at, 'submittedAt', v_now,
    'countedByName', coalesce(v_actor.name,''), 'actualCounts', p_actual_counts, 'actualTotal', v_actual_total
  );
end;
$$;


ALTER FUNCTION "public"."submit_cash_count"("p_session_id" "uuid", "p_actual_counts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_acid_stock_entry"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_active_user boolean;
  v_created_by_user_id uuid;
  v_created_by_name text;
  v_created_by_phone text;
  v_location_id uuid;
  v_product_id uuid;
  v_product_name text;
  v_tx_date date;
  v_quantity numeric;
  v_amount numeric;
  v_date text;
  v_next_seq integer;
  v_server_bill_no text;
  v_entry_id uuid;
begin
  v_active_user := private.is_active_user();
  if not coalesce(v_active_user, false) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Unauthorized or inactive user');
  end if;

  v_created_by_user_id := auth.uid();
  select name, phone into v_created_by_name, v_created_by_phone
  from public.profiles
  where id = v_created_by_user_id;

  v_location_id := (payload->>'locationId')::uuid;
  v_product_id := (payload->>'productId')::uuid;
  v_tx_date := (payload->>'txDate')::date;
  v_quantity := (payload->>'quantity')::numeric;
  v_amount := coalesce(nullif(payload->>'amount', '')::numeric, 0);

  if not public.can_access_location(v_location_id) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Location access denied');
  end if;

  if v_quantity is null or v_quantity <= 0 then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'จำนวนรับเข้าต้องมากกว่า 0');
  end if;

  select name into v_product_name
  from public.acid_products
  where id = v_product_id
    and is_active = true;

  if v_product_name is null then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'ไม่พบสินค้าในสต็อก');
  end if;

  v_date := to_char(v_tx_date, 'YYMMDD');
  perform pg_advisory_xact_lock(hashtext(v_location_id::text || ':acid-receive:' || v_date));

  select count(*) + 1 into v_next_seq
  from public.acid_stock_entries
  where location_id = v_location_id
    and tx_date = v_tx_date
    and tx_type = 'receive'
    and server_bill_no is not null;

  v_server_bill_no := 'AS-' || v_date || '-' || lpad(v_next_seq::text, 4, '0');

  insert into public.acid_stock_entries (
    server_bill_no, tx_date, product_id, product_name, quantity_delta,
    amount, location_id, tx_type, created_by_user_id, created_by_name, created_by_phone
  ) values (
    v_server_bill_no, v_tx_date, v_product_id, v_product_name, v_quantity,
    v_amount, v_location_id, 'receive', v_created_by_user_id, coalesce(v_created_by_name, ''), v_created_by_phone
  )
  returning id into v_entry_id;

  return jsonb_build_object(
    'status', 'synced',
    'id', v_entry_id,
    'serverBillNo', v_server_bill_no,
    'serverReceivedAt', now()
  );
exception when others then
  return jsonb_build_object('status', 'failed', 'errorMessage', sqlerrm);
end;
$$;


ALTER FUNCTION "public"."sync_acid_stock_entry"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_income_expense"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  v_approval jsonb;
  v_stock_result jsonb;
begin
  if coalesce(current_setting('app.bypass_income_expense_approval', true), 'false') = 'true' then
    return private.sync_income_expense_dispatch_20260805020000(payload);
  end if;

  if payload->>'billOption' = 'บิลขาย'
     and payload->>'operation' in ('create', 'update') then
    v_approval := public.create_income_expense_approval_request(payload);
    if v_approval->>'status' <> 'no_approval' then
      return v_approval;
    end if;

    v_stock_result := private.preflight_income_sale_stock(payload);
    if v_stock_result->>'status' <> 'ok' then
      return v_stock_result;
    end if;
    perform set_config('app.bypass_income_expense_approval', 'true', true);
    return private.sync_income_expense_dispatch_20260805020000(payload);
  end if;

  v_approval := public.create_income_expense_approval_request(payload);
  if v_approval->>'status' = 'no_approval' then
    return private.sync_income_expense_dispatch_20260805020000(payload);
  end if;
  if v_approval->>'status' = 'pending' then
    return jsonb_build_object(
      'status', 'pending_approval',
      'requestId', v_approval->>'requestId',
      'matchedReasons', coalesce(v_approval->'matchedReasons', '[]'::jsonb),
      'errorMessage', 'รายการนี้ต้องรออนุมัติ'
    );
  end if;
  return v_approval;
end;
$$;


ALTER FUNCTION "public"."sync_income_expense"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_income_expense_core"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_operation text;
  v_expected_revision integer;
  v_client_temp_id text;
  v_location_id uuid;
  v_idempotency_key text;

  v_row_id uuid;
  v_current_revision integer;
  v_server_bill_no text;
  v_existing_idempotency_key text;
  v_existing_location_id uuid;
  v_existing_stock_product_id uuid;
  v_existing_stock_quantity numeric;
  v_existing_record_status record_status;

  v_active_user boolean;
  v_created_by_user_id uuid;
  v_created_by_name text;
  v_created_by_phone text;

  v_type text;
  v_bill_option text;
  v_cost numeric;
  v_date text;
  v_next_seq integer;

  v_title text;
  v_internal_bypass boolean;
  v_keyword_id uuid;
  v_threshold numeric;
  v_threshold_scope text;
  v_amount_match boolean;
  v_keyword_match boolean;

  v_income_sale_item_id uuid;
  v_stock_product_id uuid;
  v_stock_quantity numeric;
  v_mapped_stock_product_id uuid;
  v_current_balance numeric;
  v_projected_balance numeric;
  v_existing_credit numeric;
begin
  v_active_user := private.is_active_user();
  if not coalesce(v_active_user, false) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Unauthorized or inactive user');
  end if;

  v_internal_bypass := coalesce(current_setting('app.bypass_income_expense_approval', true), 'false') = 'true';

  if v_internal_bypass and nullif(payload->>'createdByUserId', '') is not null then
    v_created_by_user_id := (payload->>'createdByUserId')::uuid;
    select name, phone into v_created_by_name, v_created_by_phone
    from public.profiles where id = v_created_by_user_id;
    v_created_by_name := coalesce(nullif(payload->>'createdByName', ''), v_created_by_name, '');
    v_created_by_phone := coalesce(nullif(payload->>'createdByPhone', ''), v_created_by_phone, '');
  else
    v_created_by_user_id := auth.uid();
    select name, phone into v_created_by_name, v_created_by_phone
    from public.profiles where id = v_created_by_user_id;
  end if;

  v_operation := payload->>'operation';
  if v_operation not in ('create', 'update', 'delete') then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Invalid operation');
  end if;

  v_expected_revision := (payload->>'expectedRevisionNo')::integer;
  v_client_temp_id := payload->>'clientTempId';
  v_location_id := (payload->>'locationId')::uuid;
  perform (payload->>'recordStatus')::record_status;
  v_idempotency_key := payload->>'idempotencyKey';
  v_type := payload->>'type';
  v_bill_option := payload->>'billOption';
  v_cost := (payload->>'cost')::numeric;
  v_title := trim(coalesce(payload->>'title', ''));
  v_income_sale_item_id := nullif(payload->>'incomeSaleItemId', '')::uuid;
  v_stock_product_id := nullif(payload->>'stockProductId', '')::uuid;
  v_stock_quantity := nullif(payload->>'stockQuantity', '')::numeric;

  if not v_internal_bypass and v_operation = 'create' then
    if v_title like 'รับโอนจาก%' or v_title like 'โยกเงินไป%' or v_title like 'สาขาจ่ายส่วนต่างให้%' or lower(v_title) = 'branch transfer' then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'ไม่สามารถซิงก์รายการโยกเงินโดยตรงได้ ต้องทำผ่านระบบโยกเงินเท่านั้น');
    end if;
  end if;

  if not v_internal_bypass and v_operation in ('create', 'update') then
    select id
      into v_keyword_id
    from public.income_expense_approval_keywords
    where is_active = true
      and deleted_at is null
      and applies_to in (v_type, 'both')
      and (approval_min_amount is null or v_cost >= approval_min_amount)
      and (
        (match_mode = 'exact' and lower(trim(v_title)) = lower(trim(keyword)))
        or
        (match_mode = 'contains' and position(lower(trim(keyword)) in lower(trim(v_title))) > 0)
      )
    limit 1;
    v_keyword_match := v_keyword_id is not null;

    select approval_min_amount, applies_to
      into v_threshold, v_threshold_scope
    from public.income_expense_approval_settings
    where id = true;

    v_amount_match := v_threshold is not null
      and v_cost >= v_threshold
      and coalesce(v_threshold_scope, 'both') in (v_type, 'both');

    if v_keyword_match or v_amount_match then
       return jsonb_build_object('status', 'conflict', 'errorMessage', 'รายการนี้ต้องขออนุมัติ ไม่สามารถซิงก์โดยตรงได้');
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtext('income_expense:' || v_client_temp_id));

  if not public.can_access_location(v_location_id) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Location access denied');
  end if;

  if v_operation != 'delete' then
    if v_type not in ('income', 'expense') then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'Invalid type');
    end if;
    if v_cost is null or v_cost <= 0 then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'cost must be > 0');
    end if;
    if v_bill_option is null then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'billOption is required');
    end if;
    if v_type = 'income' and v_bill_option not in ('รายรับ', 'บิลขาย') then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'Invalid billOption for income');
    end if;
    if v_type = 'expense' and v_bill_option != 'ค่าใช้จ่าย' then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'Invalid billOption for expense');
    end if;
    if v_bill_option = 'บิลขาย' then
      if coalesce((payload->>'unit')::numeric, 0) <= 0 then
        return jsonb_build_object('status', 'failed', 'errorMessage', 'unit must be > 0 for บิลขาย');
      end if;
      if coalesce((payload->>'price')::numeric, 0) <= 0 then
        return jsonb_build_object('status', 'failed', 'errorMessage', 'price must be > 0 for บิลขาย');
      end if;
      if v_income_sale_item_id is null or v_stock_product_id is null or coalesce(v_stock_quantity, 0) <= 0 then
        return jsonb_build_object('status', 'failed', 'errorMessage', 'บิลขายต้องเลือกรายการสินค้าที่ผูกกับสต็อก');
      end if;

      select stock_product_id
        into v_mapped_stock_product_id
      from public.income_sale_items
      where id = v_income_sale_item_id
        and is_active = true;

      if v_mapped_stock_product_id is null or v_mapped_stock_product_id <> v_stock_product_id then
        return jsonb_build_object('status', 'failed', 'errorMessage', 'รายการบิลขายไม่ตรงกับสินค้าในสต็อก');
      end if;
    else
      v_income_sale_item_id := null;
      v_stock_product_id := null;
      v_stock_quantity := null;
    end if;
  end if;

  select id, revision_no, server_bill_no, idempotency_key, location_id, stock_product_id, stock_quantity, record_status
    into v_row_id, v_current_revision, v_server_bill_no, v_existing_idempotency_key,
         v_existing_location_id, v_existing_stock_product_id, v_existing_stock_quantity, v_existing_record_status
  from public.income_expense
  where client_temp_id = v_client_temp_id
  for update;

  if v_row_id is not null then
    if v_idempotency_key = v_existing_idempotency_key then
      return jsonb_build_object(
        'status', 'synced',
        'id', v_row_id,
        'serverBillNo', v_server_bill_no,
        'revisionNo', v_current_revision,
        'serverReceivedAt', now()
      );
    end if;

    if v_operation = 'create' then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'Record already exists');
    else
      if v_current_revision != coalesce(v_expected_revision, v_current_revision) then
        return jsonb_build_object('status', 'conflict', 'errorMessage', 'Revision mismatch');
      end if;
    end if;
  else
    if v_operation != 'create' then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'Cannot update or delete non-existent record');
    end if;
  end if;

  if v_operation in ('create', 'update') and v_bill_option = 'บิลขาย' then
    perform pg_advisory_xact_lock(hashtext('acid-stock:' || v_location_id::text || ':' || v_stock_product_id::text));
    v_current_balance := public.get_acid_stock_balance(v_location_id, v_stock_product_id);
    v_existing_credit := 0;

    if v_row_id is not null
       and v_existing_record_status = 'active'
       and v_existing_location_id = v_location_id
       and v_existing_stock_product_id = v_stock_product_id then
      v_existing_credit := coalesce(v_existing_stock_quantity, 0);
    end if;

    v_projected_balance := v_current_balance + v_existing_credit - v_stock_quantity;
    if v_projected_balance < 0 then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'สต็อกสินค้าไม่พอสำหรับบิลขาย');
    end if;
  end if;

  if v_operation = 'delete' then
    update public.income_expense
    set record_status = 'deleted',
        deleted_at = now(),
        deleted_by_name = payload->>'deletedByName',
        deleted_by_phone = payload->>'deletedByPhone',
        revision_no = revision_no + 1,
        idempotency_key = v_idempotency_key,
        server_received_at = now()
    where id = v_row_id
    returning id, revision_no into v_row_id, v_current_revision;

  else
    if v_operation = 'create' then
      v_date := to_char((payload->>'txDate')::date, 'YYMMDD');
      perform pg_advisory_xact_lock(hashtext(v_location_id::text || v_date));

      select count(*) + 1 into v_next_seq
      from public.income_expense
      where location_id = v_location_id
        and tx_date = (payload->>'txDate')::date
        and server_bill_no is not null;

      v_server_bill_no := v_date || lpad(v_next_seq::text, 4, '0');

      insert into public.income_expense (
        client_temp_id, idempotency_key, revision_no, sync_status, record_status,
        location_id, type, number, local_bill_no, server_bill_no,
        tx_date, title, cost, unit, price, bill_option,
        income_sale_item_id, stock_product_id, stock_quantity,
        client_recorded_at, client_created_at, server_received_at,
        created_by_user_id, created_by_name, created_by_phone
      ) values (
        v_client_temp_id,
        v_idempotency_key,
        1,
        'synced',
        'active',
        v_location_id,
        v_type::transaction_type,
        v_server_bill_no,
        payload->>'localBillNo',
        v_server_bill_no,
        (payload->>'txDate')::date,
        v_title,
        v_cost,
        case when v_bill_option = 'บิลขาย' then payload->>'unit' else null end,
        case when v_bill_option = 'บิลขาย' then (payload->>'price')::numeric else null end,
        v_bill_option,
        v_income_sale_item_id,
        v_stock_product_id,
        v_stock_quantity,
        (payload->>'clientRecordedAt')::timestamptz,
        (payload->>'clientCreatedAt')::timestamptz,
        now(),
        v_created_by_user_id,
        coalesce(v_created_by_name, ''),
        coalesce(v_created_by_phone, '')
      )
      returning id, revision_no into v_row_id, v_current_revision;
    else
      update public.income_expense
      set location_id = v_location_id,
          type = v_type::transaction_type,
          tx_date = (payload->>'txDate')::date,
          title = v_title,
          cost = v_cost,
          unit = case when v_bill_option = 'บิลขาย' then payload->>'unit' else null end,
          price = case when v_bill_option = 'บิลขาย' then (payload->>'price')::numeric else null end,
          bill_option = v_bill_option,
          income_sale_item_id = v_income_sale_item_id,
          stock_product_id = v_stock_product_id,
          stock_quantity = v_stock_quantity,
          client_recorded_at = (payload->>'clientRecordedAt')::timestamptz,
          revision_no = revision_no + 1,
          idempotency_key = v_idempotency_key,
          server_received_at = now()
      where id = v_row_id
      returning id, revision_no into v_row_id, v_current_revision;
    end if;
  end if;

  return jsonb_build_object(
    'status', 'synced',
    'id', v_row_id,
    'serverBillNo', coalesce(v_server_bill_no, payload->>'localBillNo'),
    'revisionNo', v_current_revision,
    'serverReceivedAt', now()
  );
exception when others then
  return jsonb_build_object('status', 'failed', 'errorMessage', sqlerrm);
end;
$$;


ALTER FUNCTION "public"."sync_income_expense_core"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_money_transfer_item_source_fks"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_transfer_location_id uuid;
  v_source_location_id uuid;
begin
  select t.location_id into v_transfer_location_id
  from public.money_transfers t
  where t.id = new.transfer_id and t.record_status <> 'deleted'
  for update;
  if v_transfer_location_id is null then raise exception 'money transfer not found'; end if;
  if new.source_type <> 'rubber_bill' then
    raise exception 'unsupported money transfer source type: %', new.source_type;
  end if;
  if new.rubber_bill_id is not null and new.rubber_bill_id <> new.source_id then
    raise exception 'rubber_bill_id must match source_id';
  end if;
  new.rubber_bill_id := new.source_id;
  select rb.location_id into v_source_location_id
  from public.rubber_bills rb
  where rb.id = new.rubber_bill_id and rb.record_status <> 'deleted'
  for update;
  if v_source_location_id is null then raise exception 'money transfer source not found'; end if;
  if v_source_location_id <> v_transfer_location_id then
    raise exception 'money transfer source must belong to the transfer location';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."sync_money_transfer_item_source_fks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_rubber_bill"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_reservation jsonb;
  v_result jsonb;
begin
  begin
    v_reservation := private.reserve_rubber_bill_ocr_source(payload);
    if v_reservation->>'status' = 'conflict' then
      return v_reservation;
    end if;
    if v_reservation->>'status' <> 'ok' then
      v_result := v_reservation;
      raise exception using errcode = 'P0002', message = 'ROLLBACK_OCR_RESERVATION';
    end if;

    v_result := private.sync_rubber_bill_approval_20260823010000(payload);
    if v_result->>'status' in ('failed', 'conflict') then
      raise exception using errcode = 'P0002', message = 'ROLLBACK_OCR_RESERVATION';
    end if;
    return v_result;
  exception when sqlstate 'P0002' then
    return v_result;
  end;
end
$$;


ALTER FUNCTION "public"."sync_rubber_bill"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_rubber_bill_core_20260725010000"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
  v_source public.rubber_bill_ocr_sources%rowtype;
  v_upload_id uuid;
  v_bill_id uuid;
  v_expected_owner uuid := auth.uid();
  v_operation text := payload->>'operation';
  v_input_method text := coalesce(nullif(payload->>'inputMethod', ''), 'manual');
begin
  if v_operation = 'create' and v_input_method = 'ocr' then
    begin
      v_upload_id := (payload->>'ocrUploadId')::uuid;
    exception when others then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'ข้อมูลอ้างอิงรูป OCR ไม่ถูกต้อง');
    end;
    select * into v_source
    from public.rubber_bill_ocr_sources s
    where s.id = v_upload_id
    for update;
    if v_source.id is null then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'ไม่พบรูป OCR ที่อ้างอิง');
    end if;

    if v_source.owner_user_id <> v_expected_owner then
      select r.requested_by_user_id into v_expected_owner
      from public.rubber_bill_approval_requests r
      where r.request_status = 'pending'
        and r.requested_by_user_id = v_source.owner_user_id
        and r.location_id = v_source.location_id
        and r.client_temp_id = v_source.reserved_client_temp_id
        and r.idempotency_key = v_source.reserved_idempotency_key
        and r.proposed_payload->>'ocrUploadId' = v_source.id::text
      order by r.requested_at desc
      limit 1;
    end if;

    if v_expected_owner is distinct from v_source.owner_user_id
       or v_source.location_id is distinct from (payload->>'locationId')::uuid
       or v_source.reserved_client_temp_id is distinct from payload->>'clientTempId'
       or v_source.reserved_idempotency_key is distinct from payload->>'idempotencyKey'
       or v_source.state not in ('reserved', 'attached') then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'ข้อมูลอ้างอิงรูป OCR ไม่ตรงกับคำขอ');
    end if;
  end if;

  payload := payload - 'ocrUploadId' - 'ocrSourceId' - 'ocrImageSha256' - 'driveFileId' - 'driveUrl';
  v_result := public.sync_rubber_bill_legacy_core_20260824010000(payload);
  if v_result->>'status' <> 'synced' then
    return v_result;
  end if;

  if v_operation = 'create' and v_input_method = 'ocr' then
    v_bill_id := (v_result->>'id')::uuid;
    if v_source.state = 'attached' then
      if not exists (
        select 1
        from public.rubber_bills b
        where b.id = v_bill_id
          and b.location_id = v_source.location_id
          and b.client_temp_id = v_source.reserved_client_temp_id
          and b.idempotency_key = v_source.reserved_idempotency_key
          and b.input_method = 'ocr'
          and b.ocr_source_id = v_source.id
          and b.ocr_image_sha256 = v_source.image_sha256
      ) then
        return jsonb_build_object(
          'status', 'conflict',
          'errorCode', 'OCR_REPLAY_ATTACHMENT_MISMATCH',
          'errorMessage', 'ข้อมูลบิลยางไม่ตรงกับรูป OCR ที่แนบไว้'
        );
      end if;
      return v_result;
    end if;

    update public.rubber_bills
    set input_method = 'ocr',
        ocr_source_id = v_source.id,
        ocr_image_sha256 = v_source.image_sha256
    where id = v_bill_id
      and location_id = v_source.location_id
      and client_temp_id = v_source.reserved_client_temp_id
      and idempotency_key = v_source.reserved_idempotency_key;
    if not found then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'ข้อมูลบิลยางไม่ตรงกับรูป OCR');
    end if;
    update public.rubber_bill_ocr_sources
    set state = 'attached', attached_at = now(), updated_at = now()
    where id = v_source.id and state = 'reserved';
    if not found then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'แนบรูป OCR กับบิลยางไม่สำเร็จ');
    end if;
  end if;
  return v_result;
exception
  when unique_violation then
    return jsonb_build_object('status', 'conflict', 'errorMessage', 'รูป OCR นี้ถูกใช้กับบิลยางที่ยังใช้งานอยู่แล้ว');
  when others then
    return jsonb_build_object('status', 'failed', 'errorMessage', sqlerrm);
end
$$;


ALTER FUNCTION "public"."sync_rubber_bill_core_20260725010000"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_rubber_bill_legacy_core_20260824010000"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_operation text;
  v_expected_revision integer;
  v_client_temp_id text;
  v_location_id uuid;
  v_idempotency_key text;
  v_customer_id uuid;
  v_deduct_weight numeric;

  v_bill_id uuid;
  v_current_revision integer;
  v_server_bill_no text;
  v_existing_idempotency_key text;
  v_existing_record_status record_status;
  v_transfer_locked boolean;

  v_item jsonb;
  v_active_user boolean;
  v_created_by_user_id uuid;
  v_created_by_name text;
  v_created_by_phone text;

  v_date text;
  v_next_seq integer;
  v_stock_product_id uuid;
  v_stock_quantity numeric;
  v_stock_row record;
  v_current_balance numeric;
  v_projected_balance numeric;
begin
  payload := private.normalize_rubber_bill_calculation_payload(payload);
  v_active_user := private.is_active_user();
  if not coalesce(v_active_user, false) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Unauthorized or inactive user');
  end if;

  v_created_by_user_id := auth.uid();
  select name, phone into v_created_by_name, v_created_by_phone
  from public.profiles
  where id = v_created_by_user_id;

  v_operation := payload->>'operation';
  if v_operation not in ('create', 'update', 'delete') then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Invalid operation');
  end if;

  v_expected_revision := (payload->>'expectedRevisionNo')::integer;
  v_client_temp_id := payload->>'clientTempId';
  v_location_id := (payload->>'locationId')::uuid;
  perform (payload->>'recordStatus')::record_status;
  v_idempotency_key := payload->>'idempotencyKey';

  if v_operation in ('create', 'update') then
    v_customer_id := nullif(payload->>'customerId', '')::uuid;
    v_deduct_weight := coalesce(nullif(payload->>'deductWeight', '')::numeric, 0);

    if v_deduct_weight < 0 then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'deductWeight must be non-negative');
    end if;

    if v_customer_id is not null
       and not exists (select 1 from public.customers where id = v_customer_id) then
      return jsonb_build_object('status', 'failed', 'errorMessage', 'Customer not found');
    end if;
  end if;

  if not public.can_access_location(v_location_id) then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Location access denied');
  end if;

  select id, revision_no, server_bill_no, idempotency_key, record_status
    into v_bill_id, v_current_revision, v_server_bill_no, v_existing_idempotency_key, v_existing_record_status
  from public.rubber_bills
  where client_temp_id = v_client_temp_id
  for update;

  if v_bill_id is not null then
    if v_idempotency_key = v_existing_idempotency_key then
      return jsonb_build_object(
        'status', 'synced',
        'id', v_bill_id,
        'serverBillNo', v_server_bill_no,
        'revisionNo', v_current_revision,
        'serverReceivedAt', now()
      );
    end if;

    if v_operation = 'create' then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'Record already exists');
    elsif v_current_revision != coalesce(v_expected_revision, v_current_revision) then
      return jsonb_build_object('status', 'conflict', 'errorMessage', 'Revision mismatch');
    end if;
  elsif v_operation != 'create' then
    return jsonb_build_object('status', 'failed', 'errorMessage', 'Cannot update or delete non-existent record');
  end if;

  if v_bill_id is not null and v_operation in ('update', 'delete') then
    select exists (
      select 1
      from public.money_transfer_items i
      join public.money_transfers t on t.id = i.transfer_id
      where i.source_type = 'rubber_bill'
        and i.source_id = v_bill_id
        and t.record_status <> 'deleted'
    ) into v_transfer_locked;

    if coalesce(v_transfer_locked, false) then
      return jsonb_build_object(
        'status', 'failed',
        'errorMessage', 'รายการนี้ถูกล็อก ต้องลบ item ออกจากรายการโอนก่อน'
      );
    end if;
  end if;

  if v_operation in ('create', 'update') then
    for v_item in
      select *
      from jsonb_array_elements(coalesce(payload->'items', '[]'::jsonb))
    loop
      if v_item->>'itemType' in ('acid', 'stock_deduction') then
        v_stock_product_id := nullif(v_item->>'stockProductId', '')::uuid;
        v_stock_quantity := nullif(v_item->>'quantity', '')::numeric;

        if v_stock_product_id is null or coalesce(v_stock_quantity, 0) <= 0 then
          return jsonb_build_object(
            'status', 'failed',
            'errorMessage', 'รายการหักสินค้าต้องเลือกสินค้าในสต็อกและระบุจำนวน'
          );
        end if;

        if not exists (
          select 1
          from public.acid_products
          where id = v_stock_product_id
            and is_active = true
        ) then
          return jsonb_build_object(
            'status', 'failed',
            'errorMessage', 'ไม่พบสินค้าในสต็อกสำหรับรายการหักสินค้า'
          );
        end if;
      end if;
    end loop;

    for v_stock_row in
      with old_stock as (
        select
          stock_product_id as product_id,
          sum(quantity) as old_qty
        from public.rubber_bill_items
        where v_bill_id is not null
          and v_existing_record_status = 'active'
          and bill_id = v_bill_id
          and item_type in ('acid', 'stock_deduction')
          and stock_product_id is not null
        group by stock_product_id
      ),
      new_stock as (
        select
          nullif(item->>'stockProductId', '')::uuid as product_id,
          sum(nullif(item->>'quantity', '')::numeric) as new_qty
        from jsonb_array_elements(coalesce(payload->'items', '[]'::jsonb)) as item
        where item->>'itemType' in ('acid', 'stock_deduction')
        group by nullif(item->>'stockProductId', '')::uuid
      )
      select
        coalesce(old_stock.product_id, new_stock.product_id) as product_id,
        coalesce(old_stock.old_qty, 0) as old_qty,
        coalesce(new_stock.new_qty, 0) as new_qty
      from old_stock
      full join new_stock using (product_id)
      order by product_id
    loop
      perform pg_advisory_xact_lock(
        hashtext('acid-stock:' || v_location_id::text || ':' || v_stock_row.product_id::text)
      );
      v_current_balance := public.get_acid_stock_balance(
        v_location_id,
        v_stock_row.product_id
      );
      v_projected_balance :=
        v_current_balance + v_stock_row.old_qty - v_stock_row.new_qty;

      if v_projected_balance < 0 then
        return jsonb_build_object(
          'status', 'failed',
          'errorMessage', 'สต็อกสินค้าไม่พอสำหรับรายการหักสินค้าในบิลยาง'
        );
      end if;
    end loop;
  end if;

  if v_operation = 'delete' then
    update public.rubber_bills
    set record_status = 'deleted',
        deleted_at = now(),
        deleted_by_name = payload->>'deletedByName',
        deleted_by_phone = payload->>'deletedByPhone',
        revision_no = revision_no + 1,
        idempotency_key = v_idempotency_key,
        server_received_at = now(),
        approval_state = 'not_required',
        approved_by_name = null,
        approval_revision_no = null
    where id = v_bill_id
    returning id, revision_no into v_bill_id, v_current_revision;

  else
    if v_bill_id is null then
      v_date := to_char((payload->>'billDate')::date, 'YYMMDD');
      perform pg_advisory_xact_lock(hashtext(v_location_id::text || v_date));

      select count(*) + 1 into v_next_seq
      from public.rubber_bills
      where location_id = v_location_id
        and to_char(bill_date, 'YYMMDD') = v_date
        and server_bill_no is not null;

      v_server_bill_no := v_date || lpad(v_next_seq::text, 4, '0');
    end if;

    insert into public.rubber_bills (
      client_temp_id, idempotency_key, revision_no, sync_status, record_status,
      location_id, bill_no, local_bill_no, server_bill_no, bill_date,
      customer_id, customer_name, configured_price_snapshot, bill_type,
      deduct_weight, weight, rubber_value, average_price,
      deduction_total, net_total, acid_pack_count,
      client_recorded_at, client_created_at, server_received_at,
      created_by_user_id, created_by_name, created_by_phone,
      approval_state, approved_by_name, approval_revision_no
    ) values (
      v_client_temp_id,
      v_idempotency_key,
      coalesce(v_expected_revision + 1, 1),
      'synced',
      'active',
      v_location_id,
      coalesce(v_server_bill_no, payload->>'localBillNo'),
      payload->>'localBillNo',
      v_server_bill_no,
      (payload->>'billDate')::date,
      v_customer_id,
      payload->>'customerName',
      case
        when v_operation = 'create' then (payload->>'configuredPriceSnapshot')::numeric
        else null
      end,
      coalesce(nullif(payload->>'billType', ''), 'weighing'),
      v_deduct_weight,
      (payload->>'weight')::numeric,
      (payload->>'rubberValue')::numeric,
      (payload->>'averagePrice')::numeric,
      (payload->>'deductionTotal')::numeric,
      (payload->>'netTotal')::numeric,
      (payload->>'acidPackCount')::numeric,
      (payload->>'clientRecordedAt')::timestamptz,
      (payload->>'clientCreatedAt')::timestamptz,
      now(),
      v_created_by_user_id,
      coalesce(v_created_by_name, ''),
      coalesce(v_created_by_phone, ''),
      'not_required',
      null,
      null
    )
    on conflict (client_temp_id) do update set
      revision_no = public.rubber_bills.revision_no + 1,
      idempotency_key = excluded.idempotency_key,
      sync_status = 'synced',
      record_status = 'active',
      bill_date = excluded.bill_date,
      customer_id = excluded.customer_id,
      customer_name = excluded.customer_name,
      bill_type = excluded.bill_type,
      deduct_weight = excluded.deduct_weight,
      weight = excluded.weight,
      rubber_value = excluded.rubber_value,
      average_price = excluded.average_price,
      deduction_total = excluded.deduction_total,
      net_total = excluded.net_total,
      acid_pack_count = excluded.acid_pack_count,
      client_recorded_at = excluded.client_recorded_at,
      server_received_at = now(),
      approval_state = 'not_required',
      approved_by_name = null,
      approval_revision_no = null
    returning id, revision_no into v_bill_id, v_current_revision;

    delete from public.rubber_bill_items where bill_id = v_bill_id;

    for v_item in select * from jsonb_array_elements(coalesce(payload->'items', '[]'::jsonb))
    loop
      insert into public.rubber_bill_items (
        bill_id, item_type, description,
        weight_in, weight_out, net_weight,
        quantity, unit, price, total, stock_product_id, sequence_no
      ) values (
        v_bill_id,
        v_item->>'itemType',
        coalesce(v_item->>'description', v_item->>'title'),
        (v_item->>'inWeight')::numeric,
        (v_item->>'outWeight')::numeric,
        (v_item->>'netWeight')::numeric,
        (v_item->>'quantity')::numeric,
        v_item->>'unit',
        (v_item->>'unitPrice')::numeric,
        (v_item->>'totalAmount')::numeric,
        nullif(v_item->>'stockProductId', '')::uuid,
        nullif(v_item->>'sequenceNo', '')::integer
      );
    end loop;
  end if;

  return jsonb_build_object(
    'status', 'synced',
    'id', v_bill_id,
    'serverBillNo', v_server_bill_no,
    'revisionNo', v_current_revision,
    'serverReceivedAt', now()
  );
exception when others then
  return jsonb_build_object('status', 'failed', 'errorMessage', sqlerrm);
end;
$$;


