CREATE OR REPLACE FUNCTION "public"."update_admin_user_profile"("p_user_id" "uuid", "p_name" "text", "p_location_ids" "uuid"[], "p_primary_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_role text;
  v_target public.profiles%rowtype;
  v_normalized_name text;
  v_location_ids uuid[];
  v_old_location_ids uuid[];
  v_old_primary_location_id uuid;
  v_old_data jsonb;
  v_new_data jsonb;
  v_audit_id uuid;
  v_can_manage_system boolean;
begin
  if v_actor_id is null or not private.is_active_user() then
    raise exception 'FORBIDDEN: ไม่มีสิทธิ์จัดการพนักงาน';
  end if;
  if p_user_id is null or p_user_id = v_actor_id then
    raise exception 'FORBIDDEN: ไม่สามารถแก้ข้อมูลบัญชีของตัวเองได้';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('admin-profile:' || p_user_id::text, 0));
  select * into v_target from public.profiles p where p.id = p_user_id for update;
  if v_target.id is null then
    raise exception 'ADMIN_USER_NOT_FOUND: ไม่พบบัญชีพนักงาน';
  end if;
  if v_target.role = 'super_admin' or not v_target.is_active then
    raise exception 'FORBIDDEN: บัญชีนี้ไม่สามารถแก้ข้อมูลได้';
  end if;

  v_normalized_name := regexp_replace(btrim(coalesce(p_name, '')), '[[:space:]]+', ' ', 'g');
  if v_normalized_name = '' or char_length(v_normalized_name) > 100 then
    raise exception 'ADMIN_PROFILE_INVALID: ชื่อพนักงานต้องมี 1-100 ตัวอักษร';
  end if;

  if coalesce(cardinality(p_location_ids), 0) <> (
    select count(distinct location_id)
    from unnest(coalesce(p_location_ids, array[]::uuid[])) location_id
    where location_id is not null
  ) then
    raise exception 'ADMIN_PROFILE_INVALID: รายการสาขาซ้ำหรือไม่ถูกต้อง';
  end if;
  select coalesce(array_agg(location_id order by location_id), array[]::uuid[])
    into v_location_ids
  from unnest(coalesce(p_location_ids, array[]::uuid[])) location_id;

  if cardinality(v_location_ids) = 0 and p_primary_location_id is not null then
    raise exception 'ADMIN_PROFILE_INVALID: บัญชีไม่มีสาขาต้องไม่มีสาขาหลัก';
  end if;
  if cardinality(v_location_ids) > 0
     and (p_primary_location_id is null or not p_primary_location_id = any(v_location_ids)) then
    raise exception 'ADMIN_PROFILE_INVALID: ต้องเลือกสาขาหลักหนึ่งสาขาจากสาขาที่มอบหมาย';
  end if;
  if exists (
    select 1 from unnest(v_location_ids) requested(location_id)
    left join public.locations l on l.id = requested.location_id and l.is_active = true
    where l.id is null
  ) then
    raise exception 'ADMIN_PROFILE_INVALID: มีสาขาที่ไม่พร้อมใช้งาน';
  end if;

  select p.role into v_actor_role from public.profiles p where p.id = v_actor_id;
  v_can_manage_system := private.can_access_super_admin_features();
  if not v_can_manage_system then
    if v_actor_role <> 'admin' or v_target.role <> 'user'
       or not private.can_manage_profile(p_user_id) then
      raise exception 'FORBIDDEN: ไม่มีสิทธิ์จัดการพนักงานคนนี้';
    end if;
    if v_normalized_name <> v_target.name then
      raise exception 'FORBIDDEN: Admin ทั่วไปไม่มีสิทธิ์เปลี่ยนชื่อพนักงาน';
    end if;
  end if;

  select
    coalesce(array_agg(ul.location_id order by ul.location_id), array[]::uuid[]),
    (array_agg(ul.location_id) filter (where ul.is_primary))[1]
  into v_old_location_ids, v_old_primary_location_id
  from public.user_locations ul
  where ul.user_id = p_user_id;

  if not v_can_manage_system then
    if exists (
      select changed.location_id
      from (
        (select unnest(v_old_location_ids) location_id
         except select unnest(v_location_ids))
        union
        (select unnest(v_location_ids)
         except select unnest(v_old_location_ids))
      ) changed
      where not private.can_manage_location(changed.location_id)
    ) then
      raise exception 'FORBIDDEN: ไม่มีสิทธิ์เปลี่ยนสาขานอกขอบเขตของ Admin';
    end if;
    if v_old_primary_location_id is not null
       and v_old_primary_location_id is distinct from p_primary_location_id then
      raise exception 'FORBIDDEN: Admin ทั่วไปไม่มีสิทธิ์ย้ายสาขาหลักเดิม';
    end if;
    if v_old_primary_location_id is null
       and p_primary_location_id is not null
       and not private.can_manage_location(p_primary_location_id) then
      raise exception 'FORBIDDEN: ไม่มีสิทธิ์กำหนดสาขาหลักนอกขอบเขตของ Admin';
    end if;
  end if;

  v_old_data := jsonb_build_object(
    'name', v_target.name,
    'locationIds', to_jsonb(v_old_location_ids),
    'primaryLocationId', v_old_primary_location_id
  );

  update public.profiles
  set name = v_normalized_name, updated_at = now()
  where id = p_user_id;

  update public.user_locations set is_primary = false where user_id = p_user_id;
  delete from public.user_locations ul
  where ul.user_id = p_user_id and not (ul.location_id = any(v_location_ids));
  insert into public.user_locations (user_id, location_id, assigned_by, is_primary)
  select p_user_id, location_id, v_actor_id, false
  from unnest(v_location_ids) location_id
  on conflict (user_id, location_id) do nothing;
  if p_primary_location_id is not null then
    update public.user_locations
    set is_primary = true
    where user_id = p_user_id and location_id = p_primary_location_id;
  end if;

  v_new_data := jsonb_build_object(
    'name', v_normalized_name,
    'locationIds', to_jsonb(v_location_ids),
    'primaryLocationId', p_primary_location_id
  );
  insert into public.admin_account_audit_logs (
    actor_user_id, target_user_id, action, status,
    old_data, new_data, completed_at
  ) values (
    v_actor_id, p_user_id, 'profile_update', 'succeeded',
    v_old_data, v_new_data, now()
  ) returning id into v_audit_id;

  return jsonb_build_object(
    'user', jsonb_build_object(
      'id', v_target.id,
      'phone', v_target.phone,
      'name', v_normalized_name,
      'role', v_target.role,
      'isActive', v_target.is_active,
      'locationIds', to_jsonb(v_location_ids),
      'primaryLocationId', p_primary_location_id,
      'canAccessSystemManager', v_target.role = 'super_admin' or v_target.can_access_super_admin_features,
      'canAccessMoneyTransfer', v_target.role = 'super_admin'
        or v_target.can_access_super_admin_features or v_target.can_access_money_transfer,
      'canManageTimePayroll', v_target.role = 'super_admin'
        or v_target.can_access_super_admin_features or v_target.can_manage_time_payroll
    ),
    'auditId', v_audit_id
  );
end
$$;


ALTER FUNCTION "public"."update_admin_user_profile"("p_user_id" "uuid", "p_name" "text", "p_location_ids" "uuid"[], "p_primary_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_cash_branch_transfer"("p_transfer_id" "uuid", "payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'private'
    AS $$
declare
  transfer_row public.money_transfers%rowtype;
  target_id uuid := (payload->>'targetLocationId')::uuid;
  target_name text;
  counts integer[];
begin
  select * into transfer_row from public.money_transfers where id = p_transfer_id for update;
  if transfer_row.id is null or transfer_row.transfer_method <> 'cash' then raise exception 'ไม่พบรายการเงินสด'; end if;
  if not private.is_active_user() or not private.can_access_location(transfer_row.location_id) then raise exception 'ไม่มีสิทธิ์แก้ไขรายการนี้'; end if;
  if auth.uid() <> transfer_row.created_by_user_id and not private.is_super_admin() then raise exception 'ผู้สร้างหรือ super_admin เท่านั้นที่แก้ไขได้'; end if;
  if target_id is null or target_id = transfer_row.location_id then raise exception 'สาขาปลายทางต้องต่างจากสาขาต้นทาง'; end if;
  if not exists (select 1 from public.money_transfer_cash_details where transfer_id = p_transfer_id and cash_status = 'pending_receipt') then raise exception 'แก้ไขได้ก่อนตรวจรับเงินเท่านั้น'; end if;
  select name into target_name from public.locations where id = target_id and is_active = true;
  if target_name is null then raise exception 'ไม่พบสาขาปลายทางที่ใช้งาน'; end if;
  counts := private.cash_transfer_counts(payload, 'sent');
  update public.money_transfer_cash_details set
    sent_coin_1_count = counts[1], sent_coin_2_count = counts[2], sent_coin_5_count = counts[3], sent_coin_10_count = counts[4],
    sent_banknote_20_count = counts[5], sent_banknote_50_count = counts[6], sent_banknote_100_count = counts[7], sent_banknote_500_count = counts[8], sent_banknote_1000_count = counts[9],
    note = nullif(btrim(payload->>'note'), ''), updated_at = now()
  where transfer_id = p_transfer_id;
  update public.money_transfers set
    target_location_id = target_id, target_location_name = target_name,
    net_amount_to_pay = d.sent_total, revision_no = revision_no + 1, updated_at = now()
  from public.money_transfer_cash_details d
  where money_transfers.id = p_transfer_id and d.transfer_id = p_transfer_id;
  return jsonb_build_object('id', p_transfer_id, 'status', 'synced');
end;
$$;


ALTER FUNCTION "public"."update_cash_branch_transfer"("p_transfer_id" "uuid", "payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_export_vehicle_weigh_bill"("p_wex_id" "uuid", "p_expected_revision" integer, "p_lines" "jsonb", "p_rubber_export_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_wex public.export_vehicle_weigh_bills%rowtype;
  v_actor public.profiles%rowtype;
  v_now timestamptz := clock_timestamp();
  v_vehicle_net numeric(14,2);
  v_rubber_weight numeric(14,2);
  v_lock_ids uuid[];
begin
  select * into v_wex
  from public.export_vehicle_weigh_bills w
  where w.id = p_wex_id
  for update;
  if v_wex.id is null then
    raise exception 'WEX_NOT_FOUND: ไม่พบบิลรถส่งออก';
  end if;
  if not private.can_manage_reports(v_wex.location_id) then
    raise exception 'WEX_FORBIDDEN: ไม่มีสิทธิ์แก้ไขบิลรถส่งออกของสาขานี้';
  end if;
  if p_expected_revision is null or p_expected_revision <> v_wex.revision then
    raise exception 'WEX_STALE_REVISION: บิลรถส่งออกถูกแก้ไขแล้ว กรุณาโหลดข้อมูลใหม่';
  end if;

  perform 1 from private.normalized_export_vehicle_weigh_lines(v_wex.location_id, p_lines);
  select coalesce(array_agg(distinct id order by id), array[]::uuid[])
  into v_lock_ids
  from (
    select unnest(coalesce(p_rubber_export_ids, array[]::uuid[])) as id
    union
    select r.rubber_export_id
    from public.export_vehicle_weigh_bill_reservations r
    where r.wex_id = v_wex.id
  ) locked;
  perform e.id
  from public.rubber_exports e
  where e.id = any(v_lock_ids)
  order by e.id
  for update;

  v_rubber_weight := private.validate_wex_rubber_exports(
    v_wex.location_id, v_wex.id, p_rubber_export_ids
  );
  select * into v_actor
  from public.profiles p
  where p.id = auth.uid() and p.is_active = true;
  if v_actor.id is null then
    raise exception 'WEX_FORBIDDEN: บัญชีผู้ใช้ไม่พร้อมใช้งาน';
  end if;

  delete from public.export_vehicle_weigh_bill_reservations
  where wex_id = v_wex.id;
  delete from public.export_vehicle_weigh_lines
  where wex_id = v_wex.id;

  insert into public.export_vehicle_weigh_lines (
    wex_id, sequence_no, vehicle_registration, carrier_id, carrier_name,
    inbound_at, inbound_weight, outbound_at, outbound_weight
  )
  select
    v_wex.id, l.sequence_no, l.vehicle_registration, l.carrier_id, l.carrier_name,
    l.inbound_at, l.inbound_weight, l.outbound_at, l.outbound_weight
  from private.normalized_export_vehicle_weigh_lines(v_wex.location_id, p_lines) l;

  select round(sum(l.net_weight), 2)
  into v_vehicle_net
  from public.export_vehicle_weigh_lines l
  where l.wex_id = v_wex.id;

  if v_rubber_weight > v_vehicle_net then
    raise exception 'WEX_OVERWEIGHT: น้ำหนักรายการขายยางรวมเกินน้ำหนักสุทธิรถ';
  end if;

  insert into public.export_vehicle_weigh_bill_reservations (
    wex_id, rubber_export_id, sequence_no, export_no, current_weight, created_at
  )
  select
    v_wex.id, e.id, selected.ordinality::integer, e.export_no, e.current_weight, v_now
  from unnest(coalesce(p_rubber_export_ids, array[]::uuid[]))
    with ordinality as selected(id, ordinality)
  join public.rubber_exports e on e.id = selected.id
  order by selected.ordinality;

  update public.export_vehicle_weigh_bills
  set revision = revision + 1,
      updated_by_user_id = v_actor.id,
      updated_by_name = v_actor.name,
      updated_at = v_now
  where id = v_wex.id
  returning revision into v_wex.revision;

  return jsonb_build_object(
    'id', v_wex.id, 'wexNo', v_wex.wex_no, 'revision', v_wex.revision
  );
exception
  when unique_violation then
    raise exception 'WEX_REX_RESERVED: มีรายการขายยางถูกจองในบิลรถส่งออกอื่นแล้ว';
end;
$$;


ALTER FUNCTION "public"."update_export_vehicle_weigh_bill"("p_wex_id" "uuid", "p_expected_revision" integer, "p_lines" "jsonb", "p_rubber_export_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_rubber_approval_group"("p_group_id" "uuid", "p_location_ids" "uuid"[], "p_edit_window_minutes" integer, "p_configured_price" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_location_ids uuid[];
  v_group public.rubber_approval_groups%rowtype;
  v_actor public.profiles%rowtype;
begin
  if not private.is_active_user() or not private.can_access_super_admin_features() then
    raise exception 'FORBIDDEN: ไม่มีสิทธิ์จัดการกลุ่มอนุมัติบิลยาง';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('rubber-approval-groups', 0));
  select * into v_group from public.rubber_approval_groups g
  where g.id = p_group_id for update;
  if v_group.id is null then
    raise exception 'RUBBER_GROUP_NOT_FOUND: ไม่พบกลุ่ม';
  end if;
  v_location_ids := private.validate_rubber_approval_group_input(
    p_location_ids, p_edit_window_minutes, p_configured_price
  );
  if exists (
    select 1 from public.rubber_approval_group_locations gl
    where gl.location_id = any(v_location_ids) and gl.group_id <> p_group_id
  ) then
    raise exception 'RUBBER_GROUP_BRANCH_CONFLICT: มีสาขาอยู่ในกลุ่มอื่นแล้ว';
  end if;

  select * into v_actor from public.profiles p where p.id = auth.uid();
  update public.rubber_approval_groups
  set edit_window_minutes = p_edit_window_minutes,
      configured_price = p_configured_price,
      updated_by_user_id = auth.uid(),
      updated_by_name = v_actor.name,
      updated_by_phone = v_actor.phone,
      updated_at = now()
  where id = p_group_id
  returning * into v_group;

  delete from public.rubber_approval_group_locations gl
  where gl.group_id = p_group_id and not (gl.location_id = any(v_location_ids));
  insert into public.rubber_approval_group_locations (group_id, location_id)
  select p_group_id, location_id from unnest(v_location_ids) location_id
  on conflict (group_id, location_id) do nothing;

  return jsonb_build_object(
    'id', v_group.id,
    'locationIds', to_jsonb(v_location_ids),
    'editWindowMinutes', v_group.edit_window_minutes,
    'configuredPrice', v_group.configured_price,
    'updatedAt', v_group.updated_at
  );
exception when unique_violation then
  raise exception 'RUBBER_GROUP_BRANCH_CONFLICT: มีสาขาอยู่ในกลุ่มอื่นแล้ว';
end
$$;


ALTER FUNCTION "public"."update_rubber_approval_group"("p_group_id" "uuid", "p_location_ids" "uuid"[], "p_edit_window_minutes" integer, "p_configured_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_rubber_export"("p_export_id" "uuid", "p_current_weight" numeric, "p_work_rate" numeric, "p_other_operating_cost" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_export public.rubber_exports%rowtype;
  v_other numeric := coalesce(p_other_operating_cost, 0);
  v_loss numeric;
  v_total numeric;
begin
  select *
  into v_export
  from public.rubber_exports
  where id = p_export_id
  for update;

  if v_export.id is null
    or not private.can_manage_reports(v_export.location_id)
  then
    raise exception 'ไม่มีสิทธิ์แก้ไขรายการส่งออกนี้';
  end if;
  if v_export.status <> 'draft' then
    raise exception 'แก้ไขได้เฉพาะรายการฉบับร่าง';
  end if;
  if p_current_weight is not null
    and (p_current_weight <= 0 or p_current_weight > v_export.original_weight_total)
  then
    raise exception 'น้ำหนักปัจจุบันต้องมากกว่า 0 และไม่เกินน้ำหนักสุทธิหลังหักรวม';
  end if;
  if p_work_rate is not null and p_work_rate < 0 then
    raise exception 'ค่าทำงานต้องไม่ติดลบ';
  end if;
  if v_other < 0 then
    raise exception 'ค่าดำเนินการอื่นต้องไม่ติดลบ';
  end if;

  v_loss := case when p_current_weight is null then null
    else round(
      (v_export.original_weight_total - p_current_weight)
        / v_export.original_weight_total * 100,
      2
    )
  end;
  v_total := case when p_work_rate is null then null
    else round(v_export.original_weight_total * p_work_rate + v_other, 2)
  end;

  update public.rubber_exports
  set current_weight = p_current_weight,
      weight_loss_percent = v_loss,
      work_rate = p_work_rate,
      other_operating_cost = v_other,
      work_total = v_total
  where id = p_export_id;

  return jsonb_build_object(
    'id', p_export_id,
    'status', 'draft',
    'weightLossPercent', v_loss,
    'workTotal', v_total
  );
end;
$$;


ALTER FUNCTION "public"."update_rubber_export"("p_export_id" "uuid", "p_current_weight" numeric, "p_work_rate" numeric, "p_other_operating_cost" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_time_payroll_config"("p_workday_end_time" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_time time;
  v_today date := (now() at time zone 'Asia/Bangkok')::date;
begin
  if v_actor is null or not private.is_global_time_payroll_manager() then raise exception 'Forbidden'; end if;
  if p_workday_end_time is null or p_workday_end_time !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
  then raise exception 'INVALID_WORKDAY_END_TIME'; end if;
  v_time := p_workday_end_time::time;
  update public.time_payroll_settings
  set workday_end_time = case when pending_effective_date <= v_today then pending_workday_end_time else workday_end_time end,
      pending_workday_end_time = v_time,
      pending_effective_date = v_today + 1,
      updated_by = v_actor,
      updated_at = now()
  where singleton = true;
  insert into public.time_tracking_audit_logs(admin_id, action, target_table, record_id, new_data, comment)
  values (v_actor, 'UPDATE_TIME_PAYROLL_CONFIG', 'time_payroll_settings', v_actor,
    jsonb_build_object('workdayEndTime', p_workday_end_time, 'effectiveDate', v_today + 1), 'ตั้งค่าเวลาสิ้นสุดวัน');
  return public.get_time_payroll_settings();
end
$_$;


ALTER FUNCTION "public"."update_time_payroll_config"("p_workday_end_time" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_time_tracking_wage"("p_profile_id" "uuid", "p_daily_wage" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or not private.is_global_time_payroll_manager() then raise exception 'Forbidden'; end if;
  return public.update_time_tracking_wage_internal_20260829(p_profile_id, p_daily_wage);
end
$$;


ALTER FUNCTION "public"."update_time_tracking_wage"("p_profile_id" "uuid", "p_daily_wage" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_time_tracking_wage_internal_20260829"("p_profile_id" "uuid", "p_daily_wage" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_old_wage numeric;
begin
  if v_actor_id is null or not private.can_approve_time_tracking_profile(p_profile_id) then
    raise exception 'Forbidden';
  end if;
  if p_daily_wage is null or p_daily_wage < 0 then
    raise exception 'INVALID_WAGE';
  end if;

  select p.daily_wage into v_old_wage
  from public.profiles p
  where p.id = p_profile_id
  for update;
  if not found then raise exception 'PROFILE_NOT_FOUND'; end if;
  if exists (
    select 1
    from public.financial_transactions ft
    where ft.profile_id = p_profile_id
      and ft.status = 'APPROVED'
      and ft.type in ('DEBT_DEDUCTION', 'WITHDRAWAL_DEDUCTION')
      and not exists (
        select 1
        from public.payroll_slips ps
        where ps.profile_id = p_profile_id
          and ps.month = to_char(ft.applied_month, 'YYYY-MM')
      )
  ) then
    raise exception 'DEDUCTION_WAGE_LOCKED';
  end if;

  update public.profiles
  set daily_wage = trunc(p_daily_wage, 2)
  where id = p_profile_id;

  insert into public.time_tracking_audit_logs (
    admin_id, action, target_table, record_id, old_data, new_data
  )
  values (
    v_actor_id,
    'UPDATE_WAGE',
    'profiles',
    p_profile_id,
    jsonb_build_object('daily_wage', v_old_wage),
    jsonb_build_object('daily_wage', trunc(p_daily_wage, 2))
  );

  return jsonb_build_object('dailyWage', trunc(p_daily_wage, 2));
end;
$$;


ALTER FUNCTION "public"."update_time_tracking_wage_internal_20260829"("p_profile_id" "uuid", "p_daily_wage" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_stock_non_negative_after_entry_delete"("p_location_id" "uuid", "p_product_id" "uuid", "p_deleted_entry_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_balance numeric := 0;
  v_movement record;
begin
  for v_movement in
    select
      movement_id,
      source_type,
      source_id,
      tx_date,
      display_bill_no,
      quantity_delta
    from public.stock_movements
    where location_id = p_location_id
      and product_id = p_product_id
      and not (
        source_type = 'stock_entry'
        and source_id = any(p_deleted_entry_ids)
      )
    order by tx_date asc, movement_id asc
  loop
    v_balance := v_balance + coalesce(v_movement.quantity_delta, 0);

    if v_balance < -0.000001 then
      return jsonb_build_object(
        'status', 'failed',
        'errorMessage', 'ลบรายการนี้ไม่ได้ เพราะรายการ ' || coalesce(v_movement.display_bill_no, v_movement.movement_id) || ' วันที่ ' || v_movement.tx_date::text || ' จะทำให้สต็อกติดลบ'
      );
    end if;
  end loop;

  return jsonb_build_object('status', 'ok');
end;
$$;


ALTER FUNCTION "public"."validate_stock_non_negative_after_entry_delete"("p_location_id" "uuid", "p_product_id" "uuid", "p_deleted_entry_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_rubber_export_atomic"("p_export_id" "uuid", "p_current_weight" numeric, "p_work_rate" numeric, "p_other_operating_cost" numeric, "p_expense_destination" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_export public.rubber_exports%rowtype;
  v_actor_name text;
  v_actor_phone text;
  v_now timestamptz := clock_timestamp();
  v_age record;
begin
  if not private.can_delete_reports() then raise exception 'เฉพาะ super_admin หรือผู้มีสิทธิ์จัดการระบบเท่านั้นที่ตรวจสอบได้'; end if;
  if p_expense_destination not in ('branch', 'external') then raise exception 'กรุณาเลือกปลายทางค่าใช้จ่าย'; end if;
  select * into v_export from public.rubber_exports where id = p_export_id for update;
  if v_export.id is null then raise exception 'ไม่พบรายการส่งออก'; end if;
  if v_export.status = 'verified' then
    if v_export.current_weight is not distinct from p_current_weight
      and v_export.work_rate is not distinct from p_work_rate
      and v_export.other_operating_cost is not distinct from p_other_operating_cost
      and v_export.expense_destination = p_expense_destination then
      return jsonb_build_object('id', p_export_id, 'status', 'verified', 'verifiedAt', v_export.verified_at);
    end if;
    raise exception 'รายการนี้ตรวจสอบแล้วด้วยข้อมูลอื่น';
  end if;
  if v_export.status <> 'draft' then raise exception 'ตรวจสอบได้เฉพาะรายการฉบับร่าง'; end if;
  if p_current_weight is null or p_current_weight <= 0 or p_current_weight > v_export.original_weight_total then
    raise exception 'น้ำหนักปัจจุบันต้องมากกว่า 0 และไม่เกินน้ำหนักเดิม';
  end if;
  if p_work_rate is null or p_work_rate < 0 then raise exception 'ค่าทำงานต้องไม่น้อยกว่า 0'; end if;
  if p_other_operating_cost is null or p_other_operating_cost < 0 then raise exception 'ค่าใช้จ่ายอื่นต้องไม่น้อยกว่า 0'; end if;

  select p.name, p.phone into v_actor_name, v_actor_phone from public.profiles p where p.id = auth.uid();
  select * into v_age from private.rubber_export_age_summary(p_export_id, v_now);
  update public.rubber_exports
  set current_weight = p_current_weight,
      work_rate = p_work_rate,
      other_operating_cost = p_other_operating_cost,
      weight_loss_percent = round((original_weight_total - p_current_weight) / original_weight_total * 100, 2),
      work_total = round(original_weight_total * p_work_rate + p_other_operating_cost, 2),
      expense_destination = p_expense_destination,
      status = 'verified',
      verified_by_user_id = auth.uid(),
      verified_by_name = coalesce(v_actor_name, ''),
      verified_by_phone = coalesce(v_actor_phone, ''),
      verified_at = v_now,
      age_cutoff_at = v_now,
      average_age_hours = v_age.average_age_hours,
      oldest_age_hours = v_age.oldest_age_hours,
      estimated_age_item_count = v_age.estimated_age_item_count
  where id = p_export_id;
  return jsonb_build_object('id', p_export_id, 'status', 'verified', 'verifiedAt', v_now);
end;
$$;


ALTER FUNCTION "public"."verify_rubber_export_atomic"("p_export_id" "uuid", "p_current_weight" numeric, "p_work_rate" numeric, "p_other_operating_cost" numeric, "p_expense_destination" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_telegram_badge_dispatch_secret"("p_secret" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.role() = 'service_role'
    and coalesce(
      (
        select p_secret = ds.decrypted_secret
        from public.telegram_badge_settings s
        join vault.decrypted_secrets ds on ds.id = s.dispatch_secret_id
        where s.id = true
      ),
      false
    )
$$;


